/// Semantic class of one durable mutable-transfer scheduling cursor.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum MutableTransferCursorClass {
    /// Selected mutable State transfers.
    State,
    /// Immutable Record-revision transfers.
    Record,
    /// Immutable selected Blob source transfers.
    Blob,
}

impl MutableTransferCursorClass {
    const fn tag(self) -> u8 {
        match self {
            Self::State => 1,
            Self::Record => 2,
            Self::Blob => 3,
        }
    }

    fn from_tag(tag: u8) -> Result<Self, StoreError> {
        match tag {
            1 => Ok(Self::State),
            2 => Ok(Self::Record),
            3 => Ok(Self::Blob),
            _ => Err(StoreError::MutableTransferCursorInvariant(
                "mutable-transfer cursor key has an invalid class tag",
            )),
        }
    }
}

/// Local scheduling mode of one durable mutable-transfer cursor.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum MutableTransferCursorMode {
    /// Locally offer retained objects to the peer.
    OfferToPeer,
    /// Locally fetch missing objects from the peer.
    FetchFromPeer,
}

impl MutableTransferCursorMode {
    const fn tag(self) -> u8 {
        match self {
            Self::OfferToPeer => 1,
            Self::FetchFromPeer => 2,
        }
    }

    fn from_tag(tag: u8) -> Result<Self, StoreError> {
        match tag {
            1 => Ok(Self::OfferToPeer),
            2 => Ok(Self::FetchFromPeer),
            _ => Err(StoreError::MutableTransferCursorInvariant(
                "mutable-transfer cursor key has an invalid local-mode tag",
            )),
        }
    }
}

/// Validated durable admission limits for one store.
///
/// Both limits count aggregate legacy opaque rows, accepted exact source-sealed
/// Event, State, Record, and signed Blob representations, durable State, Record,
/// Blob, and not-yet-migrated legacy Event operation mappings, route-only cache
/// entries, exact controls, canonical local control-publication intents, and
/// opaque selected Event bridge authorizations, deduplicated sources, wrappers,
/// and route metadata. Permanent schema-v3 Event operations are governed by
/// [`EventOperationLimits`] instead, but remain part of deployment's total state
/// allocation. Physical Blob-depot files are governed by [`BlobDepotLimits`]
/// instead of being double-counted here. Unmarked or hostile untracked filesystem
/// allocation and filesystem/redb overhead remain outside these logical
/// admission claims.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct StoreLimits {
    max_items: u64,
    max_total_payload_bytes: u64,
}

impl StoreLimits {
    /// Constructs nonzero store admission limits.
    pub const fn new(
        max_items: u64,
        max_total_payload_bytes: u64,
    ) -> Result<Self, StoreLimitsError> {
        if max_items == 0 {
            return Err(StoreLimitsError::ZeroMaxItems);
        }
        if max_total_payload_bytes == 0 {
            return Err(StoreLimitsError::ZeroMaxTotalPayloadBytes);
        }
        Ok(Self {
            max_items,
            max_total_payload_bytes,
        })
    }

    /// Returns the maximum accepted-item count.
    pub const fn max_items(self) -> u64 {
        self.max_items
    }

    /// Returns the maximum aggregate retained payload/source-envelope bytes.
    pub const fn max_total_payload_bytes(self) -> u64 {
        self.max_total_payload_bytes
    }
}

impl Default for StoreLimits {
    fn default() -> Self {
        Self {
            max_items: DEFAULT_MAX_ITEMS,
            max_total_payload_bytes: DEFAULT_MAX_TOTAL_PAYLOAD_BYTES,
        }
    }
}

/// Invalid store-limit configuration.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum StoreLimitsError {
    /// At least one item must be admissible.
    ZeroMaxItems,
    /// At least one opaque payload byte must be admissible.
    ZeroMaxTotalPayloadBytes,
}

impl fmt::Display for StoreLimitsError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::ZeroMaxItems => formatter.write_str("maximum item count must be nonzero"),
            Self::ZeroMaxTotalPayloadBytes => {
                formatter.write_str("maximum total payload bytes must be nonzero")
            }
        }
    }
}

impl Error for StoreLimitsError {}

/// The result of atomically accepting an item and recording its acceptance marker.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ApplyOutcome {
    /// The identifier and bytes were new and committed with this marker.
    Inserted { acceptance_marker: u64 },
    /// The same identifier and exact bytes were already committed.
    Duplicate { acceptance_marker: u64 },
}

impl ApplyOutcome {
    /// Returns the durable marker associated with the item.
    pub const fn acceptance_marker(self) -> u64 {
        match self {
            Self::Inserted { acceptance_marker } | Self::Duplicate { acceptance_marker } => {
                acceptance_marker
            }
        }
    }

    /// Returns whether this call inserted a new durable item.
    pub const fn inserted(self) -> bool {
        matches!(self, Self::Inserted { .. })
    }
}

