/// Optimistic Event publication reservation derived only from durable ledgers.
///
/// Sealing may occur after this value is returned. Commit rechecks both high
/// waters in the redb write transaction; a concurrent publisher receives
/// [`StoreError::ReservationChanged`] and must reserve and seal again.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct EventReservation {
    control_policy: ControlPolicySnapshot,
    publisher: NodeId,
    topic: Topic,
    scope: Scope,
    previous_counter: u64,
    counter: u64,
    previous_event_sequence: u64,
    event_sequence: u64,
    context: VersionVector,
}

impl EventReservation {
    /// Exact settled control policy atomically observed with this reservation.
    pub const fn control_policy(&self) -> &ControlPolicySnapshot {
        &self.control_policy
    }

    /// Source identity for this reservation.
    pub const fn publisher(&self) -> NodeId {
        self.publisher
    }

    /// Reserved nonzero source causal counter.
    pub const fn counter(&self) -> u64 {
        self.counter
    }

    /// Reserved nonzero position in the publisher/topic/scope Event stream.
    pub const fn event_sequence(&self) -> u64 {
        self.event_sequence
    }

    /// Directly accepted causal frontier captured for this topic and scope.
    pub const fn context(&self) -> &VersionVector {
        &self.context
    }

    /// Builds the exact proven Event header for source sealing.
    pub fn header(
        &self,
        priority: Priority,
        logical_key: Vec<u8>,
        ttl_ms: Option<u64>,
        content_len: u64,
        tombstone: bool,
        key_epoch: u64,
    ) -> Result<EnvelopeHeader, StoreError> {
        if logical_key.len() > MAX_LOGICAL_KEY_BYTES {
            return Err(StoreError::InvalidSemanticEvent(
                "logical key exceeds 4096 bytes",
            ));
        }
        Ok(EnvelopeHeader {
            class: SemanticDataClass::Event,
            topic: self.topic.clone(),
            scope: self.scope.clone(),
            priority,
            stamp: CausalStamp {
                dot: Dot {
                    publisher: self.publisher,
                    counter: self.counter,
                },
                context: self.context.clone(),
            },
            event_sequence: Some(self.event_sequence),
            logical_key,
            blob_route: None,
            ttl_ms,
            content_len,
            tombstone,
            key_epoch,
        })
    }
}

/// Optimistic local State publication reservation derived from shared causal ledgers.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct StateReservation {
    control_policy: ControlPolicySnapshot,
    publisher: NodeId,
    topic: Topic,
    scope: Scope,
    previous_counter: u64,
    counter: u64,
    context: VersionVector,
}

impl StateReservation {
    /// Exact settled control policy observed with the reservation.
    pub const fn control_policy(&self) -> &ControlPolicySnapshot {
        &self.control_policy
    }

    /// Source identity for this reservation.
    pub const fn publisher(&self) -> NodeId {
        self.publisher
    }

    /// Reserved nonzero publisher-global causal counter.
    pub const fn counter(&self) -> u64 {
        self.counter
    }

    /// Topic/scope causal frontier captured by this reservation.
    pub const fn context(&self) -> &VersionVector {
        &self.context
    }

    /// Builds the exact authenticated State header for source sealing.
    pub fn header(
        &self,
        priority: Priority,
        logical_key: Vec<u8>,
        content_len: u64,
        tombstone: bool,
        key_epoch: u64,
    ) -> Result<EnvelopeHeader, StoreError> {
        if logical_key.is_empty() || logical_key.len() > MAX_STATE_LOGICAL_KEY_BYTES {
            return Err(StoreError::InvalidSemanticState(
                "logical key length is outside 1..=4096 bytes",
            ));
        }
        if tombstone && content_len != 0 {
            return Err(StoreError::InvalidSemanticState(
                "State tombstone content length must be zero",
            ));
        }
        Ok(EnvelopeHeader {
            class: SemanticDataClass::State,
            topic: self.topic.clone(),
            scope: self.scope.clone(),
            priority,
            stamp: CausalStamp {
                dot: Dot {
                    publisher: self.publisher,
                    counter: self.counter,
                },
                context: self.context.clone(),
            },
            event_sequence: None,
            logical_key,
            blob_route: None,
            ttl_ms: None,
            content_len,
            tombstone,
            key_epoch,
        })
    }
}

