struct EventCommit {
    transfer_id: EventTransferId,
    semantic_id: EventSemanticId,
    apply: ApplyOutcome,
    operation_existing: bool,
    retirement: Option<CustodyRetirementReason>,
}

fn event_once_outcome(committed: EventCommit) -> Result<EventOnceOutcome, StoreError> {
    let transfer_id = committed.transfer_id;
    let semantic_id = committed.semantic_id;
    let acceptance_marker = committed.apply.acceptance_marker();
    if let Some(reason) = committed.retirement {
        Ok(EventOnceOutcome::Retired {
            transfer_id,
            semantic_id,
            acceptance_marker,
            reason,
        })
    } else if committed.operation_existing {
        Ok(EventOnceOutcome::Existing {
            transfer_id,
            semantic_id,
            acceptance_marker,
        })
    } else if matches!(committed.apply, ApplyOutcome::Inserted { .. }) {
        Ok(EventOnceOutcome::Inserted {
            transfer_id,
            semantic_id,
            acceptance_marker,
        })
    } else {
        Ok(EventOnceOutcome::BoundExisting {
            transfer_id,
            semantic_id,
            acceptance_marker,
        })
    }
}

fn state_once_outcome(committed: StateCommit) -> StateOnceOutcome {
    if committed.operation_existing {
        StateOnceOutcome::Existing {
            state: committed.state,
        }
    } else if committed.apply.inserted() {
        StateOnceOutcome::Inserted {
            state: committed.state,
        }
    } else {
        StateOnceOutcome::BoundExisting {
            state: committed.state,
        }
    }
}

fn record_once_outcome(committed: RecordCommit) -> RecordOnceOutcome {
    if committed.operation_existing {
        RecordOnceOutcome::Existing {
            record: committed.record,
        }
    } else if committed.apply.inserted() {
        RecordOnceOutcome::Inserted {
            record: committed.record,
        }
    } else {
        RecordOnceOutcome::BoundExisting {
            record: committed.record,
        }
    }
}

