fn record_stats_read(read: &redb::ReadTransaction) -> Result<RecordStoreStats, StoreError> {
    let records = read.open_table(RECORDS)?;
    let record_bytes = read.open_table(RECORD_BYTES)?;
    let markers = read.open_table(RECORD_ACCEPTANCE_MARKERS)?;
    let operations = read.open_table(RECORD_OPERATIONS)?;
    let metadata = read.open_table(METADATA)?;
    let mut total_sealed_bytes = 0u64;
    let mut last_acceptance_marker = 0u64;
    for row in records.iter()? {
        let (key, _) = row?;
        let bytes = record_bytes
            .get(key.value())?
            .ok_or(StoreError::RecordInvariant(
                "Record stats row is missing exact source bytes",
            ))?;
        total_sealed_bytes = total_sealed_bytes
            .checked_add(
                u64::try_from(bytes.value().len())
                    .map_err(|_| StoreError::PayloadByteAccountingOverflow)?,
            )
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        let marker = markers.get(key.value())?.map(|value| value.value()).ok_or(
            StoreError::RecordInvariant("Record stats row is missing its acceptance marker"),
        )?;
        last_acceptance_marker = last_acceptance_marker.max(marker);
    }
    let mut operation_bytes = 0u64;
    for row in operations.iter()? {
        let (key, value) = row?;
        RecordOperationKey::new(key.value().to_vec())?;
        decode_record_operation_record(value.value())?;
        operation_bytes = operation_bytes
            .checked_add(
                key.value()
                    .len()
                    .checked_add(value.value().len())
                    .and_then(|length| u64::try_from(length).ok())
                    .ok_or(StoreError::PayloadByteAccountingOverflow)?,
            )
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    }
    let stats = RecordStoreStats {
        records: records.len()?,
        acceptance_markers: markers.len()?,
        total_sealed_bytes,
        last_acceptance_marker,
        operations: operations.len()?,
        operation_bytes,
    };
    for (field, reconstructed) in [
        (RECORD_ITEM_COUNT, stats.records),
        (RECORD_TOTAL_BYTES, stats.total_sealed_bytes),
        (LAST_RECORD_ACCEPTANCE_MARKER, stats.last_acceptance_marker),
        (RECORD_OPERATION_COUNT, stats.operations),
        (RECORD_OPERATION_TOTAL_BYTES, stats.operation_bytes),
    ] {
        let durable = metadata.get(field)?.map_or(0, |value| value.value());
        if durable != reconstructed {
            return Err(StoreError::AccountingMismatch {
                field,
                durable,
                reconstructed,
            });
        }
    }
    Ok(stats)
}

fn load_route_cached_event_read(
    read: &redb::ReadTransaction,
    transfer_id: EventTransferId,
) -> Result<Option<RouteCachedEvent>, StoreError> {
    let sealed = read
        .open_table(ROUTE_CACHE)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec());
    let encoded = read
        .open_table(ROUTE_CACHE_CLAIMS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec());
    match (sealed, encoded) {
        (None, None) => Ok(None),
        (Some(sealed), Some(encoded)) => {
            let metadata = decode_event_metadata(&encoded)?;
            if metadata.transfer_id != transfer_id
                || EventTransferId::new(Sha256::digest(&sealed).into()) != transfer_id
            {
                return Err(StoreError::SemanticInvariant(
                    "route-cache representation fails exact identity audit",
                ));
            }
            Ok(Some(RouteCachedEvent {
                transfer_id,
                semantic_claim: metadata.semantic_id,
                header_claim: metadata.header,
                sealed,
            }))
        }
        _ => Err(StoreError::SemanticInvariant(
            "route-cache bytes and claim are not atomically paired",
        )),
    }
}

fn load_transfer_read(
    read: &redb::ReadTransaction,
    transfer_id: EventTransferId,
) -> Result<Option<StoredEventTransfer>, StoreError> {
    let event_live = custody::sender_row_live_read(read, CustodyObjectKey::event(transfer_id))?;
    let route_live =
        custody::sender_row_live_read(read, CustodyObjectKey::route_event(transfer_id))?;
    if event_live && route_live {
        return Err(StoreError::SemanticInvariant(
            "one Event transfer has live accepted and route custody rows",
        ));
    }
    if read
        .open_table(EVENT_BYTES)?
        .get(transfer_id.as_bytes().as_slice())?
        .is_some()
        && read
            .open_table(ROUTE_CACHE)?
            .get(transfer_id.as_bytes().as_slice())?
            .is_some()
    {
        return Err(StoreError::SemanticInvariant(
            "one Event transfer has accepted and route exact representations",
        ));
    }
    if event_live {
        return load_event_from_read(read, transfer_id)?
            .map(StoredEventTransfer::Accepted)
            .ok_or(StoreError::SemanticInvariant(
                "live accepted custody row is missing its exact Event representation",
            ))
            .map(Some);
    }
    if route_live {
        return load_route_cached_event_read(read, transfer_id)?
            .map(StoredEventTransfer::RouteCached)
            .ok_or(StoreError::SemanticInvariant(
                "live route custody row is missing its exact Event representation",
            ))
            .map(Some);
    }
    Ok(None)
}

fn sender_transfer_inventory_read(
    read: &redb::ReadTransaction,
    sample: Option<aster_mesh::CustodySample>,
    limits: StoreLimits,
) -> Result<Vec<CustodySenderProjection>, StoreError> {
    let projections = custody::sender_event_projection_read(read, sample, limits.max_items())?;
    transfer_source_projections_read(read, projections, limits, true)
}

fn retained_transfer_source_inventory_read(
    read: &redb::ReadTransaction,
    limits: StoreLimits,
) -> Result<Vec<CustodySenderProjection>, StoreError> {
    let projections = custody::retained_event_projection_read(read, limits.max_items())?;
    transfer_source_projections_read(read, projections, limits, false)
}

fn transfer_source_projections_read(
    read: &redb::ReadTransaction,
    projections: Vec<CustodySenderProjection>,
    limits: StoreLimits,
    filter_inactive: bool,
) -> Result<Vec<CustodySenderProjection>, StoreError> {
    let key_count =
        u64::try_from(projections.len()).map_err(|_| StoreError::ItemCountAccountingOverflow)?;
    if key_count > limits.max_items() {
        return Err(StoreError::ItemLimitExceeded {
            current: key_count,
            limit: limits.max_items(),
        });
    }
    let events = read.open_table(EVENTS)?;
    let event_bytes = read.open_table(EVENT_BYTES)?;
    let event_markers = read.open_table(EVENT_ACCEPTANCE_MARKERS)?;
    let route_cache = read.open_table(ROUTE_CACHE)?;
    let route_claims = read.open_table(ROUTE_CACHE_CLAIMS)?;
    let revocations = read.open_table(CONTROL_REVOCATIONS)?;
    let scope_epochs = read.open_table(CONTROL_SCOPE_EPOCHS)?;
    let mut total_bytes = 0u64;
    let mut active = Vec::with_capacity(projections.len());
    for projection in projections {
        let key = projection.object();
        let transfer_id = EventTransferId::new(key.transfer_id());
        let encoded_key = transfer_id.as_bytes().as_slice();
        let event_metadata = events
            .get(encoded_key)?
            .map(|value| decode_event_metadata(value.value()))
            .transpose()?;
        let event_length = event_bytes
            .get(encoded_key)?
            .map(|value| value.value().len());
        let event_marker = event_markers.get(encoded_key)?.is_some();
        if event_metadata.is_some() != event_length.is_some()
            || event_metadata.is_some() != event_marker
        {
            return Err(StoreError::SemanticInvariant(
                "sender Event metadata, bytes, and acceptance marker are not atomically paired",
            ));
        }
        let route_length = route_cache
            .get(encoded_key)?
            .map(|value| value.value().len());
        let route_metadata = route_claims
            .get(encoded_key)?
            .map(|value| decode_event_metadata(value.value()))
            .transpose()?;
        if route_length.is_some() != route_metadata.is_some() {
            return Err(StoreError::SemanticInvariant(
                "sender route Event bytes and claim are not atomically paired",
            ));
        }
        if event_metadata.is_some() && route_metadata.is_some() {
            return Err(StoreError::SemanticInvariant(
                "one Event transfer has accepted and route exact representations",
            ));
        }
        let (metadata, source_length) = match key.class() {
            CustodyObjectClass::Event => (
                event_metadata.ok_or(StoreError::SemanticInvariant(
                    "live accepted custody row is missing its exact Event representation",
                ))?,
                event_length.expect("paired accepted Event source length"),
            ),
            CustodyObjectClass::RouteEvent => (
                route_metadata.ok_or(StoreError::SemanticInvariant(
                    "live route custody row is missing its exact Event representation",
                ))?,
                route_length.expect("paired route Event source length"),
            ),
            CustodyObjectClass::State | CustodyObjectClass::Record | CustodyObjectClass::Blob => {
                return Err(StoreError::SemanticInvariant(
                    "sender Event inventory contains a non-Event custody class",
                ));
            }
        };
        let incoming =
            u64::try_from(source_length).map_err(|_| StoreError::PayloadByteAccountingOverflow)?;
        if metadata.transfer_id != transfer_id
            || *metadata.semantic_id.as_bytes() != projection.semantic_id()
            || metadata.header.stamp.dot.publisher != projection.source_publisher()
            || metadata.header.topic != *projection.topic()
            || metadata.header.scope != *projection.scope()
            || metadata.header.key_epoch != projection.key_epoch()
            || metadata.header.priority != projection.priority()
            || metadata.header.ttl_ms != projection.ttl_ms()
            || metadata.header.tombstone != projection.tombstone()
            || incoming != projection.accounted_bytes()
        {
            return Err(StoreError::SemanticInvariant(
                "sender custody projection differs from authenticated Event metadata or exact length",
            ));
        }
        let active_epoch = scope_epochs
            .get(projection.scope().as_str())?
            .map(|value| decode_scope_epoch_index(value.value()))
            .transpose()?
            .map_or(1, |(epoch, _)| epoch);
        if filter_inactive
            && (projection.key_epoch() != active_epoch
                || revocations
                    .get(projection.source_publisher().as_slice())?
                    .is_some())
        {
            continue;
        }
        let Some(next_total) = total_bytes.checked_add(incoming) else {
            return Err(StoreError::PayloadByteAccountingOverflow);
        };
        if next_total > limits.max_total_payload_bytes() {
            return Err(StoreError::PayloadByteLimitExceeded {
                current: total_bytes,
                incoming,
                limit: limits.max_total_payload_bytes(),
            });
        }
        total_bytes = next_total;
        active.push(projection);
    }
    Ok(active)
}

fn state_sender_inventory_read(
    read: &redb::ReadTransaction,
    limits: StoreLimits,
    filter_inactive: bool,
) -> Result<Vec<StateSenderProjection>, StoreError> {
    let item_limit = limits.max_items().min(MAX_MUTABLE_NETWORK_ITEMS_PER_CLASS);
    let byte_limit = limits
        .max_total_payload_bytes()
        .min(MAX_MUTABLE_NETWORK_BYTES_PER_CLASS);
    let states = read.open_table(STATES)?;
    let state_bytes = read.open_table(STATE_BYTES)?;
    let markers = read.open_table(STATE_ACCEPTANCE_MARKERS)?;
    let revocations = read.open_table(CONTROL_REVOCATIONS)?;
    let scope_epochs = read.open_table(CONTROL_SCOPE_EPOCHS)?;
    let mut projections = Vec::new();
    let mut total_bytes = 0u64;
    for row in states.iter()? {
        let (key, encoded) = row?;
        let transfer_id = parse_state_transfer_id("State sender inventory", key.value())?;
        let metadata = decode_state_metadata(encoded.value())?;
        if metadata.transfer_id != transfer_id {
            return Err(StoreError::StateInvariant(
                "State sender metadata differs from its table key",
            ));
        }
        let sealed = state_bytes
            .get(key.value())?
            .ok_or(StoreError::StateInvariant(
                "State sender metadata is missing exact source bytes",
            ))?;
        let acceptance_marker = markers.get(key.value())?.map(|value| value.value()).ok_or(
            StoreError::StateInvariant("State sender metadata is missing its acceptance marker"),
        )?;
        if acceptance_marker == 0 {
            return Err(StoreError::StateInvariant(
                "State sender acceptance marker must be nonzero",
            ));
        }
        let exact_len = u64::try_from(sealed.value().len())
            .map_err(|_| StoreError::PayloadByteAccountingOverflow)?;
        let active_epoch = scope_epochs
            .get(metadata.header.scope.as_str())?
            .map(|value| decode_scope_epoch_index(value.value()))
            .transpose()?
            .map_or(1, |(epoch, _)| epoch);
        if filter_inactive
            && (metadata.header.key_epoch != active_epoch
                || revocations
                    .get(metadata.header.stamp.dot.publisher.as_slice())?
                    .is_some())
        {
            continue;
        }
        let next_count = projections
            .len()
            .checked_add(1)
            .ok_or(StoreError::ItemCountAccountingOverflow)?;
        if u64::try_from(next_count).map_err(|_| StoreError::ItemCountAccountingOverflow)?
            > item_limit
        {
            return Err(StoreError::ItemLimitExceeded {
                current: u64::try_from(next_count)
                    .map_err(|_| StoreError::ItemCountAccountingOverflow)?,
                limit: item_limit,
            });
        }
        total_bytes = total_bytes
            .checked_add(exact_len)
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        if total_bytes > byte_limit {
            return Err(StoreError::PayloadByteLimitExceeded {
                current: total_bytes - exact_len,
                incoming: exact_len,
                limit: byte_limit,
            });
        }
        projections.push(StateSenderProjection {
            transfer_id,
            semantic_id: metadata.semantic_id,
            publisher: metadata.header.stamp.dot.publisher,
            topic: metadata.header.topic,
            scope: metadata.header.scope,
            key_epoch: metadata.header.key_epoch,
            exact_len,
            acceptance_marker,
            metadata_fingerprint: Sha256::digest(encoded.value()).into(),
        });
    }
    for row in state_bytes.iter()? {
        let (key, _) = row?;
        if states.get(key.value())?.is_none() || markers.get(key.value())?.is_none() {
            return Err(StoreError::StateInvariant(
                "State sender source bytes are not atomically paired",
            ));
        }
    }
    for row in markers.iter()? {
        let (key, _) = row?;
        if states.get(key.value())?.is_none() || state_bytes.get(key.value())?.is_none() {
            return Err(StoreError::StateInvariant(
                "State sender acceptance marker is not atomically paired",
            ));
        }
    }
    projections.sort_by_key(StateSenderProjection::transfer_id);
    Ok(projections)
}

fn record_sender_inventory_read(
    read: &redb::ReadTransaction,
    limits: StoreLimits,
    filter_inactive: bool,
) -> Result<Vec<RecordSenderProjection>, StoreError> {
    let item_limit = limits.max_items().min(MAX_MUTABLE_NETWORK_ITEMS_PER_CLASS);
    let byte_limit = limits
        .max_total_payload_bytes()
        .min(MAX_MUTABLE_NETWORK_BYTES_PER_CLASS);
    let records = read.open_table(RECORDS)?;
    let record_bytes = read.open_table(RECORD_BYTES)?;
    let markers = read.open_table(RECORD_ACCEPTANCE_MARKERS)?;
    let revocations = read.open_table(CONTROL_REVOCATIONS)?;
    let scope_epochs = read.open_table(CONTROL_SCOPE_EPOCHS)?;
    let mut projections = Vec::new();
    let mut total_bytes = 0u64;
    for row in records.iter()? {
        let (key, encoded) = row?;
        let transfer_id = parse_record_transfer_id("Record sender inventory", key.value())?;
        let metadata = decode_record_metadata(encoded.value())?;
        if metadata.transfer_id != transfer_id {
            return Err(StoreError::RecordInvariant(
                "Record sender metadata differs from its table key",
            ));
        }
        let sealed = record_bytes
            .get(key.value())?
            .ok_or(StoreError::RecordInvariant(
                "Record sender metadata is missing exact source bytes",
            ))?;
        let acceptance_marker = markers.get(key.value())?.map(|value| value.value()).ok_or(
            StoreError::RecordInvariant("Record sender metadata is missing its acceptance marker"),
        )?;
        if acceptance_marker == 0 {
            return Err(StoreError::RecordInvariant(
                "Record sender acceptance marker must be nonzero",
            ));
        }
        let exact_len = u64::try_from(sealed.value().len())
            .map_err(|_| StoreError::PayloadByteAccountingOverflow)?;
        let active_epoch = scope_epochs
            .get(metadata.header.scope.as_str())?
            .map(|value| decode_scope_epoch_index(value.value()))
            .transpose()?
            .map_or(1, |(epoch, _)| epoch);
        if filter_inactive
            && (metadata.header.key_epoch != active_epoch
                || revocations
                    .get(metadata.header.stamp.dot.publisher.as_slice())?
                    .is_some())
        {
            continue;
        }
        let next_count = projections
            .len()
            .checked_add(1)
            .ok_or(StoreError::ItemCountAccountingOverflow)?;
        if u64::try_from(next_count).map_err(|_| StoreError::ItemCountAccountingOverflow)?
            > item_limit
        {
            return Err(StoreError::ItemLimitExceeded {
                current: u64::try_from(next_count)
                    .map_err(|_| StoreError::ItemCountAccountingOverflow)?,
                limit: item_limit,
            });
        }
        total_bytes = total_bytes
            .checked_add(exact_len)
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        if total_bytes > byte_limit {
            return Err(StoreError::PayloadByteLimitExceeded {
                current: total_bytes - exact_len,
                incoming: exact_len,
                limit: byte_limit,
            });
        }
        projections.push(RecordSenderProjection {
            transfer_id,
            semantic_id: metadata.semantic_id,
            publisher: metadata.header.stamp.dot.publisher,
            topic: metadata.header.topic,
            scope: metadata.header.scope,
            key_epoch: metadata.header.key_epoch,
            exact_len,
            acceptance_marker,
            metadata_fingerprint: Sha256::digest(encoded.value()).into(),
        });
    }
    for row in record_bytes.iter()? {
        let (key, _) = row?;
        if records.get(key.value())?.is_none() || markers.get(key.value())?.is_none() {
            return Err(StoreError::RecordInvariant(
                "Record sender source bytes are not atomically paired",
            ));
        }
    }
    for row in markers.iter()? {
        let (key, _) = row?;
        if records.get(key.value())?.is_none() || record_bytes.get(key.value())?.is_none() {
            return Err(StoreError::RecordInvariant(
                "Record sender acceptance marker is not atomically paired",
            ));
        }
    }
    projections.sort_by_key(RecordSenderProjection::transfer_id);
    Ok(projections)
}

fn transfer_inventory_read(read: &redb::ReadTransaction) -> Result<EventInventory, StoreError> {
    let events = read.open_table(EVENTS)?;
    let event_bytes = read.open_table(EVENT_BYTES)?;
    let event_markers = read.open_table(EVENT_ACCEPTANCE_MARKERS)?;
    let route_cache = read.open_table(ROUTE_CACHE)?;
    let route_claims = read.open_table(ROUTE_CACHE_CLAIMS)?;
    let mut ids = std::collections::BTreeSet::new();
    for row in events.iter()? {
        let (key, _) = row?;
        let transfer_id = parse_transfer_id("Event metadata table", key.value())?;
        if !custody::sender_row_live_read(read, CustodyObjectKey::event(transfer_id))? {
            if custody::retired_event_read(read, transfer_id)?.is_some()
                && (event_bytes.get(key.value())?.is_some()
                    || event_markers.get(key.value())?.is_none())
            {
                return Err(StoreError::SemanticInvariant(
                    "retired Event inventory fence is inconsistent",
                ));
            }
            continue;
        }
        if event_bytes.get(key.value())?.is_none() || event_markers.get(key.value())?.is_none() {
            return Err(StoreError::SemanticInvariant(
                "Event inventory row is not atomically paired",
            ));
        }
        ids.insert(transfer_id);
    }
    for row in event_bytes.iter()? {
        let (key, _) = row?;
        if events.get(key.value())?.is_none() || event_markers.get(key.value())?.is_none() {
            return Err(StoreError::SemanticInvariant(
                "Event exact bytes are not atomically paired",
            ));
        }
    }
    for row in event_markers.iter()? {
        let (key, _) = row?;
        let transfer_id = parse_transfer_id("Event marker table", key.value())?;
        if events.get(key.value())?.is_none()
            || (event_bytes.get(key.value())?.is_none()
                && custody::retired_event_read(read, transfer_id)?.is_none())
        {
            return Err(StoreError::SemanticInvariant(
                "Event acceptance marker is not atomically paired",
            ));
        }
    }
    for row in route_cache.iter()? {
        let (key, _) = row?;
        if route_claims.get(key.value())?.is_none() {
            return Err(StoreError::SemanticInvariant(
                "route-cache bytes are missing their route claim",
            ));
        }
        let transfer_id = parse_transfer_id("route Event cache", key.value())?;
        if !custody::sender_row_live_read(read, CustodyObjectKey::route_event(transfer_id))? {
            continue;
        }
        if !ids.insert(transfer_id) {
            return Err(StoreError::SemanticInvariant(
                "one transfer identity exists in semantic and route-cache namespaces",
            ));
        }
    }
    for row in route_claims.iter()? {
        let (key, _) = row?;
        if route_cache.get(key.value())?.is_none() {
            return Err(StoreError::SemanticInvariant(
                "route-cache claim is missing exact source bytes",
            ));
        }
    }
    Ok(EventInventory(ids.into_iter().collect()))
}

fn event_gap_scan_plan_read(
    read: &redb::ReadTransaction,
    control_policy: ControlPolicySnapshot,
    publisher: NodeId,
    topic: &Topic,
    scope: &Scope,
    after_sequence: u64,
    scan_limit: usize,
) -> Result<EventGapScanPlan, StoreError> {
    let stream = event_stream_key(publisher, topic, scope)?;
    let high_water = read
        .open_table(EVENT_HIGH_WATER)?
        .get(stream.as_slice())?
        .map_or(0, |value| value.value());
    let start = accepted_event_key(publisher, topic, scope, after_sequence)?;
    let accepted = read.open_table(ACCEPTED_EVENTS)?;
    let bounds = (
        std::ops::Bound::Excluded(start.as_slice()),
        std::ops::Bound::<&[u8]>::Unbounded,
    );
    let mut candidates = Vec::with_capacity(scan_limit);
    let mut has_more = false;
    let mut scanned_through = after_sequence;
    for (scanned_rows, row) in accepted.range::<&[u8]>(bounds)?.enumerate() {
        let (key, value) = row?;
        let key = key.value();
        if !key.starts_with(&stream) {
            break;
        }
        if key.len() != stream.len() + 8 {
            return Err(StoreError::SemanticInvariant(
                "accepted Event stream position has invalid length",
            ));
        }
        let sequence = u64::from_be_bytes(
            key[stream.len()..]
                .try_into()
                .expect("validated Event sequence suffix"),
        );
        if sequence <= after_sequence || sequence > high_water {
            return Err(StoreError::SemanticInvariant(
                "accepted Event stream position disagrees with its scan boundary or high-water",
            ));
        }
        if scanned_rows == scan_limit {
            has_more = true;
            break;
        }
        scanned_through = sequence;
        let semantic_id = parse_semantic_id("accepted Event table", value.value())?;
        let transfer_id = read
            .open_table(SEMANTIC_ITEMS)?
            .get(semantic_id.as_bytes().as_slice())?
            .map(|value| parse_transfer_id("semantic item table", value.value()))
            .transpose()?
            .ok_or(StoreError::SemanticInvariant(
                "accepted Event stream position points to a missing semantic index",
            ))?;
        let encoded = read
            .open_table(EVENTS)?
            .get(transfer_id.as_bytes().as_slice())?
            .map(|value| value.value().to_vec())
            .ok_or(StoreError::SemanticInvariant(
                "accepted Event stream position points to missing metadata",
            ))?;
        let metadata = decode_event_metadata(&encoded)?;
        if metadata.semantic_id != semantic_id
            || metadata.header.stamp.dot.publisher != publisher
            || metadata.header.topic != *topic
            || metadata.header.scope != *scope
            || event_sequence(&metadata.header)? != sequence
        {
            return Err(StoreError::SemanticInvariant(
                "accepted Event stream position differs from its semantic metadata",
            ));
        }
        if !custody::sender_row_live_read(read, CustodyObjectKey::event(transfer_id))? {
            continue;
        }
        let Some(event) = load_event_from_read(read, transfer_id)? else {
            if custody::retired_event_read(read, transfer_id)?.is_none() {
                return Err(StoreError::SemanticInvariant(
                    "accepted Event stream position points to missing non-retired bytes",
                ));
            }
            continue;
        };
        if event.semantic_id != semantic_id
            || event.header.stamp.dot.publisher != publisher
            || event.header.topic != *topic
            || event.header.scope != *scope
            || event_sequence(&event.header)? != sequence
        {
            return Err(StoreError::SemanticInvariant(
                "accepted Event stream position differs from its semantic Event",
            ));
        }
        candidates.push(EventGapCandidate { sequence, event });
    }
    if (has_more && high_water <= scanned_through) || (!has_more && high_water > scanned_through) {
        return Err(StoreError::SemanticInvariant(
            "Event stream high-water differs from its accepted positions",
        ));
    }
    Ok(EventGapScanPlan {
        control_policy,
        publisher,
        topic: topic.clone(),
        scope: scope.clone(),
        after_sequence,
        scan_limit,
        candidates,
        scanned_through,
        high_water,
        has_more,
    })
}

fn events_after_read(
    read: &redb::ReadTransaction,
    after_acceptance_marker: u64,
    limit: usize,
) -> Result<Vec<StoredEvent>, StoreError> {
    let events = read.open_table(EVENTS)?;
    let event_bytes = read.open_table(EVENT_BYTES)?;
    let markers = read.open_table(EVENT_ACCEPTANCE_MARKERS)?;
    let mut page = Vec::new();
    for row in events.iter()? {
        let (key, value) = row?;
        let transfer_id = parse_transfer_id("Event metadata table", key.value())?;
        let marker = markers.get(key.value())?.map(|value| value.value()).ok_or(
            StoreError::SemanticInvariant("Event page row is missing its acceptance marker"),
        )?;
        if marker <= after_acceptance_marker {
            continue;
        }
        let Some(sealed) = event_bytes
            .get(key.value())?
            .map(|value| value.value().to_vec())
        else {
            if custody::retired_event_read(read, transfer_id)?.is_some() {
                continue;
            }
            return Err(StoreError::SemanticInvariant(
                "Event page row is missing non-retired exact source bytes",
            ));
        };
        page.push(decode_stored_event(
            transfer_id,
            value.value(),
            sealed,
            marker,
        )?);
    }
    page.sort_by_key(|event| (event.acceptance_marker, event.transfer_id));
    page.truncate(limit);
    Ok(page)
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ZeroizationRecord {
    state: StoreZeroizationState,
    authority: NodeId,
    intent: ZeroizationIntent,
}

fn validate_zeroization_descriptor(
    artifact: ZeroizationArtifact,
    descriptor: &[u8],
) -> Result<(), StoreError> {
    if descriptor.is_empty() || descriptor.len() > MAX_ZEROIZATION_DESCRIPTOR_BYTES {
        return Err(StoreError::InvalidZeroizationDescriptor {
            artifact,
            length: descriptor.len(),
        });
    }
    Ok(())
}

fn zeroization_phase_and_flags(state: StoreZeroizationState) -> Result<(u8, u8), StoreError> {
    match state {
        StoreZeroizationState::Live => Err(StoreError::ZeroizationInvariant(
            "live state must be represented by an absent terminal table",
        )),
        StoreZeroizationState::CleanupPending => Ok((1, 0)),
        StoreZeroizationState::MissionDestroyed => Ok((2, 1)),
        StoreZeroizationState::IdentityDestroyed => Ok((3, 3)),
        StoreZeroizationState::Complete => Ok((4, 3)),
    }
}

fn encode_zeroization_record(record: &ZeroizationRecord) -> Result<Vec<u8>, StoreError> {
    let (phase, flags) = zeroization_phase_and_flags(record.state)?;
    let mission = record.intent.descriptor(ZeroizationArtifact::MissionBundle);
    let identity = record
        .intent
        .descriptor(ZeroizationArtifact::CarrierIdentity);
    validate_zeroization_descriptor(ZeroizationArtifact::MissionBundle, mission)?;
    validate_zeroization_descriptor(ZeroizationArtifact::CarrierIdentity, identity)?;
    let mission_len =
        u32::try_from(mission.len()).map_err(|_| StoreError::InvalidZeroizationDescriptor {
            artifact: ZeroizationArtifact::MissionBundle,
            length: mission.len(),
        })?;
    let identity_len =
        u32::try_from(identity.len()).map_err(|_| StoreError::InvalidZeroizationDescriptor {
            artifact: ZeroizationArtifact::CarrierIdentity,
            length: identity.len(),
        })?;
    let mut encoded = Vec::with_capacity(
        ZEROIZATION_HEADER_BYTES + mission.len() + identity.len() + ZEROIZATION_DIGEST_BYTES,
    );
    encoded.extend_from_slice(ZEROIZATION_MAGIC);
    encoded.push(phase);
    encoded.push(flags);
    encoded.extend_from_slice(record.authority.as_slice());
    encoded.extend_from_slice(&mission_len.to_be_bytes());
    encoded.extend_from_slice(&identity_len.to_be_bytes());
    encoded.extend_from_slice(mission);
    encoded.extend_from_slice(identity);
    let digest: [u8; ZEROIZATION_DIGEST_BYTES] = Sha256::digest(&encoded).into();
    encoded.extend_from_slice(&digest);
    Ok(encoded)
}

fn decode_zeroization_record(encoded: &[u8]) -> Result<ZeroizationRecord, StoreError> {
    if encoded.len() > MAX_ZEROIZATION_RECORD_BYTES {
        return Err(StoreError::ZeroizationInvariant(
            "terminal record exceeds maximum encoded length",
        ));
    }
    if encoded.len() < ZEROIZATION_HEADER_BYTES + ZEROIZATION_DIGEST_BYTES {
        return Err(StoreError::ZeroizationInvariant(
            "terminal record is shorter than its fixed header and digest",
        ));
    }
    let digest_offset = encoded.len() - ZEROIZATION_DIGEST_BYTES;
    let expected: [u8; ZEROIZATION_DIGEST_BYTES] = Sha256::digest(&encoded[..digest_offset]).into();
    if encoded[digest_offset..] != expected {
        return Err(StoreError::ZeroizationInvariant(
            "terminal record digest does not match its encoded state",
        ));
    }
    if &encoded[..ZEROIZATION_MAGIC.len()] != ZEROIZATION_MAGIC {
        return Err(StoreError::ZeroizationInvariant(
            "terminal record magic or schema version is invalid",
        ));
    }
    let phase = encoded[8];
    let flags = encoded[9];
    let state = match (phase, flags) {
        (1, 0) => StoreZeroizationState::CleanupPending,
        (2, 1) => StoreZeroizationState::MissionDestroyed,
        (3, 3) => StoreZeroizationState::IdentityDestroyed,
        (4, 3) => StoreZeroizationState::Complete,
        _ => {
            return Err(StoreError::ZeroizationInvariant(
                "terminal phase and artifact receipts disagree",
            ));
        }
    };
    let authority = parse_node_id("zeroization mission authority", &encoded[10..42])?;
    let mission_len =
        usize::try_from(u32::from_be_bytes(encoded[42..46].try_into().map_err(
            |_| StoreError::ZeroizationInvariant("invalid mission descriptor length"),
        )?))
        .map_err(|_| StoreError::ZeroizationInvariant("invalid mission descriptor length"))?;
    let identity_len =
        usize::try_from(u32::from_be_bytes(encoded[46..50].try_into().map_err(
            |_| StoreError::ZeroizationInvariant("invalid identity descriptor length"),
        )?))
        .map_err(|_| StoreError::ZeroizationInvariant("invalid identity descriptor length"))?;
    if mission_len == 0 || mission_len > MAX_ZEROIZATION_DESCRIPTOR_BYTES {
        return Err(StoreError::ZeroizationInvariant(
            "terminal mission descriptor length is outside its bound",
        ));
    }
    if identity_len == 0 || identity_len > MAX_ZEROIZATION_DESCRIPTOR_BYTES {
        return Err(StoreError::ZeroizationInvariant(
            "terminal identity descriptor length is outside its bound",
        ));
    }
    let payload_len =
        mission_len
            .checked_add(identity_len)
            .ok_or(StoreError::ZeroizationInvariant(
                "terminal descriptor lengths overflow",
            ))?;
    if ZEROIZATION_HEADER_BYTES.checked_add(payload_len) != Some(digest_offset) {
        return Err(StoreError::ZeroizationInvariant(
            "terminal descriptor lengths do not match the record",
        ));
    }
    let mission_end = ZEROIZATION_HEADER_BYTES + mission_len;
    let intent = ZeroizationIntent::new(
        encoded[ZEROIZATION_HEADER_BYTES..mission_end].to_vec(),
        encoded[mission_end..digest_offset].to_vec(),
    )
    .map_err(|_| StoreError::ZeroizationInvariant("terminal artifact descriptor is invalid"))?;
    Ok(ZeroizationRecord {
        state,
        authority,
        intent,
    })
}

fn inspect_zeroization_readable(
    database: &impl ReadableDatabase,
) -> Result<StoreZeroizationStatus, StoreError> {
    let read = database.begin_read()?;
    inspect_zeroization_read(&read)
}

fn inspect_zeroization_read(
    read: &redb::ReadTransaction,
) -> Result<StoreZeroizationStatus, StoreError> {
    let multimap_names = read
        .list_multimap_tables()?
        .map(|table| table.name().to_owned())
        .collect::<std::collections::BTreeSet<_>>();
    if multimap_names.contains(ZEROIZATION.name()) {
        return Err(StoreError::ZeroizationInvariant(
            "reserved terminal table name has the wrong table kind",
        ));
    }
    if multimap_names.contains(SEMANTIC_DOMAIN.name()) {
        return Err(StoreError::SemanticInvariant(
            "semantic mission domain has the wrong table kind",
        ));
    }
    let table_names = read
        .list_tables()?
        .map(|table| table.name().to_owned())
        .collect::<std::collections::BTreeSet<_>>();
    let mission_authority = if table_names.contains(SEMANTIC_DOMAIN.name()) {
        let domain = read.open_table(SEMANTIC_DOMAIN)?;
        domain
            .get(MISSION_AUTHORITY_ID)?
            .map(|value| parse_node_id("semantic mission authority", value.value()))
            .transpose()?
    } else {
        None
    };
    inspect_mutable_transfer_cursors_read(read, mission_authority)?;
    if !table_names.contains(ZEROIZATION.name()) {
        return Ok(StoreZeroizationStatus {
            state: StoreZeroizationState::Live,
            mission_authority,
            intent: None,
        });
    }
    let terminal = read.open_table(ZEROIZATION)?;
    if terminal.len()? != 1 {
        return Err(StoreError::ZeroizationInvariant(
            "terminal table must contain exactly one state record",
        ));
    }
    let encoded = terminal
        .get(ZEROIZATION_STATE_KEY)?
        .ok_or(StoreError::ZeroizationInvariant(
            "terminal table is missing its state record",
        ))?;
    let record = decode_zeroization_record(encoded.value())?;
    if mission_authority != Some(record.authority) {
        return Err(StoreError::ZeroizationInvariant(
            "terminal authority differs from the stable mission binding",
        ));
    }
    Ok(StoreZeroizationStatus {
        state: record.state,
        mission_authority,
        intent: Some(record.intent),
    })
}

fn zeroization_record_write(
    write: &redb::WriteTransaction,
) -> Result<Option<ZeroizationRecord>, StoreError> {
    if write
        .list_multimap_tables()?
        .any(|table| table.name() == ZEROIZATION.name())
    {
        return Err(StoreError::ZeroizationInvariant(
            "reserved terminal table name has the wrong table kind",
        ));
    }
    let present = write
        .list_tables()?
        .any(|table| table.name() == ZEROIZATION.name());
    if !present {
        return Ok(None);
    }
    let terminal = write.open_table(ZEROIZATION)?;
    if terminal.len()? != 1 {
        return Err(StoreError::ZeroizationInvariant(
            "terminal table must contain exactly one state record",
        ));
    }
    let encoded = terminal
        .get(ZEROIZATION_STATE_KEY)?
        .ok_or(StoreError::ZeroizationInvariant(
            "terminal table is missing its state record",
        ))?;
    Ok(Some(decode_zeroization_record(encoded.value())?))
}

fn enforce_live_write(write: &redb::WriteTransaction) -> Result<(), StoreError> {
    match zeroization_record_write(write)? {
        None => Ok(()),
        Some(record) => Err(StoreError::StoreZeroized(record.state)),
    }
}

fn require_zeroization_authority(
    write: &redb::WriteTransaction,
    authority: NodeId,
) -> Result<(), StoreError> {
    match read_mission_binding(write)? {
        Some(bound) if bound == authority => Ok(()),
        Some(bound) => Err(StoreError::MissionAuthorityMismatch {
            bound,
            received: authority,
        }),
        None => Err(StoreError::MissionNotBound),
    }
}

fn write_zeroization_record(
    write: &redb::WriteTransaction,
    record: &ZeroizationRecord,
) -> Result<(), StoreError> {
    let encoded = encode_zeroization_record(record)?;
    let mut terminal = write.open_table(ZEROIZATION)?;
    terminal.insert(ZEROIZATION_STATE_KEY, encoded.as_slice())?;
    Ok(())
}

fn begin_zeroization_write(
    write: &redb::WriteTransaction,
    authority: NodeId,
    intent: &ZeroizationIntent,
) -> Result<BeginZeroizationOutcome, StoreError> {
    require_zeroization_authority(write, authority)?;
    if let Some(record) = zeroization_record_write(write)? {
        if record.authority != authority {
            return Err(StoreError::ZeroizationInvariant(
                "terminal authority differs from the cleanup handle",
            ));
        }
        if &record.intent != intent {
            return Err(StoreError::ZeroizationIntentConflict);
        }
        return Ok(BeginZeroizationOutcome::AlreadyStarted(record.state));
    }
    write_zeroization_record(
        write,
        &ZeroizationRecord {
            state: StoreZeroizationState::CleanupPending,
            authority,
            intent: intent.clone(),
        },
    )?;
    Ok(BeginZeroizationOutcome::EnteredCleanupPending)
}

fn mark_artifact_destroyed_write(
    write: &redb::WriteTransaction,
    authority: NodeId,
    artifact: ZeroizationArtifact,
) -> Result<ArtifactDestructionOutcome, StoreError> {
    require_zeroization_authority(write, authority)?;
    let mut record = zeroization_record_write(write)?.ok_or(
        StoreError::ZeroizationOrderViolation("terminal cleanup has not begun"),
    )?;
    if record.authority != authority {
        return Err(StoreError::ZeroizationInvariant(
            "terminal authority differs from the cleanup handle",
        ));
    }
    let next = match (artifact, record.state) {
        (ZeroizationArtifact::MissionBundle, StoreZeroizationState::CleanupPending) => {
            StoreZeroizationState::MissionDestroyed
        }
        (ZeroizationArtifact::MissionBundle, _) if record.state.mission_destroyed() => {
            return Ok(ArtifactDestructionOutcome::AlreadyMarked);
        }
        (ZeroizationArtifact::CarrierIdentity, StoreZeroizationState::CleanupPending) => {
            return Err(StoreError::ZeroizationOrderViolation(
                "mission bundle must be destroyed before carrier identity",
            ));
        }
        (ZeroizationArtifact::CarrierIdentity, StoreZeroizationState::MissionDestroyed) => {
            StoreZeroizationState::IdentityDestroyed
        }
        (ZeroizationArtifact::CarrierIdentity, _) if record.state.identity_destroyed() => {
            return Ok(ArtifactDestructionOutcome::AlreadyMarked);
        }
        _ => {
            return Err(StoreError::ZeroizationInvariant(
                "terminal artifact state cannot advance",
            ));
        }
    };
    record.state = next;
    write_zeroization_record(write, &record)?;
    Ok(ArtifactDestructionOutcome::Marked)
}

fn finalize_zeroization_write(
    write: &redb::WriteTransaction,
    authority: NodeId,
) -> Result<FinalizeZeroizationOutcome, StoreError> {
    require_zeroization_authority(write, authority)?;
    let mut record = zeroization_record_write(write)?.ok_or(
        StoreError::ZeroizationOrderViolation("terminal cleanup has not begun"),
    )?;
    if record.authority != authority {
        return Err(StoreError::ZeroizationInvariant(
            "terminal authority differs from the cleanup handle",
        ));
    }
    match record.state {
        StoreZeroizationState::IdentityDestroyed => {
            record.state = StoreZeroizationState::Complete;
            write_zeroization_record(write, &record)?;
            Ok(FinalizeZeroizationOutcome::Finalized)
        }
        StoreZeroizationState::Complete => Ok(FinalizeZeroizationOutcome::AlreadyComplete),
        _ => Err(StoreError::ZeroizationOrderViolation(
            "both artifact destruction receipts are required before finalization",
        )),
    }
}

fn reject_terminal_normal_open(path: &Path) -> Result<(), StoreError> {
    let status = Store::inspect_zeroization_state(path)?;
    if status.state.is_terminal() {
        Err(StoreError::StoreZeroized(status.state))
    } else {
        Ok(())
    }
}

fn encode_security_profile_policy_binding(binding: SecurityProfilePolicyBinding) -> Vec<u8> {
    let mut encoded = Vec::with_capacity(SECURITY_PROFILE_POLICY_RECORD_BYTES);
    encoded.extend_from_slice(SECURITY_PROFILE_POLICY_MAGIC);
    encoded.extend_from_slice(binding.mission_authority.as_slice());
    encoded.extend_from_slice(&binding.profile_id.to_be_bytes());
    encoded.extend_from_slice(&binding.policy_generation.to_be_bytes());
    debug_assert_eq!(encoded.len(), SECURITY_PROFILE_POLICY_BODY_BYTES);
    let mut digest = Sha256::new();
    digest.update(SECURITY_PROFILE_POLICY_DIGEST_DOMAIN);
    digest.update(&encoded);
    encoded.extend_from_slice(&digest.finalize());
    debug_assert_eq!(encoded.len(), SECURITY_PROFILE_POLICY_RECORD_BYTES);
    encoded
}

fn decode_security_profile_policy_binding(
    encoded: &[u8],
) -> Result<SecurityProfilePolicyBinding, StoreError> {
    if encoded.len() != SECURITY_PROFILE_POLICY_RECORD_BYTES {
        return Err(StoreError::SecurityProfilePolicyInvariant(
            "binding record has invalid length",
        ));
    }
    if &encoded[..SECURITY_PROFILE_POLICY_MAGIC.len()] != SECURITY_PROFILE_POLICY_MAGIC {
        return Err(StoreError::SecurityProfilePolicyInvariant(
            "binding record has invalid version magic",
        ));
    }
    let mut digest = Sha256::new();
    digest.update(SECURITY_PROFILE_POLICY_DIGEST_DOMAIN);
    digest.update(&encoded[..SECURITY_PROFILE_POLICY_BODY_BYTES]);
    let expected_digest: [u8; 32] = digest.finalize().into();
    if &encoded[SECURITY_PROFILE_POLICY_BODY_BYTES..] != expected_digest.as_slice() {
        return Err(StoreError::SecurityProfilePolicyInvariant(
            "binding record checksum does not match",
        ));
    }
    let authority_start = SECURITY_PROFILE_POLICY_MAGIC.len();
    let authority_end = authority_start + 32;
    let mission_authority = encoded[authority_start..authority_end]
        .try_into()
        .map_err(|_| {
            StoreError::SecurityProfilePolicyInvariant(
                "binding record has invalid mission authority",
            )
        })?;
    let profile_end = authority_end + 2;
    let profile_id = u16::from_be_bytes(encoded[authority_end..profile_end].try_into().map_err(
        |_| {
            StoreError::SecurityProfilePolicyInvariant(
                "binding record has invalid profile identifier",
            )
        },
    )?);
    let policy_generation = u64::from_be_bytes(
        encoded[profile_end..SECURITY_PROFILE_POLICY_BODY_BYTES]
            .try_into()
            .map_err(|_| {
                StoreError::SecurityProfilePolicyInvariant(
                    "binding record has invalid policy generation",
                )
            })?,
    );
    if policy_generation == 0 {
        return Err(StoreError::SecurityProfilePolicyInvariant(
            "binding policy generation must be nonzero",
        ));
    }
    Ok(SecurityProfilePolicyBinding {
        mission_authority,
        profile_id,
        policy_generation,
    })
}

fn validate_security_profile_policy_mission(
    binding: SecurityProfilePolicyBinding,
    mission_authority: Option<NodeId>,
) -> Result<(), StoreError> {
    match mission_authority {
        Some(authority) if authority == binding.mission_authority => Ok(()),
        Some(_) => Err(StoreError::SecurityProfilePolicyInvariant(
            "binding authority differs from the stable mission authority",
        )),
        None => Err(StoreError::SecurityProfilePolicyInvariant(
            "binding exists without a stable mission authority",
        )),
    }
}

fn validate_security_profile_policy_expectation(
    current: SecurityProfilePolicyBinding,
    expected: SecurityProfilePolicyExpectation,
) -> Result<bool, StoreError> {
    if current.mission_authority != expected.binding.mission_authority {
        return Err(StoreError::SecurityProfilePolicyInvariant(
            "binding authority differs from the requested mission authority",
        ));
    }
    if current.profile_id != expected.binding.profile_id {
        return Err(StoreError::SecurityProfileMismatch {
            bound: current.profile_id,
            received: expected.binding.profile_id,
        });
    }
    if expected.binding.policy_generation < current.policy_generation {
        return Err(StoreError::SecurityPolicyGenerationRollback {
            high_water: current.policy_generation,
            received: expected.binding.policy_generation,
        });
    }
    if expected.binding.policy_generation == current.policy_generation {
        return Ok(false);
    }
    match expected.mode {
        SecurityProfilePolicyOpenMode::InitializeOrValidate => {
            Err(StoreError::SecurityPolicyGenerationAdvanceRequired {
                high_water: current.policy_generation,
                received: expected.binding.policy_generation,
            })
        }
        SecurityProfilePolicyOpenMode::BindOrAdvance => Ok(true),
    }
}

fn inspect_security_profile_policy_read(
    read: &redb::ReadTransaction,
    mission_authority: Option<NodeId>,
) -> Result<Option<SecurityProfilePolicyBinding>, StoreError> {
    if read
        .list_multimap_tables()?
        .any(|table| table.name() == SECURITY_PROFILE_POLICY.name())
    {
        return Err(StoreError::SecurityProfilePolicyInvariant(
            "binding table has the wrong table kind",
        ));
    }
    if !read
        .list_tables()?
        .any(|table| table.name() == SECURITY_PROFILE_POLICY.name())
    {
        return Ok(None);
    }
    let table = read.open_table(SECURITY_PROFILE_POLICY)?;
    if table.len()? != 1 {
        return Err(StoreError::SecurityProfilePolicyInvariant(
            "binding table must contain exactly one record",
        ));
    }
    let encoded = table.get(SECURITY_PROFILE_POLICY_KEY)?.ok_or(
        StoreError::SecurityProfilePolicyInvariant("binding table is missing its canonical record"),
    )?;
    let binding = decode_security_profile_policy_binding(encoded.value())?;
    validate_security_profile_policy_mission(binding, mission_authority)?;
    Ok(Some(binding))
}

fn inspect_security_profile_policy_write(
    write: &redb::WriteTransaction,
    mission_authority: Option<NodeId>,
) -> Result<Option<SecurityProfilePolicyBinding>, StoreError> {
    if write
        .list_multimap_tables()?
        .any(|table| table.name() == SECURITY_PROFILE_POLICY.name())
    {
        return Err(StoreError::SecurityProfilePolicyInvariant(
            "binding table has the wrong table kind",
        ));
    }
    if !write
        .list_tables()?
        .any(|table| table.name() == SECURITY_PROFILE_POLICY.name())
    {
        return Ok(None);
    }
    let table = write.open_table(SECURITY_PROFILE_POLICY)?;
    if table.len()? != 1 {
        return Err(StoreError::SecurityProfilePolicyInvariant(
            "binding table must contain exactly one record",
        ));
    }
    let encoded = table.get(SECURITY_PROFILE_POLICY_KEY)?.ok_or(
        StoreError::SecurityProfilePolicyInvariant("binding table is missing its canonical record"),
    )?;
    let binding = decode_security_profile_policy_binding(encoded.value())?;
    validate_security_profile_policy_mission(binding, mission_authority)?;
    Ok(Some(binding))
}

fn inspect_security_profile_policy_read_only(
    path: &Path,
) -> Result<Option<SecurityProfilePolicyBinding>, StoreError> {
    let database = redb::Builder::new().open_read_only(path)?;
    let read = database.begin_read()?;
    let mission_authority = if read
        .list_tables()?
        .any(|table| table.name() == SEMANTIC_DOMAIN.name())
    {
        let domain = read.open_table(SEMANTIC_DOMAIN)?;
        domain
            .get(MISSION_AUTHORITY_ID)?
            .map(|value| parse_node_id("semantic mission authority", value.value()))
            .transpose()?
    } else {
        None
    };
    inspect_security_profile_policy_read(&read, mission_authority)
}

fn bind_security_profile_policy_write(
    write: &redb::WriteTransaction,
    expected: SecurityProfilePolicyExpectation,
) -> Result<(), StoreError> {
    let mission_authority = read_mission_binding(write)?;
    let current = inspect_security_profile_policy_write(write, mission_authority)?;
    match current {
        Some(current) => {
            if validate_security_profile_policy_expectation(current, expected)? {
                let encoded = encode_security_profile_policy_binding(expected.binding);
                write
                    .open_table(SECURITY_PROFILE_POLICY)?
                    .insert(SECURITY_PROFILE_POLICY_KEY, encoded.as_slice())?;
            }
        }
        None => {
            if let Some(authority) = mission_authority
                && authority != expected.binding.mission_authority
            {
                return Err(StoreError::MissionAuthorityMismatch {
                    bound: authority,
                    received: expected.binding.mission_authority,
                });
            }
            let encoded = encode_security_profile_policy_binding(expected.binding);
            write
                .open_table(SECURITY_PROFILE_POLICY)?
                .insert(SECURITY_PROFILE_POLICY_KEY, encoded.as_slice())?;
        }
    }
    Ok(())
}

fn inspect_mission_binding_read_only(path: &Path) -> Result<Option<NodeId>, StoreError> {
    let database = redb::Builder::new().open_read_only(path)?;
    let read = database.begin_read()?;
    let table_names = read
        .list_tables()?
        .map(|table| table.name().to_owned())
        .collect::<std::collections::BTreeSet<_>>();
    let binding = if table_names.contains(SEMANTIC_DOMAIN.name()) {
        let domain = read.open_table(SEMANTIC_DOMAIN)?;
        domain
            .get(MISSION_AUTHORITY_ID)?
            .map(|value| parse_node_id("semantic mission authority", value.value()))
            .transpose()?
    } else {
        None
    };
    if binding.is_none() {
        if table_names.contains(EVENT_OPERATIONS.name())
            && read.open_table(EVENT_OPERATIONS)?.len()? != 0
        {
            return Err(StoreError::EventOperationMigrationMissingMissionBinding);
        }
        let semantic_rows = if table_names.contains(EVENTS.name()) {
            read.open_table(EVENTS)?.len()?
        } else {
            0
        };
        let state_rows = if table_names.contains(STATES.name()) {
            read.open_table(STATES)?.len()?
        } else {
            0
        };
        let record_rows = if table_names.contains(RECORDS.name()) {
            read.open_table(RECORDS)?.len()?
        } else {
            0
        };
        let blob_publication_rows = if table_names.contains(blob::BLOB_PUBLICATIONS.name()) {
            read.open_table(blob::BLOB_PUBLICATIONS)?.len()?
        } else {
            0
        };
        let blob_import_rows = if table_names.contains(blob::BLOB_IMPORTS.name()) {
            read.open_table(blob::BLOB_IMPORTS)?.len()?
        } else {
            0
        };
        let blob_chunk_rows = if table_names.contains(blob::BLOB_CHUNKS.name()) {
            read.open_table(blob::BLOB_CHUNKS)?.len()?
        } else {
            0
        };
        let cached_rows = if table_names.contains(ROUTE_CACHE.name()) {
            read.open_table(ROUTE_CACHE)?.len()?
        } else {
            0
        };
        let control_rows = if table_names.contains(CONTROL_RECORDS.name()) {
            read.open_table(CONTROL_RECORDS)?.len()?
        } else {
            0
        };
        let cursor_rows = if table_names.contains(MUTABLE_TRANSFER_CURSORS.name()) {
            read.open_table(MUTABLE_TRANSFER_CURSORS)?.len()?
        } else {
            0
        };
        if semantic_rows != 0
            || state_rows != 0
            || record_rows != 0
            || blob_publication_rows != 0
            || blob_import_rows != 0
            || blob_chunk_rows != 0
            || cached_rows != 0
            || control_rows != 0
            || cursor_rows != 0
        {
            return Err(StoreError::SemanticInvariant(
                "unbound store contains mission-scoped Event, State, Record, Blob, or control state",
            ));
        }
    }
    Ok(binding)
}

fn inspect_control_state_read_only(path: &Path) -> Result<(), StoreError> {
    let database = redb::Builder::new().open_read_only(path)?;
    let read = database.begin_read()?;
    let table_names = read
        .list_tables()?
        .map(|table| table.name().to_owned())
        .collect::<std::collections::BTreeSet<_>>();
    let mission_authority = if table_names.contains(SEMANTIC_DOMAIN.name()) {
        let domain = read.open_table(SEMANTIC_DOMAIN)?;
        domain
            .get(MISSION_AUTHORITY_ID)?
            .map(|value| parse_node_id("semantic mission authority", value.value()))
            .transpose()?
    } else {
        None
    };
    inspect_control_tables(&read, mission_authority)?;
    Ok(())
}

fn check_expected_mission_binding(
    write: &redb::WriteTransaction,
    expected: NodeId,
) -> Result<(), StoreError> {
    if write
        .list_multimap_tables()?
        .any(|table| table.name() == SEMANTIC_DOMAIN.name())
    {
        return Err(StoreError::SemanticInvariant(
            "semantic mission domain has the wrong table kind",
        ));
    }
    let domain_exists = write
        .list_tables()?
        .any(|table| table.name() == SEMANTIC_DOMAIN.name());
    let bound = if domain_exists {
        let domain = write.open_table(SEMANTIC_DOMAIN)?;
        domain
            .get(MISSION_AUTHORITY_ID)?
            .map(|value| parse_node_id("semantic mission authority", value.value()))
            .transpose()?
    } else {
        None
    };
    match bound {
        Some(bound) if bound != expected => Err(StoreError::MissionAuthorityMismatch {
            bound,
            received: expected,
        }),
        Some(_) | None => Ok(()),
    }
}

