fn control_recipient_metadata_backfill_count_read(
    read: &redb::ReadTransaction,
) -> Result<u64, StoreError> {
    let records = read.open_table(CONTROL_RECORDS)?;
    let mut remaining = 0u64;
    for row in records.iter()? {
        let (_, encoded) = row?;
        if !decode_control_record(encoded.value())?.scope_rekey_recipient_metadata_authenticated {
            remaining = remaining
                .checked_add(1)
                .ok_or(StoreError::ItemCountAccountingOverflow)?;
        }
    }
    Ok(remaining)
}

fn control_recipient_metadata_backfill_count_write(
    write: &redb::WriteTransaction,
) -> Result<u64, StoreError> {
    let records = write.open_table(CONTROL_RECORDS)?;
    let mut remaining = 0u64;
    for row in records.iter()? {
        let (_, encoded) = row?;
        if !decode_control_record(encoded.value())?.scope_rekey_recipient_metadata_authenticated {
            remaining = remaining
                .checked_add(1)
                .ok_or(StoreError::ItemCountAccountingOverflow)?;
        }
    }
    Ok(remaining)
}

fn control_recipient_metadata_migration_error_read(
    read: &redb::ReadTransaction,
) -> Result<StoreError, StoreError> {
    let remaining = control_recipient_metadata_backfill_count_read(read)?;
    if remaining == 0 {
        return Err(StoreError::ControlInvariant(
            "legacy recipient metadata marker was not counted",
        ));
    }
    Ok(StoreError::ControlRecipientMetadataMigrationRequired { remaining })
}

fn ensure_control_recipient_metadata_current_read(
    read: &redb::ReadTransaction,
) -> Result<(), StoreError> {
    let remaining = control_recipient_metadata_backfill_count_read(read)?;
    if remaining != 0 {
        return Err(StoreError::ControlRecipientMetadataMigrationRequired { remaining });
    }
    Ok(())
}

fn ensure_control_recipient_metadata_current_write(
    write: &redb::WriteTransaction,
) -> Result<(), StoreError> {
    let remaining = control_recipient_metadata_backfill_count_write(write)?;
    if remaining != 0 {
        return Err(StoreError::ControlRecipientMetadataMigrationRequired { remaining });
    }
    Ok(())
}

fn first_revoked_scope_rekey_recipient_write(
    write: &redb::WriteTransaction,
    recipients: Option<&[NodeId]>,
) -> Result<Option<NodeId>, StoreError> {
    let Some(recipients) = recipients else {
        return Ok(None);
    };
    for recipient in recipients {
        if control_principal_revoked_write(write, *recipient)? {
            return Ok(Some(*recipient));
        }
    }
    Ok(None)
}

struct MetadataCursor<'a> {
    bytes: &'a [u8],
    position: usize,
}

impl<'a> MetadataCursor<'a> {
    const fn new(bytes: &'a [u8]) -> Self {
        Self { bytes, position: 0 }
    }

    const fn remaining(&self) -> usize {
        self.bytes.len().saturating_sub(self.position)
    }

    fn take(&mut self, length: usize) -> Result<&'a [u8], StoreError> {
        let end = self
            .position
            .checked_add(length)
            .ok_or(StoreError::SemanticInvariant(
                "Event metadata length overflow",
            ))?;
        let value = self
            .bytes
            .get(self.position..end)
            .ok_or(StoreError::SemanticInvariant("truncated Event metadata"))?;
        self.position = end;
        Ok(value)
    }

    fn u8(&mut self) -> Result<u8, StoreError> {
        Ok(self.take(1)?[0])
    }

    fn u16(&mut self) -> Result<u16, StoreError> {
        Ok(u16::from_be_bytes(self.take(2)?.try_into().map_err(
            |_| StoreError::SemanticInvariant("invalid Event metadata u16"),
        )?))
    }

    fn u32(&mut self) -> Result<u32, StoreError> {
        Ok(u32::from_be_bytes(self.take(4)?.try_into().map_err(
            |_| StoreError::SemanticInvariant("invalid Event metadata u32"),
        )?))
    }

    fn u64(&mut self) -> Result<u64, StoreError> {
        Ok(u64::from_be_bytes(self.take(8)?.try_into().map_err(
            |_| StoreError::SemanticInvariant("invalid Event metadata u64"),
        )?))
    }

    fn array<const N: usize>(&mut self) -> Result<[u8; N], StoreError> {
        self.take(N)?
            .try_into()
            .map_err(|_| StoreError::SemanticInvariant("invalid Event metadata array"))
    }

    fn short_string(&mut self) -> Result<String, StoreError> {
        let length = usize::from(self.u16()?);
        String::from_utf8(self.take(length)?.to_vec())
            .map_err(|_| StoreError::SemanticInvariant("Event metadata name is not UTF-8"))
    }

    fn finish(self) -> Result<(), StoreError> {
        if self.position != self.bytes.len() {
            return Err(StoreError::SemanticInvariant(
                "Event metadata contains trailing bytes",
            ));
        }
        Ok(())
    }
}

fn parse_transfer_id(table: &'static str, bytes: &[u8]) -> Result<EventTransferId, StoreError> {
    let bytes: [u8; 32] = bytes
        .try_into()
        .map_err(|_| StoreError::InvalidStoredIdLength {
            table,
            length: bytes.len(),
        })?;
    Ok(EventTransferId::new(bytes))
}

