    #[test]
    fn wrong_security_profile_reopen_is_read_only_and_exact() {
        let file = TestFile::new("security-profile-policy-wrong-profile");
        let authority = [0xb1; 32];
        let store =
            Store::open_for_mission_with_security_profile_policy(&file.0, authority, 0x0002, 11)
                .expect("initial policy bind");
        let binding = store
            .security_profile_policy_binding()
            .expect("binding read")
            .expect("binding present");
        assert_eq!(binding.mission_authority(), authority);
        assert_eq!(binding.profile_id(), 0x0002);
        assert_eq!(binding.policy_generation(), 11);
        drop(store);

        let bytes_before = std::fs::read(&file.0).expect("bound store bytes");
        assert!(matches!(
            Store::open_for_mission_with_security_profile_policy(&file.0, authority, 0x0003, 11,),
            Err(StoreError::SecurityProfileMismatch {
                bound: 0x0002,
                received: 0x0003,
            })
        ));
        assert_eq!(
            std::fs::read(&file.0).expect("bytes after ordinary wrong-profile reopen"),
            bytes_before
        );

        assert!(matches!(
            Store::open_for_mission_and_bind_security_profile_policy(
                &file.0, authority, 0x0003, 12,
            ),
            Err(StoreError::SecurityProfileMismatch {
                bound: 0x0002,
                received: 0x0003,
            })
        ));
        assert_eq!(
            std::fs::read(&file.0).expect("bytes after explicit wrong-profile bind"),
            bytes_before
        );

        let reopened =
            Store::open_for_mission_with_security_profile_policy(&file.0, authority, 0x0002, 11)
                .expect("exact policy reopen");
        assert_eq!(
            reopened
                .security_profile_policy_binding()
                .expect("reopened binding"),
            Some(binding)
        );
    }

    #[test]
    fn security_policy_generation_high_water_advances_only_through_explicit_bind() {
        let file = TestFile::new("security-profile-policy-generation");
        let authority = [0xc1; 32];
        let initial =
            Store::open_for_mission_with_security_profile_policy(&file.0, authority, 0x0002, 21)
                .expect("initial policy bind");
        drop(initial);

        let same =
            Store::open_for_mission_with_security_profile_policy(&file.0, authority, 0x0002, 21)
                .expect("same-generation reopen");
        drop(same);

        let bytes_before_advance = std::fs::read(&file.0).expect("pre-advance store bytes");
        assert!(matches!(
            Store::open_for_mission_with_security_profile_policy(&file.0, authority, 0x0002, 22,),
            Err(StoreError::SecurityPolicyGenerationAdvanceRequired {
                high_water: 21,
                received: 22,
            })
        ));
        assert_eq!(
            std::fs::read(&file.0).expect("bytes after implicit advance rejection"),
            bytes_before_advance
        );

        let advanced = Store::open_for_mission_and_bind_security_profile_policy(
            &file.0, authority, 0x0002, 22,
        )
        .expect("explicit policy advance");
        assert_eq!(
            advanced
                .security_profile_policy_binding()
                .expect("advanced binding")
                .expect("advanced binding present")
                .policy_generation(),
            22
        );
        drop(advanced);

        let same_explicit = Store::open_for_mission_and_bind_security_profile_policy(
            &file.0, authority, 0x0002, 22,
        )
        .expect("same explicit bind is idempotent");
        drop(same_explicit);

        let bytes_before_rollback = std::fs::read(&file.0).expect("pre-rollback store bytes");
        assert!(matches!(
            Store::open_for_mission_with_security_profile_policy(&file.0, authority, 0x0002, 21,),
            Err(StoreError::SecurityPolicyGenerationRollback {
                high_water: 22,
                received: 21,
            })
        ));
        assert_eq!(
            std::fs::read(&file.0).expect("bytes after ordinary rollback rejection"),
            bytes_before_rollback
        );
        assert!(matches!(
            Store::open_for_mission_and_bind_security_profile_policy(
                &file.0, authority, 0x0002, 20,
            ),
            Err(StoreError::SecurityPolicyGenerationRollback {
                high_water: 22,
                received: 20,
            })
        ));
        assert_eq!(
            std::fs::read(&file.0).expect("bytes after explicit rollback rejection"),
            bytes_before_rollback
        );
    }

    #[test]
    fn semantic_and_transfer_identity_are_distinct_and_opaque_collision_cannot_poison_acceptance() {
        let file = TestFile::new("semantic-transfer");
        let mut services = event_services(0x41);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let payload = b"same semantic Event";
        let header = event_header(
            services.publisher.identity(),
            1,
            1,
            VersionVector::default(),
            b"same",
            payload,
            None,
        );
        let first = services
            .publisher
            .seal_event(&header, payload)
            .expect("first seal");
        let second = services
            .publisher
            .seal_event(&header, payload)
            .expect("second randomized seal");
        assert_eq!(first.id, second.id);
        assert_ne!(
            <[u8; 32]>::from(Sha256::digest(&first.bytes)),
            <[u8; 32]>::from(Sha256::digest(&second.bytes))
        );
        let first_content = content_event(&mut services.reader, &first.bytes);
        let second_content = content_event(&mut services.reader, &second.bytes);
        let first_transfer = EventTransferId::new(first_content.envelope_id());

        store
            .apply(first_transfer.reconciliation_item_id(), b"opaque collision")
            .expect("legacy opaque collision is isolated");
        assert!(matches!(
            store
                .apply_verified_event(&first_content, &first.bytes)
                .expect("semantic acceptance"),
            ApplyOutcome::Inserted {
                acceptance_marker: 1
            }
        ));
        let accepted_route = services
            .relay
            .verify_event(&first.bytes)
            .expect("route replay of accepted Event");
        assert!(matches!(
            store
                .cache_route_verified_event(&accepted_route, &first.bytes)
                .expect("accepted exact transfer is a cache no-op"),
            RouteCacheOutcome::Duplicate { .. }
        ));
        assert_eq!(store.event_stats().expect("separate stats").route_cached, 0);
        assert_eq!(
            store
                .transfer_inventory()
                .expect("disjoint inventory")
                .len(),
            1
        );
        let alternate_route = services
            .relay
            .verify_event(&second.bytes)
            .expect("alternate route representation");
        assert!(matches!(
            store.cache_route_verified_event(&alternate_route, &second.bytes),
            Err(StoreError::SemanticRepresentationConflict { .. })
        ));
        assert!(matches!(
            store
                .apply_verified_event(&first_content, &first.bytes)
                .expect("exact replay"),
            ApplyOutcome::Duplicate {
                acceptance_marker: 1
            }
        ));
        assert!(matches!(
            store.apply_verified_event(&second_content, &second.bytes),
            Err(StoreError::SemanticRepresentationConflict { .. })
        ));
        assert_eq!(
            store
                .get(first_transfer.reconciliation_item_id())
                .expect("legacy read"),
            Some(b"opaque collision".to_vec())
        );
        assert_eq!(
            store
                .get_event(first_transfer)
                .expect("semantic read")
                .expect("semantic Event")
                .sealed,
            first.bytes
        );
        assert_eq!(store.inventory().expect("legacy inventory").len(), 1);
        assert_eq!(store.event_inventory().expect("Event inventory").len(), 1);
        assert_eq!(store.stats().expect("legacy stats").items, 1);
        assert_eq!(store.event_stats().expect("Event stats").events, 1);
    }

    #[test]
    fn event_subscription_identity_snapshot_modes_and_quota_are_stable() {
        let vector_key = EventSubscriptionKey::new(b"app/feed".to_vec()).expect("vector key");
        assert_eq!(
            event_subscription_id([0x11; 32], &vector_key).as_bytes(),
            &[
                0xfa, 0x5c, 0xbe, 0x02, 0x70, 0xc7, 0x6d, 0xdc, 0x00, 0x24, 0x5b, 0x72, 0x21, 0x50,
                0x76, 0x46, 0x30, 0xe1, 0x24, 0xd9, 0xb1, 0x7a, 0xfd, 0xe3, 0xed, 0x71, 0xfa, 0xee,
                0xe1, 0xf5, 0xbf, 0x29,
            ],
            "domain-separated subscription identity is a frozen durable vector"
        );
        assert!(matches!(
            EventSubscriptionKey::new(Vec::new()),
            Err(StoreError::InvalidEventSubscriptionKey { length: 0 })
        ));
        assert!(matches!(
            EventSubscriptionKey::new(vec![0; MAX_EVENT_SUBSCRIPTION_KEY_BYTES + 1]),
            Err(StoreError::InvalidEventSubscriptionKey { .. })
        ));
        assert_eq!(
            next_event_acknowledgement_count(MAX_EVENT_ACKNOWLEDGEMENT_RECEIPTS - 1)
                .expect("last bounded acknowledgement receipt"),
            MAX_EVENT_ACKNOWLEDGEMENT_RECEIPTS
        );
        assert!(matches!(
            next_event_acknowledgement_count(MAX_EVENT_ACKNOWLEDGEMENT_RECEIPTS),
            Err(StoreError::EventAcknowledgementReceiptLimitExceeded {
                current: MAX_EVENT_ACKNOWLEDGEMENT_RECEIPTS,
                limit: MAX_EVENT_ACKNOWLEDGEMENT_RECEIPTS,
            })
        ));

        let file = TestFile::new("event-subscription-snapshot");
        let services = event_services(0x45);
        let store =
            Store::open_for_mission(&file.0, services.authority).expect("subscription store");
        let policy = store.control_policy_snapshot().expect("settled policy");
        let empty = store
            .event_replication_policy_snapshot()
            .expect("empty receive intent");
        assert!(empty.selectors().is_empty(), "empty means receive-none");
        assert_eq!(empty.selector_revision(), 0);

        let carry_key = EventSubscriptionKey::new(b"relay/carry".to_vec()).expect("carry key");
        let carry = subscription_spec(EventSubscriptionMode::Carry);
        let carry_created = store
            .create_event_subscription_with_policy(&policy, &carry_key, carry.clone())
            .expect("create Carry selector");
        assert!(carry_created.inserted);
        assert_eq!(
            store
                .create_event_subscription_with_policy(&policy, &carry_key, carry.clone())
                .expect("exact retry"),
            EventSubscriptionCreateOutcome {
                id: carry_created.id,
                inserted: false,
            }
        );
        assert!(matches!(
            store.create_event_subscription_with_policy(
                &policy,
                &carry_key,
                subscription_spec(EventSubscriptionMode::Consume),
            ),
            Err(StoreError::EventSubscriptionConflict)
        ));
        assert!(matches!(
            store.prepare_event_subscription_poll_with_policy(&policy, carry_created.id, 1, 1),
            Err(StoreError::EventSubscriptionNotConsumable)
        ));
        let carry_snapshot = store
            .event_replication_policy_snapshot()
            .expect("Carry projection");
        assert_eq!(carry_snapshot.selector_revision(), 1);
        assert_eq!(
            carry_snapshot.selectors()[0].mode(),
            EventSubscriptionMode::Carry
        );
        assert_eq!(
            carry_snapshot.effective_mode(&event_topic(), &event_scope()),
            Some(EventSubscriptionMode::Carry)
        );

        let consume_key =
            EventSubscriptionKey::new(b"application/consume".to_vec()).expect("consume key");
        let consume_created = store
            .create_event_subscription_with_policy(
                &policy,
                &consume_key,
                subscription_spec(EventSubscriptionMode::Consume),
            )
            .expect("same projected selector in Consume mode");
        let snapshot = store
            .event_replication_policy_snapshot()
            .expect("canonical projection");
        assert!(matches!(
            store.require_event_replication_policy(&carry_snapshot),
            Err(StoreError::EventSelectorRevisionChanged)
        ));
        assert_eq!(snapshot.selectors().len(), 1);
        assert_eq!(
            snapshot.selectors()[0].mode(),
            EventSubscriptionMode::Consume
        );
        assert_eq!(snapshot.selector_revision(), 2);
        assert_eq!(
            snapshot.effective_mode(&event_topic(), &event_scope()),
            Some(EventSubscriptionMode::Consume),
            "Consume dominates an identical Carry projection"
        );
        assert_eq!(
            store.event_subscription_stats().expect("audited stats"),
            EventSubscriptionStats {
                subscriptions: 2,
                pending_deliveries: 0,
                acknowledged_deliveries: 0,
                selector_revision: 2,
            }
        );

        let mut child_carry = subscription_spec(EventSubscriptionMode::Carry);
        child_carry.scope = child_event_scope();
        store
            .create_event_subscription_with_policy(
                &policy,
                &EventSubscriptionKey::new(b"relay/child".to_vec()).expect("child key"),
                child_carry,
            )
            .expect("child Carry selector");
        let mut descendant_consume = subscription_spec(EventSubscriptionMode::Consume);
        descendant_consume.include_descendant_scopes = true;
        store
            .create_event_subscription_with_policy(
                &policy,
                &EventSubscriptionKey::new(b"application/descendants".to_vec())
                    .expect("descendant key"),
                descendant_consume,
            )
            .expect("descendant Consume selector");
        let overlapping = store
            .event_replication_policy_snapshot()
            .expect("overlapping effective modes");
        assert_eq!(overlapping.selector_revision(), 4);
        assert_eq!(overlapping.selectors().len(), 3);
        assert_eq!(
            overlapping.effective_mode(&event_topic(), &child_event_scope()),
            Some(EventSubscriptionMode::Consume),
            "Consume dominates a distinct overlapping Carry selector"
        );
        assert_eq!(
            overlapping.effective_mode(&reaction_topic(), &child_event_scope()),
            None,
            "unselected topics remain receive-none"
        );
        for requested in [0, MAX_EVENT_POLL_DELIVERIES + 1] {
            assert!(matches!(
                store.prepare_event_subscription_poll_with_policy(
                    &policy,
                    consume_created.id,
                    requested,
                    1,
                ),
                Err(StoreError::EventSubscriptionPollLimitExceeded { .. })
            ));
        }

        for index in 4..MAX_EVENT_SUBSCRIPTIONS {
            let key = EventSubscriptionKey::new(format!("duplicate/{index}").into_bytes())
                .expect("bounded quota key");
            store
                .create_event_subscription_with_policy(&policy, &key, carry.clone())
                .expect("fill subscription quota");
        }
        let overflow_key =
            EventSubscriptionKey::new(b"quota/overflow".to_vec()).expect("overflow key");
        assert!(matches!(
            store.create_event_subscription_with_policy(&policy, &overflow_key, carry),
            Err(StoreError::EventSubscriptionLimitExceeded {
                current: MAX_EVENT_SUBSCRIPTIONS,
                limit: MAX_EVENT_SUBSCRIPTIONS,
            })
        ));
        let bounded = store
            .event_replication_policy_snapshot()
            .expect("bounded projection");
        assert_eq!(bounded.selectors().len(), 3);
        assert_eq!(bounded.selector_revision(), MAX_EVENT_SUBSCRIPTIONS);
    }

    #[test]
    fn event_unsubscribe_purges_delivery_state_and_preserves_mutation_generation() {
        let file = TestFile::new("event-subscription-remove");
        let mut services = event_services(0x5a);
        let carry_key = EventSubscriptionKey::new(b"relay/remove-carry".to_vec()).expect("key");
        let consume_key =
            EventSubscriptionKey::new(b"application/remove-consume".to_vec()).expect("key");
        let consume_id;
        let carry_id;
        {
            let store =
                Store::open_for_mission(&file.0, services.authority).expect("bound remove store");
            let policy = store.control_policy_snapshot().expect("remove policy");
            carry_id = store
                .create_event_subscription_with_policy(
                    &policy,
                    &carry_key,
                    subscription_spec(EventSubscriptionMode::Carry),
                )
                .expect("create overlapping Carry")
                .id;
            consume_id = store
                .create_event_subscription_with_policy(
                    &policy,
                    &consume_key,
                    subscription_spec(EventSubscriptionMode::Consume),
                )
                .expect("create overlapping Consume")
                .id;
            let publisher = services.publisher.identity();
            let mut accepted = Vec::new();
            for sequence in 1..=2 {
                let payload = format!("unsubscribe delivery {sequence}").into_bytes();
                accepted.push(accept_event(
                    &store,
                    &mut services,
                    event_header(
                        publisher,
                        sequence,
                        sequence,
                        VersionVector::default(),
                        &[sequence as u8],
                        &payload,
                        None,
                    ),
                    &payload,
                ));
            }
            let plan = store
                .prepare_event_subscription_poll_with_policy(&policy, consume_id, 2, 2)
                .expect("prepare two deliveries");
            let selection = verify_subscription_plan(&mut services.reader, &plan);
            store
                .commit_event_subscription_poll_with_policy(&policy, &plan, &selection)
                .expect("commit two pending deliveries");
            assert_eq!(
                store
                    .acknowledge_event_delivery_with_policy(
                        &policy,
                        consume_id,
                        accepted[0].semantic_id,
                    )
                    .expect("acknowledge first delivery"),
                EventDeliveryAck::Acknowledged
            );
            assert_eq!(
                store.event_subscription_stats().expect("before remove"),
                EventSubscriptionStats {
                    subscriptions: 2,
                    pending_deliveries: 1,
                    acknowledged_deliveries: 1,
                    selector_revision: 2,
                }
            );
            let consume_snapshot = store
                .event_replication_policy_snapshot()
                .expect("overlapping Consume snapshot");
            assert_eq!(consume_snapshot.selector_generation(), 2);
            assert_eq!(
                store
                    .remove_event_subscription_with_policy(&policy, consume_id)
                    .expect("remove Consume selector"),
                EventSubscriptionRemoveOutcome {
                    id: consume_id,
                    removed: true,
                }
            );
            assert!(matches!(
                store.require_event_replication_policy(&consume_snapshot),
                Err(StoreError::EventSelectorRevisionChanged)
            ));
            let carry_snapshot = store
                .event_replication_policy_snapshot()
                .expect("Carry revealed after removal");
            assert_eq!(carry_snapshot.selector_generation(), 3);
            assert_eq!(carry_snapshot.selectors().len(), 1);
            assert_eq!(
                carry_snapshot.effective_mode(&event_topic(), &event_scope()),
                Some(EventSubscriptionMode::Carry),
                "removing overlapping Consume must reveal surviving Carry intent"
            );
            assert_eq!(
                store.event_subscription_stats().expect("purged ledgers"),
                EventSubscriptionStats {
                    subscriptions: 1,
                    pending_deliveries: 0,
                    acknowledged_deliveries: 0,
                    selector_revision: 3,
                }
            );
        }

        let store = Store::open_for_mission(&file.0, services.authority)
            .expect("non-count selector generation audits after reopen");
        let policy = store.control_policy_snapshot().expect("reopen policy");
        assert_eq!(
            store
                .remove_event_subscription_with_policy(&policy, consume_id)
                .expect("idempotent remove retry"),
            EventSubscriptionRemoveOutcome {
                id: consume_id,
                removed: false,
            }
        );
        assert_eq!(
            store
                .event_replication_policy_snapshot()
                .expect("retry snapshot")
                .selector_generation(),
            3,
            "an idempotent missing retry must not advance generation"
        );
        let recreated = store
            .create_event_subscription_with_policy(
                &policy,
                &consume_key,
                subscription_spec(EventSubscriptionMode::Consume),
            )
            .expect("recreate exact subscription identity");
        assert_eq!(recreated.id, consume_id);
        assert!(recreated.inserted);
        assert_eq!(
            store
                .event_replication_policy_snapshot()
                .expect("recreated snapshot")
                .selector_generation(),
            4
        );
        store
            .remove_event_subscription_with_policy(&policy, carry_id)
            .expect("remove overlapping Carry");
        let last_consume = store
            .event_replication_policy_snapshot()
            .expect("only Consume remains");
        assert_eq!(last_consume.selector_generation(), 5);
        assert_eq!(last_consume.selectors().len(), 1);
        store
            .remove_event_subscription_with_policy(&policy, consume_id)
            .expect("remove final selector");
        let receive_none = store
            .event_replication_policy_snapshot()
            .expect("last removal becomes receive-none");
        assert_eq!(receive_none.selector_generation(), 6);
        assert!(receive_none.selectors().is_empty());
        assert_eq!(
            receive_none.effective_mode(&event_topic(), &event_scope()),
            None
        );
        assert!(matches!(
            store.require_event_replication_policy(&last_consume),
            Err(StoreError::EventSelectorRevisionChanged)
        ));
        assert_eq!(
            store
                .event_subscription_stats()
                .expect("final remove stats"),
            EventSubscriptionStats {
                subscriptions: 0,
                pending_deliveries: 0,
                acknowledged_deliveries: 0,
                selector_revision: 6,
            }
        );
    }

    #[test]
    fn replication_snapshot_checks_full_projection_and_generation_corruption() {
        let file = TestFile::new("event-selector-projection-corruption");
        let services = event_services(0x5b);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let policy = store.control_policy_snapshot().expect("settled policy");
        let created = store
            .create_event_subscription_with_policy(
                &policy,
                &EventSubscriptionKey::new(b"projection/carry".to_vec()).expect("key"),
                subscription_spec(EventSubscriptionMode::Carry),
            )
            .expect("create selector");
        let snapshot = store
            .event_replication_policy_snapshot()
            .expect("original projection");
        {
            let write = store
                .database
                .begin_write()
                .expect("begin projection mutation");
            let mut subscriptions = write
                .open_table(EVENT_SUBSCRIPTIONS)
                .expect("subscription table");
            let encoded = subscriptions
                .get(created.id.as_bytes().as_slice())
                .expect("read subscription")
                .expect("subscription row")
                .value()
                .to_vec();
            let mut record = decode_event_subscription_record(&encoded).expect("decode row");
            record.spec.include_descendant_scopes = true;
            let changed = encode_event_subscription_record(&record).expect("encode changed row");
            subscriptions
                .insert(created.id.as_bytes().as_slice(), changed.as_slice())
                .expect("mutate projection without generation");
            drop(subscriptions);
            write.commit().expect("commit projection mutation");
        }
        assert!(matches!(
            store.require_event_replication_policy(&snapshot),
            Err(StoreError::EventSelectorRevisionChanged)
        ));
        {
            let write = store
                .database
                .begin_write()
                .expect("begin generation corruption");
            write
                .open_table(METADATA)
                .expect("metadata")
                .insert(EVENT_SELECTOR_REVISION, 2)
                .expect("write impossible generation parity");
            write.commit().expect("commit generation corruption");
        }
        assert!(matches!(
            store.event_subscription_stats(),
            Err(StoreError::SemanticInvariant(
                "Event selector mutation generation is inconsistent with the live subscription count"
            ))
        ));
        drop(store);
        for result in [
            Store::inspect_existing(&file.0).map(|_| ()),
            Store::open_for_mission(&file.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::SemanticInvariant(
                    "Event selector mutation generation is inconsistent with the live subscription count"
                ))
            ));
        }
    }

    #[test]
    fn replication_snapshot_atomically_guards_route_cache_admission() {
        let file = TestFile::new("replication-route-admission");
        let mut services = event_services(0x4c);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let policy = store.control_policy_snapshot().expect("settled policy");
        let receive_none = store
            .event_replication_policy_snapshot()
            .expect("empty receive intent");

        let first_payload = b"Carry-selected route representation";
        let first_header = event_header(
            services.publisher.identity(),
            1,
            1,
            VersionVector::default(),
            b"route-first",
            first_payload,
            None,
        );
        let first = services
            .publisher
            .seal_event(&first_header, first_payload)
            .expect("seal first route Event");
        let first_route = services
            .relay
            .verify_event(&first.bytes)
            .expect("verify first route Event");
        assert!(matches!(
            store.cache_route_verified_event_with_replication_policy(
                &receive_none,
                &first_route,
                &first.bytes,
            ),
            Err(StoreError::EventReplicationNotSelected)
        ));
        assert_eq!(
            store.event_stats().expect("receive-none stats"),
            EventStoreStats::default()
        );

        store
            .create_event_subscription_with_policy(
                &policy,
                &EventSubscriptionKey::new(b"relay/carry-atomic".to_vec()).expect("Carry key"),
                subscription_spec(EventSubscriptionMode::Carry),
            )
            .expect("create Carry selector");
        let stale_carry = store
            .event_replication_policy_snapshot()
            .expect("Carry snapshot");
        assert!(matches!(
            store.cache_route_verified_event_with_replication_policy(
                &stale_carry,
                &first_route,
                &first.bytes,
            ),
            Ok(RouteCacheOutcome::Inserted { .. })
        ));

        store
            .create_event_subscription_with_policy(
                &policy,
                &EventSubscriptionKey::new(b"application/consume-atomic".to_vec())
                    .expect("Consume key"),
                subscription_spec(EventSubscriptionMode::Consume),
            )
            .expect("insert overlapping Consume selector");
        let before_stale_attempt = store.event_stats().expect("pre-attempt stats");

        let second_payload = b"must not enter cache under stale mode";
        let second_header = event_header(
            services.publisher.identity(),
            2,
            2,
            VersionVector::default(),
            b"route-second",
            second_payload,
            None,
        );
        let second = services
            .publisher
            .seal_event(&second_header, second_payload)
            .expect("seal second route Event");
        let second_route = services
            .relay
            .verify_event(&second.bytes)
            .expect("verify second route Event");
        let second_transfer = EventTransferId::new(second_route.envelope_id());
        assert!(matches!(
            store.cache_route_verified_event_with_replication_policy(
                &stale_carry,
                &second_route,
                &second.bytes,
            ),
            Err(StoreError::EventSelectorRevisionChanged)
        ));
        assert_eq!(
            store.event_stats().expect("post-attempt stats"),
            before_stale_attempt,
            "a stale replication snapshot cannot mutate route-cache accounting"
        );
        assert!(
            store
                .get_route_cached_event(second_transfer)
                .expect("read rejected transfer")
                .is_none(),
            "a stale replication snapshot cannot insert route bytes or claims"
        );

        let current = store
            .event_replication_policy_snapshot()
            .expect("current Consume snapshot");
        assert!(matches!(
            store.cache_route_verified_event_with_replication_policy(
                &current,
                &second_route,
                &second.bytes,
            ),
            Ok(RouteCacheOutcome::Inserted { .. })
        ));
    }

    #[test]
    fn replication_snapshot_atomically_guards_semantic_event_admission() {
        let file = TestFile::new("replication-semantic-admission");
        let mut services = event_services(0x4d);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let policy = store.control_policy_snapshot().expect("settled policy");
        let receive_none = store
            .event_replication_policy_snapshot()
            .expect("empty receive intent");
        let payload = b"Consume-only semantic admission";
        let header = event_header(
            services.publisher.identity(),
            1,
            1,
            VersionVector::default(),
            b"semantic-atomic",
            payload,
            None,
        );
        let sealed = services
            .publisher
            .seal_event(&header, payload)
            .expect("seal semantic Event");
        let event = content_event(&mut services.reader, &sealed.bytes);
        let transfer_id = EventTransferId::new(event.envelope_id());

        assert!(matches!(
            store.apply_verified_event_with_replication_policy(
                &receive_none,
                &event,
                &sealed.bytes,
            ),
            Err(StoreError::EventReplicationNotSelected)
        ));
        store
            .create_event_subscription_with_policy(
                &policy,
                &EventSubscriptionKey::new(b"relay/carry-semantic".to_vec()).expect("Carry key"),
                subscription_spec(EventSubscriptionMode::Carry),
            )
            .expect("create Carry selector");
        let stale_carry = store
            .event_replication_policy_snapshot()
            .expect("Carry snapshot");
        assert!(matches!(
            store
                .apply_verified_event_with_replication_policy(&stale_carry, &event, &sealed.bytes,),
            Err(StoreError::EventReplicationNotConsumable)
        ));
        assert_eq!(
            store.event_stats().expect("pre-stale stats"),
            EventStoreStats::default()
        );

        store
            .create_event_subscription_with_policy(
                &policy,
                &EventSubscriptionKey::new(b"application/consume-semantic".to_vec())
                    .expect("Consume key"),
                subscription_spec(EventSubscriptionMode::Consume),
            )
            .expect("insert overlapping Consume selector");
        let before_stale_attempt = store.event_stats().expect("pre-attempt stats");
        assert!(matches!(
            store
                .apply_verified_event_with_replication_policy(&stale_carry, &event, &sealed.bytes,),
            Err(StoreError::EventSelectorRevisionChanged)
        ));
        assert_eq!(
            store.event_stats().expect("post-attempt stats"),
            before_stale_attempt,
            "a stale replication snapshot cannot mutate semantic accounting"
        );
        assert!(
            store
                .get_event(transfer_id)
                .expect("read rejected semantic Event")
                .is_none(),
            "a stale replication snapshot cannot insert semantic bytes or indexes"
        );

        let current = store
            .event_replication_policy_snapshot()
            .expect("current Consume snapshot");
        assert!(matches!(
            store.apply_verified_event_with_replication_policy(&current, &event, &sealed.bytes),
            Ok(ApplyOutcome::Inserted { .. })
        ));
    }

    #[test]
    fn cross_store_same_revision_snapshot_cannot_admit_route_cache() {
        let source_file = TestFile::new("cross-store-route-source");
        let target_file = TestFile::new("cross-store-route-target");
        let mut services = event_services(0x4e);
        let source =
            Store::open_for_mission(&source_file.0, services.authority).expect("source store");
        let target =
            Store::open_for_mission(&target_file.0, services.authority).expect("target store");
        let source_policy = source.control_policy_snapshot().expect("source policy");
        let target_policy = target.control_policy_snapshot().expect("target policy");
        source
            .create_event_subscription_with_policy(
                &source_policy,
                &EventSubscriptionKey::new(b"source/carry".to_vec()).expect("source key"),
                subscription_spec(EventSubscriptionMode::Carry),
            )
            .expect("source selector");
        let mut unrelated = subscription_spec(EventSubscriptionMode::Carry);
        unrelated.topic = reaction_topic();
        target
            .create_event_subscription_with_policy(
                &target_policy,
                &EventSubscriptionKey::new(b"target/carry".to_vec()).expect("target key"),
                unrelated,
            )
            .expect("target unrelated selector");
        let cross_wired = source
            .event_replication_policy_snapshot()
            .expect("source snapshot");
        let target_snapshot = target
            .event_replication_policy_snapshot()
            .expect("target snapshot");
        assert_eq!(cross_wired.selector_revision(), 1);
        assert_eq!(target_snapshot.selector_revision(), 1);
        assert_eq!(
            cross_wired.effective_mode(&event_topic(), &event_scope()),
            Some(EventSubscriptionMode::Carry)
        );
        assert_eq!(
            target_snapshot.effective_mode(&event_topic(), &event_scope()),
            None
        );

        let payload = b"cross-wired route snapshot";
        let header = event_header(
            services.publisher.identity(),
            1,
            1,
            VersionVector::default(),
            b"cross-route",
            payload,
            None,
        );
        let sealed = services
            .publisher
            .seal_event(&header, payload)
            .expect("seal route Event");
        let route = services
            .relay
            .verify_event(&sealed.bytes)
            .expect("verify route Event");
        let transfer_id = EventTransferId::new(route.envelope_id());
        let before = target.event_stats().expect("target stats before");
        assert!(matches!(
            target.cache_route_verified_event_with_replication_policy(
                &cross_wired,
                &route,
                &sealed.bytes,
            ),
            Err(StoreError::EventSelectorRevisionChanged)
        ));
        assert_eq!(target.event_stats().expect("target stats after"), before);
        assert!(
            target
                .get_route_cached_event(transfer_id)
                .expect("read rejected route Event")
                .is_none(),
            "same numeric revision cannot cross-wire route authority between stores"
        );
    }

