    #[test]
    fn event_subscription_poll_restarts_retries_acks_and_closes_filter_gaps() {
        let file = TestFile::new("event-subscription-delivery");
        let mut services = event_services(0x46);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let policy = store.control_policy_snapshot().expect("poll policy");
        let key = EventSubscriptionKey::new(b"application/events".to_vec()).expect("key");
        let subscription = store
            .create_event_subscription_with_policy(
                &policy,
                &key,
                subscription_spec(EventSubscriptionMode::Consume),
            )
            .expect("create Consume")
            .id;
        let publisher = services.publisher.identity();
        let first_payload = b"first delivery";
        let first = accept_event(
            &store,
            &mut services,
            event_header(
                publisher,
                1,
                1,
                VersionVector::default(),
                b"first",
                first_payload,
                None,
            ),
            first_payload,
        );
        let skipped_payload = b"different topic creates a filter gap";
        let mut skipped_header = event_header(
            publisher,
            2,
            1,
            VersionVector::default(),
            b"skip",
            skipped_payload,
            None,
        );
        skipped_header.topic = reaction_topic();
        let skipped = accept_event(&store, &mut services, skipped_header, skipped_payload);
        let third_payload = b"delivery after the filter gap";
        let third = accept_event(
            &store,
            &mut services,
            event_header(
                publisher,
                3,
                2,
                VersionVector::default(),
                b"third",
                third_payload,
                None,
            ),
            third_payload,
        );
        assert_eq!(
            (
                first.acceptance_marker,
                skipped.acceptance_marker,
                third.acceptance_marker
            ),
            (1, 2, 3)
        );
        assert!(matches!(
            store.acknowledge_event_delivery_with_policy(
                &policy,
                subscription,
                EventSemanticId::new([0xff; 32]),
            ),
            Err(StoreError::EventDeliveryNotFound)
        ));
        assert!(matches!(
            store.acknowledge_event_delivery_with_policy(&policy, subscription, first.semantic_id,),
            Err(StoreError::EventDeliveryNotFound)
        ));

        let plan = store
            .prepare_event_subscription_poll_with_policy(&policy, subscription, 1, 1)
            .expect("first bounded plan");
        assert_eq!(plan.discovered_through(), 0);
        assert_eq!(plan.scanned_candidates(), std::slice::from_ref(&first));
        let stale_plan = plan.clone();
        let selection = verify_subscription_plan(&mut services.reader, &plan);
        let first_attempt = store
            .commit_event_subscription_poll_with_policy(&policy, &plan, &selection)
            .expect("commit attempt one");
        assert_eq!(first_attempt.deliveries[0].attempt, 1);
        assert_eq!(first_attempt.scanned_through, 1);
        assert!(first_attempt.has_more);
        assert!(matches!(
            store.commit_event_subscription_poll_with_policy(&policy, &stale_plan, &selection),
            Err(StoreError::EventSubscriptionPlanChanged)
        ));
        drop(store);

        let store = Store::open_for_mission(&file.0, services.authority).expect("restart store");
        let policy = store.control_policy_snapshot().expect("restart policy");
        let retry_plan = store
            .prepare_event_subscription_poll_with_policy(&policy, subscription, 1, 4)
            .expect("pending retry plan");
        assert!(retry_plan.scanned_candidates().is_empty());
        assert_eq!(retry_plan.pending_candidates().len(), 1);
        assert_eq!(retry_plan.pending_candidates()[0].previous_attempt, 1);
        let retry_selection = verify_subscription_plan(&mut services.reader, &retry_plan);
        let retry = store
            .commit_event_subscription_poll_with_policy(&policy, &retry_plan, &retry_selection)
            .expect("durably commit retry");
        assert_eq!(retry.deliveries[0].attempt, 2);
        assert_eq!(retry.deliveries[0].event, first);
        assert_eq!(
            store
                .acknowledge_event_delivery_with_policy(&policy, subscription, first.semantic_id)
                .expect("ack first"),
            EventDeliveryAck::Acknowledged
        );
        drop(store);
        let mut store = Store::open_for_mission(&file.0, services.authority)
            .expect("acknowledgement receipt restart");
        let policy = store
            .control_policy_snapshot()
            .expect("acknowledgement retry policy");
        assert_eq!(
            store
                .acknowledge_event_delivery_with_policy(&policy, subscription, first.semantic_id)
                .expect("durable idempotent ack retry"),
            EventDeliveryAck::AlreadyAcknowledged
        );

        let gap_plan = store
            .prepare_event_subscription_poll_with_policy(&policy, subscription, 4, 1)
            .expect("bounded unfiltered gap plan");
        assert_eq!(
            gap_plan.scanned_candidates(),
            std::slice::from_ref(&skipped)
        );
        let gap_selection = verify_subscription_plan(&mut services.reader, &gap_plan);
        assert!(gap_selection.deliveries.is_empty());
        let gap_page = store
            .commit_event_subscription_poll_with_policy(&policy, &gap_plan, &gap_selection)
            .expect("advance over verified nonmatch");
        assert_eq!(gap_page.scanned_through, 2);
        assert!(gap_page.deliveries.is_empty());
        assert!(gap_page.has_more);
        assert!(matches!(
            store.acknowledge_event_delivery_with_policy(
                &policy,
                subscription,
                skipped.semantic_id,
            ),
            Err(StoreError::EventDeliveryNotFound)
        ));

        let final_plan = store
            .prepare_event_subscription_poll_with_policy(&policy, subscription, 4, 4)
            .expect("post-gap plan");
        assert_eq!(
            final_plan.scanned_candidates(),
            std::slice::from_ref(&third)
        );
        let final_selection = verify_subscription_plan(&mut services.reader, &final_plan);
        let appended_payload = b"accepted after prepare before commit";
        let appended = accept_event(
            &store,
            &mut services,
            event_header(
                publisher,
                4,
                3,
                VersionVector::default(),
                b"appended",
                appended_payload,
                None,
            ),
            appended_payload,
        );
        let final_page = store
            .commit_event_subscription_poll_with_policy(&policy, &final_plan, &final_selection)
            .expect("post-gap delivery");
        assert_eq!(final_page.deliveries[0].attempt, 1);
        assert_eq!(final_page.deliveries[0].event, third);
        assert!(
            final_page.has_more,
            "commit must observe Events accepted after bounded preparation"
        );
        assert_eq!(
            store
                .acknowledge_event_delivery_with_policy(&policy, subscription, third.semantic_id)
                .expect("ack post-gap delivery"),
            EventDeliveryAck::Acknowledged
        );
        let appended_plan = store
            .prepare_event_subscription_poll_with_policy(&policy, subscription, 1, 1)
            .expect("appended Event plan");
        assert_eq!(
            appended_plan.scanned_candidates(),
            std::slice::from_ref(&appended)
        );
        let appended_selection = verify_subscription_plan(&mut services.reader, &appended_plan);
        let appended_page = store
            .commit_event_subscription_poll_with_policy(
                &policy,
                &appended_plan,
                &appended_selection,
            )
            .expect("appended Event delivery");
        assert!(!appended_page.has_more);
        assert_eq!(appended_page.deliveries[0].event, appended);
        assert_eq!(
            store
                .acknowledge_event_delivery_with_policy(
                    &policy,
                    subscription,
                    appended.semantic_id,
                )
                .expect("ack appended delivery"),
            EventDeliveryAck::Acknowledged
        );
        assert_eq!(
            store.event_subscription_stats().expect("empty ledger"),
            EventSubscriptionStats {
                subscriptions: 1,
                pending_deliveries: 0,
                acknowledged_deliveries: 3,
                selector_revision: 1,
            }
        );

        let intent = ZeroizationIntent::new(
            b"v1:mission:/subscription-test".to_vec(),
            b"v1:identity:/subscription-test".to_vec(),
        )
        .expect("terminal intent");
        store
            .begin_zeroization(&intent)
            .expect("enter terminal state");
        assert!(matches!(
            store.prepare_event_subscription_poll_with_policy(&policy, subscription, 1, 1),
            Err(StoreError::StoreZeroized(
                StoreZeroizationState::CleanupPending
            ))
        ));
    }

    #[test]
    fn event_subscription_retires_verified_inactive_pending_without_starvation() {
        let file = TestFile::new("event-subscription-inactive");
        let mut services = control_services(0x47);
        let store =
            Store::open_for_mission(&file.0, services.authority_id).expect("control-bound store");
        let initial_policy = store.control_policy_snapshot().expect("initial policy");
        let key = EventSubscriptionKey::new(b"application/inactive".to_vec()).expect("key");
        let subscription = store
            .create_event_subscription_with_policy(
                &initial_policy,
                &key,
                subscription_spec(EventSubscriptionMode::Consume),
            )
            .expect("create Consume")
            .id;
        let payload = b"delivery revoked after first attempt";
        let header = event_header(
            services.verifier.identity(),
            1,
            1,
            VersionVector::default(),
            b"inactive",
            payload,
            None,
        );
        let sealed = services
            .verifier
            .seal_event(&header, payload)
            .expect("seal pre-revocation Event");
        let event = content_event(&mut services.authority, &sealed.bytes);
        store
            .apply_verified_event_with_policy(&initial_policy, &event, &sealed.bytes)
            .expect("accept pre-revocation Event");
        let stored = store
            .event_by_semantic_id(EventSemanticId::new(event.item_id()))
            .expect("read Event")
            .expect("stored Event");
        let never_delivered_payload = b"inactive before first bounded scan";
        let never_delivered_header = event_header(
            services.verifier.identity(),
            2,
            2,
            VersionVector::default(),
            b"inactive-first-scan",
            never_delivered_payload,
            None,
        );
        let never_delivered_sealed = services
            .verifier
            .seal_event(&never_delivered_header, never_delivered_payload)
            .expect("seal undiscovered pre-revocation Event");
        let never_delivered_event =
            content_event(&mut services.authority, &never_delivered_sealed.bytes);
        store
            .apply_verified_event_with_policy(
                &initial_policy,
                &never_delivered_event,
                &never_delivered_sealed.bytes,
            )
            .expect("accept undiscovered pre-revocation Event");
        let never_delivered = store
            .event_by_semantic_id(EventSemanticId::new(never_delivered_event.item_id()))
            .expect("read undiscovered Event")
            .expect("undiscovered Event row");
        let first_plan = store
            .prepare_event_subscription_poll_with_policy(&initial_policy, subscription, 1, 1)
            .expect("initial plan");
        let first_selection = verify_subscription_plan(&mut services.authority, &first_plan);
        store
            .commit_event_subscription_poll_with_policy(
                &initial_policy,
                &first_plan,
                &first_selection,
            )
            .expect("first attempt");

        let revoked = services.verifier.identity();
        let control = services
            .authority
            .seal_chained_revocation_control(revoked, 1, 1, None)
            .expect("seal revocation");
        let verified = verify_control(&mut services.verifier, &control);
        store
            .ingest_verified_control(&verified, &control)
            .expect("apply revocation");
        let current_policy = store.control_policy_snapshot().expect("current policy");
        assert!(matches!(
            store.prepare_event_subscription_poll_with_policy(&initial_policy, subscription, 1, 1,),
            Err(StoreError::ControlPolicyChanged)
        ));
        let inactive_plan = store
            .prepare_event_subscription_poll_with_policy(&current_policy, subscription, 1, 1)
            .expect("inactive pending plan");
        assert_eq!(inactive_plan.pending_candidates().len(), 1);
        content_event(
            &mut services.authority,
            &inactive_plan.pending_candidates()[0].event.sealed,
        );
        let selection = EventSubscriptionPollSelection {
            deliveries: Vec::new(),
            inactive_pending: vec![stored.semantic_id],
        };
        let retired = store
            .commit_event_subscription_poll_with_policy(&current_policy, &inactive_plan, &selection)
            .expect("retire inactive pending row");
        assert!(retired.deliveries.is_empty());
        assert_eq!(
            store
                .event_subscription_stats()
                .expect("retired pending stats")
                .pending_deliveries,
            0
        );
        let first_inactive_scan = store
            .prepare_event_subscription_poll_with_policy(&current_policy, subscription, 1, 1)
            .expect("first scan of already-inactive Event");
        assert!(first_inactive_scan.pending_candidates().is_empty());
        assert_eq!(
            first_inactive_scan.scanned_candidates(),
            std::slice::from_ref(&never_delivered)
        );
        content_event(
            &mut services.authority,
            &first_inactive_scan.scanned_candidates()[0].sealed,
        );
        let inactive_scan_page = store
            .commit_event_subscription_poll_with_policy(
                &current_policy,
                &first_inactive_scan,
                &EventSubscriptionPollSelection::default(),
            )
            .expect("advance over first-scan inactive Event");
        assert!(inactive_scan_page.deliveries.is_empty());
        assert_eq!(
            inactive_scan_page.scanned_through,
            never_delivered.acceptance_marker
        );
        assert!(matches!(
            store.acknowledge_event_delivery_with_policy(
                &current_policy,
                subscription,
                stored.semantic_id,
            ),
            Err(StoreError::EventDeliveryNotFound)
        ));
        assert!(matches!(
            store.acknowledge_event_delivery_with_policy(
                &current_policy,
                subscription,
                never_delivered.semantic_id,
            ),
            Err(StoreError::EventDeliveryNotFound)
        ));
        assert_eq!(
            store
                .event_subscription_stats()
                .expect("inactive retirement has no false receipt")
                .acknowledged_deliveries,
            0
        );
        let empty = store
            .prepare_event_subscription_poll_with_policy(&current_policy, subscription, 1, 1)
            .expect("no starvation after inactive first scan");
        assert!(empty.pending_candidates().is_empty());
        assert!(empty.scanned_candidates().is_empty());
    }

    #[test]
    fn event_acknowledgement_receipt_corruption_and_accounting_fail_closed() {
        let file = TestFile::new("event-acknowledgement-corruption");
        let mut services = event_services(0x4a);
        let subscription;
        let stored;
        {
            let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
            let policy = store.control_policy_snapshot().expect("settled policy");
            subscription = store
                .create_event_subscription_with_policy(
                    &policy,
                    &EventSubscriptionKey::new(b"application/receipt-audit".to_vec())
                        .expect("subscription key"),
                    subscription_spec(EventSubscriptionMode::Consume),
                )
                .expect("create Consume")
                .id;
            let payload = b"acknowledgement receipt audit";
            let publisher = services.publisher.identity();
            stored = accept_event(
                &store,
                &mut services,
                event_header(
                    publisher,
                    1,
                    1,
                    VersionVector::default(),
                    b"receipt-audit",
                    payload,
                    None,
                ),
                payload,
            );
            let plan = store
                .prepare_event_subscription_poll_with_policy(&policy, subscription, 1, 1)
                .expect("receipt poll plan");
            let selection = verify_subscription_plan(&mut services.reader, &plan);
            store
                .commit_event_subscription_poll_with_policy(&policy, &plan, &selection)
                .expect("durable delivery attempt");
            assert_eq!(
                store
                    .acknowledge_event_delivery_with_policy(
                        &policy,
                        subscription,
                        stored.semantic_id,
                    )
                    .expect("first acknowledgement"),
                EventDeliveryAck::Acknowledged
            );
            assert_eq!(
                store
                    .event_subscription_stats()
                    .expect("receipt stats")
                    .acknowledged_deliveries,
                1
            );
        }

        let acknowledgement_key = event_acknowledgement_key(subscription, stored.semantic_id);
        {
            let database = Database::open(&file.0).expect("open receipt corruption");
            let write = database.begin_write().expect("begin receipt corruption");
            let corrupt = encode_event_acknowledgement_record(EventAcknowledgementRecord {
                acceptance_marker: stored.acceptance_marker,
                attempts: 0,
            });
            write
                .open_table(EVENT_DELIVERY_ACKNOWLEDGEMENTS)
                .expect("acknowledgement table")
                .insert(acknowledgement_key.as_slice(), corrupt.as_slice())
                .expect("stage corrupt receipt");
            write.commit().expect("commit corrupt receipt");
        }
        for result in [
            Store::inspect_existing(&file.0).map(|_| ()),
            Store::open_for_mission(&file.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::SemanticInvariant(
                    "Event acknowledgement contains a zero attempt count"
                ))
            ));
        }

        {
            let database = Database::open(&file.0).expect("open receipt accounting corruption");
            let write = database
                .begin_write()
                .expect("begin receipt accounting corruption");
            let valid = encode_event_acknowledgement_record(EventAcknowledgementRecord {
                acceptance_marker: stored.acceptance_marker,
                attempts: 1,
            });
            write
                .open_table(EVENT_DELIVERY_ACKNOWLEDGEMENTS)
                .expect("acknowledgement table")
                .insert(acknowledgement_key.as_slice(), valid.as_slice())
                .expect("restore canonical receipt");
            write
                .open_table(METADATA)
                .expect("metadata")
                .insert(EVENT_ACKNOWLEDGEMENT_COUNT, 0)
                .expect("corrupt receipt accounting");
            write
                .commit()
                .expect("commit receipt accounting corruption");
        }
        for result in [
            Store::inspect_existing(&file.0).map(|_| ()),
            Store::open_for_mission(&file.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::AccountingMismatch {
                    field: EVENT_ACKNOWLEDGEMENT_COUNT,
                    durable: 0,
                    reconstructed: 1,
                })
            ));
        }
    }

    #[test]
    fn event_acknowledgement_cap_preserves_the_pending_delivery() {
        let file = TestFile::new("event-acknowledgement-cap");
        let mut services = event_services(0x4b);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let policy = store.control_policy_snapshot().expect("settled policy");
        let subscription = store
            .create_event_subscription_with_policy(
                &policy,
                &EventSubscriptionKey::new(b"application/receipt-cap".to_vec())
                    .expect("subscription key"),
                subscription_spec(EventSubscriptionMode::Consume),
            )
            .expect("create Consume")
            .id;
        let payload = b"pending at acknowledgement cap";
        let publisher = services.publisher.identity();
        let stored = accept_event(
            &store,
            &mut services,
            event_header(
                publisher,
                1,
                1,
                VersionVector::default(),
                b"receipt-cap",
                payload,
                None,
            ),
            payload,
        );
        let plan = store
            .prepare_event_subscription_poll_with_policy(&policy, subscription, 1, 1)
            .expect("cap poll plan");
        let selection = verify_subscription_plan(&mut services.reader, &plan);
        store
            .commit_event_subscription_poll_with_policy(&policy, &plan, &selection)
            .expect("pending delivery");

        {
            let write = store.database.begin_write().expect("begin cap fixture");
            let dummy_subscription = EventSubscriptionId::from_bytes([0xa5; 32]);
            let encoded = encode_event_acknowledgement_record(EventAcknowledgementRecord {
                acceptance_marker: 1,
                attempts: 1,
            });
            {
                let mut acknowledgements = write
                    .open_table(EVENT_DELIVERY_ACKNOWLEDGEMENTS)
                    .expect("acknowledgement table");
                for index in 0..MAX_EVENT_ACKNOWLEDGEMENT_RECEIPTS {
                    let mut semantic = [0x5a; 32];
                    semantic[24..].copy_from_slice(&index.to_be_bytes());
                    let key = event_acknowledgement_key(
                        dummy_subscription,
                        EventSemanticId::new(semantic),
                    );
                    acknowledgements
                        .insert(key.as_slice(), encoded.as_slice())
                        .expect("fill bounded receipt fixture");
                }
            }
            write
                .open_table(METADATA)
                .expect("metadata")
                .insert(
                    EVENT_ACKNOWLEDGEMENT_COUNT,
                    MAX_EVENT_ACKNOWLEDGEMENT_RECEIPTS,
                )
                .expect("set bounded receipt accounting");
            write.commit().expect("commit full receipt fixture");
        }

        assert!(matches!(
            store
                .acknowledge_event_delivery_with_policy(&policy, subscription, stored.semantic_id,),
            Err(StoreError::EventAcknowledgementReceiptLimitExceeded {
                current: MAX_EVENT_ACKNOWLEDGEMENT_RECEIPTS,
                limit: MAX_EVENT_ACKNOWLEDGEMENT_RECEIPTS,
            })
        ));
        let read = store.database.begin_read().expect("read cap rollback");
        let pending_key = event_pending_delivery_key(subscription, stored.acceptance_marker);
        assert!(
            read.open_table(EVENT_SUBSCRIPTION_PENDING)
                .expect("pending table")
                .get(pending_key.as_slice())
                .expect("read pending")
                .is_some(),
            "failed acknowledgement must retain the pending delivery"
        );
        let acknowledgement_key = event_acknowledgement_key(subscription, stored.semantic_id);
        assert!(
            read.open_table(EVENT_DELIVERY_ACKNOWLEDGEMENTS)
                .expect("acknowledgement table")
                .get(acknowledgement_key.as_slice())
                .expect("read target acknowledgement")
                .is_none(),
            "failed acknowledgement must not create a target receipt"
        );
    }

    #[test]
    fn event_subscription_schema_migrates_absent_and_exact_legacy_groups_only() {
        let file = TestFile::new("event-subscription-migration");
        let services = event_services(0x48);
        {
            let store =
                Store::open_for_mission(&file.0, services.authority).expect("initialize store");
            assert_eq!(
                store.event_subscription_stats().expect("initial stats"),
                EventSubscriptionStats::default()
            );
        }
        {
            let database = Database::open(&file.0).expect("open legacy simulation");
            let write = database.begin_write().expect("begin legacy simulation");
            write
                .delete_table(EVENT_SUBSCRIPTIONS)
                .expect("remove selector table");
            write
                .delete_table(EVENT_SUBSCRIPTION_PENDING)
                .expect("remove pending table");
            write
                .delete_table(EVENT_DELIVERY_ACKNOWLEDGEMENTS)
                .expect("remove acknowledgement table");
            {
                let mut metadata = write.open_table(METADATA).expect("metadata");
                metadata
                    .remove(EVENT_SUBSCRIPTION_COUNT)
                    .expect("remove selector counter");
                metadata
                    .remove(EVENT_PENDING_DELIVERY_COUNT)
                    .expect("remove pending counter");
                metadata
                    .remove(EVENT_SELECTOR_REVISION)
                    .expect("remove selector revision");
                metadata
                    .remove(EVENT_ACKNOWLEDGEMENT_COUNT)
                    .expect("remove acknowledgement counter");
            }
            write.commit().expect("commit wholly absent legacy group");
        }
        assert_eq!(
            Store::inspect_existing(&file.0)
                .expect("legacy read-only inspection")
                .event_subscription_stats,
            EventSubscriptionStats::default()
        );
        {
            let migrated = Store::open_for_mission(&file.0, services.authority)
                .expect("all-absent group migrates");
            assert_eq!(
                migrated.event_subscription_stats().expect("migrated stats"),
                EventSubscriptionStats::default()
            );
            let policy = migrated
                .control_policy_snapshot()
                .expect("legacy setup policy");
            for (key, mode) in [
                (b"legacy/carry".as_slice(), EventSubscriptionMode::Carry),
                (b"legacy/consume".as_slice(), EventSubscriptionMode::Consume),
            ] {
                migrated
                    .create_event_subscription_with_policy(
                        &policy,
                        &EventSubscriptionKey::new(key.to_vec()).expect("legacy key"),
                        subscription_spec(mode),
                    )
                    .expect("legacy duplicate projection");
            }
        }
        {
            let database = Database::open(&file.0).expect("open exact legacy group");
            let write = database.begin_write().expect("begin exact legacy group");
            write
                .delete_table(EVENT_DELIVERY_ACKNOWLEDGEMENTS)
                .expect("remove new receipt table");
            {
                let mut metadata = write.open_table(METADATA).expect("legacy metadata");
                metadata
                    .remove(EVENT_ACKNOWLEDGEMENT_COUNT)
                    .expect("remove new receipt counter");
                metadata
                    .insert(EVENT_SELECTOR_REVISION, 1)
                    .expect("restore projection-count legacy revision");
            }
            write.commit().expect("commit exact legacy group");
        }
        assert_eq!(
            Store::inspect_existing(&file.0)
                .expect("exact legacy group remains read-only inspectable")
                .event_subscription_stats,
            EventSubscriptionStats {
                subscriptions: 2,
                pending_deliveries: 0,
                acknowledged_deliveries: 0,
                selector_revision: 1,
            }
        );
        {
            let migrated = Store::open_for_mission(&file.0, services.authority)
                .expect("exact legacy group migrates atomically");
            assert_eq!(
                migrated
                    .event_subscription_stats()
                    .expect("current grouped stats"),
                EventSubscriptionStats {
                    subscriptions: 2,
                    pending_deliveries: 0,
                    acknowledged_deliveries: 0,
                    selector_revision: 2,
                }
            );
        }
        {
            let database = Database::open(&file.0).expect("open partial simulation");
            let write = database.begin_write().expect("begin partial simulation");
            write
                .delete_table(EVENT_SUBSCRIPTION_PENDING)
                .expect("remove one grouped table");
            write.commit().expect("commit partial schema");
        }
        assert!(matches!(
            Store::inspect_existing(&file.0),
            Err(StoreError::SemanticInvariant(
                "Event subscription schema group is incomplete"
            ))
        ));
        assert!(matches!(
            Store::open_for_mission(&file.0, services.authority),
            Err(StoreError::SemanticInvariant(
                "Event subscription schema group is incomplete"
            ))
        ));
        let database = Database::open(&file.0).expect("inspect failed migration");
        let read = database.begin_read().expect("read failed migration");
        assert!(
            !read
                .list_tables()
                .expect("list tables")
                .any(|table| table.name() == EVENT_SUBSCRIPTION_PENDING.name()),
            "partial schema must never be repaired"
        );

        let wrong_kind = TestFile::new("event-subscription-wrong-kind");
        {
            let store = Store::open_for_mission(&wrong_kind.0, services.authority)
                .expect("initialize wrong-kind store");
            drop(store);
            let database = Database::open(&wrong_kind.0).expect("open wrong-kind store");
            let write = database.begin_write().expect("begin wrong-kind write");
            write
                .delete_table(EVENT_DELIVERY_ACKNOWLEDGEMENTS)
                .expect("remove regular acknowledgement table");
            let definition = redb::MultimapTableDefinition::<&[u8], &[u8]>::new(
                EVENT_DELIVERY_ACKNOWLEDGEMENTS.name(),
            );
            write
                .open_multimap_table(definition)
                .expect("wrong-kind acknowledgement table")
                .insert(b"bad-key".as_slice(), b"bad-value".as_slice())
                .expect("wrong-kind row");
            write.commit().expect("commit wrong-kind schema");
        }
        for result in [
            Store::inspect_existing(&wrong_kind.0).map(|_| ()),
            Store::open_for_mission(&wrong_kind.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::SemanticInvariant(
                    "Event subscription schema has the wrong table kind"
                ))
            ));
        }
    }

    #[test]
    fn event_subscription_attempt_overflow_and_pending_corruption_fail_closed() {
        let file = TestFile::new("event-subscription-attempt-terminal");
        let mut services = event_services(0x49);
        let subscription;
        let stored;
        {
            let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
            let policy = store.control_policy_snapshot().expect("policy");
            subscription = store
                .create_event_subscription_with_policy(
                    &policy,
                    &EventSubscriptionKey::new(b"application/overflow".to_vec()).expect("key"),
                    subscription_spec(EventSubscriptionMode::Consume),
                )
                .expect("create Consume")
                .id;
            let payload = b"attempt overflow candidate";
            let publisher = services.publisher.identity();
            stored = accept_event(
                &store,
                &mut services,
                event_header(
                    publisher,
                    1,
                    1,
                    VersionVector::default(),
                    b"overflow",
                    payload,
                    None,
                ),
                payload,
            );
            let plan = store
                .prepare_event_subscription_poll_with_policy(&policy, subscription, 1, 1)
                .expect("first plan");
            let selection = verify_subscription_plan(&mut services.reader, &plan);
            store
                .commit_event_subscription_poll_with_policy(&policy, &plan, &selection)
                .expect("first attempt");
        }
        let pending_key = event_pending_delivery_key(subscription, stored.acceptance_marker);
        {
            let database = Database::open(&file.0).expect("open attempt simulation");
            let write = database.begin_write().expect("begin attempt simulation");
            let encoded = encode_event_pending_delivery_record(EventPendingDeliveryRecord {
                semantic_id: stored.semantic_id,
                attempts: u64::MAX,
            });
            write
                .open_table(EVENT_SUBSCRIPTION_PENDING)
                .expect("pending table")
                .insert(pending_key.as_slice(), encoded.as_slice())
                .expect("stage terminal attempt");
            write.commit().expect("commit terminal attempt");
        }
        {
            let store = Store::open_for_mission(&file.0, services.authority)
                .expect("maximum nonzero attempt audits");
            let policy = store.control_policy_snapshot().expect("reopen policy");
            let plan = store
                .prepare_event_subscription_poll_with_policy(&policy, subscription, 1, 1)
                .expect("terminal attempt plan");
            assert_eq!(plan.pending_candidates()[0].previous_attempt, u64::MAX);
            let selection = verify_subscription_plan(&mut services.reader, &plan);
            assert!(matches!(
                store.commit_event_subscription_poll_with_policy(&policy, &plan, &selection),
                Err(StoreError::EventDeliveryAttemptExhausted)
            ));
            assert_eq!(
                store
                    .event_subscription_stats()
                    .expect("overflow rollback stats")
                    .pending_deliveries,
                1
            );
        }
        {
            let database = Database::open(&file.0).expect("open corruption simulation");
            let write = database.begin_write().expect("begin corruption simulation");
            let mut invalid = Vec::with_capacity(41);
            invalid.push(EVENT_PENDING_DELIVERY_VERSION);
            invalid.extend_from_slice(stored.semantic_id.as_bytes());
            invalid.extend_from_slice(&0u64.to_be_bytes());
            write
                .open_table(EVENT_SUBSCRIPTION_PENDING)
                .expect("pending table")
                .insert(pending_key.as_slice(), invalid.as_slice())
                .expect("stage zero attempt corruption");
            write.commit().expect("commit zero attempt corruption");
        }
        assert!(matches!(
            Store::inspect_existing(&file.0),
            Err(StoreError::SemanticInvariant(
                "Event pending-delivery attempt count is zero"
            ))
        ));
        assert!(matches!(
            Store::open_for_mission(&file.0, services.authority),
            Err(StoreError::SemanticInvariant(
                "Event pending-delivery attempt count is zero"
            ))
        ));
    }

    #[test]
    fn fresh_event_candidate_query_is_bounded_ordered_filtered_and_route_separated() {
        let file = TestFile::new("event-candidate-query");
        let mut services = event_services_with_child_scope(0x42);
        let store = Store::open_for_mission(&file.0, services.authority).expect("fresh store");
        let publisher = services.publisher.identity();

        let first_payload = b"first accepted Event";
        let first = accept_event(
            &store,
            &mut services,
            event_header(
                publisher,
                1,
                1,
                VersionVector::default(),
                b"alpha",
                first_payload,
                None,
            ),
            first_payload,
        );
        let second_payload = b"second accepted Event";
        let mut second_header = event_header(
            publisher,
            2,
            1,
            VersionVector::default(),
            b"beta",
            second_payload,
            None,
        );
        second_header.topic = reaction_topic();
        let second = accept_event(&store, &mut services, second_header, second_payload);
        let third_payload = b"third accepted Event";
        let mut third_header = event_header(
            publisher,
            3,
            1,
            VersionVector::default(),
            b"alpha",
            third_payload,
            None,
        );
        third_header.scope = child_event_scope();
        let third = accept_event(&store, &mut services, third_header, third_payload);
        let fourth_payload = b"fourth accepted Event";
        let fourth = accept_event(
            &store,
            &mut services,
            event_header(
                publisher,
                4,
                2,
                VersionVector::default(),
                b"gamma",
                fourth_payload,
                None,
            ),
            fourth_payload,
        );

        let route_payload = b"route cache is not an accepted Event";
        let route_header = event_header(
            publisher,
            5,
            3,
            VersionVector::default(),
            b"route-only",
            route_payload,
            None,
        );
        let route_sealed = services
            .publisher
            .seal_event(&route_header, route_payload)
            .expect("seal route-only Event");
        let route = services
            .relay
            .verify_event(&route_sealed.bytes)
            .expect("route verification");
        store
            .cache_route_verified_event(&route, &route_sealed.bytes)
            .expect("cache route-only representation");

        let policy = store.control_policy_snapshot().expect("query policy");
        let unmatched = store
            .query_event_candidates_with_policy(
                &policy,
                &EventQueryFilter {
                    publisher: Some([0xee; 32]),
                    ..EventQueryFilter::default()
                },
                0,
                2,
            )
            .expect("bounded unmatched scan");
        assert!(unmatched.events.is_empty());
        assert_eq!(unmatched.scanned_through, 2);
        assert!(unmatched.has_more, "continuation is independent of matches");

        let first_page = store
            .query_event_candidates_with_policy(&policy, &EventQueryFilter::default(), 0, 2)
            .expect("first page");
        assert_eq!(
            first_page
                .events
                .iter()
                .map(|event| event.transfer_id)
                .collect::<Vec<_>>(),
            vec![first.transfer_id, second.transfer_id]
        );
        assert_eq!(first_page.scanned_through, 2);
        assert!(first_page.has_more);
        let second_page = store
            .query_event_candidates_with_policy(
                &policy,
                &EventQueryFilter::default(),
                first_page.scanned_through,
                2,
            )
            .expect("second page");
        assert_eq!(
            second_page
                .events
                .iter()
                .map(|event| event.transfer_id)
                .collect::<Vec<_>>(),
            vec![third.transfer_id, fourth.transfer_id]
        );
        assert_eq!(second_page.scanned_through, 4);
        assert!(!second_page.has_more);
        assert_eq!(
            store
                .event_stats()
                .expect("separate route stats")
                .route_cached,
            1
        );

        let descendant_match = store
            .query_event_candidates_with_policy(
                &policy,
                &EventQueryFilter {
                    publisher: Some(publisher),
                    topic: Some(event_topic()),
                    scope: Some(event_scope()),
                    logical_key: Some(b"alpha".to_vec()),
                    include_descendant_scopes: true,
                },
                0,
                MAX_EVENT_PAGE,
            )
            .expect("combined descendant filter");
        assert_eq!(
            descendant_match
                .events
                .iter()
                .map(|event| event.transfer_id)
                .collect::<Vec<_>>(),
            vec![first.transfer_id, third.transfer_id]
        );
        assert_eq!(descendant_match.scanned_through, 4);
        assert!(!descendant_match.has_more);

        let exact_scope_match = store
            .query_event_candidates_with_policy(
                &policy,
                &EventQueryFilter {
                    scope: Some(event_scope()),
                    logical_key: Some(b"alpha".to_vec()),
                    ..EventQueryFilter::default()
                },
                0,
                MAX_EVENT_PAGE,
            )
            .expect("exact scope filter");
        assert_eq!(exact_scope_match.events, vec![first.clone()]);
        let topic_match = store
            .query_event_candidates_with_policy(
                &policy,
                &EventQueryFilter {
                    topic: Some(reaction_topic()),
                    ..EventQueryFilter::default()
                },
                0,
                MAX_EVENT_PAGE,
            )
            .expect("topic filter");
        assert_eq!(topic_match.events, vec![second.clone()]);
        let key_match = store
            .query_event_candidates_with_policy(
                &policy,
                &EventQueryFilter {
                    logical_key: Some(b"gamma".to_vec()),
                    ..EventQueryFilter::default()
                },
                0,
                MAX_EVENT_PAGE,
            )
            .expect("logical-key filter");
        assert_eq!(key_match.events, vec![fourth.clone()]);

        for requested in [0, MAX_EVENT_PAGE + 1] {
            assert!(matches!(
                store.query_event_candidates_with_policy(
                    &policy,
                    &EventQueryFilter::default(),
                    0,
                    requested,
                ),
                Err(StoreError::EventPageLimitExceeded { maximum, .. })
                    if maximum == MAX_EVENT_PAGE
            ));
        }
        let wrong_policy = ControlPolicySnapshot {
            authority: [0xed; 32],
            head: policy.head,
        };
        assert!(matches!(
            store.query_event_candidates_with_policy(
                &wrong_policy,
                &EventQueryFilter::default(),
                0,
                1,
            ),
            Err(StoreError::MissionAuthorityMismatch { .. })
        ));
    }

    #[test]
    fn event_candidate_query_rejects_inverse_gaps_and_truncated_high_water() {
        let file = TestFile::new("event-candidate-query-corruption");
        let mut services = event_services(0x44);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let publisher = services.publisher.identity();
        let mut accepted = Vec::new();
        for marker in 1..=3u64 {
            let payload = format!("accepted Event {marker}").into_bytes();
            accepted.push(accept_event(
                &store,
                &mut services,
                event_header(
                    publisher,
                    marker,
                    marker,
                    VersionVector::default(),
                    &[marker as u8],
                    &payload,
                    None,
                ),
                &payload,
            ));
        }
        let policy = store.control_policy_snapshot().expect("query policy");

        {
            let write = store.database.begin_write().expect("gap corruption write");
            {
                let mut order = write
                    .open_table(EVENT_ACCEPTANCE_ORDER)
                    .expect("acceptance order");
                assert!(order.remove(2).expect("remove middle marker").is_some());
            }
            write.commit().expect("commit middle gap");
        }
        assert!(matches!(
            store.query_event_candidates_with_policy(&policy, &EventQueryFilter::default(), 0, 3,),
            Err(StoreError::SemanticInvariant(
                "Event acceptance-order query encountered a nonconsecutive marker"
            ))
        ));

        {
            let write = store.database.begin_write().expect("tail corruption write");
            {
                let mut order = write
                    .open_table(EVENT_ACCEPTANCE_ORDER)
                    .expect("acceptance order");
                order
                    .insert(2, accepted[1].transfer_id.as_bytes().as_slice())
                    .expect("restore middle marker");
                assert!(order.remove(3).expect("remove tail marker").is_some());
            }
            write.commit().expect("commit truncated tail");
        }
        assert!(matches!(
            store.query_event_candidates_with_policy(&policy, &EventQueryFilter::default(), 0, 3,),
            Err(StoreError::SemanticInvariant(
                "Event acceptance-order query ended before durable acceptance high-water"
            ))
        ));
    }

    #[test]
    fn acceptance_order_migrates_legacy_live_store_reopens_and_rejects_corruption() {
        let file = TestFile::new("event-acceptance-order-migration");
        let mut services = event_services(0x43);
        let publisher = services.publisher.identity();
        let (first, second) = {
            let store =
                Store::open_for_mission(&file.0, services.authority).expect("fresh bound store");
            let first_payload = b"legacy first Event";
            let first = accept_event(
                &store,
                &mut services,
                event_header(
                    publisher,
                    1,
                    1,
                    VersionVector::default(),
                    b"first",
                    first_payload,
                    None,
                ),
                first_payload,
            );
            let second_payload = b"legacy second Event";
            let second = accept_event(
                &store,
                &mut services,
                event_header(
                    publisher,
                    2,
                    2,
                    VersionVector::default(),
                    b"second",
                    second_payload,
                    None,
                ),
                second_payload,
            );
            (first, second)
        };

        {
            let database = Database::open(&file.0).expect("open legacy simulation");
            let write = database.begin_write().expect("legacy simulation write");
            write
                .delete_table(EVENT_ACCEPTANCE_ORDER)
                .expect("remove post-legacy index");
            write.commit().expect("commit legacy simulation");
        }
        assert_eq!(
            Store::inspect_existing(&file.0)
                .expect("legacy store remains read-only inspectable")
                .event_stats
                .events,
            2
        );

        {
            let migrated = Store::open_for_mission(&file.0, services.authority)
                .expect("live open backfills acceptance order");
            let policy = migrated.control_policy_snapshot().expect("migrated policy");
            let page = migrated
                .query_event_candidates_with_policy(
                    &policy,
                    &EventQueryFilter::default(),
                    0,
                    MAX_EVENT_PAGE,
                )
                .expect("query migrated order");
            assert_eq!(page.events, vec![first.clone(), second.clone()]);
            assert_eq!(page.scanned_through, 2);
            assert!(!page.has_more);
        }
        assert_eq!(
            Store::inspect_existing(&file.0)
                .expect("persisted backfill reopens read-only")
                .event_stats
                .events,
            2
        );

        {
            let database = Database::open(&file.0).expect("open corrupt index");
            let write = database.begin_write().expect("corrupt index write");
            {
                let mut order = write
                    .open_table(EVENT_ACCEPTANCE_ORDER)
                    .expect("acceptance order");
                order
                    .insert(1, second.transfer_id.as_bytes().as_slice())
                    .expect("misindex first marker");
            }
            write.commit().expect("commit corrupt index");
        }
        assert!(matches!(
            Store::inspect_existing(&file.0),
            Err(StoreError::SemanticInvariant(
                "Event acceptance-order index differs from its forward marker"
            ))
        ));
        assert!(matches!(
            Store::open_for_mission(&file.0, services.authority),
            Err(StoreError::SemanticInvariant(
                "Event acceptance-order index differs from its forward marker"
            ))
        ));
    }

    #[test]
    fn wrong_kind_acceptance_order_fails_closed_without_unrelated_migration() {
        let file = TestFile::new("event-acceptance-order-wrong-kind");
        let services = event_services(0x45);
        {
            let store =
                Store::open_for_mission(&file.0, services.authority).expect("initialized store");
            assert_eq!(
                store.control_stats().expect("initialized control stats"),
                ControlStoreStats::default()
            );
        }
        {
            let database = Database::open(&file.0).expect("open wrong-kind store");
            let write = database.begin_write().expect("wrong-kind write");
            write
                .open_table(METADATA)
                .expect("metadata")
                .remove(SEMANTIC_ITEM_COUNT)
                .expect("remove unrelated migration target");
            write
                .delete_table(EVENT_ACCEPTANCE_ORDER)
                .expect("remove regular acceptance order");
            let definition =
                redb::MultimapTableDefinition::<u64, &[u8]>::new(EVENT_ACCEPTANCE_ORDER.name());
            write
                .open_multimap_table(definition)
                .expect("wrong-kind acceptance order")
                .insert(1, b"wrong-kind".as_slice())
                .expect("wrong-kind row");
            write.commit().expect("commit wrong-kind schema");
        }

        for result in [
            Store::inspect_existing(&file.0).map(|_| ()),
            Store::open_for_mission(&file.0, services.authority).map(|_| ()),
        ] {
            assert!(
                matches!(
                    &result,
                    Err(StoreError::SemanticInvariant(
                        "Event acceptance-order index has the wrong table kind"
                    ))
                ),
                "unexpected wrong-kind result: {result:?}"
            );
        }

        let database = redb::Builder::new()
            .open_read_only(&file.0)
            .expect("read wrong-kind store");
        let read = database.begin_read().expect("read transaction");
        assert!(
            read.open_table(METADATA)
                .expect("metadata")
                .get(SEMANTIC_ITEM_COUNT)
                .expect("unrelated migration target")
                .is_none(),
            "wrong-kind rejection must not repair unrelated Event accounting"
        );
        assert!(
            !read
                .list_tables()
                .expect("regular tables")
                .any(|table| table.name() == EVENT_ACCEPTANCE_ORDER.name())
        );
        assert!(
            read.list_multimap_tables()
                .expect("multimap tables")
                .any(|table| table.name() == EVENT_ACCEPTANCE_ORDER.name())
        );
    }

    #[test]
    fn route_only_content_tamper_cannot_create_semantic_ledgers_or_poison_valid_content() {
        let file = TestFile::new("route-content-boundary");
        let mut services = event_services(0x51);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let payload = b"content authenticated separately";
        let header = event_header(
            services.publisher.identity(),
            1,
            1,
            VersionVector::default(),
            b"content",
            payload,
            None,
        );
        let sealed = services
            .publisher
            .seal_event(&header, payload)
            .expect("seal Event");
        let mut tampered = sealed.bytes.clone();
        *tampered.last_mut().expect("sealed content") ^= 1;
        let route = services
            .relay
            .verify_event(&tampered)
            .expect("route metadata remains authenticated");
        store
            .cache_route_verified_event(&route, &tampered)
            .expect("bounded route cache");
        let alternate = services
            .publisher
            .seal_event(&header, payload)
            .expect("alternate randomized representation");
        let alternate_route = services
            .relay
            .verify_event(&alternate.bytes)
            .expect("alternate route token");
        store
            .cache_route_verified_event(&alternate_route, &alternate.bytes)
            .expect("second bounded route representation");
        let member_route = services
            .reader
            .verify_event(&tampered)
            .expect("member route verification");
        assert!(
            services
                .reader
                .verify_event_content(member_route, &tampered)
                .is_err()
        );
        assert_eq!(store.event_stats().expect("cache stats").events, 0);
        assert_eq!(store.event_stats().expect("cache stats").route_cached, 2);
        assert_eq!(store.event_gaps().expect("no semantic gaps"), Vec::new());

        let valid = content_event(&mut services.reader, &sealed.bytes);
        store
            .apply_verified_event(&valid, &sealed.bytes)
            .expect("valid content remains admissible");
        let stats = store.event_stats().expect("separate stats");
        assert_eq!(stats.events, 1);
        assert_eq!(stats.route_cached, 0);
        assert_eq!(
            store
                .transfer_inventory()
                .expect("combined inventory")
                .len(),
            1
        );
    }

    #[test]
    fn exact_stream_gap_plan_is_bounded_verified_and_race_rechecked() {
        let file = TestFile::new("event-gap-scan-plan");
        let mut services = event_services(0x60);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let policy = store.control_policy_snapshot().expect("gap policy");
        let publisher = services.publisher.identity();
        let mut accepted = Vec::new();
        for sequence in [1u64, 3] {
            let payload = format!("gap boundary {sequence}").into_bytes();
            accepted.push(accept_event(
                &store,
                &mut services,
                event_header(
                    publisher,
                    sequence,
                    sequence,
                    VersionVector::default(),
                    &[sequence as u8],
                    &payload,
                    None,
                ),
                &payload,
            ));
        }
        let unrelated_payload = b"another exact topic stream";
        let mut unrelated_header = event_header(
            publisher,
            4,
            1,
            VersionVector::default(),
            b"unrelated",
            unrelated_payload,
            None,
        );
        unrelated_header.topic = reaction_topic();
        accept_event(&store, &mut services, unrelated_header, unrelated_payload);
        let fifth_payload = b"gap boundary 5";
        accepted.push(accept_event(
            &store,
            &mut services,
            event_header(
                publisher,
                5,
                5,
                VersionVector::default(),
                b"five",
                fifth_payload,
                None,
            ),
            fifth_payload,
        ));

        for requested in [0, MAX_EVENT_PAGE + 1] {
            assert!(matches!(
                store.prepare_event_gap_scan_with_policy(
                    &policy,
                    publisher,
                    &event_topic(),
                    &event_scope(),
                    0,
                    requested,
                ),
                Err(StoreError::EventPageLimitExceeded {
                    requested: observed,
                    maximum: MAX_EVENT_PAGE,
                }) if observed == requested
            ));
        }
        let plan = store
            .prepare_event_gap_scan_with_policy(
                &policy,
                publisher,
                &event_topic(),
                &event_scope(),
                0,
                2,
            )
            .expect("bounded exact-stream plan");
        assert_eq!(plan.control_policy(), &policy);
        assert_eq!(plan.publisher(), publisher);
        assert_eq!(plan.topic(), &event_topic());
        assert_eq!(plan.scope(), &event_scope());
        assert_eq!(plan.after_sequence(), 0);
        assert_eq!(plan.scan_limit(), 2);
        assert_eq!(
            plan.candidates()
                .iter()
                .map(EventGapCandidate::sequence)
                .collect::<Vec<_>>(),
            vec![1, 3]
        );
        assert_eq!(plan.candidates()[0].event(), &accepted[0]);
        assert_eq!(plan.candidates()[1].event(), &accepted[1]);
        assert_eq!(plan.scanned_through(), 3);
        assert_eq!(plan.high_water(), 5);
        assert!(plan.has_more(), "sequence 5 remains beyond the bound");
        for candidate in plan.candidates() {
            let verified = content_event(&mut services.reader, &candidate.event().sealed);
            assert_eq!(
                EventTransferId::new(verified.envelope_id()),
                candidate.event().transfer_id
            );
        }
        store
            .require_event_gap_scan_plan_with_policy(&policy, &plan)
            .expect("freshly verified plan remains exact");

        let second_payload = b"late sequence 2 closes the first structural gap";
        accept_event(
            &store,
            &mut services,
            event_header(
                publisher,
                2,
                2,
                VersionVector::default(),
                b"two",
                second_payload,
                None,
            ),
            second_payload,
        );
        assert!(matches!(
            store.require_event_gap_scan_plan_with_policy(&policy, &plan),
            Err(StoreError::EventGapScanPlanChanged)
        ));
        let current = store
            .prepare_event_gap_scan_with_policy(
                &policy,
                publisher,
                &event_topic(),
                &event_scope(),
                0,
                2,
            )
            .expect("replacement plan after race");
        assert_eq!(
            current
                .candidates()
                .iter()
                .map(EventGapCandidate::sequence)
                .collect::<Vec<_>>(),
            vec![1, 2]
        );
        assert_eq!(current.high_water(), 5);
        assert!(current.has_more());
        let tail = store
            .prepare_event_gap_scan_with_policy(
                &policy,
                publisher,
                &event_topic(),
                &event_scope(),
                3,
                MAX_EVENT_PAGE,
            )
            .expect("tail boundary plan");
        assert_eq!(tail.candidates().len(), 1);
        assert_eq!(tail.candidates()[0].sequence(), 5);
        assert_eq!(tail.scanned_through(), 5);
        assert_eq!(tail.high_water(), 5);
        assert!(!tail.has_more());
        let beyond = store
            .prepare_event_gap_scan_with_policy(
                &policy,
                publisher,
                &event_topic(),
                &event_scope(),
                10,
                1,
            )
            .expect("boundary beyond high-water");
        assert!(beyond.candidates().is_empty());
        assert_eq!(beyond.scanned_through(), 10);
        assert_eq!(beyond.high_water(), 5);
        assert!(!beyond.has_more());

        drop(store);
        let store = Store::open_for_mission(&file.0, services.authority)
            .expect("gap plan store reopens cleanly");
        let reopened_policy = store.control_policy_snapshot().expect("reopened policy");
        store
            .require_event_gap_scan_plan_with_policy(&reopened_policy, &current)
            .expect("exact plan survives a clean reopen");
        {
            let write = store
                .database
                .begin_write()
                .expect("begin position corruption");
            write
                .open_table(ACCEPTED_EVENTS)
                .expect("accepted positions")
                .remove(
                    accepted_event_key(publisher, &event_topic(), &event_scope(), 2)
                        .expect("position key")
                        .as_slice(),
                )
                .expect("remove accepted position");
            write.commit().expect("commit position corruption");
        }
        assert!(matches!(
            store.require_event_gap_scan_plan_with_policy(&reopened_policy, &current),
            Err(StoreError::EventGapScanPlanChanged)
        ));
        drop(store);
        for result in [
            Store::inspect_existing(&file.0).map(|_| ()),
            Store::open_for_mission(&file.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::SemanticInvariant(
                    "Event metadata is missing its accepted-position ledger row"
                ))
            ));
        }
    }

    #[test]
    fn accepted_dot_and_event_position_ledgers_reject_equivocation_and_track_gaps() {
        let file = TestFile::new("event-ledgers");
        let mut services = event_services(0x61);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let publisher = services.publisher.identity();

        let mut accepted = Vec::new();
        for sequence in [1u64, 3] {
            let payload = format!("event-{sequence}").into_bytes();
            let header = event_header(
                publisher,
                sequence,
                sequence,
                VersionVector::default(),
                &[sequence as u8],
                &payload,
                None,
            );
            let sealed = services
                .publisher
                .seal_event(&header, &payload)
                .expect("seal out-of-order Event");
            let event = content_event(&mut services.reader, &sealed.bytes);
            store
                .apply_verified_event(&event, &sealed.bytes)
                .expect("accept out of order");
            accepted.push((event, sealed.bytes));
        }
        assert_eq!(
            store.event_gaps().expect("gap after 1,3"),
            vec![EventGap {
                publisher,
                topic: event_topic(),
                scope: event_scope(),
                start_sequence: 2,
                end_sequence: 3,
            }]
        );

        let payload = b"event-2";
        let second_header = event_header(
            publisher,
            2,
            2,
            VersionVector::default(),
            b"2",
            payload,
            None,
        );
        let second = services
            .publisher
            .seal_event(&second_header, payload)
            .expect("seal missing Event");
        let second_event = content_event(&mut services.reader, &second.bytes);
        store
            .apply_verified_event(&second_event, &second.bytes)
            .expect("close gap");
        assert!(store.event_gaps().expect("closed gap").is_empty());

        let conflicting_dot_payload = b"different dot payload";
        let conflicting_dot_header = event_header(
            publisher,
            1,
            4,
            VersionVector::default(),
            b"dot-conflict",
            conflicting_dot_payload,
            None,
        );
        let conflicting_dot = services
            .publisher
            .seal_event(&conflicting_dot_header, conflicting_dot_payload)
            .expect("seal dot conflict");
        let conflicting_dot_event = content_event(&mut services.reader, &conflicting_dot.bytes);
        assert!(matches!(
            store.apply_verified_event(&conflicting_dot_event, &conflicting_dot.bytes),
            Err(StoreError::CausalEquivocation {
                publisher: source,
                counter: 1
            }) if source == publisher
        ));

        let conflicting_position_payload = b"different position payload";
        let conflicting_position_header = event_header(
            publisher,
            4,
            1,
            VersionVector::default(),
            b"position-conflict",
            conflicting_position_payload,
            None,
        );
        let conflicting_position = services
            .publisher
            .seal_event(&conflicting_position_header, conflicting_position_payload)
            .expect("seal position conflict");
        let conflicting_position_event =
            content_event(&mut services.reader, &conflicting_position.bytes);
        assert!(matches!(
            store.apply_verified_event(
                &conflicting_position_event,
                &conflicting_position.bytes
            ),
            Err(StoreError::EventEquivocation {
                publisher: source,
                sequence: 1
            }) if source == publisher
        ));
    }

    #[test]
    fn operation_and_reaction_commit_are_atomic_causal_and_restart_idempotent() {
        let file = TestFile::new("operation-reaction");
        let mut services = event_services(0x71);
        let publisher = services.publisher.identity();
        let ping_key = EventOperationKey::new(b"sample/ping/once".to_vec()).expect("Ping key");
        let ping_alias_key =
            EventOperationKey::new(b"sample/ping/alias".to_vec()).expect("Ping alias key");
        let pong_key =
            EventOperationKey::new(b"sample/pong/for-ping-1".to_vec()).expect("Pong key");
        let ping_semantic;
        let pong_event;
        let pong_bytes;
        {
            let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
            let ping_payload = b"Ping";
            let ping_reservation = store
                .reserve_event(publisher, &event_topic(), &event_scope())
                .expect("reserve Ping");
            let ping_header = ping_reservation
                .header(
                    Priority::Immediate,
                    b"ping".to_vec(),
                    None,
                    ping_payload.len() as u64,
                    false,
                    1,
                )
                .expect("Ping header");
            let ping = services
                .publisher
                .seal_event(&ping_header, ping_payload)
                .expect("seal Ping");
            let ping_event = content_event(&mut services.reader, &ping.bytes);
            let ping_intent = event_publication_intent(&ping_header, ping_payload);
            let ping_request =
                EventOperationRequest::new(&ping_key, &ping_intent, ping_payload, None)
                    .expect("Ping request");
            let ping_outcome = store
                .commit_reserved_event_once(
                    &ping_request,
                    &ping_reservation,
                    &ping_event,
                    &ping.bytes,
                )
                .expect("atomic Ping");
            ping_semantic = match ping_outcome {
                EventOnceOutcome::Inserted { semantic_id, .. } => semantic_id,
                EventOnceOutcome::BoundExisting { .. } => {
                    panic!("first Ping cannot bind an existing Event")
                }
                EventOnceOutcome::Existing { .. } => panic!("first Ping is new"),
                EventOnceOutcome::Retired { .. } => panic!("first Ping cannot be retired"),
            };
            let ping_alias_request =
                EventOperationRequest::new(&ping_alias_key, &ping_intent, ping_payload, None)
                    .expect("Ping alias request");
            assert!(matches!(
                store
                    .commit_reserved_event_once(
                        &ping_alias_request,
                        &ping_reservation,
                        &ping_event,
                        &ping.bytes,
                    )
                    .expect("bind a new operation to the accepted exact Ping"),
                EventOnceOutcome::BoundExisting { .. }
            ));
            let after_alias = store.event_stats().expect("alias stats");
            assert_eq!(after_alias.events, 1);
            assert_eq!(after_alias.acceptance_markers, 1);

            let pong_payload = b"Pong";
            let ordinary_pong_reservation = store
                .reserve_event(publisher, &reaction_topic(), &event_scope())
                .expect("ordinary cross-topic reservation");
            assert!(
                !ordinary_pong_reservation
                    .context()
                    .observes(ping_event.dot())
            );
            let pong_reservation = store
                .reserve_reaction_event(publisher, &reaction_topic(), &event_scope(), ping_semantic)
                .expect("reserve cross-topic Pong reaction");
            assert!(pong_reservation.context().observes(ping_event.dot()));
            let pong_header = pong_reservation
                .header(
                    Priority::Immediate,
                    ping_semantic.as_bytes().to_vec(),
                    None,
                    pong_payload.len() as u64,
                    false,
                    1,
                )
                .expect("Pong header");
            let sealed_pong = services
                .publisher
                .seal_event(&pong_header, pong_payload)
                .expect("seal Pong");
            pong_event = content_event(&mut services.reader, &sealed_pong.bytes);
            pong_bytes = sealed_pong.bytes;
            let pong_intent = event_publication_intent(&pong_header, pong_payload);
            let pong_request = EventOperationRequest::new(
                &pong_key,
                &pong_intent,
                pong_payload,
                Some(ping_semantic),
            )
            .expect("Pong request");
            assert!(matches!(
                store
                    .commit_reserved_event_once(
                        &pong_request,
                        &pong_reservation,
                        &pong_event,
                        &pong_bytes,
                    )
                    .expect("atomic reaction"),
                EventOnceOutcome::Inserted { .. }
            ));
            let wrong_predecessor =
                EventOperationRequest::new(&pong_key, &pong_intent, pong_payload, None)
                    .expect("wrong predecessor request");
            assert!(matches!(
                store.commit_reserved_event_once(
                    &wrong_predecessor,
                    &pong_reservation,
                    &pong_event,
                    &pong_bytes,
                ),
                Err(StoreError::OperationPredecessorMismatch)
            ));
        }

        let reopened = Store::open_for_mission(&file.0, services.authority).expect("reopen");
        assert!(
            reopened
                .event_for_operation(&ping_key)
                .expect("Ping operation")
                .is_some()
        );
        assert!(
            reopened
                .event_for_operation(&ping_alias_key)
                .expect("Ping alias operation")
                .is_some()
        );
        let stale_reservation = reopened
            .reserve_event(publisher, &event_topic(), &event_scope())
            .expect("stale retry reservation");
        let pong_intent = event_publication_intent(pong_event.header(), b"Pong");
        let pong_request =
            EventOperationRequest::new(&pong_key, &pong_intent, b"Pong", Some(ping_semantic))
                .expect("reopened Pong request");
        assert!(matches!(
            reopened
                .commit_reserved_event_once(
                    &pong_request,
                    &stale_reservation,
                    &pong_event,
                    &pong_bytes,
                )
                .expect("operation result wins before reservation"),
            EventOnceOutcome::Existing { .. }
        ));
        let stats = reopened.event_stats().expect("Event stats");
        assert_eq!(stats.events, 2);
        assert_eq!(stats.acceptance_markers, 2);
        let usage = reopened.aggregate_usage().expect("aggregate usage");
        assert_eq!(usage.items, 5, "two Events plus three operation rows");
        assert_eq!(
            usage.payload_bytes,
            stats.total_sealed_bytes + stats.operation_bytes,
            "aggregate usage includes both Event and operation bytes"
        );
        assert!(usage.items <= reopened.limits().max_items());
        assert!(usage.payload_bytes <= reopened.limits().max_total_payload_bytes());
    }

    #[test]
    fn finite_ttl_fails_closed_for_route_remote_and_local_durability() {
        let file = TestFile::new("ttl-fail-closed");
        let mut services = event_services(0x81);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let payload = b"finite TTL";
        let header = event_header(
            services.publisher.identity(),
            1,
            1,
            VersionVector::default(),
            b"ttl",
            payload,
            Some(100),
        );
        let sealed = services
            .publisher
            .seal_event(&header, payload)
            .expect("seal TTL Event");
        let route = services
            .relay
            .verify_event(&sealed.bytes)
            .expect("route TTL Event");
        assert!(matches!(
            store.cache_route_verified_event(&route, &sealed.bytes),
            Err(StoreError::AuthenticatedCustodyAgeRequired)
        ));
        let event = content_event(&mut services.reader, &sealed.bytes);
        assert!(matches!(
            store.apply_verified_event(&event, &sealed.bytes),
            Err(StoreError::AuthenticatedCustodyAgeRequired)
        ));
        let reservation = store
            .reserve_event(
                services.publisher.identity(),
                &event_topic(),
                &event_scope(),
            )
            .expect("reserve local TTL Event");
        let local_header = reservation
            .header(
                Priority::Immediate,
                b"local-ttl".to_vec(),
                Some(100),
                payload.len() as u64,
                false,
                1,
            )
            .expect("local TTL header");
        let local = services
            .publisher
            .seal_event(&local_header, payload)
            .expect("seal local TTL Event");
        let local_event = content_event(&mut services.reader, &local.bytes);
        assert!(matches!(
            store.commit_reserved_event(&reservation, &local_event, &local.bytes),
            Err(StoreError::AuthenticatedCustodyAgeRequired)
        ));
        assert_eq!(store.event_stats().expect("empty stats").events, 0);
    }

    #[test]
    fn route_cache_caps_each_semantic_claim_and_aggregate_quota_spans_namespaces() {
        let file = TestFile::new("route-cache-cap");
        let mut services = event_services(0x91);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let payload = b"randomized route representation";
        let header = event_header(
            services.publisher.identity(),
            1,
            1,
            VersionVector::default(),
            b"route-cap",
            payload,
            None,
        );
        for index in 0..=MAX_ROUTE_CACHE_REPRESENTATIONS_PER_SEMANTIC {
            let sealed = services
                .publisher
                .seal_event(&header, payload)
                .expect("randomized seal");
            let route = services
                .relay
                .verify_event(&sealed.bytes)
                .expect("route token");
            let outcome = store.cache_route_verified_event(&route, &sealed.bytes);
            if index < MAX_ROUTE_CACHE_REPRESENTATIONS_PER_SEMANTIC {
                outcome.expect("within per-semantic cap");
            } else {
                assert!(matches!(
                    outcome,
                    Err(StoreError::RouteCacheSemanticRepresentationLimit { .. })
                ));
            }
        }
        assert_eq!(
            store.event_stats().expect("route cache stats").route_cached,
            MAX_ROUTE_CACHE_REPRESENTATIONS_PER_SEMANTIC
        );

        let quota_file = TestFile::new("aggregate-quota");
        let limits = StoreLimits::new(
            MAX_CONTROL_ITEMS + CUSTODY_EMERGENCY_ITEM_RESERVE + 2,
            MAX_CONTROL_BYTES + CUSTODY_EMERGENCY_BYTE_RESERVE + 1024 * 1024,
        )
        .expect("limits");
        let quota_store =
            Store::open_with_limits_for_mission(&quota_file.0, limits, services.authority)
                .expect("quota store");
        quota_store
            .apply(item(0xaa), b"opaque")
            .expect("opaque namespace");
        let cached_payload = b"cached";
        let cached_header = event_header(
            services.publisher.identity(),
            10,
            10,
            VersionVector::default(),
            b"cached",
            cached_payload,
            None,
        );
        let cached = services
            .publisher
            .seal_event(&cached_header, cached_payload)
            .expect("cache seal");
        let cached_route = services
            .relay
            .verify_event(&cached.bytes)
            .expect("cache route");
        quota_store
            .cache_route_verified_event(&cached_route, &cached.bytes)
            .expect("route namespace");
        let semantic_payload = b"semantic";
        let semantic_header = event_header(
            services.publisher.identity(),
            11,
            11,
            VersionVector::default(),
            b"semantic",
            semantic_payload,
            None,
        );
        let semantic = services
            .publisher
            .seal_event(&semantic_header, semantic_payload)
            .expect("semantic seal");
        let semantic_event = content_event(&mut services.reader, &semantic.bytes);
        assert!(matches!(
            quota_store.apply_verified_event(&semantic_event, &semantic.bytes),
            Err(StoreError::ItemLimitExceeded {
                current: 2,
                limit: 2
            })
        ));
    }

    #[test]
    fn read_only_inspection_reports_all_namespaces_without_mutating_the_store() {
        let file = TestFile::new("inspect-semantic-namespaces");
        let mut services = event_services(0xa1);
        {
            let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
            store.apply(item(0xa1), b"opaque").expect("opaque item");

            let accepted_payload = b"accepted";
            let accepted_header = event_header(
                services.publisher.identity(),
                1,
                1,
                VersionVector::default(),
                b"accepted",
                accepted_payload,
                None,
            );
            let accepted = services
                .publisher
                .seal_event(&accepted_header, accepted_payload)
                .expect("seal accepted Event");
            let accepted_event = content_event(&mut services.reader, &accepted.bytes);
            store
                .apply_verified_event(&accepted_event, &accepted.bytes)
                .expect("accept semantic Event");

            let cached_payload = b"route-only";
            let cached_header = event_header(
                services.publisher.identity(),
                2,
                2,
                VersionVector::default(),
                b"cached",
                cached_payload,
                None,
            );
            let cached = services
                .publisher
                .seal_event(&cached_header, cached_payload)
                .expect("seal cached Event");
            let cached_route = services
                .relay
                .verify_event(&cached.bytes)
                .expect("route cached Event");
            store
                .cache_route_verified_event(&cached_route, &cached.bytes)
                .expect("cache route Event");
        }
        let bytes_before = std::fs::read(&file.0).expect("read before inspection");
        let modified_before = std::fs::metadata(&file.0)
            .expect("metadata before inspection")
            .modified()
            .expect("modified before inspection");
        let inspection = Store::inspect_existing(&file.0).expect("strict read-only inspection");
        assert_eq!(inspection.stats.items, 1);
        assert_eq!(inspection.event_stats.events, 1);
        assert_eq!(inspection.event_stats.acceptance_markers, 1);
        assert_eq!(inspection.event_stats.route_cached, 1);
        assert!(inspection.event_stats.total_sealed_bytes > 0);
        assert!(inspection.event_stats.route_cached_bytes > 0);
        assert_eq!(inspection.mission_authority, Some(services.authority));
        assert_eq!(
            std::fs::read(&file.0).expect("read after inspection"),
            bytes_before
        );
        assert_eq!(
            std::fs::metadata(&file.0)
                .expect("metadata after inspection")
                .modified()
                .expect("modified after inspection"),
            modified_before
        );
    }

    #[test]
    fn read_only_inspection_rejects_partial_schema_and_inflated_high_water() {
        let partial = TestFile::new("inspect-partial-semantic-schema");
        {
            let store = Store::open(&partial.0).expect("create current schema");
            let write = store
                .database
                .begin_write()
                .expect("begin schema corruption");
            write
                .delete_table(ROUTE_CACHE_CLAIMS)
                .expect("delete one semantic table");
            write.commit().expect("commit partial schema");
        }
        assert!(matches!(
            Store::inspect_existing(&partial.0),
            Err(StoreError::SemanticInvariant(
                "mission-scoped Event schema is incomplete"
            ))
        ));

        let inflated = TestFile::new("inspect-inflated-high-water");
        let mut services = event_services(0xa2);
        {
            let store =
                Store::open_for_mission(&inflated.0, services.authority).expect("bound store");
            let payload = b"audited";
            let header = event_header(
                services.publisher.identity(),
                1,
                1,
                VersionVector::default(),
                b"audit",
                payload,
                None,
            );
            let sealed = services
                .publisher
                .seal_event(&header, payload)
                .expect("seal audited Event");
            let event = content_event(&mut services.reader, &sealed.bytes);
            store
                .apply_verified_event(&event, &sealed.bytes)
                .expect("accept audited Event");
        }
        {
            let database = Database::open(&inflated.0).expect("open raw database");
            let write = database.begin_write().expect("begin high-water corruption");
            write
                .open_table(PUBLISHER_HIGH_WATER)
                .expect("publisher high-water")
                .insert(services.publisher.identity().as_slice(), 99)
                .expect("inflate publisher high-water");
            write.commit().expect("commit high-water corruption");
        }
        let corrupted = std::fs::read(&inflated.0).expect("read corrupted store");
        assert!(matches!(
            Store::inspect_existing(&inflated.0),
            Err(StoreError::SemanticInvariant(
                "publisher high-water contains an orphan, missing, or inflated row"
            ))
        ));
        assert_eq!(
            std::fs::read(&inflated.0).expect("failed inspection is read-only"),
            corrupted
        );
        assert!(matches!(
            Store::open_for_mission(&inflated.0, services.authority),
            Err(StoreError::SemanticInvariant(
                "publisher high-water contains an orphan, missing, or inflated row"
            ))
        ));
    }

    #[test]
    fn controls_apply_only_as_exact_contiguous_suffix_and_restart_replays_fresh_verification() {
        let file = TestFile::new("control-contiguous-restart");
        let mut services = control_services(0xb1);
        let first = services
            .authority
            .seal_chained_revocation_control([0x71; 32], 1, 1, None)
            .expect("first control");
        let first_verified = verify_control(&mut services.verifier, &first);
        let first_id = ControlTransferId::new(first_verified.envelope_id());
        let second = services
            .authority
            .seal_chained_revocation_control([0x72; 32], 1, 2, Some(first_verified.envelope_id()))
            .expect("second control");
        let second_verified = verify_control(&mut services.verifier, &second);
        let second_id = ControlTransferId::new(second_verified.envelope_id());
        let third = services
            .authority
            .seal_chained_revocation_control([0x73; 32], 1, 3, Some(second_verified.envelope_id()))
            .expect("third control");
        let third_verified = verify_control(&mut services.verifier, &third);
        let third_id = ControlTransferId::new(third_verified.envelope_id());

        {
            let store = Store::open_for_mission(&file.0, services.authority_id)
                .expect("mission-bound store");
            let pending = store
                .ingest_verified_control(&third_verified, &third)
                .expect("retain out-of-order third");
            assert!(
                matches!(pending, ControlOutcome::Pending { transfer_id } if transfer_id == third_id)
            );
            assert!(pending.activated().is_empty());
            assert!(store.applied_controls().expect("applied prefix").is_empty());

            let ControlOutcome::Applied { activated, .. } = store
                .ingest_verified_control(&first_verified, &first)
                .expect("apply first")
            else {
                panic!("first link must apply");
            };
            assert_eq!(
                activated
                    .iter()
                    .map(|control| control.transfer_id)
                    .collect::<Vec<_>>(),
                vec![first_id]
            );
            assert!(
                activated
                    .iter()
                    .all(|control| control.applied && control.priority() == Priority::Flash)
            );

            let duplicate = store
                .ingest_verified_control(&first_verified, &first)
                .expect("duplicate first");
            assert!(
                matches!(duplicate, ControlOutcome::Duplicate { transfer_id } if transfer_id == first_id)
            );
            assert!(duplicate.activated().is_empty());

            let ControlOutcome::Applied { activated, .. } = store
                .ingest_verified_control(&second_verified, &second)
                .expect("close pending gap")
            else {
                panic!("second must activate itself and third");
            };
            assert_eq!(
                activated
                    .iter()
                    .map(|control| control.transfer_id)
                    .collect::<Vec<_>>(),
                vec![second_id, third_id]
            );
            assert_eq!(store.control_head().expect("head"), Some((3, third_id)));
            assert_eq!(store.control_inventory().expect("inventory").len(), 3);
            assert!(store.event_inventory().expect("Event inventory").is_empty());
            assert_eq!(
                store.control_stats().expect("control stats"),
                ControlStoreStats {
                    controls: 3,
                    applied: 3,
                    pending: 0,
                    total_sealed_bytes: (first.len() + second.len() + third.len()) as u64,
                    publication_intent_bytes: 0,
                    head_sequence: 3,
                    revocations: 3,
                    scope_epochs: 0,
                    reservation_receipts: 0,
                    scope_rekey_recipient_backfills_required: 0,
                }
            );
        }

        let reopened =
            Store::open_for_mission(&file.0, services.authority_id).expect("reopen audited store");
        let applied = reopened
            .applied_controls()
            .expect("restart applied controls");
        assert_eq!(
            applied
                .iter()
                .map(|control| control.transfer_id)
                .collect::<Vec<_>>(),
            vec![first_id, second_id, third_id]
        );
        let mut fresh_verifier = ReferenceEnvelopeSealer::open(
            ProvisioningBundle::from_bytes(&services.verifier_bundle)
                .expect("restore verifier bundle"),
        )
        .expect("fresh verifier");
        for stored in applied {
            let verified = fresh_verifier
                .verify_control(&stored.sealed)
                .expect("fresh restart verification");
            assert_eq!(verified.envelope_id(), *stored.transfer_id.as_bytes());
            assert_eq!(verified.authority_id(), stored.authority);
            assert_eq!(verified.signer(), stored.signer);
            assert_eq!(verified.control_sequence(), stored.sequence);
            assert_eq!(
                verified.previous_control(),
                stored.previous_control.map(|id| *id.as_bytes())
            );
            let ready = fresh_verifier
                .prepare_committed_control_activation(&verified, &stored.sealed)
                .expect("prepare only audited applied row");
            fresh_verifier
                .activate_committed_control(ready, false)
                .expect("idempotent restart activation");
        }
        drop(reopened);
        let inspection = Store::inspect_existing(&file.0).expect("strict read-only inspection");
        assert_eq!(inspection.control_stats.applied, 3);
        assert_eq!(inspection.mission_authority, Some(services.authority_id));
    }

    #[test]
    fn authenticated_pending_predecessor_and_rollback_poison_is_purged_without_losing_gap_closer() {
        let predecessor_file = TestFile::new("control-pending-predecessor-poison");
        let mut services = control_services(0xa7);
        let first = services
            .authority
            .seal_chained_revocation_control([0x61; 32], 1, 1, None)
            .expect("valid first control");
        let first_verified = verify_control(&mut services.verifier, &first);
        let first_id = ControlTransferId::new(first_verified.envelope_id());
        let poisoned = services
            .authority
            .seal_chained_revocation_control([0x62; 32], 1, 2, Some([0xee; 32]))
            .expect("authenticated wrong-predecessor control");
        let poisoned_verified = verify_control(&mut services.verifier, &poisoned);
        let poisoned_id = ControlTransferId::new(poisoned_verified.envelope_id());
        let dependent = services
            .authority
            .seal_chained_revocation_control(
                [0x63; 32],
                1,
                3,
                Some(poisoned_verified.envelope_id()),
            )
            .expect("dependent poisoned suffix");
        let dependent_verified = verify_control(&mut services.verifier, &dependent);
        let dependent_id = ControlTransferId::new(dependent_verified.envelope_id());
        {
            let store = Store::open_for_mission(&predecessor_file.0, services.authority_id)
                .expect("predecessor poison store");
            assert!(matches!(
                store
                    .ingest_verified_control(&poisoned_verified, &poisoned)
                    .expect("retain poisoned second"),
                ControlOutcome::Pending { .. }
            ));
            assert!(matches!(
                store
                    .ingest_verified_control(&dependent_verified, &dependent)
                    .expect("retain dependent third"),
                ControlOutcome::Pending { .. }
            ));
        }
        let store = Store::open_for_mission(&predecessor_file.0, services.authority_id)
            .expect("reopen predecessor poison");
        let ControlOutcome::Applied {
            activated,
            rejected,
            ..
        } = store
            .ingest_verified_control(&first_verified, &first)
            .expect("valid gap closer commits while poison is purged")
        else {
            panic!("valid first control must apply");
        };
        assert_eq!(
            activated
                .iter()
                .map(|control| control.transfer_id)
                .collect::<Vec<_>>(),
            vec![first_id]
        );
        assert_eq!(
            rejected,
            vec![
                RejectedControl {
                    transfer_id: poisoned_id,
                    signer: poisoned_verified.signer(),
                    reason: ControlRejectionReason::PredecessorMismatch,
                },
                RejectedControl {
                    transfer_id: dependent_id,
                    signer: dependent_verified.signer(),
                    reason: ControlRejectionReason::InvalidatedPredecessor(poisoned_id),
                },
            ]
        );
        assert_eq!(
            store.control_head().expect("stable head"),
            Some((1, first_id))
        );
        assert_eq!(
            store.control_stats().expect("purged accounting"),
            ControlStoreStats {
                controls: 1,
                applied: 1,
                pending: 0,
                total_sealed_bytes: first.len() as u64,
                publication_intent_bytes: 0,
                head_sequence: 1,
                revocations: 1,
                scope_epochs: 0,
                reservation_receipts: 0,
                scope_rekey_recipient_backfills_required: 0,
            }
        );
        assert!(
            store
                .get_control(poisoned_id)
                .expect("poison lookup")
                .is_none()
        );
        drop(store);
        Store::open_for_mission(&predecessor_file.0, services.authority_id)
            .expect("reopen audited predecessor cleanup");

        let rollback_file = TestFile::new("control-pending-effect-rollback");
        let mut rollback_services = control_services(0xa8);
        let subject = [0x64; 32];
        let newer = rollback_services
            .authority
            .seal_chained_revocation_control(subject, 2, 1, None)
            .expect("newer gap closer");
        let newer_verified = verify_control(&mut rollback_services.verifier, &newer);
        let newer_id = ControlTransferId::new(newer_verified.envelope_id());
        let rollback = rollback_services
            .authority
            .seal_chained_revocation_control(subject, 1, 2, Some(newer_verified.envelope_id()))
            .expect("rollback suffix");
        let rollback_verified = verify_control(&mut rollback_services.verifier, &rollback);
        let rollback_id = ControlTransferId::new(rollback_verified.envelope_id());
        {
            let store = Store::open_for_mission(&rollback_file.0, rollback_services.authority_id)
                .expect("rollback poison store");
            assert!(matches!(
                store
                    .ingest_verified_control(&rollback_verified, &rollback)
                    .expect("retain rollback pending"),
                ControlOutcome::Pending { .. }
            ));
        }
        let store = Store::open_for_mission(&rollback_file.0, rollback_services.authority_id)
            .expect("reopen rollback poison");
        let ControlOutcome::Applied {
            activated,
            rejected,
            ..
        } = store
            .ingest_verified_control(&newer_verified, &newer)
            .expect("newer revocation commits and purges rollback")
        else {
            panic!("newer revocation must apply");
        };
        assert_eq!(activated[0].transfer_id, newer_id);
        assert_eq!(
            rejected,
            vec![RejectedControl {
                transfer_id: rollback_id,
                signer: rollback_verified.signer(),
                reason: ControlRejectionReason::EffectRollback,
            }]
        );
        assert_eq!(store.control_stats().expect("rollback stats").pending, 0);
        assert_eq!(
            store.active_revocation(subject).expect("newer active"),
            Some((2, newer_id))
        );
        assert!(
            store
                .get_control(rollback_id)
                .expect("rollback lookup")
                .is_none()
        );
        drop(store);
        Store::open_for_mission(&rollback_file.0, rollback_services.authority_id)
            .expect("reopen audited rollback cleanup");
    }

    #[test]
    fn rejected_sequence_fence_blocks_replayed_descendants_until_valid_alternate_applies() {
        let file = TestFile::new("control-rejected-sequence-fence");
        let mut services = control_services(0xa9);
        let rollback_subject = [0x71; 32];
        let first = services
            .authority
            .seal_chained_revocation_control(rollback_subject, 2, 1, None)
            .expect("newer first revocation");
        let first_verified = verify_control(&mut services.verifier, &first);
        let first_id = ControlTransferId::new(first_verified.envelope_id());
        let rejected = services
            .authority
            .seal_chained_revocation_control(
                rollback_subject,
                1,
                2,
                Some(first_verified.envelope_id()),
            )
            .expect("authenticated rollback");
        let rejected_verified = verify_control(&mut services.verifier, &rejected);
        let rejected_id = ControlTransferId::new(rejected_verified.envelope_id());
        let descendant = services
            .authority
            .seal_chained_revocation_control(
                [0x72; 32],
                1,
                3,
                Some(rejected_verified.envelope_id()),
            )
            .expect("authenticated rejected descendant");
        let descendant_verified = verify_control(&mut services.verifier, &descendant);
        let descendant_id = ControlTransferId::new(descendant_verified.envelope_id());

        {
            let store = Store::open_for_mission(&file.0, services.authority_id).expect("store");
            store
                .ingest_verified_control(&first_verified, &first)
                .expect("apply first");
            assert!(matches!(
                store
                    .ingest_verified_control(&descendant_verified, &descendant)
                    .expect("retain out-of-order descendant"),
                ControlOutcome::Pending { transfer_id } if transfer_id == descendant_id
            ));
            let outcome = store
                .ingest_verified_control(&rejected_verified, &rejected)
                .expect("reject rollback and purge descendant");
            assert!(matches!(
                outcome,
                ControlOutcome::Rejected {
                    transfer_id,
                    reason: ControlRejectionReason::EffectRollback,
                    ..
                } if transfer_id == rejected_id
            ));
            assert_eq!(store.control_stats().expect("purged stats").pending, 0);
        }

        let store = Store::open_for_mission(&file.0, services.authority_id)
            .expect("reopen with durable rejection fence");
        assert!(matches!(
            store
                .ingest_verified_control(&descendant_verified, &descendant)
                .expect("reject replayed descendant"),
            ControlOutcome::Rejected {
                transfer_id,
                reason: ControlRejectionReason::RejectedSequenceFence(2),
                ..
            } if transfer_id == descendant_id
        ));
        assert!(matches!(
            store
                .ingest_verified_control(&rejected_verified, &rejected)
                .expect("reject replayed bad link"),
            ControlOutcome::Rejected {
                transfer_id,
                reason: ControlRejectionReason::EffectRollback,
                ..
            } if transfer_id == rejected_id
        ));
        assert_eq!(
            store.control_stats().expect("replay-stable stats"),
            ControlStoreStats {
                controls: 1,
                applied: 1,
                pending: 0,
                total_sealed_bytes: first.len() as u64,
                publication_intent_bytes: 0,
                head_sequence: 1,
                revocations: 1,
                scope_epochs: 0,
                reservation_receipts: 0,
                scope_rekey_recipient_backfills_required: 0,
            }
        );

        let alternate = services
            .authority
            .seal_chained_revocation_control([0x73; 32], 1, 2, Some(first_verified.envelope_id()))
            .expect("valid alternate link");
        let alternate_verified = verify_control(&mut services.verifier, &alternate);
        let alternate_id = ControlTransferId::new(alternate_verified.envelope_id());
        assert!(matches!(
            store
                .ingest_verified_control(&alternate_verified, &alternate)
                .expect("valid alternate clears fence"),
            ControlOutcome::Applied { .. }
        ));
        let successor = services
            .authority
            .seal_chained_revocation_control(
                [0x74; 32],
                1,
                3,
                Some(alternate_verified.envelope_id()),
            )
            .expect("valid successor");
        let successor_verified = verify_control(&mut services.verifier, &successor);
        let successor_id = ControlTransferId::new(successor_verified.envelope_id());
        store
            .ingest_verified_control(&successor_verified, &successor)
            .expect("successor applies after fence clears");
        assert_eq!(
            store.control_head().expect("advanced head"),
            Some((3, successor_id))
        );
        assert_eq!(
            store
                .find_applied_control_effect(&StoredControlEffect::Revocation {
                    subject: [0x73; 32],
                    generation: 1,
                })
                .expect("alternate lookup"),
            Some(alternate_id)
        );
        drop(store);
        Store::open_for_mission(&file.0, services.authority_id)
            .expect("reopen after valid alternate cleared fence");
        assert_eq!(
            first_id,
            ControlTransferId::new(first_verified.envelope_id())
        );
    }

    #[test]
    fn legacy_scope_epoch_is_historical_before_revocation_but_rejected_afterward() {
        let historical_file = TestFile::new("control-legacy-scope-before-revocation");
        let mut historical = control_services(0xaa);
        let legacy = historical
            .authority
            .seal_scope_epoch_control(&event_scope(), 1, 1, None)
            .expect("legacy scope epoch");
        let legacy_verified = verify_control(&mut historical.verifier, &legacy);
        let legacy_id = ControlTransferId::new(legacy_verified.envelope_id());
        let revocation = historical
            .authority
            .seal_chained_revocation_control([0x75; 32], 1, 2, Some(legacy_verified.envelope_id()))
            .expect("later revocation");
        let revocation_verified = verify_control(&mut historical.verifier, &revocation);
        {
            let store = Store::open_for_mission(&historical_file.0, historical.authority_id)
                .expect("historical store");
            store
                .ingest_verified_control(&legacy_verified, &legacy)
                .expect("pre-revocation legacy scope remains historical");
            store
                .ingest_verified_control(&revocation_verified, &revocation)
                .expect("later revocation applies");
            assert_eq!(
                store
                    .active_scope_epoch(&event_scope())
                    .expect("historical scope epoch"),
                Some((1, legacy_id))
            );
        }
        Store::open_for_mission(&historical_file.0, historical.authority_id)
            .expect("historical ordering reopens");

        let rejected_file = TestFile::new("control-legacy-scope-after-revocation");
        let mut rejected_services = control_services(0xab);
        let first = rejected_services
            .authority
            .seal_chained_revocation_control([0x76; 32], 1, 1, None)
            .expect("first revocation");
        let first_verified = verify_control(&mut rejected_services.verifier, &first);
        let legacy_after = rejected_services
            .authority
            .seal_scope_epoch_control(&event_scope(), 1, 2, Some(first_verified.envelope_id()))
            .expect("legacy post-revocation scope epoch");
        let legacy_after_verified = verify_control(&mut rejected_services.verifier, &legacy_after);
        let legacy_after_id = ControlTransferId::new(legacy_after_verified.envelope_id());
        let legacy_far = rejected_services
            .authority
            .seal_scope_epoch_control(&event_scope(), 1, 3, Some([0xee; 32]))
            .expect("out-of-order legacy post-revocation scope epoch");
        let legacy_far_verified = verify_control(&mut rejected_services.verifier, &legacy_far);
        let legacy_far_id = ControlTransferId::new(legacy_far_verified.envelope_id());
        let store = Store::open_for_mission(&rejected_file.0, rejected_services.authority_id)
            .expect("rejection store");
        store
            .ingest_verified_control(&first_verified, &first)
            .expect("apply first revocation");
        assert!(matches!(
            store
                .ingest_verified_control(&legacy_far_verified, &legacy_far)
                .expect("reject out-of-order legacy scope without recipient evidence"),
            ControlOutcome::Rejected {
                transfer_id,
                reason: ControlRejectionReason::LegacyRecipientSetUnavailable,
                ..
            } if transfer_id == legacy_far_id
        ));
        assert!(
            store
                .get_control(legacy_far_id)
                .expect("out-of-order legacy lookup")
                .is_none()
        );
        assert!(matches!(
            store
                .ingest_verified_control(&legacy_after_verified, &legacy_after)
                .expect("reject legacy scope without recipient evidence"),
            ControlOutcome::Rejected {
                transfer_id,
                reason: ControlRejectionReason::LegacyRecipientSetUnavailable,
                ..
            } if transfer_id == legacy_after_id
        ));
        assert!(
            store
                .active_scope_epoch(&event_scope())
                .expect("no unsafe scope activation")
                .is_none()
        );
        assert_eq!(store.control_stats().expect("rejection stats").controls, 1);
        drop(store);
        Store::open_for_mission(&rejected_file.0, rejected_services.authority_id)
            .expect("rejected legacy scope does not poison reopen");
    }

    #[test]
    fn local_control_reservation_is_atomic_idempotent_and_cannot_survive_race_or_tamper() {
        let file = TestFile::new("control-local-reservation");
        let mut services = control_services(0xb2);
        let store = Store::open_for_mission(&file.0, services.authority_id).expect("store");
        let principal = services
            .authority
            .verified_control_principal()
            .expect("verified principal");
        let reservation = store.reserve_control(principal).expect("reserve first");
        let sealed = services
            .authority
            .seal_chained_revocation_control(
                [0x81; 32],
                1,
                reservation.sequence(),
                reservation.previous_control().map(|id| *id.as_bytes()),
            )
            .expect("seal reserved control");
        let verified = verify_control(&mut services.verifier, &sealed);
        let transfer_id = ControlTransferId::new(verified.envelope_id());
        assert!(matches!(
            store
                .commit_reserved_control(&reservation, &verified, &sealed)
                .expect("commit reserved control"),
            ControlOutcome::Applied { ref activated, .. }
                if activated.iter().map(|row| row.transfer_id).collect::<Vec<_>>() == vec![transfer_id]
        ));
        assert_eq!(
            store.control_stats().expect("stats").reservation_receipts,
            1
        );
        assert!(
            store
                .local_control_receipt_matches(transfer_id, principal)
                .expect("exact local receipt proof")
        );
        assert_eq!(
            store
                .find_applied_control_effect(&StoredControlEffect::Revocation {
                    subject: [0x81; 32],
                    generation: 1,
                })
                .expect("historical effect lookup"),
            Some(transfer_id)
        );
        assert!(matches!(
            store
                .commit_reserved_control(&reservation, &verified, &sealed)
                .expect("exact local replay"),
            ControlOutcome::Duplicate { transfer_id: id } if id == transfer_id
        ));

        let stale = store.reserve_control(principal).expect("stale reservation");
        let remote = services
            .authority
            .seal_chained_revocation_control(
                [0x82; 32],
                1,
                stale.sequence(),
                stale.previous_control().map(|id| *id.as_bytes()),
            )
            .expect("remote winner");
        let remote_verified = verify_control(&mut services.verifier, &remote);
        let remote_id = ControlTransferId::new(remote_verified.envelope_id());
        store
            .ingest_verified_control(&remote_verified, &remote)
            .expect("remote winner applies");
        assert!(
            !store
                .local_control_receipt_matches(remote_id, principal)
                .expect("remote input has no local receipt")
        );
        let loser = services
            .authority
            .seal_chained_revocation_control(
                [0x83; 32],
                1,
                stale.sequence(),
                stale.previous_control().map(|id| *id.as_bytes()),
            )
            .expect("stale loser");
        let loser_verified = verify_control(&mut services.verifier, &loser);
        assert!(matches!(
            store.commit_reserved_control(&stale, &loser_verified, &loser),
            Err(StoreError::ControlReservationChanged)
        ));
        assert_eq!(
            store
                .control_stats()
                .expect("stats after race")
                .reservation_receipts,
            1,
            "the rejected race cannot write a reservation receipt"
        );

        let mut tampered = remote.clone();
        *tampered.last_mut().expect("sealed control") ^= 1;
        assert!(matches!(
            store.ingest_verified_control(&remote_verified, &tampered),
            Err(StoreError::ControlVerification(_))
        ));

        let wrong = control_services(0xb3);
        let wrong_file = TestFile::new("control-wrong-authority");
        let wrong_store =
            Store::open_for_mission(&wrong_file.0, wrong.authority_id).expect("wrong store");
        assert!(matches!(
            wrong_store.ingest_verified_control(&remote_verified, &remote),
            Err(StoreError::MissionAuthorityMismatch { .. })
        ));
        assert_eq!(
            wrong_store.control_stats().expect("wrong stats").controls,
            0
        );
    }

    #[test]
    fn revoked_signer_far_future_suffix_is_purged_and_recovery_survives_restart() {
        let file = TestFile::new("control-revoked-future");
        let mut provisioner = ReferenceProvisioner::from_seed([0xb4; 32]).expect("provisioner");
        let access = ProvisioningAccess::member(event_scope(), vec![1], vec![event_topic()])
            .expect("access");
        let old_bundle = provisioner
            .issue_control_authority(1, std::slice::from_ref(&access))
            .expect("old signer");
        let recovery_bundle = provisioner
            .issue_control_authority(2, std::slice::from_ref(&access))
            .expect("recovery signer");
        let verifier_bundle = provisioner.issue_node(3, &[access]).expect("verifier");
        let mut old = ReferenceEnvelopeSealer::open(old_bundle).expect("old signer service");
        let mut recovery =
            ReferenceEnvelopeSealer::open(recovery_bundle).expect("recovery service");
        let mut verifier =
            ReferenceEnvelopeSealer::open(verifier_bundle).expect("verifier service");
        let authority_id = recovery.mission_authority_id();
        let old_signer = old.identity();

        let first = recovery
            .seal_chained_revocation_control(old_signer, 1, 1, None)
            .expect("revoke old signer");
        let first_verified = verify_control(&mut verifier, &first);
        let first_id = ControlTransferId::new(first_verified.envelope_id());
        let valid_two = recovery
            .seal_chained_revocation_control([0x91; 32], 1, 2, Some(first_verified.envelope_id()))
            .expect("valid recovery link");
        let valid_two_verified = verify_control(&mut verifier, &valid_two);
        let valid_two_id = ControlTransferId::new(valid_two_verified.envelope_id());
        let poisoned = old
            .seal_chained_revocation_control([0x92; 32], 1, 1_000_000, Some([0xee; 32]))
            .expect("far-future poisoned link");
        let poisoned_verified = verify_control(&mut verifier, &poisoned);
        let poisoned_id = ControlTransferId::new(poisoned_verified.envelope_id());

        {
            let store = Store::open_for_mission(&file.0, authority_id).expect("store");
            assert!(matches!(
                store
                    .ingest_verified_control(&poisoned_verified, &poisoned)
                    .expect("retain poison pending"),
                ControlOutcome::Pending { .. }
            ));
            assert!(matches!(
                store
                    .ingest_verified_control(&valid_two_verified, &valid_two)
                    .expect("retain valid second pending"),
                ControlOutcome::Pending { .. }
            ));
        }
        let store = Store::open_for_mission(&file.0, authority_id).expect("restart with pending");
        let ControlOutcome::Applied {
            activated,
            rejected,
            ..
        } = store
            .ingest_verified_control(&first_verified, &first)
            .expect("commit revocation and recovery")
        else {
            panic!("revocation must activate recovery prefix");
        };
        assert_eq!(
            activated
                .iter()
                .map(|control| control.transfer_id)
                .collect::<Vec<_>>(),
            vec![first_id, valid_two_id]
        );
        assert_eq!(
            rejected,
            vec![RejectedControl {
                transfer_id: poisoned_id,
                signer: old_signer,
                reason: ControlRejectionReason::SignerRevoked(old_signer),
            }]
        );
        assert!(
            store
                .get_control(poisoned_id)
                .expect("poison query")
                .is_none()
        );
        assert!(
            store
                .is_control_principal_revoked(old_signer)
                .expect("old signer revocation")
        );
        assert_eq!(
            store
                .active_revocation(old_signer)
                .expect("active revocation source"),
            Some((1, first_id))
        );

        let rejected_three = old
            .seal_chained_revocation_control(
                [0x93; 32],
                1,
                3,
                Some(valid_two_verified.envelope_id()),
            )
            .expect("revoked signer candidate");
        let rejected_three_verified = verify_control(&mut verifier, &rejected_three);
        let outcome = store
            .ingest_verified_control(&rejected_three_verified, &rejected_three)
            .expect("attribute revoked input");
        assert!(matches!(outcome, ControlOutcome::Rejected { .. }));
        assert_eq!(
            outcome.rejected_input().map(|value| value.signer),
            Some(old_signer)
        );
        let old_principal = old
            .verified_control_principal()
            .expect("old cryptographic principal remains inspectable");
        assert!(matches!(
            store.reserve_control(old_principal),
            Err(StoreError::ControlSignerRevoked(node)) if node == old_signer
        ));
        assert_eq!(store.control_stats().expect("stats").controls, 2);
    }

    #[test]
    fn control_fork_rollback_quota_and_forward_inverse_tamper_fail_atomically() {
        let file = TestFile::new("control-fork-rollback");
        let mut services = control_services(0xb5);
        let target = [0xa1; 32];
        let first = services
            .authority
            .seal_chained_revocation_control(target, 2, 1, None)
            .expect("first");
        let first_verified = verify_control(&mut services.verifier, &first);
        let first_id = ControlTransferId::new(first_verified.envelope_id());
        {
            let store = Store::open_for_mission(&file.0, services.authority_id).expect("store");
            store
                .ingest_verified_control(&first_verified, &first)
                .expect("apply first");
            let fork = services
                .authority
                .seal_chained_revocation_control([0xa2; 32], 1, 1, None)
                .expect("fork");
            let fork_verified = verify_control(&mut services.verifier, &fork);
            assert!(matches!(
                store.ingest_verified_control(&fork_verified, &fork),
                Err(StoreError::ControlFork)
            ));
            let wrong_predecessor = services
                .authority
                .seal_chained_revocation_control(target, 3, 2, Some([0xff; 32]))
                .expect("wrong predecessor candidate");
            let wrong_predecessor_verified =
                verify_control(&mut services.verifier, &wrong_predecessor);
            assert!(matches!(
                store
                    .ingest_verified_control(&wrong_predecessor_verified, &wrong_predecessor)
                    .expect("reject authenticated wrong predecessor"),
                ControlOutcome::Rejected {
                    reason: ControlRejectionReason::PredecessorMismatch,
                    ..
                }
            ));
            let rollback = services
                .authority
                .seal_chained_revocation_control(target, 1, 2, Some(first_verified.envelope_id()))
                .expect("rollback");
            let rollback_verified = verify_control(&mut services.verifier, &rollback);
            assert!(matches!(
                store
                    .ingest_verified_control(&rollback_verified, &rollback)
                    .expect("reject authenticated rollback"),
                ControlOutcome::Rejected {
                    reason: ControlRejectionReason::EffectRollback,
                    ..
                }
            ));
            assert_eq!(store.control_stats().expect("atomic stats").controls, 1);
            assert_eq!(store.control_head().expect("head"), Some((1, first_id)));
        }

        let database = Database::open(&file.0).expect("raw tamper open");
        let write = database.begin_write().expect("raw tamper write");
        write
            .open_table(CONTROL_REVOCATIONS)
            .expect("revocations")
            .remove(target.as_slice())
            .expect("remove inverse index");
        write.commit().expect("commit tamper");
        drop(database);
        assert!(matches!(
            Store::inspect_existing(&file.0),
            Err(StoreError::ControlInvariant(_))
        ));
        assert!(matches!(
            Store::open_for_mission(&file.0, services.authority_id),
            Err(StoreError::ControlInvariant(_))
        ));

        let quota_file = TestFile::new("control-aggregate-quota");
        let limits = StoreLimits::new(
            MAX_CONTROL_ITEMS + CUSTODY_EMERGENCY_ITEM_RESERVE + 1,
            u64::MAX,
        )
        .expect("limits");
        let quota =
            Store::open_with_limits_for_mission(&quota_file.0, limits, services.authority_id)
                .expect("quota store");
        quota
            .apply(item(0xf1), b"opaque")
            .expect("fill opaque quota");
        assert!(matches!(
            quota
                .ingest_verified_control(&first_verified, &first)
                .expect("control consumes the emergency reserve"),
            ControlOutcome::Applied { .. }
        ));
        assert_eq!(quota.control_stats().expect("quota stats").controls, 1);

        let reverse_file = TestFile::new("control-first-classified-ordinary-quota");
        let reverse =
            Store::open_with_limits_for_mission(&reverse_file.0, limits, services.authority_id)
                .expect("reverse quota store");
        assert!(matches!(
            reverse
                .ingest_verified_control(&first_verified, &first)
                .expect("control first"),
            ControlOutcome::Applied { .. }
        ));
        reverse
            .apply(item(0xf2), b"opaque")
            .expect("classified ordinary capacity is independent of admission order");
        assert_eq!(reverse.control_stats().expect("reverse stats").controls, 1);

        let byte_file = TestFile::new("control-byte-quota");
        let byte_limits =
            StoreLimits::new(10, (first.len() as u64).saturating_sub(1)).expect("byte limits");
        let byte_store =
            Store::open_with_limits_for_mission(&byte_file.0, byte_limits, services.authority_id)
                .expect("byte quota store");
        assert!(matches!(
            byte_store.ingest_verified_control(&first_verified, &first),
            Err(StoreError::PayloadByteLimitExceeded { .. })
        ));
        assert_eq!(byte_store.control_stats().expect("byte stats").controls, 0);

        let dedicated_file = TestFile::new("control-dedicated-quota");
        let dedicated =
            Store::open_for_mission(&dedicated_file.0, services.authority_id).expect("store");
        let prepared = PreparedControl::from_verified(&first_verified, &first).expect("prepared");
        {
            let write = dedicated
                .database
                .begin_write()
                .expect("item cap transaction");
            write
                .open_table(METADATA)
                .expect("metadata")
                .insert(CONTROL_ITEM_COUNT, MAX_CONTROL_ITEMS)
                .expect("stage item cap");
            assert!(matches!(
                insert_control(&write, &prepared, dedicated.limits(), 0),
                Err(StoreError::ControlItemLimitExceeded { .. })
            ));
            // Dropping this deliberately uncommitted transaction models an
            // admission failure: neither the synthetic counter nor a control
            // row may become durable.
        }
        assert_eq!(
            dedicated
                .control_stats()
                .expect("item cap rollback")
                .controls,
            0
        );
        {
            let write = dedicated
                .database
                .begin_write()
                .expect("byte cap transaction");
            write
                .open_table(METADATA)
                .expect("metadata")
                .insert(CONTROL_TOTAL_BYTES, MAX_CONTROL_BYTES)
                .expect("stage byte cap");
            assert!(matches!(
                insert_control(&write, &prepared, dedicated.limits(), 0),
                Err(StoreError::ControlByteLimitExceeded { .. })
            ));
        }
        assert_eq!(
            dedicated
                .control_stats()
                .expect("byte cap rollback")
                .controls,
            0
        );
    }

    #[test]
    fn scope_epoch_rollback_is_rejected_without_changing_durable_effect_state() {
        let file = TestFile::new("control-scope-rollback");
        let mut services = control_services(0xb6);
        let recipients = vec![
            ScopeRekeyRecipient::member(services.authority.identity(), vec![event_topic()])
                .expect("authority recipient"),
            ScopeRekeyRecipient::member(services.verifier.identity(), vec![event_topic()])
                .expect("verifier recipient"),
        ];
        let (first, registry_generation) = services
            .authority
            .seal_chained_scope_rekey_control_from_registry(
                &services.registry,
                0,
                event_scope(),
                2,
                recipients.clone(),
                1,
                None,
            )
            .expect("scope epoch two");
        let first_verified = verify_control(&mut services.verifier, &first);
        let first_id = ControlTransferId::new(first_verified.envelope_id());
        let store = Store::open_for_mission(&file.0, services.authority_id).expect("store");
        store
            .ingest_verified_control(&first_verified, &first)
            .expect("apply scope epoch two");
        assert_eq!(
            store
                .active_scope_epoch(&event_scope())
                .expect("active epoch"),
            Some((2, first_id))
        );
        let remote_intent = ScopeRekeyPublicationIntent::new(
            services
                .authority
                .verified_control_principal()
                .expect("principal"),
            &services.registry,
            registry_generation,
            event_scope(),
            2,
            &recipients,
        )
        .expect("candidate retry intent");
        assert!(matches!(
            store.verify_scope_rekey_publication_intent(first_id, &remote_intent),
            Err(StoreError::ControlPublicationIntentUnknown { transfer_id })
                if transfer_id == first_id
        ));

        let (rollback, _) = services
            .authority
            .seal_chained_scope_rekey_control_from_registry(
                &services.registry,
                0,
                event_scope(),
                1,
                recipients,
                2,
                Some(first_verified.envelope_id()),
            )
            .expect("authenticated rollback candidate");
        let rollback_verified = verify_control(&mut services.verifier, &rollback);
        assert!(matches!(
            store
                .ingest_verified_control(&rollback_verified, &rollback)
                .expect("reject authenticated scope rollback"),
            ControlOutcome::Rejected {
                reason: ControlRejectionReason::EffectRollback,
                ..
            }
        ));
        assert_eq!(
            store
                .active_scope_epoch(&event_scope())
                .expect("stable epoch"),
            Some((2, first_id))
        );
        assert_eq!(store.control_stats().expect("stats").controls, 1);
    }

    #[test]
    fn local_scope_rekey_intent_is_crash_idempotent_and_rejects_changed_retry_inputs() {
        let file = TestFile::new("control-rekey-intent");
        let mut services = control_services(0xc1);
        let principal = services
            .authority
            .verified_control_principal()
            .expect("control principal");
        let recipients = vec![
            ScopeRekeyRecipient::member(services.verifier.identity(), vec![event_topic()])
                .expect("verifier recipient"),
            ScopeRekeyRecipient::member(services.authority.identity(), vec![event_topic()])
                .expect("authority recipient"),
        ];
        let reservation = {
            let store =
                Store::open_for_mission(&file.0, services.authority_id).expect("intent store");
            store.reserve_control(principal).expect("reserve rekey")
        };
        let plan = services
            .authority
            .plan_scope_rekey_control_from_registry(
                &services.registry,
                0,
                event_scope(),
                2,
                recipients.clone(),
            )
            .expect("plan rekey");
        let registry_generation = plan.registry_generation();
        let (sealed, publication) = services
            .authority
            .seal_chained_scope_rekey_control_for_publication(
                &plan,
                reservation.sequence(),
                reservation.previous_control().map(|id| *id.as_bytes()),
            )
            .expect("seal rekey");
        let verified = verify_control(&mut services.verifier, &sealed);
        let transfer_id = ControlTransferId::new(verified.envelope_id());
        let intent = ScopeRekeyPublicationIntent::new(
            principal,
            &services.registry,
            registry_generation,
            event_scope(),
            2,
            &recipients,
        )
        .expect("canonical intent");

        {
            let store =
                Store::open_for_mission(&file.0, services.authority_id).expect("commit store");
            assert!(matches!(
                store.commit_reserved_control(&reservation, &verified, &sealed),
                Err(StoreError::MissingControlPublicationIntent)
            ));
            assert_eq!(store.control_stats().expect("unmutated stats").controls, 0);
            assert!(matches!(
                store
                    .commit_reserved_scope_rekey_control(
                        &reservation,
                        &verified,
                        &sealed,
                        &publication,
                        &intent,
                    )
                    .expect("commit with intent"),
                ControlOutcome::Applied { .. }
            ));
            store
                .verify_scope_rekey_publication_intent(transfer_id, &intent)
                .expect("exact committed intent");
            store
                .verify_scope_rekey_publication_request(
                    transfer_id,
                    principal,
                    &services.registry,
                    event_scope(),
                    2,
                    &recipients,
                )
                .expect("exact request uses committed registry generation");
            let mut expected_nodes = recipients
                .iter()
                .map(ScopeRekeyRecipient::node)
                .collect::<Vec<_>>();
            expected_nodes.sort_unstable();
            assert_eq!(
                store
                    .get_control(transfer_id)
                    .expect("stored rekey")
                    .expect("rekey row")
                    .scope_rekey_recipients,
                Some(expected_nodes)
            );
        }

        let reopened =
            Store::open_for_mission(&file.0, services.authority_id).expect("crash reopen");
        assert!(matches!(
            reopened
                .commit_reserved_scope_rekey_control(
                    &reservation,
                    &verified,
                    &sealed,
                    &publication,
                    &intent,
                )
                .expect("exact retry after lost response"),
            ControlOutcome::Duplicate { transfer_id: id } if id == transfer_id
        ));
        let mut reordered = recipients.clone();
        reordered.reverse();
        let reordered_intent = ScopeRekeyPublicationIntent::new(
            principal,
            &services.registry,
            registry_generation,
            event_scope(),
            2,
            &reordered,
        )
        .expect("reordered equivalent intent");
        assert_eq!(reordered_intent, intent);
        reopened
            .verify_scope_rekey_publication_intent(transfer_id, &reordered_intent)
            .expect("reordered intent remains exact");
        reopened
            .verify_scope_rekey_publication_request(
                transfer_id,
                principal,
                &services.registry,
                event_scope(),
                2,
                &reordered,
            )
            .expect("reordered request remains exact without provider authentication");

        let recipient = services.verifier.identity();
        let later_revocation = services
            .authority
            .seal_chained_revocation_control(recipient, 1, 2, Some(verified.envelope_id()))
            .expect("seal later recipient revocation");
        let later_revocation_verified = verify_control(&mut services.verifier, &later_revocation);
        assert!(matches!(
            reopened
                .ingest_verified_control(&later_revocation_verified, &later_revocation)
                .expect("apply later recipient revocation"),
            ControlOutcome::Applied { .. }
        ));
        assert!(matches!(
            reopened
                .commit_reserved_scope_rekey_control(
                    &reservation,
                    &verified,
                    &sealed,
                    &publication,
                    &intent,
                )
                .expect("historical exact commit retry after recipient revocation"),
            ControlOutcome::Duplicate { transfer_id: id } if id == transfer_id
        ));

        let changed_recipients = vec![
            ScopeRekeyRecipient::route_only(services.verifier.identity()),
            ScopeRekeyRecipient::member(services.authority.identity(), vec![event_topic()])
                .expect("authority recipient"),
        ];
        let changed_recipient_intent = ScopeRekeyPublicationIntent::new(
            principal,
            &services.registry,
            registry_generation,
            event_scope(),
            2,
            &changed_recipients,
        )
        .expect("changed recipient intent");
        assert!(matches!(
            reopened.verify_scope_rekey_publication_intent(
                transfer_id,
                &changed_recipient_intent
            ),
            Err(StoreError::ControlPublicationIntentConflict { transfer_id: id })
                if id == transfer_id
        ));
        assert!(matches!(
            reopened.verify_scope_rekey_publication_request(
                transfer_id,
                principal,
                &services.registry,
                event_scope(),
                2,
                &changed_recipients,
            ),
            Err(StoreError::ControlPublicationIntentConflict { transfer_id: id })
                if id == transfer_id
        ));
        assert!(matches!(
            reopened.commit_reserved_scope_rekey_control(
                &reservation,
                &verified,
                &sealed,
                &publication,
                &changed_recipient_intent,
            ),
            Err(StoreError::InvalidControlPublicationIntent)
        ));

        let mut changed_registry = services.registry.clone();
        *changed_registry.last_mut().expect("registry byte") ^= 1;
        let changed_registry_intent = ScopeRekeyPublicationIntent::new(
            principal,
            &changed_registry,
            registry_generation,
            event_scope(),
            2,
            &recipients,
        )
        .expect("changed registry identity");
        assert!(matches!(
            reopened
                .verify_scope_rekey_publication_intent(transfer_id, &changed_registry_intent),
            Err(StoreError::ControlPublicationIntentConflict { transfer_id: id })
                if id == transfer_id
        ));
        assert!(matches!(
            reopened.verify_scope_rekey_publication_request(
                transfer_id,
                principal,
                &changed_registry,
                event_scope(),
                2,
                &recipients,
            ),
            Err(StoreError::ControlPublicationIntentConflict { transfer_id: id })
                if id == transfer_id
        ));
        assert_eq!(reopened.control_stats().expect("stable stats").controls, 2);
        drop(reopened);

        {
            let database = Database::open(&file.0).expect("raw intent store");
            let write = database.begin_write().expect("intent tamper transaction");
            write
                .open_table(CONTROL_PUBLICATION_INTENTS)
                .expect("intent table")
                .remove(transfer_id.as_bytes().as_slice())
                .expect("remove intent");
            write.commit().expect("commit intent tamper");
        }
        assert!(matches!(
            Store::inspect_existing(&file.0),
            Err(StoreError::ControlInvariant(_))
        ));
        assert!(matches!(
            Store::open_for_mission(&file.0, services.authority_id),
            Err(StoreError::ControlInvariant(_))
        ));
    }

    #[test]
    fn scope_rekey_recipient_revocation_purges_pending_and_closes_local_commit_race() {
        let pending_file = TestFile::new("control-rekey-recipient-pending-revocation");
        let mut pending_services = control_services(0xc5);
        let revoked_recipient = pending_services.verifier.identity();
        let recipients = vec![
            ScopeRekeyRecipient::route_only(pending_services.authority.identity()),
            ScopeRekeyRecipient::content_only(revoked_recipient, vec![event_topic()])
                .expect("content-only recipient"),
        ];
        let revocation = pending_services
            .authority
            .seal_chained_revocation_control(revoked_recipient, 1, 1, None)
            .expect("recipient revocation");
        let revocation_verified = verify_control(&mut pending_services.verifier, &revocation);
        let revocation_id = ControlTransferId::new(revocation_verified.envelope_id());
        let plan = pending_services
            .authority
            .plan_scope_rekey_control_from_registry(
                &pending_services.registry,
                0,
                event_scope(),
                2,
                recipients.clone(),
            )
            .expect("plan pending rekey");
        let rekey = pending_services
            .authority
            .seal_chained_scope_rekey_control(&plan, 2, Some(revocation_verified.envelope_id()))
            .expect("seal pending rekey");
        let rekey_verified = verify_control(&mut pending_services.verifier, &rekey);
        let rekey_id = ControlTransferId::new(rekey_verified.envelope_id());
        let expected_nodes = plan.recipient_nodes().collect::<Vec<_>>();
        let pending_store =
            Store::open_for_mission(&pending_file.0, pending_services.authority_id).expect("store");
        assert!(matches!(
            pending_store
                .ingest_verified_control(&rekey_verified, &rekey)
                .expect("retain pre-revocation rekey"),
            ControlOutcome::Pending { transfer_id } if transfer_id == rekey_id
        ));
        assert_eq!(
            pending_store
                .get_control(rekey_id)
                .expect("pending lookup")
                .expect("pending row")
                .scope_rekey_recipients,
            Some(expected_nodes)
        );
        let ControlOutcome::Applied {
            activated,
            rejected,
            ..
        } = pending_store
            .ingest_verified_control(&revocation_verified, &revocation)
            .expect("activate recipient revocation")
        else {
            panic!("revocation must apply and reject the pending rekey");
        };
        assert_eq!(
            activated
                .iter()
                .map(|control| control.transfer_id)
                .collect::<Vec<_>>(),
            vec![revocation_id]
        );
        assert_eq!(
            rejected,
            vec![RejectedControl {
                transfer_id: rekey_id,
                signer: pending_services.authority.identity(),
                reason: ControlRejectionReason::ScopeRekeyRecipientRevoked(revoked_recipient),
            }]
        );
        assert!(
            pending_store
                .get_control(rekey_id)
                .expect("purged lookup")
                .is_none()
        );
        assert_eq!(
            pending_store.control_head().expect("revocation head"),
            Some((1, revocation_id))
        );
        assert_eq!(
            pending_store
                .control_stats()
                .expect("purged stats")
                .controls,
            1
        );

        let race_file = TestFile::new("control-rekey-recipient-commit-race");
        let mut race_services = control_services(0xc6);
        let race_recipient = race_services.verifier.identity();
        let race_recipients = vec![
            ScopeRekeyRecipient::route_only(race_services.authority.identity()),
            ScopeRekeyRecipient::content_only(race_recipient, vec![event_topic()])
                .expect("race content-only recipient"),
        ];
        let principal = race_services
            .authority
            .verified_control_principal()
            .expect("control principal");
        let race_store =
            Store::open_for_mission(&race_file.0, race_services.authority_id).expect("race store");
        let reservation = race_store
            .reserve_control(principal)
            .expect("reserve before race");
        let foreign_services = control_services(0xcb);
        let foreign_plan = foreign_services
            .authority
            .plan_scope_rekey_control_from_registry(
                &foreign_services.registry,
                0,
                event_scope(),
                2,
                vec![
                    ScopeRekeyRecipient::member(
                        foreign_services.verifier.identity(),
                        vec![event_topic()],
                    )
                    .expect("foreign recipient"),
                ],
            )
            .expect("foreign registry plan");
        assert!(
            race_services
                .authority
                .seal_chained_scope_rekey_control_for_publication(
                    &foreign_plan,
                    reservation.sequence(),
                    reservation.previous_control().map(|id| *id.as_bytes()),
                )
                .is_err()
        );
        assert_eq!(
            race_store
                .control_stats()
                .expect("foreign plan rejection stats"),
            ControlStoreStats::default()
        );
        assert_eq!(
            race_store
                .control_head()
                .expect("foreign plan rejection head"),
            None
        );
        let race_plan = race_services
            .authority
            .plan_scope_rekey_control_from_registry(
                &race_services.registry,
                0,
                event_scope(),
                2,
                race_recipients.clone(),
            )
            .expect("plan race rekey");
        let (race_rekey, race_publication) = race_services
            .authority
            .seal_chained_scope_rekey_control_for_publication(
                &race_plan,
                reservation.sequence(),
                reservation.previous_control().map(|id| *id.as_bytes()),
            )
            .expect("seal race rekey");
        let race_verified = verify_control(&mut race_services.verifier, &race_rekey);
        let race_rekey_id = ControlTransferId::new(race_verified.envelope_id());
        let intent = ScopeRekeyPublicationIntent::new(
            principal,
            &race_services.registry,
            race_plan.registry_generation(),
            event_scope(),
            2,
            &race_recipients,
        )
        .expect("race intent");
        let wrong_recipient_intent = ScopeRekeyPublicationIntent::new(
            principal,
            &race_services.registry,
            race_plan.registry_generation(),
            event_scope(),
            2,
            &[ScopeRekeyRecipient::route_only(
                race_services.authority.identity(),
            )],
        )
        .expect("wrong recipient intent");
        assert!(matches!(
            race_store.commit_reserved_scope_rekey_control(
                &reservation,
                &race_verified,
                &race_rekey,
                &race_publication,
                &wrong_recipient_intent,
            ),
            Err(StoreError::InvalidControlPublicationIntent)
        ));
        assert_eq!(
            race_store
                .control_stats()
                .expect("binding rollback")
                .controls,
            0
        );

        let changed_route_intent = ScopeRekeyPublicationIntent::new(
            principal,
            &race_services.registry,
            race_plan.registry_generation(),
            event_scope(),
            2,
            &[
                ScopeRekeyRecipient::route_only(race_services.authority.identity()),
                ScopeRekeyRecipient::member(race_recipient, vec![event_topic()])
                    .expect("changed route recipient"),
            ],
        )
        .expect("same-node changed-route intent");
        let changed_topic_intent = ScopeRekeyPublicationIntent::new(
            principal,
            &race_services.registry,
            race_plan.registry_generation(),
            event_scope(),
            2,
            &[
                ScopeRekeyRecipient::route_only(race_services.authority.identity()),
                ScopeRekeyRecipient::content_only(race_recipient, vec![reaction_topic()])
                    .expect("changed topic recipient"),
            ],
        )
        .expect("same-node changed-topic intent");
        let mut changed_registry = race_services.registry.clone();
        *changed_registry.last_mut().expect("registry byte") ^= 1;
        let changed_registry_intent = ScopeRekeyPublicationIntent::new(
            principal,
            &changed_registry,
            race_plan.registry_generation(),
            event_scope(),
            2,
            &race_recipients,
        )
        .expect("changed registry intent");
        let before_mismatches = race_store.control_stats().expect("pre-mismatch stats");
        for mismatched_intent in [
            &changed_route_intent,
            &changed_topic_intent,
            &changed_registry_intent,
        ] {
            assert!(matches!(
                race_store.commit_reserved_scope_rekey_control(
                    &reservation,
                    &race_verified,
                    &race_rekey,
                    &race_publication,
                    mismatched_intent,
                ),
                Err(StoreError::InvalidControlPublicationIntent)
            ));
            assert_eq!(
                race_store.control_stats().expect("atomic mismatch stats"),
                before_mismatches
            );
        }

        let (other_rekey, _other_publication) = race_services
            .authority
            .seal_chained_scope_rekey_control_for_publication(
                &race_plan,
                reservation.sequence(),
                reservation.previous_control().map(|id| *id.as_bytes()),
            )
            .expect("seal distinct exact output");
        let other_verified = verify_control(&mut race_services.verifier, &other_rekey);
        assert!(matches!(
            race_store.commit_reserved_scope_rekey_control(
                &reservation,
                &other_verified,
                &other_rekey,
                &race_publication,
                &intent,
            ),
            Err(StoreError::InvalidControlPublicationIntent)
        ));
        assert_eq!(
            race_store
                .control_stats()
                .expect("exact-envelope mismatch stats"),
            before_mismatches
        );
        assert_eq!(race_store.control_head().expect("mismatch head"), None);
        assert!(
            race_store
                .get_control(race_rekey_id)
                .expect("mismatch original lookup")
                .is_none()
        );
        assert!(
            race_store
                .get_control(ControlTransferId::new(other_verified.envelope_id()))
                .expect("mismatch alternate lookup")
                .is_none()
        );

        let prepared = PreparedControl::from_verified(&race_verified, &race_rekey)
            .expect("prepared recipient-bearing rekey");
        let mut legacy_without_recipients = prepared.encoded.clone();
        legacy_without_recipients[0] = LEGACY_CONTROL_METADATA_VERSION;
        legacy_without_recipients.truncate(
            legacy_without_recipients.len() - (1 + 2 + 32 * race_plan.recipient_nodes().len()),
        );
        let legacy_record =
            decode_control_record(&legacy_without_recipients).expect("decode legacy scope row");
        assert!(!legacy_record.scope_rekey_recipient_metadata_authenticated);
        assert_eq!(legacy_record.scope_rekey_recipients, None);

        let raced_revocation = race_services
            .authority
            .seal_chained_revocation_control(race_recipient, 1, 1, None)
            .expect("racing revocation");
        let raced_revocation_verified =
            verify_control(&mut race_services.verifier, &raced_revocation);
        let raced_revocation_id = ControlTransferId::new(raced_revocation_verified.envelope_id());
        race_store
            .ingest_verified_control(&raced_revocation_verified, &raced_revocation)
            .expect("commit racing revocation");
        assert!(matches!(
            race_store.ensure_scope_rekey_recipients_active(
                &race_plan.recipient_nodes().collect::<Vec<_>>()
            ),
            Err(StoreError::ControlRecipientRevoked(node)) if node == race_recipient
        ));
        let stable_stats = race_store.control_stats().expect("pre-rejection stats");
        assert!(matches!(
            race_store.commit_reserved_scope_rekey_control(
                &reservation,
                &race_verified,
                &race_rekey,
                &race_publication,
                &intent,
            ),
            Err(StoreError::ControlRecipientRevoked(node)) if node == race_recipient
        ));
        assert_eq!(
            race_store.control_stats().expect("atomic rejection stats"),
            stable_stats
        );
        assert_eq!(
            race_store.control_head().expect("unchanged race head"),
            Some((1, raced_revocation_id))
        );
        assert!(
            race_store
                .get_control(race_rekey_id)
                .expect("race lookup")
                .is_none()
        );
    }

    #[test]
    fn legacy_applied_and_pending_rekeys_require_authenticated_backfill_before_mutation() {
        let file = TestFile::new("control-legacy-rekey-recipient-backfill");
        let mut services = control_services(0xc7);
        let principal = services
            .authority
            .verified_control_principal()
            .expect("control principal");
        let recipients = vec![
            ScopeRekeyRecipient::route_only(services.authority.identity()),
            ScopeRekeyRecipient::content_only(services.verifier.identity(), vec![event_topic()])
                .expect("content-only recipient"),
        ];
        let store = Store::open_for_mission(&file.0, services.authority_id).expect("store");
        let reservation = store
            .reserve_control(principal)
            .expect("reserve applied rekey");
        let applied_plan = services
            .authority
            .plan_scope_rekey_control_from_registry(
                &services.registry,
                0,
                event_scope(),
                2,
                recipients.clone(),
            )
            .expect("plan applied rekey");
        let (applied, applied_publication) = services
            .authority
            .seal_chained_scope_rekey_control_for_publication(
                &applied_plan,
                reservation.sequence(),
                reservation.previous_control().map(|id| *id.as_bytes()),
            )
            .expect("seal applied rekey");
        let applied_verified = verify_control(&mut services.verifier, &applied);
        let applied_id = ControlTransferId::new(applied_verified.envelope_id());
        let intent = ScopeRekeyPublicationIntent::new(
            principal,
            &services.registry,
            applied_plan.registry_generation(),
            event_scope(),
            2,
            &recipients,
        )
        .expect("applied intent");
        assert!(matches!(
            store
                .commit_reserved_scope_rekey_control(
                    &reservation,
                    &applied_verified,
                    &applied,
                    &applied_publication,
                    &intent,
                )
                .expect("commit applied rekey"),
            ControlOutcome::Applied { .. }
        ));

        let pending_plan = services
            .authority
            .plan_scope_rekey_control_from_registry(
                &services.registry,
                0,
                event_scope(),
                3,
                recipients.clone(),
            )
            .expect("plan pending rekey");
        let pending = services
            .authority
            .seal_chained_scope_rekey_control(
                &pending_plan,
                3,
                Some(applied_verified.envelope_id()),
            )
            .expect("seal pending rekey");
        let pending_verified = verify_control(&mut services.verifier, &pending);
        let pending_id = ControlTransferId::new(pending_verified.envelope_id());
        assert!(matches!(
            store
                .ingest_verified_control(&pending_verified, &pending)
                .expect("retain pending rekey"),
            ControlOutcome::Pending { transfer_id } if transfer_id == pending_id
        ));
        let dependent_plan = services
            .authority
            .plan_scope_rekey_control_from_registry(
                &services.registry,
                0,
                event_scope(),
                4,
                recipients.clone(),
            )
            .expect("plan dependent pending rekey");
        let dependent = services
            .authority
            .seal_chained_scope_rekey_control(
                &dependent_plan,
                4,
                Some(pending_verified.envelope_id()),
            )
            .expect("seal dependent pending rekey");
        let dependent_verified = verify_control(&mut services.verifier, &dependent);
        let dependent_id = ControlTransferId::new(dependent_verified.envelope_id());
        assert!(matches!(
            store
                .ingest_verified_control(&dependent_verified, &dependent)
                .expect("retain dependent pending rekey"),
            ControlOutcome::Pending { transfer_id } if transfer_id == dependent_id
        ));
        downgrade_scope_rekey_recipient_metadata(&store, applied_id);
        downgrade_scope_rekey_recipient_metadata(&store, pending_id);
        downgrade_scope_rekey_recipient_metadata(&store, dependent_id);
        drop(store);

        assert_eq!(
            Store::inspect_existing(&file.0)
                .expect("read-only legacy inspection")
                .control_stats
                .scope_rekey_recipient_backfills_required,
            3
        );
        let reopened = Store::open_for_mission(&file.0, services.authority_id)
            .expect("legacy applied and pending rows reopen for bounded migration");
        assert_eq!(
            reopened
                .control_stats()
                .expect("legacy control stats")
                .scope_rekey_recipient_backfills_required,
            3
        );
        assert!(matches!(
            reopened.reserve_control(principal),
            Err(StoreError::ControlRecipientMetadataMigrationRequired { remaining: 3 })
        ));
        let gap_closer = services
            .authority
            .seal_chained_revocation_control([0xc7; 32], 1, 2, Some(applied_verified.envelope_id()))
            .expect("seal migration-gated ingest");
        let gap_closer_verified = verify_control(&mut services.verifier, &gap_closer);
        let gated_stats = reopened.control_stats().expect("pre-ingest legacy stats");
        assert!(matches!(
            reopened.ingest_verified_control(&gap_closer_verified, &gap_closer),
            Err(StoreError::ControlRecipientMetadataMigrationRequired { remaining: 3 })
        ));
        assert_eq!(
            reopened.control_stats().expect("gated ingest is atomic"),
            gated_stats
        );
        assert!(matches!(
            reopened.verify_scope_rekey_publication_request(
                applied_id,
                principal,
                &services.registry,
                event_scope(),
                2,
                &recipients,
            ),
            Err(StoreError::ControlRecipientMetadataMigrationRequired { remaining: 3 })
        ));

        let backfills = reopened
            .scope_rekey_recipient_backfill_controls()
            .expect("bounded backfill rows");
        assert_eq!(
            backfills
                .iter()
                .map(|control| (control.sequence, control.transfer_id))
                .collect::<Vec<_>>(),
            vec![(1, applied_id), (3, pending_id), (4, dependent_id)]
        );
        assert!(backfills.iter().all(|control| {
            !control.scope_rekey_recipient_metadata_authenticated
                && control.scope_rekey_recipients.is_none()
        }));
        let verified_backfills = backfills
            .iter()
            .map(|stored| {
                services
                    .verifier
                    .verify_control(&stored.sealed)
                    .expect("freshly authenticate legacy exact bytes")
            })
            .collect::<Vec<_>>();
        reopened
            .backfill_scope_rekey_recipients(&verified_backfills[0], &backfills[0].sealed)
            .expect("simulate one committed pre-batch migration row");
        drop(reopened);

        let reopened = Store::open_for_mission(&file.0, services.authority_id)
            .expect("reopen interrupted mixed-version migration");
        assert_eq!(
            reopened
                .control_stats()
                .expect("mixed-version migration stats")
                .scope_rekey_recipient_backfills_required,
            2
        );
        let authenticated_backfills = verified_backfills
            .iter()
            .zip(&backfills)
            .map(|(verified, stored)| (verified, stored.sealed.as_slice()))
            .collect::<Vec<_>>();
        reopened
            .backfill_scope_rekey_recipients_batch(&authenticated_backfills)
            .expect("one transaction migrates the remaining mixed-version batch");
        assert_eq!(
            reopened
                .control_stats()
                .expect("migrated stats")
                .scope_rekey_recipient_backfills_required,
            0
        );
        reopened
            .verify_scope_rekey_publication_request(
                applied_id,
                principal,
                &services.registry,
                event_scope(),
                2,
                &recipients,
            )
            .expect("historical exact match restored after migration");
        drop(reopened);

        let reopened =
            Store::open_for_mission(&file.0, services.authority_id).expect("reopen migrated store");
        assert_eq!(
            reopened
                .control_stats()
                .expect("reopened migrated stats")
                .scope_rekey_recipient_backfills_required,
            0
        );
        assert!(
            reopened
                .get_control(applied_id)
                .expect("applied migrated row")
                .expect("applied control")
                .scope_rekey_recipient_metadata_authenticated
        );
        assert!(
            reopened
                .get_control(pending_id)
                .expect("pending migrated row")
                .expect("pending control")
                .scope_rekey_recipient_metadata_authenticated
        );
        assert!(
            reopened
                .get_control(dependent_id)
                .expect("dependent pending migrated row")
                .expect("dependent pending control")
                .scope_rekey_recipient_metadata_authenticated
        );
    }

    #[test]
    fn recipient_backfill_batch_purges_a_revoked_pending_suffix_once() {
        let file = TestFile::new("control-recipient-backfill-batch-purge");
        let mut services = control_services(0xc8);
        let revoked_recipient = services.verifier.identity();
        let recipients = vec![
            ScopeRekeyRecipient::route_only(services.authority.identity()),
            ScopeRekeyRecipient::content_only(revoked_recipient, vec![event_topic()])
                .expect("revoked content recipient"),
        ];
        let first_pending_plan = services
            .authority
            .plan_scope_rekey_control_from_registry(
                &services.registry,
                0,
                event_scope(),
                2,
                recipients.clone(),
            )
            .expect("first pending plan");
        let first_pending = services
            .authority
            .seal_chained_scope_rekey_control(&first_pending_plan, 3, Some([0x31; 32]))
            .expect("first pending rekey");
        let first_pending_verified = verify_control(&mut services.verifier, &first_pending);
        let first_pending_id = ControlTransferId::new(first_pending_verified.envelope_id());
        let dependent_plan = services
            .authority
            .plan_scope_rekey_control_from_registry(
                &services.registry,
                0,
                event_scope(),
                3,
                recipients,
            )
            .expect("dependent pending plan");
        let dependent = services
            .authority
            .seal_chained_scope_rekey_control(
                &dependent_plan,
                4,
                Some(first_pending_verified.envelope_id()),
            )
            .expect("dependent pending rekey");
        let dependent_verified = verify_control(&mut services.verifier, &dependent);
        let dependent_id = ControlTransferId::new(dependent_verified.envelope_id());

        let store = Store::open_for_mission(&file.0, services.authority_id).expect("store");
        assert!(matches!(
            store
                .ingest_verified_control(&first_pending_verified, &first_pending)
                .expect("retain first pending rekey"),
            ControlOutcome::Pending { .. }
        ));
        assert!(matches!(
            store
                .ingest_verified_control(&dependent_verified, &dependent)
                .expect("retain dependent rekey"),
            ControlOutcome::Pending { .. }
        ));
        downgrade_scope_rekey_recipient_metadata(&store, first_pending_id);
        downgrade_scope_rekey_recipient_metadata(&store, dependent_id);

        // Recreate the only unsafe state an old implementation could leave:
        // an applied revocation plus metadata-v1 pending package rows whose
        // recipient identities were not yet available to the store. Sequence
        // two remains a gap, so old activation does not inspect the suffix.
        let revocation = services
            .authority
            .seal_chained_revocation_control(revoked_recipient, 1, 1, None)
            .expect("recipient revocation");
        let revocation_verified = verify_control(&mut services.verifier, &revocation);
        let revocation_id = ControlTransferId::new(revocation_verified.envelope_id());
        {
            let prepared =
                PreparedControl::from_verified(&revocation_verified, &revocation).expect("prepare");
            let write = store
                .database
                .begin_write()
                .expect("legacy activation write");
            assert_eq!(
                insert_control(&write, &prepared, store.limits(), 0)
                    .expect("insert legacy revocation"),
                ControlInsert::Inserted
            );
            let activation =
                activate_control_chain(&write, services.authority_id).expect("activate revocation");
            assert_eq!(
                activation
                    .activated
                    .iter()
                    .map(|control| control.transfer_id)
                    .collect::<Vec<_>>(),
                vec![revocation_id]
            );
            assert!(activation.rejected.is_empty());
            audit_control_tables(&write).expect("legacy snapshot remains structurally bounded");
            write.commit().expect("commit legacy unsafe fixture");
        }
        drop(store);

        let store = Store::open_for_mission(&file.0, services.authority_id)
            .expect("metadata-v1 rows remain migratable after revocation");
        let before = store.control_stats().expect("pre-batch stats");
        assert_eq!(before.applied, 1);
        assert_eq!(before.pending, 2);
        assert_eq!(before.scope_rekey_recipient_backfills_required, 2);
        let backfills = store
            .scope_rekey_recipient_backfill_controls()
            .expect("one-pass backfill source");
        let verified = backfills
            .iter()
            .map(|stored| {
                services
                    .verifier
                    .verify_control(&stored.sealed)
                    .expect("authenticate legacy pending row")
            })
            .collect::<Vec<_>>();
        let batch = verified
            .iter()
            .zip(&backfills)
            .map(|(verified, stored)| (verified, stored.sealed.as_slice()))
            .collect::<Vec<_>>();
        store
            .backfill_scope_rekey_recipients_batch(&batch)
            .expect("first revoked recipient purges the complete supplied suffix");
        let after = store.control_stats().expect("post-batch stats");
        assert_eq!(after.controls, 1);
        assert_eq!(after.applied, 1);
        assert_eq!(after.pending, 0);
        assert_eq!(after.scope_rekey_recipient_backfills_required, 0);
        assert!(
            store
                .get_control(first_pending_id)
                .expect("first lookup")
                .is_none()
        );
        assert!(
            store
                .get_control(dependent_id)
                .expect("dependent lookup")
                .is_none()
        );
        drop(store);
        let inspection = Store::inspect_existing(&file.0).expect("reopen purged batch");
        assert_eq!(inspection.control_stats.controls, 1);
        assert_eq!(
            inspection.control_stats.total_sealed_bytes,
            revocation.len() as u64
        );
    }

    #[test]
    fn maximal_scope_rekey_intent_is_quota_bound_and_rolls_back_every_control_row() {
        let mut provisioner = ReferenceProvisioner::from_seed([0xc4; 32]).expect("provisioner");
        let member_access = ProvisioningAccess::member(event_scope(), vec![1], vec![event_topic()])
            .expect("member access");
        let relay_access = ProvisioningAccess::relay(event_scope(), vec![1]).expect("relay access");
        let authority_bundle = provisioner
            .issue_control_authority(1, std::slice::from_ref(&member_access))
            .expect("authority bundle");
        let verifier_bundle = provisioner
            .issue_node(2, std::slice::from_ref(&member_access))
            .expect("verifier bundle");
        let mut authority =
            ReferenceEnvelopeSealer::open(authority_bundle).expect("authority sealer");
        let mut verifier = ReferenceEnvelopeSealer::open(verifier_bundle).expect("verifier sealer");
        let mut recipients = vec![
            ScopeRekeyRecipient::member(authority.identity(), vec![event_topic()])
                .expect("authority recipient"),
            ScopeRekeyRecipient::member(verifier.identity(), vec![event_topic()])
                .expect("verifier recipient"),
        ];
        for serial in 3..=MAX_CONTROL_INTENT_RECIPIENTS as u64 {
            let relay = provisioner
                .issue_node(serial, std::slice::from_ref(&relay_access))
                .and_then(ReferenceEnvelopeSealer::open)
                .expect("relay recipient");
            recipients.push(ScopeRekeyRecipient::route_only(relay.identity()));
        }
        assert_eq!(recipients.len(), MAX_CONTROL_INTENT_RECIPIENTS);
        let registry = provisioner
            .export_rekey_registry()
            .expect("signed registry");
        let principal = authority
            .verified_control_principal()
            .expect("control principal");
        let authority_id = authority.mission_authority_id();

        let file = TestFile::new("control-rekey-intent-quota");
        let reservation = {
            let store = Store::open_for_mission(&file.0, authority_id).expect("initial store");
            store.reserve_control(principal).expect("reserve rekey")
        };
        let plan = authority
            .plan_scope_rekey_control_from_registry(
                &registry,
                0,
                event_scope(),
                2,
                recipients.clone(),
            )
            .expect("plan maximal rekey");
        let registry_generation = plan.registry_generation();
        let (sealed, publication) = authority
            .seal_chained_scope_rekey_control_for_publication(
                &plan,
                reservation.sequence(),
                reservation.previous_control().map(|id| *id.as_bytes()),
            )
            .expect("seal maximal rekey");
        let verified = verify_control(&mut verifier, &sealed);
        let transfer_id = ControlTransferId::new(verified.envelope_id());
        let intent = ScopeRekeyPublicationIntent::new(
            principal,
            &registry,
            registry_generation,
            event_scope(),
            2,
            &recipients,
        )
        .expect("maximal canonical intent");
        let encoded_intent =
            encode_scope_rekey_publication_intent(&intent).expect("encode maximal intent");
        assert_eq!(intent.recipient_count(), MAX_CONTROL_INTENT_RECIPIENTS);
        assert!(!encoded_intent.is_empty());

        let sealed_len = u64::try_from(sealed.len()).expect("sealed length");
        let intent_len = u64::try_from(encoded_intent.len()).expect("intent length");
        let (reserved_items, reserved_bytes) =
            custody::custody_emergency_reserve(StoreLimits::default());
        assert_eq!(
            reserved_items,
            MAX_CONTROL_ITEMS + CUSTODY_EMERGENCY_ITEM_RESERVE
        );
        assert_eq!(
            reserved_bytes,
            MAX_CONTROL_BYTES + CUSTODY_EMERGENCY_BYTE_RESERVE
        );
        assert!(sealed_len + intent_len <= reserved_bytes);

        // Fill the entire one-item/one-byte ordinary ceiling with a row which
        // has no retirement lifecycle. The maximal authority transaction must
        // still fit wholly inside the dedicated Control reserve.
        let reserved_file = TestFile::new("control-rekey-full-ordinary-reserve");
        let reserved_limits =
            StoreLimits::new(reserved_items + 1, reserved_bytes + 1).expect("reserve-bound limits");
        let reserved_store =
            Store::open_with_limits_for_mission(&reserved_file.0, reserved_limits, authority_id)
                .expect("reserve-bound store");
        reserved_store
            .apply(item(0xc4), b"x")
            .expect("fill ordinary ceiling");
        let mut admitted_tombstones = 0u64;
        for counter in 1..=CUSTODY_EMERGENCY_ITEM_RESERVE {
            let mut header = event_header(
                authority.identity(),
                counter,
                counter,
                VersionVector::default(),
                counter.to_be_bytes().as_slice(),
                b"",
                Some(0),
            );
            header.tombstone = true;
            let sealed_tombstone = authority
                .seal_event(&header, b"")
                .expect("seal reserve tombstone");
            let route = verifier
                .verify_event(&sealed_tombstone.bytes)
                .expect("verify reserve tombstone");
            match reserved_store.cache_route_verified_event(&route, &sealed_tombstone.bytes) {
                Ok(RouteCacheOutcome::Inserted { .. }) => admitted_tombstones += 1,
                Err(StoreError::Custody(CustodyStoreError::ByteQuotaExceeded {
                    current,
                    incoming,
                    limit: CUSTODY_EMERGENCY_BYTE_RESERVE,
                })) if current + incoming > CUSTODY_EMERGENCY_BYTE_RESERVE => break,
                outcome => panic!("unexpected tombstone partition outcome: {outcome:?}"),
            }
        }
        assert!(admitted_tombstones > 0);
        assert!(admitted_tombstones < CUSTODY_EMERGENCY_ITEM_RESERVE);
        assert_eq!(
            reserved_store
                .database
                .begin_read()
                .expect("partition read")
                .open_table(custody::CUSTODY_ITEMS)
                .expect("partitioned custody items")
                .len()
                .expect("partitioned custody item count"),
            admitted_tombstones
        );
        assert!(matches!(
            reserved_store
                .commit_reserved_scope_rekey_control(
                    &reservation,
                    &verified,
                    &sealed,
                    &publication,
                    &intent,
                )
                .expect("commit maximal authority in reserve"),
            ControlOutcome::Applied { .. }
        ));
        drop(reserved_store);
        Store::inspect_existing(&reserved_file.0).expect("inspect reserve-bound control");

        let aggregate_limit = sealed_len
            .checked_add(intent_len)
            .and_then(|total| total.checked_sub(1))
            .expect("one byte below combined usage");
        let limits = StoreLimits::new(1, aggregate_limit).expect("restrictive limits");
        let store = Store::open_with_limits_for_mission(&file.0, limits, authority_id)
            .expect("quota store");
        assert!(matches!(
            store.commit_reserved_scope_rekey_control(
                &reservation,
                &verified,
                &sealed,
                &publication,
                &intent,
            ),
            Err(StoreError::PayloadByteLimitExceeded {
                current,
                incoming,
                limit,
            }) if current == 0
                && incoming == sealed_len + intent_len
                && limit == aggregate_limit
        ));
        assert_eq!(
            store.control_stats().expect("rolled-back stats"),
            ControlStoreStats::default()
        );
        assert!(
            store
                .get_control(transfer_id)
                .expect("rolled-back control lookup")
                .is_none()
        );
        assert_eq!(store.control_head().expect("rolled-back head"), None);
        assert!(matches!(
            store.verify_scope_rekey_publication_intent(transfer_id, &intent),
            Err(StoreError::ControlPublicationIntentUnknown { transfer_id: id })
                if id == transfer_id
        ));

        {
            let write = store
                .database
                .begin_write()
                .expect("dedicated-cap transaction");
            {
                let mut metadata = write.open_table(METADATA).expect("metadata");
                metadata
                    .insert(
                        CONTROL_TOTAL_BYTES,
                        MAX_CONTROL_BYTES
                            .checked_sub(intent_len)
                            .and_then(|remaining| remaining.checked_add(1))
                            .expect("intent smaller than dedicated cap"),
                    )
                    .expect("stage dedicated usage");
            }
            assert!(matches!(
                admit_control_publication_intent(&write, encoded_intent.len(), StoreLimits::default()),
                Err(StoreError::ControlByteLimitExceeded { incoming, limit, .. })
                    if incoming == intent_len && limit == MAX_CONTROL_BYTES
            ));
            // Dropping the transaction proves the synthetic cap state and any
            // attempted intent accounting cannot become durable.
        }
        assert_eq!(
            store.control_stats().expect("dedicated rollback stats"),
            ControlStoreStats::default()
        );
        drop(store);
        assert_eq!(
            Store::inspect_existing(&file.0)
                .expect("read-only rollback audit")
                .control_stats,
            ControlStoreStats::default()
        );
    }

    #[test]
    fn stale_revocation_policy_blocks_existing_operation_and_all_public_event_mutations() {
        let file = TestFile::new("event-policy-revocation");
        let mut services = control_services(0xc2);
        let store = Store::open_for_mission(&file.0, services.authority_id).expect("policy store");
        store
            .require_process_exclusive_lock()
            .expect("redb writer exclusion proof");
        let policy = store.control_policy_snapshot().expect("initial policy");
        let reservation = store
            .reserve_event_with_policy(
                &policy,
                services.authority.identity(),
                &event_topic(),
                &event_scope(),
            )
            .expect("policy-bound reservation");
        let payload = b"operation before policy change";
        let header = reservation
            .header(
                Priority::Immediate,
                b"policy-operation".to_vec(),
                None,
                payload.len() as u64,
                false,
                1,
            )
            .expect("reserved header");
        let sealed = services
            .authority
            .seal_event(&header, payload)
            .expect("seal local event");
        let event = content_event(&mut services.verifier, &sealed.bytes);
        let operation = EventOperationKey::new(b"policy/once".to_vec()).expect("operation key");
        let intent = event_publication_intent(&header, payload);
        let request = EventOperationRequest::new(&operation, &intent, payload, None)
            .expect("operation request");
        assert!(matches!(
            store
                .commit_reserved_event_once_with_policy(
                    &policy,
                    &request,
                    &reservation,
                    &event,
                    &sealed.bytes,
                )
                .expect("initial operation"),
            EventOnceOutcome::Inserted { .. }
        ));

        let unrelated = [0xe1; 32];
        let revoke = services
            .authority
            .seal_chained_revocation_control(unrelated, 1, 1, None)
            .expect("policy-changing revocation");
        let revoke_verified = verify_control(&mut services.verifier, &revoke);
        store
            .ingest_verified_control(&revoke_verified, &revoke)
            .expect("apply revocation");
        assert!(matches!(
            store.commit_reserved_event_once(&request, &reservation, &event, &sealed.bytes,),
            Err(StoreError::ControlPolicyChanged)
        ));
        assert!(matches!(
            store.transfer_inventory_with_policy(&policy),
            Err(StoreError::ControlPolicyChanged)
        ));
        assert_eq!(store.event_stats().expect("stable event stats").events, 1);

        let revoked_publisher = services.verifier.identity();
        let remote_payload = b"revoked publisher event";
        let remote_header = event_header(
            revoked_publisher,
            1,
            1,
            VersionVector::default(),
            b"revoked-source",
            remote_payload,
            None,
        );
        let remote = services
            .verifier
            .seal_event(&remote_header, remote_payload)
            .expect("seal before revocation");
        let remote_route = services
            .authority
            .verify_event(&remote.bytes)
            .expect("route verify remote");
        let remote_event = content_event(&mut services.authority, &remote.bytes);
        let revoke_publisher = services
            .authority
            .seal_chained_revocation_control(
                revoked_publisher,
                1,
                2,
                Some(revoke_verified.envelope_id()),
            )
            .expect("revoke publisher");
        let revoke_publisher_verified = verify_control(&mut services.verifier, &revoke_publisher);
        store
            .ingest_verified_control(&revoke_publisher_verified, &revoke_publisher)
            .expect("apply publisher revocation");
        let current = store
            .control_policy_snapshot()
            .expect("settled current policy");
        for result in [
            store.apply_verified_event(&remote_event, &remote.bytes),
            store.apply_verified_event_with_policy(&current, &remote_event, &remote.bytes),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::EventPublisherRevoked(node)) if node == revoked_publisher
            ));
        }
        for result in [
            store.cache_route_verified_event(&remote_route, &remote.bytes),
            store.cache_route_verified_event_with_policy(&current, &remote_route, &remote.bytes),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::EventPublisherRevoked(node)) if node == revoked_publisher
            ));
        }
        assert_eq!(store.event_stats().expect("no revoked mutation").events, 1);
        assert_eq!(
            store.event_stats().expect("no revoked cache").route_cached,
            0
        );
    }

    #[test]
    fn stale_rekey_and_pending_policy_reject_event_bytes_indexes_and_operations_atomically() {
        let rekey_file = TestFile::new("event-policy-rekey");
        let mut services = control_services(0xc3);
        let store =
            Store::open_for_mission(&rekey_file.0, services.authority_id).expect("rekey store");
        let old_policy = store.control_policy_snapshot().expect("old policy");
        let payload = b"epoch-one event";
        let header = event_header(
            services.verifier.identity(),
            1,
            1,
            VersionVector::default(),
            b"old-epoch",
            payload,
            None,
        );
        let sealed = services
            .verifier
            .seal_event(&header, payload)
            .expect("seal epoch one");
        let route = services
            .authority
            .verify_event(&sealed.bytes)
            .expect("route verify");
        let event = content_event(&mut services.authority, &sealed.bytes);
        let recipients = vec![
            ScopeRekeyRecipient::member(services.authority.identity(), vec![event_topic()])
                .expect("authority recipient"),
            ScopeRekeyRecipient::member(services.verifier.identity(), vec![event_topic()])
                .expect("verifier recipient"),
        ];
        let (rekey, _) = services
            .authority
            .seal_chained_scope_rekey_control_from_registry(
                &services.registry,
                0,
                event_scope(),
                2,
                recipients,
                1,
                None,
            )
            .expect("seal rekey");
        let rekey_verified = verify_control(&mut services.verifier, &rekey);
        store
            .ingest_verified_control(&rekey_verified, &rekey)
            .expect("apply rekey");
        assert!(matches!(
            store.apply_verified_event_with_policy(&old_policy, &event, &sealed.bytes),
            Err(StoreError::ControlPolicyChanged)
        ));
        assert!(matches!(
            store.cache_route_verified_event_with_policy(&old_policy, &route, &sealed.bytes),
            Err(StoreError::ControlPolicyChanged)
        ));
        let current = store
            .control_policy_snapshot()
            .expect("current rekey policy");
        for result in [
            store.apply_verified_event(&event, &sealed.bytes),
            store.apply_verified_event_with_policy(&current, &event, &sealed.bytes),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::EventKeyEpochStale {
                    current: 2,
                    received: 1
                })
            ));
        }
        assert!(matches!(
            store.cache_route_verified_event(&route, &sealed.bytes),
            Err(StoreError::EventKeyEpochStale {
                current: 2,
                received: 1
            })
        ));
        assert_eq!(store.event_stats().expect("rekey atomic stats").events, 0);
        assert_eq!(
            store.event_stats().expect("rekey cache stats").route_cached,
            0
        );

        let pending_file = TestFile::new("event-policy-pending");
        let mut pending_services = control_services(0xc4);
        let pending_store = Store::open_for_mission(&pending_file.0, pending_services.authority_id)
            .expect("pending store");
        let pending_policy = pending_store
            .control_policy_snapshot()
            .expect("pre-pending policy");
        let reservation = pending_store
            .reserve_event_with_policy(
                &pending_policy,
                pending_services.authority.identity(),
                &event_topic(),
                &event_scope(),
            )
            .expect("pre-pending reservation");
        let local_payload = b"must not commit through pending control";
        let local_header = reservation
            .header(
                Priority::Immediate,
                b"pending-local".to_vec(),
                None,
                local_payload.len() as u64,
                false,
                1,
            )
            .expect("local header");
        let local = pending_services
            .authority
            .seal_event(&local_header, local_payload)
            .expect("local seal");
        let local_route = pending_services
            .verifier
            .verify_event(&local.bytes)
            .expect("local route capability");
        let local_event = content_event(&mut pending_services.verifier, &local.bytes);
        let operation = EventOperationKey::new(b"pending/once".to_vec()).expect("operation");
        let intent = event_publication_intent(&local_header, local_payload);
        let request = EventOperationRequest::new(&operation, &intent, local_payload, None)
            .expect("pending operation request");
        let pending_control = pending_services
            .authority
            .seal_chained_revocation_control([0xe2; 32], 1, 2, Some([0xe3; 32]))
            .expect("far pending control");
        let pending_verified = verify_control(&mut pending_services.verifier, &pending_control);
        assert!(matches!(
            pending_store
                .ingest_verified_control(&pending_verified, &pending_control)
                .expect("retain pending"),
            ControlOutcome::Pending { .. }
        ));
        assert!(matches!(
            pending_store.control_policy_snapshot(),
            Err(StoreError::ControlPolicyUnsettled { pending: 1 })
        ));
        assert!(matches!(
            pending_store.commit_reserved_event_once(
                &request,
                &reservation,
                &local_event,
                &local.bytes,
            ),
            Err(StoreError::ControlPolicyUnsettled { pending: 1 })
        ));
        for result in [
            pending_store.apply_verified_event(&local_event, &local.bytes),
            pending_store.apply_verified_event_with_policy(
                &pending_policy,
                &local_event,
                &local.bytes,
            ),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::ControlPolicyUnsettled { pending: 1 })
            ));
        }
        for result in [
            pending_store.cache_route_verified_event(&local_route, &local.bytes),
            pending_store.cache_route_verified_event_with_policy(
                &pending_policy,
                &local_route,
                &local.bytes,
            ),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::ControlPolicyUnsettled { pending: 1 })
            ));
        }
        assert!(matches!(
            pending_store.get_transfer_with_policy(
                &pending_policy,
                EventTransferId::new(local_event.envelope_id()),
            ),
            Err(StoreError::ControlPolicyUnsettled { pending: 1 })
        ));
        assert!(matches!(
            pending_store.transfer_inventory_with_policy(&pending_policy),
            Err(StoreError::ControlPolicyUnsettled { pending: 1 })
        ));
        assert!(matches!(
            pending_store.events_after_with_policy(&pending_policy, 0, 0),
            Err(StoreError::ControlPolicyUnsettled { pending: 1 })
        ));
        assert!(
            pending_store
                .event_for_operation(&operation)
                .expect("operation state")
                .is_none()
        );
        assert_eq!(
            pending_store.event_stats().expect("pending stats").events,
            0
        );
        assert_eq!(
            pending_store
                .event_stats()
                .expect("pending cache stats")
                .route_cached,
            0
        );
    }

    #[test]
    fn dropped_control_transaction_leaves_no_pending_effect_or_reservation_after_restart() {
        let file = TestFile::new("control-dropped-transaction");
        let mut services = control_services(0xb7);
        let sealed = services
            .authority
            .seal_chained_revocation_control([0xb7; 32], 1, 1, None)
            .expect("control");
        let verified = verify_control(&mut services.verifier, &sealed);
        let prepared = PreparedControl::from_verified(&verified, &sealed).expect("prepared");
        {
            let store = Store::open_for_mission(&file.0, services.authority_id).expect("store");
            let write = store.database.begin_write().expect("write");
            assert_eq!(
                insert_control(&write, &prepared, store.limits(), 0).expect("stage in transaction"),
                ControlInsert::Inserted
            );
            drop(write);
        }
        {
            let reopened =
                Store::open_for_mission(&file.0, services.authority_id).expect("reopen abort");
            assert_eq!(reopened.control_stats().expect("abort stats").controls, 0);
            assert!(
                reopened
                    .control_inventory()
                    .expect("abort inventory")
                    .is_empty()
            );
            assert!(reopened.control_head().expect("abort head").is_none());
            reopened
                .ingest_verified_control(&verified, &sealed)
                .expect("real committed ingest");
        }
        let reopened =
            Store::open_for_mission(&file.0, services.authority_id).expect("reopen commit");
        assert_eq!(reopened.control_stats().expect("commit stats").applied, 1);
        assert!(
            reopened
                .is_control_principal_revoked([0xb7; 32])
                .expect("committed effect")
        );
    }

    #[test]
    fn authority_revocation_purges_suffix_and_rejected_input_survives_other_activation() {
        let authority_file = TestFile::new("control-authority-revocation");
        let mut services = control_services(0xb8);
        let first = services
            .authority
            .seal_chained_revocation_control(services.authority_id, 1, 1, None)
            .expect("authority revocation");
        let first_verified = verify_control(&mut services.verifier, &first);
        let second = services
            .authority
            .seal_chained_revocation_control([0xb9; 32], 1, 2, Some(first_verified.envelope_id()))
            .expect("pending suffix");
        let second_verified = verify_control(&mut services.verifier, &second);
        let second_id = ControlTransferId::new(second_verified.envelope_id());
        let third = services
            .authority
            .seal_chained_revocation_control([0xba; 32], 1, 3, Some(second_verified.envelope_id()))
            .expect("dependent pending suffix");
        let third_verified = verify_control(&mut services.verifier, &third);
        let third_id = ControlTransferId::new(third_verified.envelope_id());
        let principal = services
            .authority
            .verified_control_principal()
            .expect("principal");
        let store =
            Store::open_for_mission(&authority_file.0, services.authority_id).expect("store");
        assert!(matches!(
            store
                .ingest_verified_control(&second_verified, &second)
                .expect("pending second"),
            ControlOutcome::Pending { .. }
        ));
        assert!(matches!(
            store
                .ingest_verified_control(&third_verified, &third)
                .expect("pending third"),
            ControlOutcome::Pending { .. }
        ));
        let ControlOutcome::Applied {
            activated,
            rejected,
            ..
        } = store
            .ingest_verified_control(&first_verified, &first)
            .expect("apply authority revocation")
        else {
            panic!("authority revocation must apply");
        };
        assert_eq!(activated.len(), 1);
        assert_eq!(
            rejected
                .iter()
                .map(|value| (value.transfer_id, value.reason))
                .collect::<Vec<_>>(),
            vec![
                (
                    second_id,
                    ControlRejectionReason::AuthorityRevoked(services.authority_id)
                ),
                (
                    third_id,
                    ControlRejectionReason::InvalidatedPredecessor(second_id)
                )
            ]
        );
        let directly_rejected = store
            .ingest_verified_control(&second_verified, &second)
            .expect("attribute post-revocation authority input");
        assert_eq!(
            directly_rejected.rejected_input(),
            Some(RejectedControl {
                transfer_id: second_id,
                signer: second_verified.signer(),
                reason: ControlRejectionReason::AuthorityRevoked(services.authority_id),
            })
        );
        assert!(matches!(
            store.reserve_control(principal),
            Err(StoreError::ControlAuthorityRevoked(authority))
                if authority == services.authority_id
        ));
        let member_payload = b"member traffic survives control-authority revocation";
        let member_header = event_header(
            services.verifier.identity(),
            1,
            1,
            VersionVector::default(),
            b"authority-revoked-member-event",
            member_payload,
            None,
        );
        let member_sealed = services
            .verifier
            .seal_event(&member_header, member_payload)
            .expect("seal nonrevoked member event");
        let member_event = content_event(&mut services.authority, &member_sealed.bytes);
        let authority_revoked_policy = store
            .control_policy_snapshot()
            .expect("authority-revoked settled policy");
        assert!(matches!(
            store
                .apply_verified_event_with_policy(
                    &authority_revoked_policy,
                    &member_event,
                    &member_sealed.bytes,
                )
                .expect("nonrevoked Event remains accepted"),
            ApplyOutcome::Inserted { .. }
        ));

        let attribution_file = TestFile::new("control-rejected-attribution");
        let mut provisioner = ReferenceProvisioner::from_seed([0xba; 32]).expect("provisioner");
        let access = ProvisioningAccess::member(event_scope(), vec![1], vec![event_topic()])
            .expect("access");
        let old_bundle = provisioner
            .issue_control_authority(1, std::slice::from_ref(&access))
            .expect("old signer");
        let recovery_bundle = provisioner
            .issue_control_authority(2, std::slice::from_ref(&access))
            .expect("recovery signer");
        let verifier_bundle = provisioner.issue_node(3, &[access]).expect("verifier");
        let mut old = ReferenceEnvelopeSealer::open(old_bundle).expect("old");
        let mut recovery = ReferenceEnvelopeSealer::open(recovery_bundle).expect("recovery");
        let mut verifier = ReferenceEnvelopeSealer::open(verifier_bundle).expect("verifier");
        let old_signer = old.identity();
        let mission = recovery.mission_authority_id();
        let revoke = recovery
            .seal_chained_revocation_control(old_signer, 1, 1, None)
            .expect("revoke old");
        let revoke_verified = verify_control(&mut verifier, &revoke);
        let valid = recovery
            .seal_chained_revocation_control([0xbb; 32], 1, 2, Some(revoke_verified.envelope_id()))
            .expect("valid pending");
        let valid_verified = verify_control(&mut verifier, &valid);
        let valid_id = ControlTransferId::new(valid_verified.envelope_id());
        let rejected = old
            .seal_chained_revocation_control([0xbc; 32], 1, 3, Some(valid_verified.envelope_id()))
            .expect("rejected input");
        let rejected_verified = verify_control(&mut verifier, &rejected);
        let rejected_id = ControlTransferId::new(rejected_verified.envelope_id());
        let store = Store::open_for_mission(&attribution_file.0, mission).expect("store");
        store
            .ingest_verified_control(&revoke_verified, &revoke)
            .expect("apply signer revocation");
        let prepared = PreparedControl::from_verified(&valid_verified, &valid).expect("prepared");
        {
            let write = store.database.begin_write().expect("stage valid pending");
            assert_eq!(
                insert_control(&write, &prepared, store.limits(), 0).expect("insert pending"),
                ControlInsert::Inserted
            );
            write.commit().expect("commit pending only");
        }
        let outcome = store
            .ingest_verified_control(&rejected_verified, &rejected)
            .expect("rejected input also advances staged prefix");
        let ControlOutcome::Applied {
            activated,
            rejected,
            ..
        } = &outcome
        else {
            panic!("unrelated valid prefix must activate");
        };
        assert_eq!(
            activated
                .iter()
                .map(|value| value.transfer_id)
                .collect::<Vec<_>>(),
            vec![valid_id]
        );
        assert_eq!(
            rejected
                .iter()
                .map(|value| value.transfer_id)
                .collect::<Vec<_>>(),
            vec![rejected_id]
        );
        assert_eq!(
            outcome.rejected_input(),
            Some(RejectedControl {
                transfer_id: rejected_id,
                signer: old_signer,
                reason: ControlRejectionReason::SignerRevoked(old_signer),
            })
        );
        assert!(
            store
                .get_control(rejected_id)
                .expect("rejected query")
                .is_none()
        );
    }

    #[test]
    fn control_read_only_and_reopen_audits_reject_partial_orphan_inflated_and_bad_receipt_state() {
        let base = TestFile::new("control-audit-base");
        let mut services = control_services(0xbd);
        let sealed = services
            .authority
            .seal_chained_revocation_control([0xbd; 32], 1, 1, None)
            .expect("control");
        let verified = verify_control(&mut services.verifier, &sealed);
        let transfer_id = ControlTransferId::new(verified.envelope_id());
        {
            let store = Store::open_for_mission(&base.0, services.authority_id).expect("store");
            store
                .ingest_verified_control(&verified, &sealed)
                .expect("apply control");
        }
        let reject = |file: &TestFile| {
            let before = std::fs::read(&file.0).expect("corrupted bytes");
            assert!(Store::inspect_existing(&file.0).is_err());
            assert_eq!(
                std::fs::read(&file.0).expect("read after inspection"),
                before,
                "strict inspection must remain read-only"
            );
            assert!(Store::open_for_mission(&file.0, services.authority_id).is_err());
        };

        let partial = TestFile::new("control-audit-partial");
        std::fs::copy(&base.0, &partial.0).expect("copy partial");
        {
            let database = Database::open(&partial.0).expect("partial database");
            let write = database.begin_write().expect("partial write");
            write
                .delete_table(CONTROL_PENDING)
                .expect("delete pending table");
            write.commit().expect("commit partial");
        }
        reject(&partial);

        let orphan = TestFile::new("control-audit-orphan");
        std::fs::copy(&base.0, &orphan.0).expect("copy orphan");
        {
            let database = Database::open(&orphan.0).expect("orphan database");
            let write = database.begin_write().expect("orphan write");
            write
                .open_table(CONTROL_SEQUENCE)
                .expect("sequence")
                .insert(99, [0xde; 32].as_slice())
                .expect("orphan sequence");
            write.commit().expect("commit orphan");
        }
        reject(&orphan);

        let inflated = TestFile::new("control-audit-head");
        std::fs::copy(&base.0, &inflated.0).expect("copy inflated");
        {
            let database = Database::open(&inflated.0).expect("inflated database");
            let write = database.begin_write().expect("inflated write");
            let encoded = encode_control_head(99, transfer_id);
            write
                .open_table(CONTROL_HEAD)
                .expect("head")
                .insert(CONTROL_HEAD_KEY, encoded.as_slice())
                .expect("inflate head");
            write.commit().expect("commit inflated head");
        }
        reject(&inflated);

        let bad_receipt = TestFile::new("control-audit-receipt");
        std::fs::copy(&base.0, &bad_receipt.0).expect("copy receipt");
        {
            let database = Database::open(&bad_receipt.0).expect("receipt database");
            let write = database.begin_write().expect("receipt write");
            let receipt = encode_control_reservation(&ControlReservation {
                authority: services.authority_id,
                signer: verified.signer(),
                previous_sequence: 0,
                sequence: 1,
                previous_control: None,
            });
            write
                .open_table(CONTROL_RESERVATIONS)
                .expect("reservations")
                .insert([0xdf; 32].as_slice(), receipt.as_slice())
                .expect("orphan receipt");
            write.commit().expect("commit receipt");
        }
        reject(&bad_receipt);

        let accounting = TestFile::new("control-audit-accounting");
        std::fs::copy(&base.0, &accounting.0).expect("copy accounting");
        write_metadata(&accounting.0, CONTROL_ITEM_COUNT, 99);
        reject(&accounting);

        let counters_without_schema = TestFile::new("control-audit-counters-without-schema");
        std::fs::copy(&base.0, &counters_without_schema.0).expect("copy counter orphan");
        {
            let database =
                Database::open(&counters_without_schema.0).expect("counter orphan database");
            let write = database.begin_write().expect("counter orphan write");
            write.delete_table(CONTROL_RECORDS).expect("records");
            write.delete_table(CONTROL_BYTES).expect("bytes");
            write.delete_table(CONTROL_SEQUENCE).expect("sequence");
            write.delete_table(CONTROL_PENDING).expect("pending");
            write.delete_table(CONTROL_APPLIED).expect("applied");
            write
                .delete_table(CONTROL_REVOCATIONS)
                .expect("revocations");
            write
                .delete_table(CONTROL_SCOPE_EPOCHS)
                .expect("scope epochs");
            write
                .delete_table(CONTROL_RESERVATIONS)
                .expect("reservations");
            write
                .delete_table(CONTROL_PUBLICATION_INTENTS)
                .expect("publication intents");
            write.delete_table(CONTROL_HEAD).expect("head");
            write.commit().expect("commit orphan counters");
        }
        reject(&counters_without_schema);
    }

    #[test]
    fn causal_frontier_bound_rejects_a_new_direct_publisher_without_partial_acceptance() {
        let file = TestFile::new("frontier-cap");
        let mut services = event_services(0xa3);
        let store = Store::open_for_mission(&file.0, services.authority).expect("bound store");
        let incoming_publisher = services.publisher.identity();
        {
            let write = store.database.begin_write().expect("begin frontier seed");
            let mut frontier = write.open_table(CAUSAL_FRONTIER).expect("frontier");
            let mut inserted = 0usize;
            let mut candidate = 0u64;
            while inserted < MAX_CAUSAL_CONTEXT_ENTRIES {
                let mut publisher = [0xee; 32];
                publisher[24..].copy_from_slice(&candidate.to_be_bytes());
                candidate += 1;
                if publisher == incoming_publisher {
                    continue;
                }
                let key = causal_frontier_key(&event_topic(), &event_scope(), publisher)
                    .expect("frontier key");
                frontier.insert(key.as_slice(), 1).expect("seed frontier");
                inserted += 1;
            }
            drop(frontier);
            write.commit().expect("commit frontier seed");
        }
        assert!(matches!(
            store.reserve_event(incoming_publisher, &event_topic(), &event_scope()),
            Err(StoreError::InvalidSemanticEvent(
                "causal frontier publisher limit reached"
            ))
        ));

        let payload = b"one publisher too many";
        let header = event_header(
            incoming_publisher,
            1,
            1,
            VersionVector::default(),
            b"frontier-overflow",
            payload,
            None,
        );
        let sealed = services
            .publisher
            .seal_event(&header, payload)
            .expect("seal overflow Event");
        let event = content_event(&mut services.reader, &sealed.bytes);
        assert!(matches!(
            store.apply_verified_event(&event, &sealed.bytes),
            Err(StoreError::InvalidSemanticEvent(
                "causal frontier publisher limit reached"
            ))
        ));
        assert_eq!(store.event_count().expect("no accepted Events"), 0);
        let read = store.database.begin_read().expect("read ledgers");
        assert_eq!(
            read.open_table(SEMANTIC_ITEMS)
                .expect("semantic items")
                .len()
                .expect("len"),
            0
        );
        assert_eq!(
            read.open_table(ACCEPTED_DOTS)
                .expect("accepted dots")
                .len()
                .expect("len"),
            0
        );
        assert_eq!(
            read.open_table(ACCEPTED_EVENTS)
                .expect("accepted positions")
                .len()
                .expect("len"),
            0
        );
    }

    #[test]
    fn state_and_record_frontier_capacity_errors_are_typed_and_transactional() {
        let seed_full_frontier = |store: &Store, incoming_publisher: NodeId| {
            let write = store.database.begin_write().expect("begin frontier seed");
            let mut frontier = write.open_table(CAUSAL_FRONTIER).expect("frontier");
            let mut inserted = 0usize;
            let mut candidate = 0u64;
            while inserted < MAX_CAUSAL_CONTEXT_ENTRIES {
                let mut publisher = [0xce; 32];
                publisher[24..].copy_from_slice(&candidate.to_be_bytes());
                candidate += 1;
                if publisher == incoming_publisher {
                    continue;
                }
                let key = causal_frontier_key(&state_topic(), &state_scope(), publisher)
                    .expect("frontier key");
                frontier.insert(key.as_slice(), 1).expect("seed frontier");
                inserted += 1;
            }
            drop(frontier);
            write.commit().expect("commit frontier seed");
        };

        let state_file = TestFile::new("state-frontier-capacity-typed");
        let mut state_fixture = state_services(0x74);
        let state_store =
            Store::open_for_mission(&state_file.0, state_fixture.authority).expect("State store");
        let state_publisher = state_fixture.first.identity();
        seed_full_frontier(&state_store, state_publisher);
        assert!(matches!(
            state_store.reserve_state(state_publisher, &state_topic(), &state_scope()),
            Err(StoreError::StateCausalFrontierLimitExceeded {
                current: MAX_CAUSAL_CONTEXT_ENTRIES,
                limit: MAX_CAUSAL_CONTEXT_ENTRIES,
            })
        ));
        let state_policy = state_store
            .control_policy_snapshot()
            .expect("State control policy");
        let (state, state_sealed) = verified_state_for_remote_apply(
            &mut state_fixture.first,
            &mut state_fixture.reader,
            1,
            VersionVector::default(),
            b"frontier-capacity-state",
            b"State beyond frontier capacity",
        );
        let state_stats_before = state_store.state_stats().expect("State stats before");
        let state_indexes_before = {
            let read = state_store
                .database
                .begin_read()
                .expect("State indexes before");
            (
                read.open_table(STATES).expect("States").len().expect("len"),
                read.open_table(STATE_SEMANTIC_ITEMS)
                    .expect("State semantic index")
                    .len()
                    .expect("len"),
                read.open_table(ACCEPTED_DOTS)
                    .expect("accepted dots")
                    .len()
                    .expect("len"),
            )
        };
        assert!(matches!(
            state_store.apply_verified_state_with_policy(&state_policy, &state, &state_sealed,),
            Err(StoreError::StateCausalFrontierLimitExceeded {
                current: MAX_CAUSAL_CONTEXT_ENTRIES,
                limit: MAX_CAUSAL_CONTEXT_ENTRIES,
            })
        ));
        assert_eq!(
            state_store.state_stats().expect("State stats after"),
            state_stats_before
        );
        let state_indexes_after = {
            let read = state_store
                .database
                .begin_read()
                .expect("State indexes after");
            (
                read.open_table(STATES).expect("States").len().expect("len"),
                read.open_table(STATE_SEMANTIC_ITEMS)
                    .expect("State semantic index")
                    .len()
                    .expect("len"),
                read.open_table(ACCEPTED_DOTS)
                    .expect("accepted dots")
                    .len()
                    .expect("len"),
            )
        };
        assert_eq!(state_indexes_after, state_indexes_before);

        let record_file = TestFile::new("record-frontier-capacity-typed");
        let mut record_services = state_services(0x75);
        let record_store = Store::open_for_mission(&record_file.0, record_services.authority)
            .expect("Record store");
        let record_publisher = record_services.first.identity();
        seed_full_frontier(&record_store, record_publisher);
        assert!(matches!(
            record_store.reserve_record(record_publisher, &state_topic(), &state_scope()),
            Err(StoreError::RecordCausalFrontierLimitExceeded {
                current: MAX_CAUSAL_CONTEXT_ENTRIES,
                limit: MAX_CAUSAL_CONTEXT_ENTRIES,
            })
        ));
        let record_policy = record_store
            .control_policy_snapshot()
            .expect("Record control policy");
        let (record, record_sealed) = verified_record_for_remote_apply(
            &mut record_services.first,
            &mut record_services.reader,
            1,
            VersionVector::default(),
            b"frontier-capacity-record",
            b"Record beyond frontier capacity",
        );
        let record_stats_before = record_store.record_stats().expect("Record stats before");
        let record_indexes_before = {
            let read = record_store
                .database
                .begin_read()
                .expect("Record indexes before");
            (
                read.open_table(RECORDS)
                    .expect("Records")
                    .len()
                    .expect("len"),
                read.open_table(RECORD_SEMANTIC_ITEMS)
                    .expect("Record semantic index")
                    .len()
                    .expect("len"),
                read.open_table(ACCEPTED_DOTS)
                    .expect("accepted dots")
                    .len()
                    .expect("len"),
            )
        };
        assert!(matches!(
            record_store
                .apply_verified_record_with_policy(&record_policy, &record, &record_sealed,),
            Err(StoreError::RecordCausalFrontierLimitExceeded {
                current: MAX_CAUSAL_CONTEXT_ENTRIES,
                limit: MAX_CAUSAL_CONTEXT_ENTRIES,
            })
        ));
        assert_eq!(
            record_store.record_stats().expect("Record stats after"),
            record_stats_before
        );
        let record_indexes_after = {
            let read = record_store
                .database
                .begin_read()
                .expect("Record indexes after");
            (
                read.open_table(RECORDS)
                    .expect("Records")
                    .len()
                    .expect("len"),
                read.open_table(RECORD_SEMANTIC_ITEMS)
                    .expect("Record semantic index")
                    .len()
                    .expect("len"),
                read.open_table(ACCEPTED_DOTS)
                    .expect("accepted dots")
                    .len()
                    .expect("len"),
            )
        };
        assert_eq!(record_indexes_after, record_indexes_before);
    }

    #[test]
    fn mutable_transfer_cursor_cas_reconcile_reopen_and_terminal_preservation() {
        let file = TestFile::new("mutable-transfer-cursor-lifecycle");
        let services = event_services(0x71);
        let first_peer = cursor_peer(1);
        let stale_peer = cursor_peer(2);
        let first = [0x11; 32];
        let second = [0x22; 32];
        let stale = [0x33; 32];
        let store = Store::open_for_mission(&file.0, services.authority).expect("mission store");

        assert_eq!(
            store
                .mutable_transfer_cursor(
                    first_peer,
                    MutableTransferCursorClass::State,
                    MutableTransferCursorMode::OfferToPeer,
                )
                .expect("missing cursor"),
            None
        );
        assert!(
            store
                .compare_and_advance_mutable_transfer_cursor(
                    first_peer,
                    MutableTransferCursorClass::State,
                    MutableTransferCursorMode::OfferToPeer,
                    None,
                    first,
                )
                .expect("create cursor")
        );
        assert!(
            !store
                .compare_and_advance_mutable_transfer_cursor(
                    first_peer,
                    MutableTransferCursorClass::State,
                    MutableTransferCursorMode::OfferToPeer,
                    None,
                    second,
                )
                .expect("mismatched cursor is nonfatal")
        );
        assert_eq!(
            store
                .mutable_transfer_cursor(
                    first_peer,
                    MutableTransferCursorClass::State,
                    MutableTransferCursorMode::OfferToPeer,
                )
                .expect("unchanged cursor"),
            Some(first)
        );
        assert!(
            store
                .compare_and_advance_mutable_transfer_cursor(
                    first_peer,
                    MutableTransferCursorClass::State,
                    MutableTransferCursorMode::OfferToPeer,
                    Some(first),
                    second,
                )
                .expect("advance cursor")
        );
        assert!(
            store
                .compare_and_advance_mutable_transfer_cursor(
                    first_peer,
                    MutableTransferCursorClass::State,
                    MutableTransferCursorMode::OfferToPeer,
                    Some([0xff; 32]),
                    second,
                )
                .expect("already-current cursor is success")
        );
        store
            .compare_and_advance_mutable_transfer_cursor(
                stale_peer,
                MutableTransferCursorClass::Record,
                MutableTransferCursorMode::FetchFromPeer,
                None,
                stale,
            )
            .expect("create stale-peer cursor");

        let overbound = (0..=MAX_MUTABLE_TRANSFER_CURSOR_PEERS)
            .map(|index| cursor_peer(index as u64 + 100))
            .collect::<Vec<_>>();
        assert!(matches!(
            store.reconcile_mutable_transfer_cursor_peers(&overbound),
            Err(StoreError::MutableTransferCursorPeerLimitExceeded {
                requested,
                limit: MAX_MUTABLE_TRANSFER_CURSOR_PEERS,
            }) if requested == MAX_MUTABLE_TRANSFER_CURSOR_PEERS + 1
        ));
        store
            .reconcile_mutable_transfer_cursor_peers(&[first_peer])
            .expect("prune stale peer");
        assert_eq!(
            store
                .mutable_transfer_cursor(
                    stale_peer,
                    MutableTransferCursorClass::Record,
                    MutableTransferCursorMode::FetchFromPeer,
                )
                .expect("pruned cursor"),
            None
        );
        let replacement_peer = cursor_peer(3);
        assert!(
            store
                .compare_and_advance_mutable_transfer_cursor(
                    replacement_peer,
                    MutableTransferCursorClass::Record,
                    MutableTransferCursorMode::FetchFromPeer,
                    None,
                    [0x55; 32],
                )
                .expect("replacement peer after prune")
        );
        store
            .reconcile_mutable_transfer_cursor_peers(&[first_peer])
            .expect("prune replacement peer churn");
        drop(store);

        let mut reopened =
            Store::open_for_mission(&file.0, services.authority).expect("reopen cursor store");
        assert_eq!(
            reopened
                .mutable_transfer_cursor(
                    first_peer,
                    MutableTransferCursorClass::State,
                    MutableTransferCursorMode::OfferToPeer,
                )
                .expect("persistent cursor"),
            Some(second)
        );
        let intent = ZeroizationIntent::new(
            b"cursor mission descriptor".to_vec(),
            b"cursor identity descriptor".to_vec(),
        )
        .expect("zeroization intent");
        reopened
            .begin_zeroization(&intent)
            .expect("terminal marker");
        drop(reopened);
        assert_eq!(
            Store::inspect_zeroization_state(&file.0)
                .expect("terminal cursor audit")
                .state(),
            StoreZeroizationState::CleanupPending
        );
        let database = redb::Builder::new()
            .open_read_only(&file.0)
            .expect("read terminal cursor table");
        let read = database.begin_read().expect("read terminal cursor rows");
        let table = read
            .open_table(MUTABLE_TRANSFER_CURSORS)
            .expect("cursor table");
        assert_eq!(table.len().expect("cursor rows"), 1);
        let key = mutable_transfer_cursor_key(
            first_peer,
            MutableTransferCursorClass::State,
            MutableTransferCursorMode::OfferToPeer,
        );
        assert_eq!(
            table
                .get(key.as_slice())
                .expect("cursor lookup")
                .expect("preserved cursor")
                .value(),
            second
        );
    }

