    #[cfg(unix)]
    #[test]
    fn every_writable_open_requires_parent_barrier_before_store_or_terminal_use() {
        let created = TestFile::new("new-store-parent-sync-observe");
        let created_path = std::path::absolute(&created.0).expect("absolute created path");
        {
            let mut hook = PARENT_SYNC_TEST_HOOK
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            *hook = Some(ParentSyncTestHook {
                path: created_path.clone(),
                action: ParentSyncTestAction::Observe,
                invocations: 0,
            });
        }
        let store = Store::open(&created.0).expect("exclusive-new store after parent barrier");
        drop(store);
        {
            let hook = PARENT_SYNC_TEST_HOOK
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            assert_eq!(
                hook.as_ref().expect("observe hook").invocations,
                1,
                "exclusive-new initialization must invoke exactly one parent barrier"
            );
        }
        let store = Store::open(&created.0).expect("existing store reopen");
        drop(store);
        {
            let hook = PARENT_SYNC_TEST_HOOK
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            assert_eq!(
                hook.as_ref().expect("observe hook").invocations,
                2,
                "an existing writable reopen must repeat the exact parent barrier"
            );
        }

        let failed = TestFile::new("new-store-parent-sync-fail");
        let failed_path = std::path::absolute(&failed.0).expect("absolute failed path");
        {
            let mut hook = PARENT_SYNC_TEST_HOOK
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            *hook = Some(ParentSyncTestHook {
                path: failed_path,
                action: ParentSyncTestAction::Fail,
                invocations: 0,
            });
        }
        assert!(matches!(
            Store::open(&failed.0),
            Err(StoreError::StorePath(ref error))
                if error.to_string()
                    == "injected new-store parent synchronization failure"
        ));
        {
            let hook = PARENT_SYNC_TEST_HOOK
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            assert_eq!(hook.as_ref().expect("failure hook").invocations, 1);
        }
        let database = redb::Builder::new()
            .open_read_only(&failed.0)
            .expect("initialized redb after rejected parent barrier");
        let read = database.begin_read().expect("read rejected creation");
        assert_eq!(
            read.list_tables().expect("regular tables").count(),
            0,
            "parent-sync failure must precede every Aster application table"
        );
        assert_eq!(
            read.list_multimap_tables()
                .expect("multimap tables")
                .count(),
            0,
            "parent-sync failure must precede every Aster application table"
        );
        drop(read);
        drop(database);
        {
            let mut hook = PARENT_SYNC_TEST_HOOK
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            hook.as_mut().expect("failure hook").action = ParentSyncTestAction::Observe;
        }
        let services = event_services(0xdd);
        let mut store = Store::open_for_mission(&failed.0, services.authority)
            .expect("existing retry after successful parent barrier");
        {
            let hook = PARENT_SYNC_TEST_HOOK
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            assert_eq!(
                hook.as_ref().expect("retry hook").invocations,
                2,
                "retry must pass a real parent barrier before returning a usable Store"
            );
        }
        let intent = ZeroizationIntent::new(
            b"parent-barrier mission descriptor".to_vec(),
            b"parent-barrier identity descriptor".to_vec(),
        )
        .expect("intent");
        assert_eq!(
            store.begin_zeroization(&intent).expect("terminal marker"),
            BeginZeroizationOutcome::EnteredCleanupPending
        );
        drop(store);
        assert_eq!(
            Store::inspect_zeroization_state(&failed.0)
                .expect("terminal status after successful retry barrier")
                .state(),
            StoreZeroizationState::CleanupPending
        );
        *PARENT_SYNC_TEST_HOOK
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
    }

    #[test]
    fn terminal_zeroization_reopens_linearly_and_preserves_every_data_namespace() {
        let file = TestFile::new("zeroization-linear-reopen");
        let mut events = event_services(0xd1);
        let mut controls = control_services(0xd1);
        assert_eq!(events.authority, controls.authority_id);
        let intent = ZeroizationIntent::new(
            b"v1:mission:/exact/bundle:dev=7:ino=11".to_vec(),
            b"v1:identity:/exact/state/identity.key:dev=7:ino=12".to_vec(),
        )
        .expect("zeroization intent");
        let different_intent = ZeroizationIntent::new(
            b"v1:mission:/replacement:dev=7:ino=99".to_vec(),
            b"v1:identity:/exact/state/identity.key:dev=7:ino=12".to_vec(),
        )
        .expect("different intent");

        let mut store = Store::open_for_mission(&file.0, events.authority).expect("bound store");
        store
            .require_process_exclusive_lock()
            .expect("exact writer exclusion");
        assert!(matches!(
            Store::open_for_zeroization(&file.0),
            Err(StoreError::StoreInUse)
        ));
        let opaque_id = item(0xd1);
        store
            .apply(opaque_id, b"preserved opaque row")
            .expect("opaque row");

        let payload = b"preserved semantic Event";
        let header = event_header(
            events.publisher.identity(),
            1,
            1,
            VersionVector::default(),
            b"zeroization-preserved-event",
            payload,
            None,
        );
        let sealed_event = events
            .publisher
            .seal_event(&header, payload)
            .expect("seal Event");
        let verified_event = content_event(&mut events.reader, &sealed_event.bytes);
        store
            .apply_verified_event(&verified_event, &sealed_event.bytes)
            .expect("semantic Event row");

        let sealed_control = controls
            .authority
            .seal_chained_revocation_control([0xe1; 32], 1, 1, None)
            .expect("seal control");
        let verified_control = verify_control(&mut controls.verifier, &sealed_control);
        store
            .ingest_verified_control(&verified_control, &sealed_control)
            .expect("control row");

        let event_query_policy = store
            .control_policy_snapshot()
            .expect("terminal test Event query policy");
        let event_candidates = store
            .query_event_candidates_with_policy(
                &event_query_policy,
                &EventQueryFilter::default(),
                0,
                1,
            )
            .expect("Event candidate before terminal transition");
        assert_eq!(event_candidates.events.len(), 1);
        assert_eq!(event_candidates.scanned_through, 1);
        assert!(!event_candidates.has_more);

        let subscription = store
            .create_event_subscription_with_policy(
                &event_query_policy,
                &EventSubscriptionKey::new(b"terminal/preserved".to_vec())
                    .expect("terminal subscription key"),
                subscription_spec(EventSubscriptionMode::Consume),
            )
            .expect("terminal subscription")
            .id;
        let subscription_plan = store
            .prepare_event_subscription_poll_with_policy(&event_query_policy, subscription, 1, 1)
            .expect("terminal subscription plan");
        let subscription_selection =
            verify_subscription_plan(&mut events.reader, &subscription_plan);
        store
            .commit_event_subscription_poll_with_policy(
                &event_query_policy,
                &subscription_plan,
                &subscription_selection,
            )
            .expect("terminal pending delivery");
        assert_eq!(
            store
                .acknowledge_event_delivery_with_policy(
                    &event_query_policy,
                    subscription,
                    event_candidates.events[0].semantic_id,
                )
                .expect("terminal acknowledgement receipt"),
            EventDeliveryAck::Acknowledged
        );

        let opaque_before = store.stats().expect("opaque stats");
        let events_before = store.event_stats().expect("Event stats");
        let subscriptions_before = store
            .event_subscription_stats()
            .expect("subscription stats");
        let controls_before = store.control_stats().expect("control stats");
        assert_eq!(opaque_before.items, 1);
        assert_eq!(events_before.events, 1);
        assert_eq!(subscriptions_before.subscriptions, 1);
        assert_eq!(subscriptions_before.pending_deliveries, 0);
        assert_eq!(subscriptions_before.acknowledged_deliveries, 1);
        assert_eq!(controls_before.controls, 1);

        assert_eq!(
            store.begin_zeroization(&intent).expect("terminal marker"),
            BeginZeroizationOutcome::EnteredCleanupPending
        );
        assert!(matches!(
            store.get(opaque_id),
            Err(StoreError::StoreZeroized(
                StoreZeroizationState::CleanupPending
            ))
        ));
        assert!(matches!(
            store.event_count(),
            Err(StoreError::StoreZeroized(
                StoreZeroizationState::CleanupPending
            ))
        ));
        assert!(matches!(
            store.query_event_candidates_with_policy(
                &event_query_policy,
                &EventQueryFilter::default(),
                0,
                1,
            ),
            Err(StoreError::StoreZeroized(
                StoreZeroizationState::CleanupPending
            ))
        ));
        assert!(matches!(
            store.prepare_event_subscription_poll_with_policy(
                &event_query_policy,
                subscription,
                1,
                1,
            ),
            Err(StoreError::StoreZeroized(
                StoreZeroizationState::CleanupPending
            ))
        ));
        assert!(matches!(
            store.acknowledge_event_delivery_with_policy(
                &event_query_policy,
                subscription,
                event_candidates.events[0].semantic_id,
            ),
            Err(StoreError::StoreZeroized(
                StoreZeroizationState::CleanupPending
            ))
        ));
        assert!(matches!(
            store.control_inventory(),
            Err(StoreError::StoreZeroized(
                StoreZeroizationState::CleanupPending
            ))
        ));
        assert!(matches!(
            store.apply(item(0xd2), b"must not commit"),
            Err(StoreError::StoreZeroized(
                StoreZeroizationState::CleanupPending
            ))
        ));
        drop(store);

        for result in [
            Store::open(&file.0),
            Store::open_with_limits(&file.0, StoreLimits::default()),
            Store::open_for_mission(&file.0, events.authority),
            Store::open_with_limits_for_mission(&file.0, StoreLimits::default(), events.authority),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::StoreZeroized(
                    StoreZeroizationState::CleanupPending
                ))
            ));
        }

        let pending = Store::inspect_existing(&file.0).expect("terminal-safe full inspection");
        assert_eq!(pending.stats, opaque_before);
        assert_eq!(pending.event_stats, events_before);
        assert_eq!(pending.event_subscription_stats, subscriptions_before);
        assert_eq!(pending.control_stats, controls_before);
        assert_eq!(
            pending.zeroization.state(),
            StoreZeroizationState::CleanupPending
        );
        assert_eq!(pending.zeroization.intent(), Some(&intent));
        assert_eq!(
            pending.inventory.iter().copied().collect::<Vec<_>>(),
            vec![opaque_id]
        );

        let mut cleanup = Store::open_for_zeroization(&file.0).expect("resume pending cleanup");
        cleanup
            .require_process_exclusive_lock()
            .expect("cleanup writer exclusion");
        assert_eq!(cleanup.zeroization_intent(), Some(&intent));
        assert_eq!(
            cleanup.begin_zeroization(&intent).expect("exact retry"),
            BeginZeroizationOutcome::AlreadyStarted(StoreZeroizationState::CleanupPending)
        );
        assert!(matches!(
            cleanup.begin_zeroization(&different_intent),
            Err(StoreError::ZeroizationIntentConflict)
        ));
        assert!(matches!(
            cleanup.mark_identity_destroyed(),
            Err(StoreError::ZeroizationOrderViolation(_))
        ));
        assert!(matches!(
            cleanup.finalize_zeroization(),
            Err(StoreError::ZeroizationOrderViolation(_))
        ));
        assert_eq!(
            cleanup.mark_mission_destroyed().expect("mission receipt"),
            ArtifactDestructionOutcome::Marked
        );
        drop(cleanup);

        let mission = Store::inspect_zeroization_state(&file.0).expect("mission receipt reopen");
        assert_eq!(mission.state(), StoreZeroizationState::MissionDestroyed);
        assert_eq!(mission.intent(), Some(&intent));
        let mut cleanup = Store::open_for_zeroization(&file.0).expect("resume after mission");
        assert!(cleanup.mission_destroyed());
        assert!(!cleanup.identity_destroyed());
        assert_eq!(
            cleanup
                .mark_mission_destroyed()
                .expect("idempotent mission receipt"),
            ArtifactDestructionOutcome::AlreadyMarked
        );
        assert_eq!(
            cleanup.mark_identity_destroyed().expect("identity receipt"),
            ArtifactDestructionOutcome::Marked
        );
        drop(cleanup);

        assert_eq!(
            Store::inspect_zeroization_state(&file.0)
                .expect("identity receipt reopen")
                .state(),
            StoreZeroizationState::IdentityDestroyed
        );
        let mut cleanup = Store::open_for_zeroization(&file.0).expect("resume before finalize");
        assert_eq!(
            cleanup
                .mark_identity_destroyed()
                .expect("idempotent identity receipt"),
            ArtifactDestructionOutcome::AlreadyMarked
        );
        assert_eq!(
            cleanup.finalize_zeroization().expect("finalize"),
            FinalizeZeroizationOutcome::Finalized
        );
        drop(cleanup);

        let mut cleanup = Store::open_for_zeroization(&file.0).expect("complete cleanup reopen");
        assert_eq!(cleanup.zeroization_state(), StoreZeroizationState::Complete);
        assert_eq!(
            cleanup
                .begin_zeroization(&intent)
                .expect("complete exact retry"),
            BeginZeroizationOutcome::AlreadyStarted(StoreZeroizationState::Complete)
        );
        assert_eq!(
            cleanup.finalize_zeroization().expect("idempotent finalize"),
            FinalizeZeroizationOutcome::AlreadyComplete
        );
        let preserved = cleanup
            .inspect_preserved()
            .expect("preserved terminal rows");
        assert_eq!(preserved.stats, opaque_before);
        assert_eq!(preserved.event_stats, events_before);
        assert_eq!(preserved.event_subscription_stats, subscriptions_before);
        assert_eq!(preserved.control_stats, controls_before);
        assert_eq!(
            preserved.zeroization.state(),
            StoreZeroizationState::Complete
        );
    }

    #[test]
    fn normal_open_write_gate_observes_terminal_marker_before_any_schema_touch() {
        let file = TestFile::new("zeroization-open-write-gate");
        let services = event_services(0xd2);
        let intent = ZeroizationIntent::new(
            b"mission write-gate descriptor".to_vec(),
            b"identity write-gate descriptor".to_vec(),
        )
        .expect("intent");
        {
            let mut store = Store::open_for_mission(&file.0, services.authority).expect("store");
            store.apply(item(0xd2), b"preserved").expect("row");
            store.begin_zeroization(&intent).expect("terminal marker");
        }

        let database = Database::open(&file.0).expect("raw normal-open writer");
        let write = database
            .begin_write()
            .expect("normal-open write transaction");
        let tables_before = write
            .list_tables()
            .expect("tables before guard")
            .map(|table| table.name().to_owned())
            .collect::<std::collections::BTreeSet<_>>();
        assert!(matches!(
            enforce_live_write(&write),
            Err(StoreError::StoreZeroized(
                StoreZeroizationState::CleanupPending
            ))
        ));
        let tables_after = write
            .list_tables()
            .expect("tables after guard")
            .map(|table| table.name().to_owned())
            .collect::<std::collections::BTreeSet<_>>();
        assert_eq!(
            tables_after, tables_before,
            "guard must not create or repair tables"
        );
        drop(write);
        drop(database);

        let inspection = Store::inspect_existing(&file.0).expect("preserved terminal store");
        assert_eq!(inspection.stats.items, 1);
        assert_eq!(
            inspection.zeroization.state(),
            StoreZeroizationState::CleanupPending
        );
    }

    #[test]
    fn wrong_kind_reserved_terminal_table_fails_closed_without_application_repair() {
        let file = TestFile::new("zeroization-wrong-table-kind");
        let services = event_services(0xd6);
        {
            let store = Store::open_for_mission(&file.0, services.authority).expect("store");
            store.apply(item(0xd6), b"preserved").expect("row");
        }
        {
            let database = Database::open(&file.0).expect("raw wrong-kind store");
            let write = database.begin_write().expect("wrong-kind write");
            write
                .open_table(METADATA)
                .expect("metadata")
                .remove(TOTAL_PAYLOAD_BYTES)
                .expect("remove migration target");
            let definition =
                redb::MultimapTableDefinition::<&str, &[u8]>::new("aster.zeroization.v1");
            write
                .open_multimap_table(definition)
                .expect("reserved-name multimap")
                .insert("state", b"wrong-kind".as_slice())
                .expect("wrong-kind row");
            write.commit().expect("commit wrong-kind schema");
        }

        for result in [
            Store::inspect_zeroization_state(&file.0).map(|_| ()),
            Store::inspect_existing(&file.0).map(|_| ()),
            Store::open_for_mission(&file.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::ZeroizationInvariant(
                    "reserved terminal table name has the wrong table kind"
                ))
            ));
        }
        let database = redb::Builder::new()
            .open_read_only(&file.0)
            .expect("read wrong-kind store");
        let read = database.begin_read().expect("read transaction");
        assert!(
            read.open_table(METADATA)
                .expect("metadata")
                .get(TOTAL_PAYLOAD_BYTES)
                .expect("migration target")
                .is_none(),
            "wrong-kind terminal rejection must not repair application metadata"
        );
    }

    #[test]
    fn recovery_only_status_rejects_wrong_kind_mission_domain_without_application_mutation() {
        let file = TestFile::new("zeroization-wrong-domain-kind");
        {
            let database = Database::create(&file.0).expect("create wrong-kind store");
            let write = database.begin_write().expect("wrong-kind write");
            let definition =
                redb::MultimapTableDefinition::<&str, &[u8]>::new("aster.semantic-domain.v1");
            write
                .open_multimap_table(definition)
                .expect("wrong-kind mission domain")
                .insert(MISSION_AUTHORITY_ID, b"not-a-binding".as_slice())
                .expect("wrong-kind row");
            write.commit().expect("commit wrong-kind schema");
        }

        for result in [
            Store::inspect_zeroization_state(&file.0).map(|_| ()),
            Store::recover_zeroization_state(&file.0).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::SemanticInvariant(
                    "semantic mission domain has the wrong table kind"
                ))
            ));
        }

        let database = redb::Builder::new()
            .open_read_only(&file.0)
            .expect("read wrong-kind store");
        let read = database.begin_read().expect("read transaction");
        assert_eq!(
            read.list_tables().expect("regular tables").count(),
            0,
            "recovery-only rejection must not create any Aster application table"
        );
        assert!(
            read.list_multimap_tables()
                .expect("multimap tables")
                .any(|table| table.name() == SEMANTIC_DOMAIN.name())
        );
    }

    #[test]
    fn partial_or_corrupt_terminal_schema_fails_closed_without_repair() {
        let base = TestFile::new("zeroization-corruption-base");
        let services = event_services(0xd3);
        let intent = ZeroizationIntent::new(
            b"mission descriptor".to_vec(),
            b"identity descriptor".to_vec(),
        )
        .expect("intent");
        {
            let mut store = Store::open_for_mission(&base.0, services.authority).expect("store");
            store.apply(item(0xd3), b"preserve me").expect("row");
            store.begin_zeroization(&intent).expect("begin");
        }

        let reject_without_repair = |file: &TestFile| {
            let before = std::fs::read(&file.0).expect("corrupt store bytes");
            assert!(matches!(
                Store::inspect_zeroization_state(&file.0),
                Err(StoreError::ZeroizationInvariant(_))
            ));
            assert!(matches!(
                Store::inspect_existing(&file.0),
                Err(StoreError::ZeroizationInvariant(_))
            ));
            assert!(matches!(
                Store::open_for_mission(&file.0, services.authority),
                Err(StoreError::ZeroizationInvariant(_))
            ));
            assert_eq!(
                std::fs::read(&file.0).expect("bytes after rejected opens"),
                before,
                "terminal rejection must not repair or rewrite the store"
            );
        };

        let empty = TestFile::new("zeroization-empty-table");
        std::fs::copy(&base.0, &empty.0).expect("copy empty-table case");
        {
            let database = Database::open(&empty.0).expect("raw empty store");
            let write = database.begin_write().expect("raw empty write");
            write
                .delete_table(ZEROIZATION)
                .expect("delete terminal table");
            write
                .open_table(ZEROIZATION)
                .expect("recreate empty terminal table");
            write.commit().expect("commit empty terminal table");
        }
        reject_without_repair(&empty);

        let extra = TestFile::new("zeroization-extra-row");
        std::fs::copy(&base.0, &extra.0).expect("copy extra-row case");
        {
            let database = Database::open(&extra.0).expect("raw extra store");
            let write = database.begin_write().expect("raw extra write");
            write
                .open_table(ZEROIZATION)
                .expect("terminal table")
                .insert("extra", b"unexpected".as_slice())
                .expect("insert extra row");
            write.commit().expect("commit extra row");
        }
        reject_without_repair(&extra);

        let bad_digest = TestFile::new("zeroization-bad-digest");
        std::fs::copy(&base.0, &bad_digest.0).expect("copy digest case");
        {
            let database = Database::open(&bad_digest.0).expect("raw digest store");
            let write = database.begin_write().expect("raw digest write");
            let mut encoded = write
                .open_table(ZEROIZATION)
                .expect("terminal table")
                .get(ZEROIZATION_STATE_KEY)
                .expect("read terminal")
                .expect("state row")
                .value()
                .to_vec();
            encoded[10] ^= 0x01;
            write
                .open_table(ZEROIZATION)
                .expect("terminal table")
                .insert(ZEROIZATION_STATE_KEY, encoded.as_slice())
                .expect("write corrupt digest");
            write.commit().expect("commit corrupt digest");
        }
        reject_without_repair(&bad_digest);

        let bad_receipts = TestFile::new("zeroization-bad-receipts");
        std::fs::copy(&base.0, &bad_receipts.0).expect("copy receipt case");
        {
            let database = Database::open(&bad_receipts.0).expect("raw receipt store");
            let write = database.begin_write().expect("raw receipt write");
            let mut encoded = write
                .open_table(ZEROIZATION)
                .expect("terminal table")
                .get(ZEROIZATION_STATE_KEY)
                .expect("read terminal")
                .expect("state row")
                .value()
                .to_vec();
            encoded[8] = 1;
            encoded[9] = 3;
            let digest_offset = encoded.len() - ZEROIZATION_DIGEST_BYTES;
            let digest: [u8; ZEROIZATION_DIGEST_BYTES] =
                Sha256::digest(&encoded[..digest_offset]).into();
            encoded[digest_offset..].copy_from_slice(&digest);
            write
                .open_table(ZEROIZATION)
                .expect("terminal table")
                .insert(ZEROIZATION_STATE_KEY, encoded.as_slice())
                .expect("write inconsistent receipts");
            write.commit().expect("commit inconsistent receipts");
        }
        reject_without_repair(&bad_receipts);

        for (name, length_offset, length, expected_reason) in [
            (
                "zeroization-hostile-mission-length",
                42usize,
                u32::MAX,
                "terminal mission descriptor length is outside its bound",
            ),
            (
                "zeroization-hostile-identity-length",
                46usize,
                0u32,
                "terminal identity descriptor length is outside its bound",
            ),
        ] {
            let hostile = TestFile::new(name);
            std::fs::copy(&base.0, &hostile.0).expect("copy hostile length case");
            {
                let database = Database::open(&hostile.0).expect("raw hostile store");
                let write = database.begin_write().expect("raw hostile write");
                let mut encoded = write
                    .open_table(ZEROIZATION)
                    .expect("terminal table")
                    .get(ZEROIZATION_STATE_KEY)
                    .expect("read terminal")
                    .expect("state row")
                    .value()
                    .to_vec();
                encoded[length_offset..length_offset + 4].copy_from_slice(&length.to_be_bytes());
                let digest_offset = encoded.len() - ZEROIZATION_DIGEST_BYTES;
                let digest: [u8; ZEROIZATION_DIGEST_BYTES] =
                    Sha256::digest(&encoded[..digest_offset]).into();
                encoded[digest_offset..].copy_from_slice(&digest);
                write
                    .open_table(ZEROIZATION)
                    .expect("terminal table")
                    .insert(ZEROIZATION_STATE_KEY, encoded.as_slice())
                    .expect("write hostile valid-digest length");
                write.commit().expect("commit hostile length");
            }
            assert!(matches!(
                Store::inspect_zeroization_state(&hostile.0),
                Err(StoreError::ZeroizationInvariant(reason)) if reason == expected_reason
            ));
            reject_without_repair(&hostile);
        }

        let oversized = TestFile::new("zeroization-hostile-oversized-record");
        std::fs::copy(&base.0, &oversized.0).expect("copy oversized record case");
        {
            let database = Database::open(&oversized.0).expect("raw oversized store");
            let write = database.begin_write().expect("raw oversized write");
            let mut encoded = write
                .open_table(ZEROIZATION)
                .expect("terminal table")
                .get(ZEROIZATION_STATE_KEY)
                .expect("read terminal")
                .expect("state row")
                .value()
                .to_vec();
            encoded.truncate(encoded.len() - ZEROIZATION_DIGEST_BYTES);
            encoded.resize(
                (MAX_ZEROIZATION_RECORD_BYTES + 1) - ZEROIZATION_DIGEST_BYTES,
                0xa5,
            );
            let digest: [u8; ZEROIZATION_DIGEST_BYTES] = Sha256::digest(&encoded).into();
            encoded.extend_from_slice(&digest);
            assert_eq!(encoded.len(), MAX_ZEROIZATION_RECORD_BYTES + 1);
            write
                .open_table(ZEROIZATION)
                .expect("terminal table")
                .insert(ZEROIZATION_STATE_KEY, encoded.as_slice())
                .expect("write oversized valid-digest record");
            write.commit().expect("commit oversized record");
        }
        assert!(matches!(
            Store::inspect_zeroization_state(&oversized.0),
            Err(StoreError::ZeroizationInvariant(
                "terminal record exceeds maximum encoded length"
            ))
        ));
        reject_without_repair(&oversized);
    }

    #[test]
    fn state_operation_intent_is_restart_idempotent_epoch_independent_and_publisher_bound() {
        let file = TestFile::new("State operation intent");
        let mut services = state_services(0xb1);
        let store = Store::open_for_mission(&file.0, services.authority).expect("open store");
        let policy = store.control_policy_snapshot().expect("settled policy");
        let operation = StateOperationKey::new(b"state/op/1".to_vec()).expect("operation key");

        let reservation = store
            .reserve_state_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve first State");
        let (future, future_sealed, future_intent) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &reservation,
            b"asset/7",
            b"alpha",
            false,
            2,
        );
        let future_request = StateOperationRequest::new(&operation, &future_intent, b"alpha")
            .expect("future operation request");
        assert!(matches!(
            store.commit_reserved_state_once_with_policy(
                &policy,
                &future_request,
                &reservation,
                &future,
                &future_sealed,
            ),
            Err(StoreError::StateKeyEpochNotActive {
                current: 1,
                received: 2
            })
        ));
        assert_eq!(
            store.state_stats().expect("empty State stats"),
            StateStoreStats::default()
        );
        assert_eq!(
            store
                .state_for_operation(&operation)
                .expect("absent future operation"),
            None
        );
        let (state, sealed, intent) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &reservation,
            b"asset/7",
            b"alpha",
            false,
            1,
        );
        let request =
            StateOperationRequest::new(&operation, &intent, b"alpha").expect("operation request");
        let inserted = store
            .commit_reserved_state_once_with_policy(
                &policy,
                &request,
                &reservation,
                &state,
                &sealed,
            )
            .expect("commit State operation");
        assert!(matches!(inserted, StateOnceOutcome::Inserted { .. }));
        let original = inserted.state().clone();

        let activate_epoch = store.database.begin_write().expect("raw epoch activation");
        activate_epoch
            .open_table(CONTROL_SCOPE_EPOCHS)
            .expect("scope epochs")
            .insert(
                state_scope().as_str(),
                encode_scope_epoch_index(2, ControlTransferId::new([0x22; 32])).as_slice(),
            )
            .expect("activate epoch two for retry test");
        activate_epoch.commit().expect("commit epoch activation");

        let retry_reservation = store
            .reserve_state_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve retry State");
        let (retry, retry_sealed, retry_intent) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &retry_reservation,
            b"asset/7",
            b"alpha",
            false,
            2,
        );
        let retry_request = StateOperationRequest::new(&operation, &retry_intent, b"alpha")
            .expect("retry operation request");
        let existing = store
            .commit_reserved_state_once_with_policy(
                &policy,
                &retry_request,
                &retry_reservation,
                &retry,
                &retry_sealed,
            )
            .expect("exact retry after epoch change");
        assert!(matches!(existing, StateOnceOutcome::Existing { .. }));
        assert_eq!(existing.state(), &original);

        let (changed, changed_sealed, changed_intent) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &retry_reservation,
            b"asset/7",
            b"bravo",
            false,
            2,
        );
        let changed_request = StateOperationRequest::new(&operation, &changed_intent, b"bravo")
            .expect("changed operation request");
        assert!(matches!(
            store.commit_reserved_state_once_with_policy(
                &policy,
                &changed_request,
                &retry_reservation,
                &changed,
                &changed_sealed,
            ),
            Err(StoreError::StateOperationConflict)
        ));

        let other_reservation = store
            .reserve_state_with_policy(
                &policy,
                services.second.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve other publisher");
        let (other, other_sealed, other_intent) = reserved_state(
            &mut services.second,
            &mut services.reader,
            &other_reservation,
            b"asset/7",
            b"alpha",
            false,
            2,
        );
        let other_request = StateOperationRequest::new(&operation, &other_intent, b"alpha")
            .expect("other-publisher operation request");
        assert!(matches!(
            store.commit_reserved_state_once_with_policy(
                &policy,
                &other_request,
                &other_reservation,
                &other,
                &other_sealed,
            ),
            Err(StoreError::StateOperationConflict)
        ));
        let cleanup_epoch = store.database.begin_write().expect("raw epoch cleanup");
        cleanup_epoch
            .open_table(CONTROL_SCOPE_EPOCHS)
            .expect("scope epochs")
            .remove(state_scope().as_str())
            .expect("remove synthetic epoch activation");
        cleanup_epoch.commit().expect("commit epoch cleanup");
        drop(store);

        let reopened = Store::open_for_mission(&file.0, services.authority).expect("reopen store");
        let reopened_retry = reopened
            .commit_reserved_state_once_with_policy(
                &policy,
                &request,
                &reservation,
                &state,
                &sealed,
            )
            .expect("post-reopen exact operation retry");
        assert!(matches!(reopened_retry, StateOnceOutcome::Existing { .. }));
        assert_eq!(reopened_retry.state(), &original);

        let revoke = reopened
            .database
            .begin_write()
            .expect("raw publisher revocation");
        revoke
            .open_table(CONTROL_REVOCATIONS)
            .expect("revocation table")
            .insert(
                services.first.identity().as_slice(),
                encode_revocation_index(services.authority, 1, ControlTransferId::new([0x77; 32]))
                    .as_slice(),
            )
            .expect("insert synthetic revocation");
        revoke.commit().expect("commit synthetic revocation");
        assert!(matches!(
            reopened.commit_reserved_state_once_with_policy(
                &policy,
                &request,
                &reservation,
                &state,
                &sealed,
            ),
            Err(StoreError::StatePublisherRevoked(publisher))
                if publisher == services.first.identity()
        ));
        let restore = reopened
            .database
            .begin_write()
            .expect("raw revocation cleanup");
        restore
            .open_table(CONTROL_REVOCATIONS)
            .expect("revocation table")
            .remove(services.first.identity().as_slice())
            .expect("remove synthetic revocation");
        restore.commit().expect("commit revocation cleanup");
        assert_eq!(
            reopened
                .state_for_operation(&operation)
                .expect("operation lookup"),
            Some(original)
        );
        assert_eq!(
            reopened.state_stats().expect("State stats"),
            StateStoreStats {
                states: 1,
                acceptance_markers: 1,
                total_sealed_bytes: u64::try_from(sealed.len()).expect("sealed length"),
                last_acceptance_marker: 1,
                operations: 1,
                operation_bytes: u64::try_from(operation.as_bytes().len() + 65)
                    .expect("operation bytes"),
            }
        );
    }

    #[test]
    fn state_operation_caps_and_aggregate_quota_fail_atomically_on_existing_state_binding() {
        let aggregate_file = TestFile::new("State operation aggregate quota");
        let mut aggregate_services = state_services(0xb7);
        let aggregate_limits = StoreLimits::new(
            MAX_CONTROL_ITEMS + CUSTODY_EMERGENCY_ITEM_RESERVE + 2,
            DEFAULT_MAX_TOTAL_PAYLOAD_BYTES,
        )
        .expect("aggregate limits");
        let aggregate_store = Store::open_with_limits_for_mission(
            &aggregate_file.0,
            aggregate_limits,
            aggregate_services.authority,
        )
        .expect("open aggregate-limited store");
        let aggregate_policy = aggregate_store
            .control_policy_snapshot()
            .expect("aggregate policy");
        let aggregate_reservation = aggregate_store
            .reserve_state_with_policy(
                &aggregate_policy,
                aggregate_services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve aggregate State");
        let (aggregate_state, aggregate_sealed, aggregate_intent) = reserved_state(
            &mut aggregate_services.first,
            &mut aggregate_services.reader,
            &aggregate_reservation,
            b"aggregate/key",
            b"value",
            false,
            1,
        );
        let first_operation =
            StateOperationKey::new(b"aggregate/first".to_vec()).expect("first operation");
        let first_request =
            StateOperationRequest::new(&first_operation, &aggregate_intent, b"value")
                .expect("first request");
        aggregate_store
            .commit_reserved_state_once_with_policy(
                &aggregate_policy,
                &first_request,
                &aggregate_reservation,
                &aggregate_state,
                &aggregate_sealed,
            )
            .expect("fill aggregate item quota");
        let overflow_operation =
            StateOperationKey::new(b"aggregate/overflow".to_vec()).expect("overflow operation");
        let overflow_request =
            StateOperationRequest::new(&overflow_operation, &aggregate_intent, b"value")
                .expect("overflow request");
        assert!(matches!(
            aggregate_store.commit_reserved_state_once_with_policy(
                &aggregate_policy,
                &overflow_request,
                &aggregate_reservation,
                &aggregate_state,
                &aggregate_sealed,
            ),
            Err(StoreError::ItemLimitExceeded {
                current: 2,
                limit: 2
            })
        ));
        assert_eq!(
            aggregate_store
                .state_for_operation(&overflow_operation)
                .expect("aggregate overflow lookup"),
            None
        );
        assert_eq!(
            aggregate_store
                .state_stats()
                .expect("aggregate rollback stats")
                .operations,
            1
        );
        drop(aggregate_store);
        let aggregate_reopened = Store::open_with_limits_for_mission(
            &aggregate_file.0,
            aggregate_limits,
            aggregate_services.authority,
        )
        .expect("reopen aggregate-limited store");
        assert_eq!(
            aggregate_reopened
                .state_stats()
                .expect("reopened aggregate stats")
                .operations,
            1
        );
        assert_eq!(
            aggregate_reopened
                .state_for_operation(&overflow_operation)
                .expect("reopened overflow lookup"),
            None
        );
        drop(aggregate_reopened);

        let cap_file = TestFile::new("State operation dedicated caps");
        let mut cap_services = state_services(0xb8);
        let cap_store =
            Store::open_for_mission(&cap_file.0, cap_services.authority).expect("open cap store");
        let cap_policy = cap_store.control_policy_snapshot().expect("cap policy");
        let cap_reservation = cap_store
            .reserve_state_with_policy(
                &cap_policy,
                cap_services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve cap State");
        let (cap_state, cap_sealed, cap_intent) = reserved_state(
            &mut cap_services.first,
            &mut cap_services.reader,
            &cap_reservation,
            b"cap/key",
            b"value",
            false,
            1,
        );
        cap_store
            .commit_reserved_state_with_policy(
                &cap_policy,
                &cap_reservation,
                &cap_state,
                &cap_sealed,
            )
            .expect("commit unbound State");
        let transfer_id = StateTransferId::new(cap_state.envelope_id());
        let encoded_record = encode_state_operation_record(StateOperationRecord {
            transfer_id,
            intent_digest: cap_intent.digest(),
        });
        assert_eq!(encoded_record.len(), 65);

        let row_fill = cap_store
            .database
            .begin_write()
            .expect("row-cap fill write");
        let mut row_bytes = 0u64;
        {
            let mut operations = row_fill
                .open_table(STATE_OPERATIONS)
                .expect("State operations");
            for index in 0..MAX_STATE_OPERATIONS {
                let mut key = vec![b'r'];
                key.extend_from_slice(&index.to_be_bytes());
                assert_eq!(key.len(), 9);
                operations
                    .insert(key.as_slice(), encoded_record.as_slice())
                    .expect("insert row-cap operation");
                row_bytes = row_bytes
                    .checked_add(
                        u64::try_from(key.len() + encoded_record.len())
                            .expect("row-cap byte length"),
                    )
                    .expect("row-cap byte sum");
            }
        }
        {
            let mut metadata = row_fill.open_table(METADATA).expect("metadata");
            metadata
                .insert(STATE_OPERATION_COUNT, MAX_STATE_OPERATIONS)
                .expect("row-cap count");
            metadata
                .insert(STATE_OPERATION_TOTAL_BYTES, row_bytes)
                .expect("row-cap bytes");
        }
        row_fill.commit().expect("commit row-cap fill");
        assert!(row_bytes < MAX_STATE_OPERATION_BYTES);

        let row_overflow =
            StateOperationKey::new(b"row-cap/overflow".to_vec()).expect("row overflow key");
        let row_overflow_request = StateOperationRequest::new(&row_overflow, &cap_intent, b"value")
            .expect("row overflow request");
        assert!(matches!(
            cap_store.commit_reserved_state_once_with_policy(
                &cap_policy,
                &row_overflow_request,
                &cap_reservation,
                &cap_state,
                &cap_sealed,
            ),
            Err(StoreError::StateOperationLimitExceeded {
                current: MAX_STATE_OPERATIONS,
                limit: MAX_STATE_OPERATIONS
            })
        ));
        assert_eq!(
            cap_store
                .state_for_operation(&row_overflow)
                .expect("row overflow lookup"),
            None
        );
        assert_eq!(
            cap_store.state_stats().expect("row-cap stats").operations,
            MAX_STATE_OPERATIONS
        );
        drop(cap_store);
        assert_eq!(
            Store::inspect_existing(&cap_file.0)
                .expect("inspect row cap")
                .state_stats
                .operations,
            MAX_STATE_OPERATIONS
        );
        let cap_store =
            Store::open_for_mission(&cap_file.0, cap_services.authority).expect("reopen row cap");

        let byte_fill = cap_store
            .database
            .begin_write()
            .expect("byte-cap fill write");
        {
            let mut operations = byte_fill
                .open_table(STATE_OPERATIONS)
                .expect("State operations");
            let keys = operations
                .iter()
                .expect("iterate row-cap operations")
                .map(|row| row.map(|(key, _)| key.value().to_vec()))
                .collect::<Result<Vec<_>, _>>()
                .expect("collect row-cap operation keys");
            for key in keys {
                operations
                    .remove(key.as_slice())
                    .expect("remove row-cap operation");
            }
        }
        let per_byte_row = u64::try_from(MAX_STATE_OPERATION_KEY_BYTES + encoded_record.len())
            .expect("byte row length");
        let byte_rows = MAX_STATE_OPERATION_BYTES / per_byte_row;
        assert!(byte_rows < MAX_STATE_OPERATIONS);
        let mut byte_total = 0u64;
        {
            let mut operations = byte_fill
                .open_table(STATE_OPERATIONS)
                .expect("State operations");
            for index in 0..byte_rows {
                let mut key = vec![0x5a; MAX_STATE_OPERATION_KEY_BYTES];
                key[0] = b'b';
                key[1..9].copy_from_slice(&index.to_be_bytes());
                operations
                    .insert(key.as_slice(), encoded_record.as_slice())
                    .expect("insert byte-cap operation");
                byte_total = byte_total
                    .checked_add(per_byte_row)
                    .expect("byte-cap byte sum");
            }
        }
        {
            let mut metadata = byte_fill.open_table(METADATA).expect("metadata");
            metadata
                .insert(STATE_OPERATION_COUNT, byte_rows)
                .expect("byte-cap count");
            metadata
                .insert(STATE_OPERATION_TOTAL_BYTES, byte_total)
                .expect("byte-cap bytes");
        }
        byte_fill.commit().expect("commit byte-cap fill");
        assert_eq!(MAX_STATE_OPERATION_BYTES - byte_total, 95);

        let byte_overflow =
            StateOperationKey::new(vec![b'o'; 31]).expect("byte overflow operation");
        let byte_overflow_request =
            StateOperationRequest::new(&byte_overflow, &cap_intent, b"value")
                .expect("byte overflow request");
        assert!(matches!(
            cap_store.commit_reserved_state_once_with_policy(
                &cap_policy,
                &byte_overflow_request,
                &cap_reservation,
                &cap_state,
                &cap_sealed,
            ),
            Err(StoreError::StateOperationByteLimitExceeded {
                current,
                incoming: 96,
                limit: MAX_STATE_OPERATION_BYTES
            }) if current == byte_total
        ));
        assert_eq!(
            cap_store
                .state_for_operation(&byte_overflow)
                .expect("byte overflow lookup"),
            None
        );
        assert_eq!(
            cap_store
                .state_stats()
                .expect("byte-cap rollback stats")
                .operation_bytes,
            byte_total
        );
        drop(cap_store);
        let inspection = Store::inspect_existing(&cap_file.0).expect("inspect byte cap");
        assert_eq!(inspection.state_stats.operations, byte_rows);
        assert_eq!(inspection.state_stats.operation_bytes, byte_total);
        let reopened =
            Store::open_for_mission(&cap_file.0, cap_services.authority).expect("reopen byte cap");
        assert_eq!(
            reopened
                .state_for_operation(&byte_overflow)
                .expect("reopened byte overflow lookup"),
            None
        );
    }

    #[test]
    fn state_schema_group_migrates_only_whole_absent_and_rejects_partial_or_wrong_kind() {
        let mut services = event_services(0xb9);
        let payload = b"preserved Event ledger";
        let header = event_header(
            services.publisher.identity(),
            1,
            1,
            VersionVector::default(),
            b"preserved/event",
            payload,
            None,
        );
        let sealed = services
            .publisher
            .seal_event(&header, payload)
            .expect("seal preserved Event");
        let verified = content_event(&mut services.reader, &sealed.bytes);
        let event_transfer = EventTransferId::new(verified.envelope_id());
        let create_event_store = |path: &Path| {
            let store = Store::open_for_mission(path, services.authority)
                .expect("open native Event fixture store");
            store
                .apply_verified_event(&verified, &sealed.bytes)
                .expect("commit preserved Event");
        };

        let missing_table = TestFile::new("State schema missing table");
        create_event_store(&missing_table.0);
        {
            let database = Database::open(&missing_table.0).expect("missing-table database");
            let write = database.begin_write().expect("missing-table write");
            write
                .delete_table(STATE_OPERATIONS)
                .expect("delete State operation table");
            write.commit().expect("commit missing State table");
        }
        for result in [
            Store::inspect_existing(&missing_table.0).map(|_| ()),
            Store::open_for_mission(&missing_table.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::StateInvariant(
                    "mission-scoped State schema group is incomplete"
                ))
            ));
        }
        {
            let database = redb::Builder::new()
                .open_read_only(&missing_table.0)
                .expect("read missing-table store");
            let read = database.begin_read().expect("missing-table read");
            assert!(
                !read
                    .list_tables()
                    .expect("list missing-table schema")
                    .any(|table| table.name() == STATE_OPERATIONS.name())
            );
        }

        let missing_counter = TestFile::new("State schema missing counter");
        create_event_store(&missing_counter.0);
        {
            let database = Database::open(&missing_counter.0).expect("missing-counter database");
            let write = database.begin_write().expect("missing-counter write");
            write
                .open_table(METADATA)
                .expect("metadata")
                .remove(STATE_OPERATION_COUNT)
                .expect("remove State operation counter");
            write.commit().expect("commit missing State counter");
        }
        for result in [
            Store::inspect_existing(&missing_counter.0).map(|_| ()),
            Store::open_for_mission(&missing_counter.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::StateInvariant(
                    "mission-scoped State schema group is incomplete"
                ))
            ));
        }
        {
            let database = redb::Builder::new()
                .open_read_only(&missing_counter.0)
                .expect("read missing-counter store");
            let read = database.begin_read().expect("missing-counter read");
            assert!(
                read.open_table(METADATA)
                    .expect("metadata")
                    .get(STATE_OPERATION_COUNT)
                    .expect("State operation counter")
                    .is_none()
            );
        }

        let wrong_kind = TestFile::new("State schema wrong kind");
        create_event_store(&wrong_kind.0);
        {
            let database = Database::open(&wrong_kind.0).expect("wrong-kind database");
            let write = database.begin_write().expect("wrong-kind write");
            write
                .delete_table(STATE_OPERATIONS)
                .expect("delete normal State operation table");
            let definition =
                redb::MultimapTableDefinition::<&[u8], &[u8]>::new("aster.state-operations.v1");
            write
                .open_multimap_table(definition)
                .expect("wrong-kind State operation table")
                .insert(b"operation".as_slice(), b"record".as_slice())
                .expect("wrong-kind State operation row");
            write.commit().expect("commit wrong-kind State schema");
        }
        for result in [
            Store::inspect_existing(&wrong_kind.0).map(|_| ()),
            Store::open_for_mission(&wrong_kind.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::StateInvariant(
                    "mission-scoped State schema has the wrong table kind"
                ))
            ));
        }
        {
            let database = redb::Builder::new()
                .open_read_only(&wrong_kind.0)
                .expect("read wrong-kind store");
            let read = database.begin_read().expect("wrong-kind read");
            assert!(
                read.list_multimap_tables()
                    .expect("list wrong-kind schema")
                    .any(|table| table.name() == STATE_OPERATIONS.name())
            );
            assert!(
                !read
                    .list_tables()
                    .expect("list normal State schema")
                    .any(|table| table.name() == STATE_OPERATIONS.name())
            );
        }

        let legacy = TestFile::new("State schema whole-absent migration");
        create_event_store(&legacy.0);
        {
            let database = Database::open(&legacy.0).expect("legacy database");
            let write = database.begin_write().expect("legacy write");
            write.delete_table(STATES).expect("delete State metadata");
            write.delete_table(STATE_BYTES).expect("delete State bytes");
            write
                .delete_table(STATE_ACCEPTANCE_MARKERS)
                .expect("delete State markers");
            write
                .delete_table(STATE_SEMANTIC_ITEMS)
                .expect("delete State semantic index");
            write
                .delete_table(STATE_GROUP_VERSIONS)
                .expect("delete State group index");
            write
                .delete_table(STATE_OPERATIONS)
                .expect("delete State operations");
            write
                .delete_table(STATE_ACCEPTANCE_ORDER)
                .expect("delete post-legacy State acceptance order");
            write
                .delete_table(state_subscription::STATE_SUBSCRIPTIONS)
                .expect("delete post-legacy State subscriptions");
            write
                .delete_table(state_subscription::STATE_SUBSCRIPTION_PENDING)
                .expect("delete post-legacy State pending deliveries");
            write
                .delete_table(state_subscription::STATE_DELIVERY_ACKNOWLEDGEMENTS)
                .expect("delete post-legacy State acknowledgements");
            write
                .delete_table(state_subscription::STATE_DELIVERY_CURSORS)
                .expect("delete post-legacy State delivery cursors");
            {
                let mut metadata = write.open_table(METADATA).expect("metadata");
                for field in [
                    STATE_ITEM_COUNT,
                    STATE_TOTAL_BYTES,
                    LAST_STATE_ACCEPTANCE_MARKER,
                    STATE_OPERATION_COUNT,
                    STATE_OPERATION_TOTAL_BYTES,
                    state_subscription::STATE_SUBSCRIPTION_COUNT,
                    state_subscription::STATE_PENDING_DELIVERY_COUNT,
                    state_subscription::STATE_ACKNOWLEDGEMENT_COUNT,
                    state_subscription::STATE_DELIVERY_CURSOR_COUNT,
                    state_subscription::STATE_SELECTOR_GENERATION,
                ] {
                    metadata.remove(field).expect("remove State counter");
                }
            }
            write.commit().expect("commit whole-absent legacy group");
        }
        let before = Store::inspect_existing(&legacy.0).expect("inspect legacy Event store");
        assert_eq!(before.event_stats.events, 1);
        assert_eq!(before.state_stats, StateStoreStats::default());
        {
            let migrated = Store::open_for_mission(&legacy.0, services.authority)
                .expect("atomically create State schema group");
            assert_eq!(
                migrated.state_stats().expect("migrated State stats"),
                StateStoreStats::default()
            );
            assert!(
                migrated
                    .get_event(event_transfer)
                    .expect("preserved Event lookup")
                    .is_some()
            );
            assert_eq!(
                migrated
                    .event_stats()
                    .expect("preserved Event stats")
                    .events,
                1
            );
        }
        let after = Store::inspect_existing(&legacy.0).expect("inspect migrated store");
        assert_eq!(after.event_stats, before.event_stats);
        assert_eq!(after.state_stats, StateStoreStats::default());
        {
            let database = redb::Builder::new()
                .open_read_only(&legacy.0)
                .expect("read migrated store");
            let read = database.begin_read().expect("migrated read");
            let table_names = read
                .list_tables()
                .expect("list migrated tables")
                .map(|table| table.name().to_owned())
                .collect::<std::collections::BTreeSet<_>>();
            for table in [
                STATES.name(),
                STATE_BYTES.name(),
                STATE_ACCEPTANCE_MARKERS.name(),
                STATE_SEMANTIC_ITEMS.name(),
                STATE_GROUP_VERSIONS.name(),
                STATE_OPERATIONS.name(),
            ] {
                assert!(table_names.contains(table));
            }
            let metadata = read.open_table(METADATA).expect("migrated metadata");
            for field in [
                STATE_ITEM_COUNT,
                STATE_TOTAL_BYTES,
                LAST_STATE_ACCEPTANCE_MARKER,
                STATE_OPERATION_COUNT,
                STATE_OPERATION_TOTAL_BYTES,
            ] {
                assert_eq!(
                    metadata
                        .get(field)
                        .expect("migrated State counter")
                        .expect("State counter present")
                        .value(),
                    0
                );
            }
        }
    }

    #[test]
    fn state_subscription_replay_conflict_and_selector_race_fail_closed() {
        assert!(matches!(
            StateSubscriptionKey::new(Vec::new()),
            Err(StoreError::InvalidStateSubscriptionKey { length: 0 })
        ));
        assert!(matches!(
            StateSubscriptionKey::new(vec![0; MAX_STATE_SUBSCRIPTION_KEY_BYTES + 1]),
            Err(StoreError::InvalidStateSubscriptionKey { .. })
        ));

        let file = TestFile::new("State subscription replay and race");
        let mut services = state_services(0xba);
        let store = Store::open_for_mission(&file.0, services.authority).expect("open store");
        let policy = store.control_policy_snapshot().expect("settled policy");
        let key = StateSubscriptionKey::new(b"application/state".to_vec()).expect("key");
        let spec = StateSubscriptionSpec {
            topic: state_topic(),
            scope: state_scope(),
            include_descendant_scopes: false,
        };
        let created = store
            .create_state_subscription_with_policy(&policy, &key, spec.clone())
            .expect("create State subscription");
        assert!(created.inserted);
        assert_eq!(
            store
                .create_state_subscription_with_policy(&policy, &key, spec.clone())
                .expect("exact create retry"),
            StateSubscriptionCreateOutcome {
                id: created.id,
                inserted: false,
            }
        );
        let mut conflicting = spec.clone();
        conflicting.include_descendant_scopes = true;
        assert!(matches!(
            store.create_state_subscription_with_policy(&policy, &key, conflicting),
            Err(StoreError::StateSubscriptionConflict)
        ));

        let reservation = store
            .reserve_state_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve State");
        let (state, sealed, _) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &reservation,
            b"asset/race",
            b"one",
            false,
            1,
        );
        store
            .commit_reserved_state(&reservation, &state, &sealed)
            .expect("commit State");
        let plan = store
            .prepare_state_subscription_poll_with_policy(&policy, created.id, 1, 8)
            .expect("prepare full snapshot");
        let semantic_id = StateSemanticId::from_bytes(state.item_id());
        let selection = StateSubscriptionPollSelection {
            current: vec![semantic_id],
            noncurrent: Vec::new(),
            inactive: Vec::new(),
        };

        let second_key =
            StateSubscriptionKey::new(b"application/state/race".to_vec()).expect("second key");
        let second = store
            .create_state_subscription_with_policy(&policy, &second_key, spec)
            .expect("mutate selector generation");
        assert!(matches!(
            store.commit_state_subscription_poll_with_policy(&policy, &plan, &selection),
            Err(StoreError::StateSelectorGenerationChanged)
        ));
        store
            .remove_state_subscription_with_policy(&policy, second.id)
            .expect("remove racing selector");
        assert_eq!(
            store.state_subscription_stats().expect("selector stats"),
            StateSubscriptionStats {
                subscriptions: 1,
                pending_deliveries: 0,
                acknowledged_deliveries: 0,
                delivery_cursors: 0,
                selector_generation: 3,
            }
        );
    }

    #[test]
    fn state_subscription_retries_current_heads_suppresses_ancestors_and_purges_ledgers() {
        let file = TestFile::new("State subscription durable delivery");
        let mut services = state_services(0xbb);
        let store = Store::open_for_mission(&file.0, services.authority).expect("open store");
        let policy = store.control_policy_snapshot().expect("settled policy");
        let key = StateSubscriptionKey::new(b"application/current-state".to_vec()).expect("key");
        let spec = StateSubscriptionSpec {
            topic: state_topic(),
            scope: state_scope(),
            include_descendant_scopes: false,
        };
        let subscription = store
            .create_state_subscription_with_policy(&policy, &key, spec.clone())
            .expect("create subscription")
            .id;

        let first_reservation = store
            .reserve_state_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve ancestor");
        let (first, first_sealed, _) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &first_reservation,
            b"asset/lineage",
            b"ancestor",
            false,
            1,
        );
        store
            .commit_reserved_state(&first_reservation, &first, &first_sealed)
            .expect("commit ancestor");
        let first_id = StateSemanticId::from_bytes(first.item_id());
        let first_plan = store
            .prepare_state_subscription_poll_with_policy(&policy, subscription, 1, 8)
            .expect("prepare ancestor");
        assert_eq!(first_plan.candidates().len(), 1);
        assert_eq!(first_plan.candidates()[0].pending_attempt(), None);
        let first_selection = StateSubscriptionPollSelection {
            current: vec![first_id],
            noncurrent: Vec::new(),
            inactive: Vec::new(),
        };
        let stale_first_plan = first_plan.clone();
        let first_page = store
            .commit_state_subscription_poll_with_policy(&policy, &first_plan, &first_selection)
            .expect("commit ancestor attempt");
        assert_eq!(first_page.deliveries[0].attempt, 1);
        let old_a_attempt_one = first_page.deliveries[0].token;
        assert!(matches!(
            store.commit_state_subscription_poll_with_policy(
                &policy,
                &stale_first_plan,
                &first_selection,
            ),
            Err(StoreError::StateSubscriptionPlanChanged)
        ));
        drop(store);

        let store = Store::open_for_mission(&file.0, services.authority).expect("reopen retry");
        let policy = store.control_policy_snapshot().expect("reopen policy");
        let retry_plan = store
            .prepare_state_subscription_poll_with_policy(&policy, subscription, 1, 8)
            .expect("prepare durable retry");
        assert_eq!(retry_plan.candidates()[0].pending_attempt(), Some(1));
        let retry_page = store
            .commit_state_subscription_poll_with_policy(&policy, &retry_plan, &first_selection)
            .expect("commit durable retry");
        assert_eq!(retry_page.deliveries[0].attempt, 2);
        assert_eq!(
            store
                .acknowledge_state_delivery_with_policy(
                    &policy,
                    subscription,
                    first_id,
                    old_a_attempt_one,
                )
                .expect("ack ancestor"),
            StateDeliveryAck::Acknowledged
        );

        let successor_reservation = store
            .reserve_state_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve successor");
        assert!(successor_reservation.context().observes(first.dot()));
        let (successor, successor_sealed, _) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &successor_reservation,
            b"asset/lineage",
            b"successor",
            false,
            1,
        );
        store
            .commit_reserved_state(&successor_reservation, &successor, &successor_sealed)
            .expect("commit successor");
        let successor_id = StateSemanticId::from_bytes(successor.item_id());
        let successor_plan = store
            .prepare_state_subscription_poll_with_policy(&policy, subscription, 1, 8)
            .expect("prepare successor snapshot");
        assert_eq!(successor_plan.candidates().len(), 2);
        assert_eq!(
            successor_plan.candidates()[0].acknowledged_attempt(),
            Some(2)
        );
        let successor_selection = StateSubscriptionPollSelection {
            current: vec![successor_id],
            noncurrent: vec![first_id],
            inactive: Vec::new(),
        };
        let successor_page = store
            .commit_state_subscription_poll_with_policy(
                &policy,
                &successor_plan,
                &successor_selection,
            )
            .expect("deliver only successor");
        assert_eq!(successor_page.deliveries.len(), 1);
        assert_eq!(successor_page.deliveries[0].state.semantic_id, successor_id);
        assert_eq!(successor_page.deliveries[0].attempt, 1);
        assert_eq!(
            old_a_attempt_one.incarnation(),
            successor_page.deliveries[0].token.incarnation()
        );
        assert_eq!(
            old_a_attempt_one.tenure(),
            successor_page.deliveries[0].token.tenure()
        );
        assert_eq!(
            old_a_attempt_one.attempt(),
            successor_page.deliveries[0].token.attempt()
        );
        assert!(matches!(
            store.acknowledge_state_delivery_with_policy(
                &policy,
                subscription,
                successor_id,
                old_a_attempt_one,
            ),
            Err(StoreError::StateDeliveryTokenBindingMismatch)
        ));
        assert_eq!(
            store
                .state_subscription_stats()
                .expect("cross-State token swap leaves successor pending"),
            StateSubscriptionStats {
                subscriptions: 1,
                pending_deliveries: 1,
                acknowledged_deliveries: 0,
                delivery_cursors: 2,
                selector_generation: 1,
            }
        );
        assert!(matches!(
            store.prepare_state_subscription_poll_with_policy(&policy, subscription, 1, 1),
            Err(StoreError::StateSubscriptionPollLimitExceeded {
                requested: 2,
                maximum: 1,
            })
        ));
        let old_incarnation_attempt_one = successor_page.deliveries[0].token;
        drop(store);

        let store = Store::open_for_mission(&file.0, services.authority).expect("reopen successor");
        let policy = store
            .control_policy_snapshot()
            .expect("successor retry policy");
        let successor_retry_plan = store
            .prepare_state_subscription_poll_with_policy(&policy, subscription, 1, 8)
            .expect("prepare successor retry");
        assert_eq!(
            successor_retry_plan
                .candidates()
                .iter()
                .find(|candidate| candidate.state().semantic_id == successor_id)
                .expect("successor candidate")
                .pending_attempt(),
            Some(1)
        );
        let successor_retry = store
            .commit_state_subscription_poll_with_policy(
                &policy,
                &successor_retry_plan,
                &successor_selection,
            )
            .expect("commit successor retry");
        assert_eq!(successor_retry.deliveries[0].attempt, 2);
        assert_eq!(
            store
                .acknowledge_state_delivery_with_policy(
                    &policy,
                    subscription,
                    successor_id,
                    successor_retry.deliveries[0].token,
                )
                .expect("ack successor"),
            StateDeliveryAck::Acknowledged
        );
        assert_eq!(
            store
                .acknowledge_state_delivery_with_policy(
                    &policy,
                    subscription,
                    successor_id,
                    successor_retry.deliveries[0].token,
                )
                .expect("idempotent successor ack"),
            StateDeliveryAck::AlreadyAcknowledged
        );
        let settled_plan = store
            .prepare_state_subscription_poll_with_policy(&policy, subscription, 1, 8)
            .expect("prepare fully acknowledged snapshot");
        let settled = store
            .commit_state_subscription_poll_with_policy(
                &policy,
                &settled_plan,
                &successor_selection,
            )
            .expect("commit ancestor-suppressed snapshot");
        assert!(settled.deliveries.is_empty());
        assert!(!settled.has_more);
        assert_eq!(
            store
                .state_subscription_stats()
                .expect("acknowledged stats"),
            StateSubscriptionStats {
                subscriptions: 1,
                pending_deliveries: 0,
                acknowledged_deliveries: 1,
                delivery_cursors: 2,
                selector_generation: 1,
            }
        );

        let reactivate_ancestor_selection = StateSubscriptionPollSelection {
            current: vec![first_id],
            noncurrent: Vec::new(),
            inactive: vec![successor_id],
        };
        let reactivate_ancestor_plan = store
            .prepare_state_subscription_poll_with_policy(&policy, subscription, 1, 8)
            .expect("prepare acknowledged ancestor reactivation");
        let reactivate_ancestor = store
            .commit_state_subscription_poll_with_policy(
                &policy,
                &reactivate_ancestor_plan,
                &reactivate_ancestor_selection,
            )
            .expect("reactivate acknowledged ancestor");
        assert_eq!(reactivate_ancestor.deliveries.len(), 1);
        assert_eq!(
            reactivate_ancestor.deliveries[0].state.semantic_id,
            first_id
        );
        assert_eq!(reactivate_ancestor.deliveries[0].attempt, 1);
        assert_eq!(
            reactivate_ancestor.deliveries[0].token.tenure(),
            old_a_attempt_one.tenure() + 1
        );
        assert_eq!(
            store
                .acknowledge_state_delivery_with_policy(
                    &policy,
                    subscription,
                    first_id,
                    old_a_attempt_one,
                )
                .expect("late acknowledged-tenure token is idempotent"),
            StateDeliveryAck::AlreadyAcknowledged
        );
        assert_eq!(
            store
                .state_subscription_stats()
                .expect("reactivated ancestor remains pending"),
            StateSubscriptionStats {
                subscriptions: 1,
                pending_deliveries: 1,
                acknowledged_deliveries: 0,
                delivery_cursors: 2,
                selector_generation: 1,
            }
        );
        let unacknowledged_ancestor_tenure = reactivate_ancestor.deliveries[0].token;

        let reactivate_successor_plan = store
            .prepare_state_subscription_poll_with_policy(&policy, subscription, 1, 8)
            .expect("prepare successor reactivation");
        let reactivate_successor = store
            .commit_state_subscription_poll_with_policy(
                &policy,
                &reactivate_successor_plan,
                &successor_selection,
            )
            .expect("retire unacknowledged ancestor tenure");
        assert_eq!(reactivate_successor.deliveries.len(), 1);
        assert_eq!(
            reactivate_successor.deliveries[0].state.semantic_id,
            successor_id
        );
        assert_eq!(reactivate_successor.deliveries[0].attempt, 1);

        let reactivate_ancestor_again_plan = store
            .prepare_state_subscription_poll_with_policy(&policy, subscription, 1, 8)
            .expect("prepare second ancestor reactivation");
        let reactivate_ancestor_again = store
            .commit_state_subscription_poll_with_policy(
                &policy,
                &reactivate_ancestor_again_plan,
                &reactivate_ancestor_selection,
            )
            .expect("reactivate ancestor in a fresh tenure");
        assert_eq!(reactivate_ancestor_again.deliveries.len(), 1);
        assert_eq!(
            reactivate_ancestor_again.deliveries[0].state.semantic_id,
            first_id
        );
        assert_eq!(reactivate_ancestor_again.deliveries[0].attempt, 1);
        assert_eq!(
            reactivate_ancestor_again.deliveries[0].token.tenure(),
            unacknowledged_ancestor_tenure.tenure() + 1
        );
        assert!(matches!(
            store.acknowledge_state_delivery_with_policy(
                &policy,
                subscription,
                first_id,
                unacknowledged_ancestor_tenure,
            ),
            Err(StoreError::StateDeliveryTenureChanged {
                current,
                received,
            }) if current == reactivate_ancestor_again.deliveries[0].token.tenure()
                && received == unacknowledged_ancestor_tenure.tenure()
        ));
        assert_eq!(
            store
                .state_subscription_stats()
                .expect("stale unacknowledged tenure leaves fresh tenure pending"),
            StateSubscriptionStats {
                subscriptions: 1,
                pending_deliveries: 1,
                acknowledged_deliveries: 0,
                delivery_cursors: 2,
                selector_generation: 1,
            }
        );
        assert_eq!(
            store
                .acknowledge_state_delivery_with_policy(
                    &policy,
                    subscription,
                    first_id,
                    reactivate_ancestor_again.deliveries[0].token,
                )
                .expect("acknowledge fresh ancestor tenure"),
            StateDeliveryAck::Acknowledged
        );
        assert_eq!(
            store
                .state_subscription_stats()
                .expect("fresh ancestor tenure acknowledged"),
            StateSubscriptionStats {
                subscriptions: 1,
                pending_deliveries: 0,
                acknowledged_deliveries: 1,
                delivery_cursors: 2,
                selector_generation: 1,
            }
        );

        assert!(
            store
                .remove_state_subscription_with_policy(&policy, subscription)
                .expect("purge subscription")
                .removed
        );
        assert_eq!(
            store.state_subscription_stats().expect("purged stats"),
            StateSubscriptionStats {
                subscriptions: 0,
                pending_deliveries: 0,
                acknowledged_deliveries: 0,
                delivery_cursors: 0,
                selector_generation: 2,
            }
        );
        let recreated = store
            .create_state_subscription_with_policy(&policy, &key, spec)
            .expect("recreate same stable identity");
        assert_eq!(recreated.id, subscription);
        let replay_plan = store
            .prepare_state_subscription_poll_with_policy(&policy, subscription, 1, 8)
            .expect("prepare after receipt purge");
        assert!(
            replay_plan
                .candidates()
                .iter()
                .all(|candidate| candidate.acknowledged_attempt().is_none())
        );
        let replay = store
            .commit_state_subscription_poll_with_policy(&policy, &replay_plan, &successor_selection)
            .expect("redeliver current after recreate");
        assert_eq!(replay.deliveries[0].attempt, 1);
        assert_eq!(old_incarnation_attempt_one.attempt(), 1);
        assert_eq!(replay.deliveries[0].token.attempt(), 1);
        assert_ne!(
            old_incarnation_attempt_one.incarnation(),
            replay.deliveries[0].token.incarnation()
        );
        assert!(matches!(
            store.acknowledge_state_delivery_with_policy(
                &policy,
                subscription,
                successor_id,
                old_incarnation_attempt_one,
            ),
            Err(StoreError::StateSubscriptionIncarnationChanged { .. })
        ));
        assert_eq!(
            store
                .state_subscription_stats()
                .expect("stale ABA ack stats"),
            StateSubscriptionStats {
                subscriptions: 1,
                pending_deliveries: 1,
                acknowledged_deliveries: 0,
                delivery_cursors: 1,
                selector_generation: 3,
            }
        );
        let successor_marker = replay.deliveries[0].state.acceptance_marker;
        drop(store);

        {
            let database = Database::open(&file.0).expect("open corrupt ledger");
            let write = database.begin_write().expect("corrupt ledger write");
            let mut key_bytes = [0u8; 40];
            key_bytes[..32].copy_from_slice(subscription.as_bytes());
            key_bytes[32..].copy_from_slice(&successor_marker.to_be_bytes());
            let mut malformed = Vec::with_capacity(49);
            malformed.push(1);
            malformed.extend_from_slice(successor_id.as_bytes());
            malformed.extend_from_slice(&1u64.to_be_bytes());
            malformed.extend_from_slice(&0u64.to_be_bytes());
            write
                .open_table(state_subscription::STATE_SUBSCRIPTION_PENDING)
                .expect("pending table")
                .insert(key_bytes.as_slice(), malformed.as_slice())
                .expect("corrupt pending attempt");
            write.commit().expect("commit ledger corruption");
        }
        for result in [
            Store::inspect_existing(&file.0).map(|_| ()),
            Store::open_for_mission(&file.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::StateInvariant(
                    "State pending-delivery tenure or attempt count is zero"
                ))
            ));
        }
    }

    #[test]
    fn state_acceptance_order_migrates_exact_legacy_absence_and_rejects_corruption() {
        let file = TestFile::new("State acceptance order migration");
        let mut services = state_services(0xbc);
        let (first_stored, second_stored) = {
            let store =
                Store::open_for_mission(&file.0, services.authority).expect("open State store");
            let policy = store.control_policy_snapshot().expect("settled policy");
            let first_reservation = store
                .reserve_state_with_policy(
                    &policy,
                    services.first.identity(),
                    &state_topic(),
                    &state_scope(),
                )
                .expect("reserve first State");
            let (first, first_sealed, _) = reserved_state(
                &mut services.first,
                &mut services.reader,
                &first_reservation,
                b"asset/order/one",
                b"one",
                false,
                1,
            );
            store
                .commit_reserved_state(&first_reservation, &first, &first_sealed)
                .expect("commit first State");
            let second_reservation = store
                .reserve_state_with_policy(
                    &policy,
                    services.first.identity(),
                    &state_topic(),
                    &state_scope(),
                )
                .expect("reserve second State");
            let (second, second_sealed, _) = reserved_state(
                &mut services.first,
                &mut services.reader,
                &second_reservation,
                b"asset/order/two",
                b"two",
                false,
                1,
            );
            store
                .commit_reserved_state(&second_reservation, &second, &second_sealed)
                .expect("commit second State");
            (
                store
                    .state_by_semantic_id(StateSemanticId::from_bytes(first.item_id()))
                    .expect("read first State")
                    .expect("first State row"),
                store
                    .state_by_semantic_id(StateSemanticId::from_bytes(second.item_id()))
                    .expect("read second State")
                    .expect("second State row"),
            )
        };
        {
            let database = Database::open(&file.0).expect("open legacy simulation");
            let write = database.begin_write().expect("legacy simulation write");
            write
                .delete_table(STATE_ACCEPTANCE_ORDER)
                .expect("remove post-legacy State index");
            write
                .delete_table(state_subscription::STATE_SUBSCRIPTIONS)
                .expect("remove post-legacy State subscriptions");
            write
                .delete_table(state_subscription::STATE_SUBSCRIPTION_PENDING)
                .expect("remove post-legacy State pending deliveries");
            write
                .delete_table(state_subscription::STATE_DELIVERY_ACKNOWLEDGEMENTS)
                .expect("remove post-legacy State acknowledgements");
            write
                .delete_table(state_subscription::STATE_DELIVERY_CURSORS)
                .expect("remove post-legacy State delivery cursors");
            {
                let mut metadata = write.open_table(METADATA).expect("legacy metadata");
                for field in [
                    state_subscription::STATE_SUBSCRIPTION_COUNT,
                    state_subscription::STATE_PENDING_DELIVERY_COUNT,
                    state_subscription::STATE_ACKNOWLEDGEMENT_COUNT,
                    state_subscription::STATE_DELIVERY_CURSOR_COUNT,
                    state_subscription::STATE_SELECTOR_GENERATION,
                ] {
                    metadata
                        .remove(field)
                        .expect("remove post-legacy subscription metadata");
                }
            }
            write.commit().expect("commit legacy simulation");
        }
        assert_eq!(
            Store::inspect_existing(&file.0)
                .expect("legacy State store remains read-only inspectable")
                .state_stats
                .states,
            2
        );
        drop(
            Store::open_for_mission(&file.0, services.authority)
                .expect("writable open backfills State acceptance order"),
        );
        {
            let database = redb::Builder::new()
                .open_read_only(&file.0)
                .expect("read migrated State store");
            let read = database.begin_read().expect("read transaction");
            let order = read
                .open_table(STATE_ACCEPTANCE_ORDER)
                .expect("migrated State order");
            assert_eq!(
                order
                    .get(1)
                    .expect("first order row")
                    .expect("first row")
                    .value(),
                first_stored.transfer_id.as_bytes().as_slice()
            );
            assert_eq!(
                order
                    .get(2)
                    .expect("second order row")
                    .expect("second row")
                    .value(),
                second_stored.transfer_id.as_bytes().as_slice()
            );
        }
        {
            let database = Database::open(&file.0).expect("open corrupt State index");
            let write = database.begin_write().expect("corrupt State index write");
            write
                .open_table(STATE_ACCEPTANCE_ORDER)
                .expect("State acceptance order")
                .insert(1, second_stored.transfer_id.as_bytes().as_slice())
                .expect("misindex first marker");
            write.commit().expect("commit corrupt State order");
        }
        for result in [
            Store::inspect_existing(&file.0).map(|_| ()),
            Store::open_for_mission(&file.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::StateInvariant(
                    "State acceptance-order index differs from its forward marker"
                ))
            ));
        }
    }

    #[test]
    fn current_state_subscription_schema_rejects_missing_acceptance_order() {
        let file = TestFile::new("current State acceptance order deletion");
        let mut services = state_services(0xbd);
        let store =
            Store::open_for_mission(&file.0, services.authority).expect("open current State store");
        let policy = store.control_policy_snapshot().expect("settled policy");
        let subscription = store
            .create_state_subscription_with_policy(
                &policy,
                &StateSubscriptionKey::new(b"application/current-order".to_vec())
                    .expect("subscription key"),
                StateSubscriptionSpec {
                    topic: state_topic(),
                    scope: state_scope(),
                    include_descendant_scopes: false,
                },
            )
            .expect("create current subscription")
            .id;
        let reservation = store
            .reserve_state_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve subscribed State");
        let (state, sealed, _) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &reservation,
            b"asset/current-order",
            b"current",
            false,
            1,
        );
        store
            .commit_reserved_state(&reservation, &state, &sealed)
            .expect("commit subscribed State");
        let semantic_id = StateSemanticId::from_bytes(state.item_id());
        let plan = store
            .prepare_state_subscription_poll_with_policy(&policy, subscription, 1, 8)
            .expect("prepare current-schema delivery");
        let page = store
            .commit_state_subscription_poll_with_policy(
                &policy,
                &plan,
                &StateSubscriptionPollSelection {
                    current: vec![semantic_id],
                    noncurrent: Vec::new(),
                    inactive: Vec::new(),
                },
            )
            .expect("commit current-schema delivery");
        assert_eq!(page.deliveries.len(), 1);
        drop(store);

        {
            let database = Database::open(&file.0).expect("open current-schema corruption");
            let write = database
                .begin_write()
                .expect("current-schema corruption write");
            write
                .delete_table(STATE_ACCEPTANCE_ORDER)
                .expect("delete current-schema State acceptance order");
            write.commit().expect("commit current-schema corruption");
        }
        for result in [
            Store::inspect_existing(&file.0).map(|_| ()),
            Store::open_for_mission(&file.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::StateInvariant(
                    "State acceptance-order index is missing from current schema"
                ))
            ));
        }
    }

    #[test]
