    #[test]
    fn state_projection_retains_concurrent_superseded_and_tombstone_versions_and_rechecks_race() {
        let file = TestFile::new("State projection");
        let mut services = state_services(0xb2);
        let store = Store::open_for_mission(&file.0, services.authority).expect("open store");
        let policy = store.control_policy_snapshot().expect("settled policy");

        let first_reservation = store
            .reserve_state_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve first concurrent State");
        let second_reservation = store
            .reserve_state_with_policy(
                &policy,
                services.second.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve second concurrent State");
        let (first, first_sealed, _) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &first_reservation,
            b"asset/9",
            b"left",
            false,
            1,
        );
        let (second, second_sealed, _) = reserved_state(
            &mut services.second,
            &mut services.reader,
            &second_reservation,
            b"asset/9",
            b"right",
            false,
            1,
        );
        store
            .commit_reserved_state(&first_reservation, &first, &first_sealed)
            .expect("commit first concurrent State");
        store
            .commit_reserved_state(&second_reservation, &second, &second_sealed)
            .expect("commit second concurrent State");

        let raced = store
            .prepare_state_projection_with_policy(
                &policy,
                &state_topic(),
                &state_scope(),
                b"asset/9",
            )
            .expect("prepare concurrent projection");
        assert_eq!(raced.candidates().len(), 2);
        assert_eq!(
            raced
                .candidates()
                .iter()
                .filter(|candidate| {
                    candidate.disposition() == Some(StateVersionDisposition::Current)
                })
                .count(),
            1
        );
        assert_eq!(
            raced
                .candidates()
                .iter()
                .filter(|candidate| {
                    candidate.disposition() == Some(StateVersionDisposition::Concurrent)
                })
                .count(),
            1
        );
        let expected_concurrent_winner = [first.item_id(), second.item_id()]
            .into_iter()
            .max()
            .expect("winner");
        assert_eq!(
            raced
                .current()
                .expect("current concurrent winner")
                .state
                .semantic_id,
            StateSemanticId::new(expected_concurrent_winner)
        );

        let successor_reservation = store
            .reserve_state_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve causal successor");
        assert!(successor_reservation.context().observes(first.dot()));
        assert!(successor_reservation.context().observes(second.dot()));
        let (successor, successor_sealed, _) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &successor_reservation,
            b"asset/9",
            b"joined",
            false,
            1,
        );
        store
            .commit_reserved_state(&successor_reservation, &successor, &successor_sealed)
            .expect("commit causal successor");
        assert!(matches!(
            store.require_state_projection_plan_with_policy(&policy, &raced),
            Err(StoreError::StateProjectionPlanChanged)
        ));

        let after_successor = store
            .prepare_state_projection_with_policy(
                &policy,
                &state_topic(),
                &state_scope(),
                b"asset/9",
            )
            .expect("project causal successor");
        assert_eq!(after_successor.candidates().len(), 3);
        assert_eq!(
            after_successor
                .current()
                .expect("successor current")
                .state
                .semantic_id,
            StateSemanticId::new(successor.item_id())
        );
        assert_eq!(
            after_successor
                .candidates()
                .iter()
                .filter(|candidate| {
                    candidate.disposition() == Some(StateVersionDisposition::Superseded)
                })
                .count(),
            2
        );

        let mut saw_live_winner = false;
        let mut saw_tombstone_winner = false;
        for index in 0..128u16 {
            let logical_key = format!("asset/tie/{index}").into_bytes();
            let live_tie_reservation = store
                .reserve_state_with_policy(
                    &policy,
                    services.first.identity(),
                    &state_topic(),
                    &state_scope(),
                )
                .expect("reserve concurrent live tie");
            let tombstone_tie_reservation = store
                .reserve_state_with_policy(
                    &policy,
                    services.second.identity(),
                    &state_topic(),
                    &state_scope(),
                )
                .expect("reserve concurrent tombstone tie");
            let (live_tie, live_tie_sealed, _) = reserved_state(
                &mut services.first,
                &mut services.reader,
                &live_tie_reservation,
                &logical_key,
                b"live",
                false,
                1,
            );
            let (tombstone_tie, tombstone_tie_sealed, _) = reserved_state(
                &mut services.second,
                &mut services.reader,
                &tombstone_tie_reservation,
                &logical_key,
                b"",
                true,
                1,
            );
            store
                .commit_reserved_state(&live_tie_reservation, &live_tie, &live_tie_sealed)
                .expect("commit concurrent live tie");
            store
                .commit_reserved_state(
                    &tombstone_tie_reservation,
                    &tombstone_tie,
                    &tombstone_tie_sealed,
                )
                .expect("commit concurrent tombstone tie");
            let tie = store
                .prepare_state_projection_with_policy(
                    &policy,
                    &state_topic(),
                    &state_scope(),
                    &logical_key,
                )
                .expect("project live/tombstone tie");
            assert_eq!(tie.candidates().len(), 2);
            let tombstone_should_win = tombstone_tie.item_id() > live_tie.item_id();
            saw_tombstone_winner |= tombstone_should_win;
            saw_live_winner |= !tombstone_should_win;
            assert_eq!(
                tie.current().expect("tie winner").state.header.tombstone,
                tombstone_should_win,
                "concurrent tombstone must not receive delete-wins precedence"
            );
            if saw_live_winner && saw_tombstone_winner {
                break;
            }
        }
        assert!(
            saw_live_winner && saw_tombstone_winner,
            "deterministic fixture must exercise both semantic-ID ordering directions"
        );

        let tombstone_reservation = store
            .reserve_state_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve tombstone");
        assert!(tombstone_reservation.context().observes(first.dot()));
        assert!(tombstone_reservation.context().observes(second.dot()));
        assert!(tombstone_reservation.context().observes(successor.dot()));
        let (tombstone, tombstone_sealed, _) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &tombstone_reservation,
            b"asset/9",
            b"",
            true,
            1,
        );
        store
            .commit_reserved_state(&tombstone_reservation, &tombstone, &tombstone_sealed)
            .expect("commit tombstone");
        let projected = store
            .prepare_state_projection_with_policy(
                &policy,
                &state_topic(),
                &state_scope(),
                b"asset/9",
            )
            .expect("project tombstone");
        assert_eq!(projected.candidates().len(), 4);
        let current_tombstone = projected.current().expect("current tombstone");
        assert_eq!(
            current_tombstone.state.semantic_id,
            StateSemanticId::new(tombstone.item_id())
        );
        assert!(current_tombstone.state.header.tombstone);
        assert_eq!(
            projected
                .candidates()
                .iter()
                .filter(|candidate| {
                    candidate.disposition() == Some(StateVersionDisposition::Superseded)
                })
                .count(),
            3
        );
        for candidate in projected.candidates() {
            let (verified, _) = content_state(&mut services.reader, &candidate.state.sealed);
            assert_eq!(verified.item_id(), *candidate.state.semantic_id.as_bytes());
        }
        store
            .require_state_projection_plan_with_policy(&policy, &projected)
            .expect("exact projection recheck");

        drop(store);
        let reopened = Store::open_for_mission(&file.0, services.authority).expect("reopen store");
        let reopened_policy = reopened.control_policy_snapshot().expect("reopened policy");
        assert_eq!(
            reopened
                .prepare_state_projection_with_policy(
                    &reopened_policy,
                    &state_topic(),
                    &state_scope(),
                    b"asset/9",
                )
                .expect("reopened projection"),
            projected
        );
    }

    #[test]
    fn event_and_state_share_causal_ledgers_but_keep_markers_and_inventory_disjoint() {
        let file = TestFile::new("Event State shared ledgers");
        let mut services = state_services(0xb3);
        let store = Store::open_for_mission(&file.0, services.authority).expect("open store");
        let publisher = services.first.identity();
        let policy = store.control_policy_snapshot().expect("settled policy");

        let first_state_reservation = store
            .reserve_state_with_policy(&policy, publisher, &state_topic(), &state_scope())
            .expect("reserve first State");
        let (first_state, first_state_sealed, _) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &first_state_reservation,
            b"shared/key",
            b"one",
            false,
            1,
        );
        store
            .commit_reserved_state(&first_state_reservation, &first_state, &first_state_sealed)
            .expect("commit first State");

        let event_reservation = store
            .reserve_event_with_policy(&policy, publisher, &state_topic(), &state_scope())
            .expect("reserve interleaved Event");
        assert_eq!(event_reservation.counter(), 2);
        assert_eq!(event_reservation.event_sequence(), 1);
        assert!(event_reservation.context().observes(first_state.dot()));
        let event_header = event_reservation
            .header(
                Priority::Immediate,
                b"shared/event".to_vec(),
                None,
                3,
                false,
                1,
            )
            .expect("Event header");
        let event_sealed = services
            .first
            .seal_event(&event_header, b"evt")
            .expect("seal Event");
        let event = content_event(&mut services.reader, &event_sealed.bytes);
        store
            .commit_reserved_event(&event_reservation, &event, &event_sealed.bytes)
            .expect("commit Event");

        let second_state_reservation = store
            .reserve_state_with_policy(&policy, publisher, &state_topic(), &state_scope())
            .expect("reserve second State");
        assert_eq!(second_state_reservation.counter(), 3);
        assert!(second_state_reservation.context().observes(event.dot()));
        let (second_state, second_state_sealed, _) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &second_state_reservation,
            b"shared/key",
            b"two",
            false,
            1,
        );
        store
            .commit_reserved_state(
                &second_state_reservation,
                &second_state,
                &second_state_sealed,
            )
            .expect("commit second State");

        assert_eq!(store.event_inventory().expect("Event inventory").len(), 1);
        assert_eq!(
            store
                .transfer_inventory()
                .expect("transfer inventory")
                .len(),
            1
        );
        assert_eq!(
            store
                .events_after(0, MAX_EVENT_PAGE)
                .expect("Event marker page")
                .iter()
                .map(|event| event.acceptance_marker)
                .collect::<Vec<_>>(),
            vec![1]
        );
        assert_eq!(store.state_stats().expect("State stats").states, 2);
        assert_eq!(
            store
                .state_stats()
                .expect("State stats")
                .last_acceptance_marker,
            2
        );
        drop(store);

        let inspection = Store::inspect_existing(&file.0).expect("read-only union audit");
        assert_eq!(inspection.event_stats.events, 1);
        assert_eq!(inspection.state_stats.states, 2);
        let reopened = Store::open_for_mission(&file.0, services.authority).expect("reopen union");
        let next_event = reopened
            .reserve_event(publisher, &state_topic(), &state_scope())
            .expect("reserve next Event");
        assert_eq!(next_event.counter(), 4);
        assert_eq!(next_event.event_sequence(), 2);
    }

    #[test]
    fn event_state_cross_class_dot_equivocation_fails_atomically_in_both_orders() {
        let state_first_file = TestFile::new("State then Event dot equivocation");
        let mut state_first = state_services(0xb5);
        let store = Store::open_for_mission(&state_first_file.0, state_first.authority)
            .expect("open State-first store");
        let policy = store.control_policy_snapshot().expect("State-first policy");
        let reservation = store
            .reserve_state_with_policy(
                &policy,
                state_first.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve State first");
        let (state, state_sealed, _) = reserved_state(
            &mut state_first.first,
            &mut state_first.reader,
            &reservation,
            b"dot/key",
            b"state",
            false,
            1,
        );
        store
            .commit_reserved_state(&reservation, &state, &state_sealed)
            .expect("commit State first");
        let event_header = event_header(
            state_first.first.identity(),
            1,
            1,
            VersionVector::default(),
            b"dot/event",
            b"event",
            None,
        );
        let mut event_header = event_header;
        event_header.topic = state_topic();
        event_header.scope = state_scope();
        let event_sealed = state_first
            .first
            .seal_event(&event_header, b"event")
            .expect("seal conflicting Event");
        let event = content_event(&mut state_first.reader, &event_sealed.bytes);
        assert!(matches!(
            store.apply_verified_event(&event, &event_sealed.bytes),
            Err(StoreError::CausalEquivocation { counter: 1, .. })
        ));
        assert_eq!(store.event_stats().expect("Event stats").events, 0);
        assert_eq!(store.state_stats().expect("State stats").states, 1);
        drop(store);

        let event_first_file = TestFile::new("Event then State dot equivocation");
        let mut event_first = state_services(0xb6);
        let store = Store::open_for_mission(&event_first_file.0, event_first.authority)
            .expect("open Event-first store");
        let event_header = EnvelopeHeader {
            class: SemanticDataClass::Event,
            topic: state_topic(),
            scope: state_scope(),
            priority: Priority::Immediate,
            stamp: CausalStamp {
                dot: Dot {
                    publisher: event_first.first.identity(),
                    counter: 1,
                },
                context: VersionVector::default(),
            },
            event_sequence: Some(1),
            logical_key: b"dot/event".to_vec(),
            blob_route: None,
            ttl_ms: None,
            content_len: 5,
            tombstone: false,
            key_epoch: 1,
        };
        let event_sealed = event_first
            .first
            .seal_event(&event_header, b"event")
            .expect("seal first Event");
        let event = content_event(&mut event_first.reader, &event_sealed.bytes);
        store
            .apply_verified_event(&event, &event_sealed.bytes)
            .expect("commit Event first");
        let policy = store.control_policy_snapshot().expect("Event-first policy");
        let forged = StateReservation {
            control_policy: policy,
            publisher: event_first.first.identity(),
            topic: state_topic(),
            scope: state_scope(),
            previous_counter: 1,
            counter: 1,
            context: VersionVector::default(),
        };
        let (state, state_sealed, _) = reserved_state(
            &mut event_first.first,
            &mut event_first.reader,
            &forged,
            b"dot/key",
            b"state",
            false,
            1,
        );
        assert!(matches!(
            store.commit_reserved_state(&forged, &state, &state_sealed),
            Err(StoreError::CausalEquivocation { counter: 1, .. })
        ));
        assert_eq!(store.event_stats().expect("Event stats").events, 1);
        assert_eq!(store.state_stats().expect("State stats").states, 0);
    }

    #[test]
    fn state_projection_never_withholds_structurally_inactive_or_corrupt_candidates() {
        let file = TestFile::new("State projection retained inactive");
        let mut services = state_services(0xb4);
        let store = Store::open_for_mission(&file.0, services.authority).expect("open store");
        let policy = store.control_policy_snapshot().expect("settled policy");
        let reservation = store
            .reserve_state_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve State");
        let (state, sealed, _) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &reservation,
            b"asset/corrupt",
            b"value",
            false,
            1,
        );
        store
            .commit_reserved_state(&reservation, &state, &sealed)
            .expect("commit State");

        let write = store.database.begin_write().expect("raw policy write");
        write
            .open_table(CONTROL_SCOPE_EPOCHS)
            .expect("scope epochs")
            .insert(
                state_scope().as_str(),
                encode_scope_epoch_index(2, ControlTransferId::new([0x44; 32])).as_slice(),
            )
            .expect("mark retained State stale");
        let transfer_id = StateTransferId::new(state.envelope_id());
        let mut corrupted = {
            let states = write.open_table(STATES).expect("State metadata");
            let encoded = states
                .get(transfer_id.as_bytes().as_slice())
                .expect("read State metadata")
                .expect("State metadata row");
            decode_state_metadata(encoded.value()).expect("decode State metadata")
        };
        corrupted.header.key_epoch = 0;
        let corrupted = encode_state_metadata(
            corrupted.transfer_id,
            corrupted.semantic_id,
            &corrupted.header,
        )
        .expect("encode corrupted structural metadata");
        write
            .open_table(STATES)
            .expect("State metadata")
            .insert(transfer_id.as_bytes().as_slice(), corrupted.as_slice())
            .expect("persist corrupted structural metadata");
        write.commit().expect("commit raw policy marker");

        let plan = store
            .prepare_state_projection_with_policy(
                &policy,
                &state_topic(),
                &state_scope(),
                b"asset/corrupt",
            )
            .expect("prepare inactive projection");
        assert_eq!(
            plan.candidates().len(),
            1,
            "inactive row must not be withheld"
        );
        assert_eq!(plan.candidates()[0].disposition(), None);
        let (verified, opened) =
            content_state(&mut services.reader, &plan.candidates()[0].state.sealed);
        assert_eq!(opened, b"value");
        assert_eq!(verified.header().key_epoch, 1);
        assert_eq!(plan.candidates()[0].state.header.key_epoch, 0);
        assert_ne!(verified.header(), &plan.candidates()[0].state.header);
        store
            .require_state_projection_plan_with_policy(&policy, &plan)
            .expect("inactive complete-set recheck");

        let cleanup = store.database.begin_write().expect("raw cleanup write");
        cleanup
            .open_table(CONTROL_SCOPE_EPOCHS)
            .expect("scope epochs")
            .remove(state_scope().as_str())
            .expect("remove synthetic scope epoch");
        cleanup.commit().expect("commit cleanup");
        drop(store);

        let database = Database::open(&file.0).expect("raw corruption store");
        let write = database.begin_write().expect("raw corruption write");
        let key = state_group_version_key(
            &state_topic(),
            &state_scope(),
            b"asset/corrupt",
            StateSemanticId::new(state.item_id()),
        )
        .expect("group key");
        write
            .open_table(STATE_GROUP_VERSIONS)
            .expect("State groups")
            .remove(key.as_slice())
            .expect("remove group row");
        write.commit().expect("commit group corruption");
        drop(database);
        assert!(matches!(
            Store::inspect_existing(&file.0),
            Err(StoreError::StateInvariant(_))
        ));
        assert!(matches!(
            Store::open_for_mission(&file.0, services.authority),
            Err(StoreError::StateInvariant(_))
        ));
    }

    #[test]
    fn record_operation_is_restart_idempotent_publisher_bound_and_policy_checked_before_replay() {
        let file = TestFile::new("Record operation restart");
        let mut services = state_services(0xc1);
        let store = Store::open_for_mission(&file.0, services.authority).expect("Record store");
        let policy = store.control_policy_snapshot().expect("Record policy");
        let operation = RecordOperationKey::new(b"record/op/1".to_vec()).expect("operation");
        let reservation = store
            .reserve_record_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve Record");
        let (record, sealed, intent) = reserved_record(
            &mut services.first,
            &mut services.reader,
            &reservation,
            b"asset/record",
            b"alpha",
            false,
            1,
        );
        let request = RecordOperationRequest::new(&operation, &intent, b"alpha").expect("request");
        let inserted = store
            .commit_reserved_record_once_with_policy(
                &policy,
                &request,
                &reservation,
                &record,
                &sealed,
            )
            .expect("commit Record");
        assert!(matches!(inserted, RecordOnceOutcome::Inserted { .. }));
        let expected = inserted.record().clone();
        drop(store);

        let reopened =
            Store::open_for_mission(&file.0, services.authority).expect("reopen Record store");
        let retry_policy = reopened.control_policy_snapshot().expect("retry policy");
        let retry_reservation = reopened
            .reserve_record_with_policy(
                &retry_policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reserve retry");
        let (retry_record, retry_sealed, retry_intent) = reserved_record(
            &mut services.first,
            &mut services.reader,
            &retry_reservation,
            b"asset/record",
            b"alpha",
            false,
            1,
        );
        let retry_request = RecordOperationRequest::new(&operation, &retry_intent, b"alpha")
            .expect("retry request");
        let existing = reopened
            .commit_reserved_record_once_with_policy(
                &retry_policy,
                &retry_request,
                &retry_reservation,
                &retry_record,
                &retry_sealed,
            )
            .expect("exact retry");
        assert!(matches!(existing, RecordOnceOutcome::Existing { .. }));
        assert_eq!(existing.record(), &expected);

        let future_reservation = reopened
            .reserve_record_with_policy(
                &retry_policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("future reservation");
        let (future, future_sealed, future_intent) = reserved_record(
            &mut services.first,
            &mut services.reader,
            &future_reservation,
            b"asset/record",
            b"alpha",
            false,
            2,
        );
        let future_request = RecordOperationRequest::new(&operation, &future_intent, b"alpha")
            .expect("future request");
        assert!(matches!(
            reopened.commit_reserved_record_once_with_policy(
                &retry_policy,
                &future_request,
                &future_reservation,
                &future,
                &future_sealed,
            ),
            Err(StoreError::RecordKeyEpochNotActive {
                current: 1,
                received: 2
            })
        ));

        let other_reservation = reopened
            .reserve_record_with_policy(
                &retry_policy,
                services.second.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("other publisher reservation");
        let (other, other_sealed, other_intent) = reserved_record(
            &mut services.second,
            &mut services.reader,
            &other_reservation,
            b"asset/record",
            b"alpha",
            false,
            1,
        );
        let other_request = RecordOperationRequest::new(&operation, &other_intent, b"alpha")
            .expect("other request");
        assert!(matches!(
            reopened.commit_reserved_record_once_with_policy(
                &retry_policy,
                &other_request,
                &other_reservation,
                &other,
                &other_sealed,
            ),
            Err(StoreError::RecordOperationConflict)
        ));
        assert_eq!(
            reopened.record_stats().expect("Record stats"),
            RecordStoreStats {
                records: 1,
                acceptance_markers: 1,
                total_sealed_bytes: expected.sealed.len() as u64,
                last_acceptance_marker: 1,
                operations: 1,
                operation_bytes: (operation.as_bytes().len() + 65) as u64,
            }
        );
        drop(reopened);
        let inspection = Store::inspect_existing(&file.0).expect("strict Record inspection");
        assert_eq!(inspection.record_stats.records, 1);
        assert_eq!(inspection.record_stats.operations, 1);
    }

    #[test]
    fn record_projection_is_arrival_independent_retains_n_way_heads_and_has_no_delete_wins() {
        let first_file = TestFile::new("Record projection order one");
        let second_file = TestFile::new("Record projection order two");
        let mut services = state_services(0xc2);
        let first_store =
            Store::open_for_mission(&first_file.0, services.authority).expect("first store");
        let second_store =
            Store::open_for_mission(&second_file.0, services.authority).expect("second store");
        let policy = first_store.control_policy_snapshot().expect("policy");
        assert_eq!(
            second_store
                .control_policy_snapshot()
                .expect("second policy"),
            policy
        );
        let first_reservation = first_store
            .reserve_record_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("first reservation");
        let second_reservation = first_store
            .reserve_record_with_policy(
                &policy,
                services.second.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("second reservation");
        let third_reservation = first_store
            .reserve_record_with_policy(
                &policy,
                services.reader.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("third reservation");
        let (first, first_sealed, _) = reserved_record(
            &mut services.first,
            &mut services.reader,
            &first_reservation,
            b"record/n-way",
            b"first",
            false,
            1,
        );
        let (second, second_sealed, _) = reserved_record(
            &mut services.second,
            &mut services.reader,
            &second_reservation,
            b"record/n-way",
            b"second",
            false,
            1,
        );
        let third_header = third_reservation
            .header(Priority::Immediate, b"record/n-way".to_vec(), 0, true, 1)
            .expect("tombstone header");
        let third_sealed = services
            .reader
            .seal_record(&third_header, b"")
            .expect("seal tombstone")
            .bytes;
        let (third, opened) = content_record(&mut services.first, &third_sealed);
        assert!(opened.is_empty());

        for (reservation, record, sealed) in [
            (&first_reservation, &first, first_sealed.as_slice()),
            (&second_reservation, &second, second_sealed.as_slice()),
            (&third_reservation, &third, third_sealed.as_slice()),
        ] {
            first_store
                .commit_reserved_record_with_policy(&policy, reservation, record, sealed)
                .expect("first arrival order");
        }
        for (reservation, record, sealed) in [
            (&third_reservation, &third, third_sealed.as_slice()),
            (&first_reservation, &first, first_sealed.as_slice()),
            (&second_reservation, &second, second_sealed.as_slice()),
        ] {
            second_store
                .commit_reserved_record_with_policy(&policy, reservation, record, sealed)
                .expect("second arrival order");
        }
        let first_plan = first_store
            .prepare_record_projection_with_policy(
                &policy,
                &state_topic(),
                &state_scope(),
                b"record/n-way",
            )
            .expect("first projection");
        let second_plan = second_store
            .prepare_record_projection_with_policy(
                &policy,
                &state_topic(),
                &state_scope(),
                b"record/n-way",
            )
            .expect("second projection");
        let roles = |plan: &RecordProjectionPlan| {
            plan.candidates()
                .iter()
                .map(|candidate| (candidate.record().semantic_id, candidate.disposition()))
                .collect::<Vec<_>>()
        };
        assert_eq!(roles(&first_plan), roles(&second_plan));
        assert_eq!(first_plan.heads().count(), 3);
        assert_eq!(
            first_plan
                .current()
                .expect("deterministic current")
                .record()
                .semantic_id,
            [first.item_id(), second.item_id(), third.item_id()]
                .into_iter()
                .map(RecordSemanticId::new)
                .max()
                .expect("maximum ID")
        );
        let tombstone = first_plan
            .candidates()
            .iter()
            .find(|candidate| candidate.record().header.tombstone)
            .expect("retained tombstone");
        assert!(matches!(
            tombstone.disposition(),
            Some(RecordVersionDisposition::Current | RecordVersionDisposition::Concurrent)
        ));
        assert_eq!(
            first_plan
                .candidates()
                .iter()
                .filter(|candidate| candidate.record().header.tombstone)
                .count(),
            1
        );
    }

    #[test]
    fn record_conflicts_require_explicit_stale_guard_and_resolution_intent_binds_heads() {
        let file = TestFile::new("Record explicit resolution");
        let mut services = state_services(0xc3);
        let store = Store::open_for_mission(&file.0, services.authority).expect("Record store");
        let policy = store.control_policy_snapshot().expect("policy");
        let first_reservation = store
            .reserve_record_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("first reservation");
        let second_reservation = store
            .reserve_record_with_policy(
                &policy,
                services.second.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("second reservation");
        let (first, first_sealed, _) = reserved_record(
            &mut services.first,
            &mut services.reader,
            &first_reservation,
            b"record/conflict",
            b"left",
            false,
            1,
        );
        let (second, second_sealed, _) = reserved_record(
            &mut services.second,
            &mut services.reader,
            &second_reservation,
            b"record/conflict",
            b"right",
            false,
            1,
        );
        store
            .commit_reserved_record_with_policy(&policy, &first_reservation, &first, &first_sealed)
            .expect("commit left");
        store
            .commit_reserved_record_with_policy(
                &policy,
                &second_reservation,
                &second,
                &second_sealed,
            )
            .expect("commit right");
        let conflict = store
            .prepare_record_projection_with_policy(
                &policy,
                &state_topic(),
                &state_scope(),
                b"record/conflict",
            )
            .expect("conflict plan");
        assert_eq!(conflict.heads().count(), 2);

        let resolution_operation =
            RecordOperationKey::new(b"record/resolve/1".to_vec()).expect("resolution key");
        let resolution_reservation = store
            .reserve_record_with_policy(
                &policy,
                services.reader.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("resolution reservation");
        let resolution_header = resolution_reservation
            .header(
                Priority::Immediate,
                b"record/conflict".to_vec(),
                6,
                false,
                1,
            )
            .expect("resolution header");
        let resolution_intent = RecordPublicationIntent::new(
            services.reader.identity(),
            state_topic(),
            state_scope(),
            Priority::Immediate,
            b"record/conflict".to_vec(),
            b"merged",
            false,
        )
        .expect("resolution intent");
        let resolution_sealed = services
            .reader
            .seal_record(&resolution_header, b"merged")
            .expect("seal resolution")
            .bytes;
        let (resolution_record, opened) = content_record(&mut services.first, &resolution_sealed);
        assert_eq!(opened, b"merged");
        let publication =
            RecordOperationRequest::new(&resolution_operation, &resolution_intent, b"merged")
                .expect("resolution publication");

        let before = store.record_stats().expect("stats before implicit merge");
        assert!(matches!(
            store.commit_reserved_record_once_with_policy(
                &policy,
                &publication,
                &resolution_reservation,
                &resolution_record,
                &resolution_sealed,
            ),
            Err(StoreError::RecordConflictRequiresResolution)
        ));
        assert_eq!(store.record_stats().expect("rollback stats"), before);

        // Reserve a branch before resolution so it can become a later sibling
        // without implicitly observing the successful resolution revision.
        let later_branch_reservation = store
            .reserve_record_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("pre-resolution branch reservation");
        let (later_branch, later_branch_sealed, _) = reserved_record(
            &mut services.first,
            &mut services.second,
            &later_branch_reservation,
            b"record/conflict",
            b"later",
            false,
            1,
        );
        let resolution =
            RecordResolutionRequest::new(&publication, &conflict).expect("resolution request");
        let resolved = store
            .commit_reserved_record_resolution_once_with_policy(
                &policy,
                &resolution,
                &resolution_reservation,
                &resolution_record,
                &resolution_sealed,
            )
            .expect("explicit resolution");
        assert!(matches!(resolved, RecordOnceOutcome::Inserted { .. }));
        store
            .commit_reserved_record_with_policy(
                &policy,
                &later_branch_reservation,
                &later_branch,
                &later_branch_sealed,
            )
            .expect("later concurrent branch");
        let later_conflict = store
            .prepare_record_projection_with_policy(
                &policy,
                &state_topic(),
                &state_scope(),
                b"record/conflict",
            )
            .expect("later conflict");
        assert_eq!(later_conflict.heads().count(), 2);

        let retry_reservation = store
            .reserve_record_with_policy(
                &policy,
                services.reader.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("retry reservation");
        let (retry_record, retry_sealed, retry_intent) = reserved_record(
            &mut services.reader,
            &mut services.second,
            &retry_reservation,
            b"record/conflict",
            b"merged",
            false,
            1,
        );
        let retry_publication =
            RecordOperationRequest::new(&resolution_operation, &retry_intent, b"merged")
                .expect("retry publication");
        let stale_operation =
            RecordOperationKey::new(b"record/resolve/stale".to_vec()).expect("stale key");
        let stale_publication =
            RecordOperationRequest::new(&stale_operation, &retry_intent, b"merged")
                .expect("stale publication");
        let stale_resolution = RecordResolutionRequest::new(&stale_publication, &conflict)
            .expect("stale resolution guard");
        let stable = store.record_stats().expect("stable stats");
        assert!(matches!(
            store.commit_reserved_record_resolution_once_with_policy(
                &policy,
                &stale_resolution,
                &retry_reservation,
                &retry_record,
                &retry_sealed,
            ),
            Err(StoreError::RecordProjectionPlanChanged)
        ));
        assert_eq!(
            store
                .record_for_operation(&stale_operation)
                .expect("stale operation lookup"),
            None
        );
        assert_eq!(store.record_stats().expect("stale rollback"), stable);
        let different_guard = RecordResolutionRequest::new(&retry_publication, &later_conflict)
            .expect("different resolution guard");
        assert!(matches!(
            store.commit_reserved_record_resolution_once_with_policy(
                &policy,
                &different_guard,
                &retry_reservation,
                &retry_record,
                &retry_sealed,
            ),
            Err(StoreError::RecordOperationConflict)
        ));
        assert_eq!(store.record_stats().expect("conflict rollback"), stable);
        let original_guard = RecordResolutionRequest::new(&retry_publication, &conflict)
            .expect("original guard retry");
        let existing = store
            .commit_reserved_record_resolution_once_with_policy(
                &policy,
                &original_guard,
                &retry_reservation,
                &retry_record,
                &retry_sealed,
            )
            .expect("original exact guard retry");
        assert!(matches!(existing, RecordOnceOutcome::Existing { .. }));
        assert_eq!(existing.record(), resolved.record());

        // An authorized exact retry may reseal at the current epoch while the
        // durable result remains the original immutable revision. Current epoch
        // is enforced before operation lookup; the old plan is used only to
        // reproduce the same plan-bound operation digest.
        let write = store.database.begin_write().expect("synthetic rekey write");
        write
            .open_table(CONTROL_SCOPE_EPOCHS)
            .expect("scope epochs")
            .insert(
                state_scope().as_str(),
                encode_scope_epoch_index(2, ControlTransferId::new([0xd2; 32])).as_slice(),
            )
            .expect("activate synthetic epoch");
        write.commit().expect("commit synthetic epoch");
        let rekey_reservation = store
            .reserve_record_with_policy(
                &policy,
                services.reader.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("post-rekey retry reservation");
        let (rekey_record, rekey_sealed, rekey_intent) = reserved_record(
            &mut services.reader,
            &mut services.second,
            &rekey_reservation,
            b"record/conflict",
            b"merged",
            false,
            2,
        );
        let rekey_publication =
            RecordOperationRequest::new(&resolution_operation, &rekey_intent, b"merged")
                .expect("post-rekey publication");
        let rekey_resolution = RecordResolutionRequest::new(&rekey_publication, &conflict)
            .expect("post-rekey exact guard");
        let rekey_existing = store
            .commit_reserved_record_resolution_once_with_policy(
                &policy,
                &rekey_resolution,
                &rekey_reservation,
                &rekey_record,
                &rekey_sealed,
            )
            .expect("authorized post-rekey exact retry");
        assert!(matches!(rekey_existing, RecordOnceOutcome::Existing { .. }));
        assert_eq!(rekey_existing.record(), resolved.record());
    }

    #[test]
    fn record_subscription_retries_whole_projections_and_accepts_earlier_attempt_tokens() {
        assert!(matches!(
            RecordSubscriptionKey::new(Vec::new()),
            Err(StoreError::InvalidRecordSubscriptionKey { length: 0 })
        ));
        assert!(matches!(
            RecordSubscriptionKey::new(vec![0; MAX_RECORD_SUBSCRIPTION_KEY_BYTES + 1]),
            Err(StoreError::InvalidRecordSubscriptionKey { .. })
        ));

        let file = TestFile::new("Record projection subscription retry");
        let mut services = state_services(0xce);
        let store = Store::open_for_mission(&file.0, services.authority).expect("Record store");
        let policy = store.control_policy_snapshot().expect("settled policy");
        let spec = RecordSubscriptionSpec {
            topic: state_topic(),
            scope: state_scope(),
            include_descendant_scopes: false,
        };
        let key = RecordSubscriptionKey::new(b"application/records".to_vec()).expect("key");
        let subscription = store
            .create_record_subscription_with_policy(&policy, &key, spec.clone())
            .expect("create Record subscription")
            .id;
        assert_eq!(
            store
                .create_record_subscription_with_policy(&policy, &key, spec.clone())
                .expect("idempotent create"),
            RecordSubscriptionCreateOutcome {
                id: subscription,
                inserted: false,
            }
        );
        let mut conflicting_spec = spec.clone();
        conflicting_spec.include_descendant_scopes = true;
        assert!(matches!(
            store.create_record_subscription_with_policy(&policy, &key, conflicting_spec),
            Err(StoreError::RecordSubscriptionConflict)
        ));

        let (first, first_sealed) = verified_record_for_remote_apply(
            &mut services.first,
            &mut services.reader,
            1,
            VersionVector::default(),
            b"record/subscription/one",
            b"one",
        );
        let (second, second_sealed) = verified_record_for_remote_apply(
            &mut services.second,
            &mut services.reader,
            1,
            VersionVector::default(),
            b"record/subscription/two",
            b"two",
        );
        store
            .apply_verified_record_with_policy(&policy, &first, &first_sealed)
            .expect("apply first Record");
        store
            .apply_verified_record_with_policy(&policy, &second, &second_sealed)
            .expect("apply second Record");
        assert!(matches!(
            store.prepare_record_subscription_poll_with_policy(&policy, subscription, 0, 8),
            Err(StoreError::RecordSubscriptionPollLimitExceeded {
                requested: 0,
                maximum: MAX_RECORD_POLL_DELIVERIES,
            })
        ));
        assert!(matches!(
            store.prepare_record_subscription_poll_with_policy(
                &policy,
                subscription,
                MAX_RECORD_POLL_DELIVERIES + 1,
                8,
            ),
            Err(StoreError::RecordSubscriptionPollLimitExceeded {
                requested,
                maximum: MAX_RECORD_POLL_DELIVERIES,
            }) if requested == MAX_RECORD_POLL_DELIVERIES + 1
        ));
        assert!(matches!(
            store.prepare_record_subscription_poll_with_policy(&policy, subscription, 1, 0),
            Err(StoreError::RecordSubscriptionPollLimitExceeded {
                requested: 0,
                maximum: MAX_RECORD_SUBSCRIPTION_SCAN,
            })
        ));
        assert!(matches!(
            store.prepare_record_subscription_poll_with_policy(
                &policy,
                subscription,
                1,
                MAX_RECORD_SUBSCRIPTION_SCAN + 1,
            ),
            Err(StoreError::RecordSubscriptionPollLimitExceeded {
                requested,
                maximum: MAX_RECORD_SUBSCRIPTION_SCAN,
            }) if requested == MAX_RECORD_SUBSCRIPTION_SCAN + 1
        ));
        assert!(matches!(
            store.prepare_record_subscription_poll_with_policy(&policy, subscription, 1, 1),
            Err(StoreError::RecordSubscriptionPollLimitExceeded {
                requested: 2,
                maximum: 1,
            })
        ));

        let first_plan = store
            .prepare_record_subscription_poll_with_policy(&policy, subscription, 1, 8)
            .expect("prepare whole projections");
        assert_eq!(first_plan.candidates().len(), 2);
        assert!(
            first_plan
                .candidates()
                .iter()
                .all(|candidate| candidate.plan().heads().count() == 1)
        );
        let first_selection = record_subscription_selection(&first_plan);
        let stale_plan = first_plan.clone();
        let first_page = store
            .commit_record_subscription_poll_with_policy(&policy, &first_plan, &first_selection)
            .expect("commit first bounded projection");
        assert_eq!(first_page.deliveries.len(), 1);
        assert!(first_page.has_more);
        assert_eq!(first_page.deliveries[0].attempt, 1);
        assert_eq!(first_page.deliveries[0].plan.heads().count(), 1);
        let first_projection = first_page.deliveries[0].projection_id;
        let attempt_one = first_page.deliveries[0].token;
        assert!(matches!(
            store.commit_record_subscription_poll_with_policy(
                &policy,
                &stale_plan,
                &first_selection,
            ),
            Err(StoreError::RecordSubscriptionPlanChanged)
        ));

        let retry_plan = store
            .prepare_record_subscription_poll_with_policy(&policy, subscription, 2, 8)
            .expect("prepare pending-first retry");
        assert_eq!(
            retry_plan
                .candidates()
                .iter()
                .find(|candidate| candidate.projection_id() == first_projection)
                .expect("pending projection")
                .pending_attempt(),
            Some(1)
        );
        let retry_selection = record_subscription_selection(&retry_plan);
        let retry_page = store
            .commit_record_subscription_poll_with_policy(&policy, &retry_plan, &retry_selection)
            .expect("commit pending-first retry");
        assert_eq!(retry_page.deliveries.len(), 2);
        assert_eq!(retry_page.deliveries[0].projection_id, first_projection);
        assert_eq!(retry_page.deliveries[0].attempt, 2);
        let second_projection = retry_page.deliveries[1].projection_id;
        let second_attempt_one = retry_page.deliveries[1].token;
        assert_ne!(second_projection, first_projection);
        assert_eq!(retry_page.deliveries[1].attempt, 1);
        assert!(!retry_page.has_more);

        let fair_retry_plan = store
            .prepare_record_subscription_poll_with_policy(&policy, subscription, 1, 8)
            .expect("prepare lowered-limit fair retry");
        let fair_retry_page = store
            .commit_record_subscription_poll_with_policy(
                &policy,
                &fair_retry_plan,
                &record_subscription_selection(&fair_retry_plan),
            )
            .expect("least-attempt pending projection wins lowered limit");
        assert_eq!(fair_retry_page.deliveries.len(), 1);
        assert_eq!(
            fair_retry_page.deliveries[0].projection_id,
            second_projection
        );
        assert_eq!(fair_retry_page.deliveries[0].attempt, 2);
        assert!(fair_retry_page.has_more);
        assert_eq!(
            store
                .acknowledge_record_delivery_with_policy(
                    &policy,
                    subscription,
                    first_projection,
                    attempt_one,
                )
                .expect("earlier issued attempt remains valid"),
            RecordDeliveryAck::Acknowledged
        );
        assert_eq!(
            store
                .acknowledge_record_delivery_with_policy(
                    &policy,
                    subscription,
                    first_projection,
                    attempt_one,
                )
                .expect("idempotent reack"),
            RecordDeliveryAck::AlreadyAcknowledged
        );
        assert_eq!(
            store
                .acknowledge_record_delivery_with_policy(
                    &policy,
                    subscription,
                    second_projection,
                    second_attempt_one,
                )
                .expect("earlier attempt acknowledges the fair retry"),
            RecordDeliveryAck::Acknowledged
        );

        let wrong_projection = RecordProjectionId::from_bytes([0x55; 32]);
        assert!(matches!(
            store.acknowledge_record_delivery_with_policy(
                &policy,
                subscription,
                wrong_projection,
                attempt_one,
            ),
            Err(StoreError::RecordDeliveryTokenBindingMismatch)
        ));
        let other_subscription = store
            .create_record_subscription_with_policy(
                &policy,
                &RecordSubscriptionKey::new(b"application/records/other".to_vec())
                    .expect("other key"),
                spec,
            )
            .expect("other subscription")
            .id;
        assert!(matches!(
            store.acknowledge_record_delivery_with_policy(
                &policy,
                other_subscription,
                first_projection,
                attempt_one,
            ),
            Err(StoreError::RecordDeliveryTokenBindingMismatch)
        ));
        let mut malformed = *attempt_one.as_bytes();
        malformed[0] = 0xff;
        assert!(matches!(
            RecordDeliveryToken::from_bytes(malformed),
            Err(StoreError::InvalidRecordDeliveryToken)
        ));
        let mut forged = *attempt_one.as_bytes();
        *forged.last_mut().expect("digest byte") ^= 1;
        let forged = RecordDeliveryToken::from_bytes(forged).expect("structural token");
        assert!(matches!(
            store.acknowledge_record_delivery_with_policy(
                &policy,
                subscription,
                first_projection,
                forged,
            ),
            Err(StoreError::RecordDeliveryTokenBindingMismatch)
        ));
        assert_eq!(
            store.record_subscription_stats().expect("durable stats"),
            RecordSubscriptionStats {
                subscriptions: 2,
                pending_deliveries: 0,
                acknowledged_deliveries: 2,
                delivery_cursors: 2,
                selector_generation: 2,
            }
        );
    }

    #[test]
    fn record_subscription_head_set_and_selector_aba_open_fresh_tenures() {
        let file = TestFile::new("Record projection and selector ABA");
        let mut services = state_services(0xcf);
        let store = Store::open_for_mission(&file.0, services.authority).expect("Record store");
        let initial_policy = store.control_policy_snapshot().expect("settled policy");
        let spec = RecordSubscriptionSpec {
            topic: state_topic(),
            scope: state_scope(),
            include_descendant_scopes: false,
        };
        let operation_key =
            RecordSubscriptionKey::new(b"application/record-aba".to_vec()).expect("key");
        let subscription = store
            .create_record_subscription_with_policy(&initial_policy, &operation_key, spec.clone())
            .expect("create subscription")
            .id;

        let (left, left_sealed) = verified_record_for_remote_apply(
            &mut services.first,
            &mut services.reader,
            1,
            VersionVector::default(),
            b"record/subscription/aba",
            b"left",
        );
        store
            .apply_verified_record_with_policy(&initial_policy, &left, &left_sealed)
            .expect("apply left head");
        let left_plan = store
            .prepare_record_subscription_poll_with_policy(&initial_policy, subscription, 1, 8)
            .expect("prepare left head");
        assert_eq!(left_plan.candidates().len(), 1);
        assert_eq!(left_plan.candidates()[0].plan().heads().count(), 1);
        let left_projection = left_plan.candidates()[0].projection_id();
        let left_page = store
            .commit_record_subscription_poll_with_policy(
                &initial_policy,
                &left_plan,
                &record_subscription_selection(&left_plan),
            )
            .expect("deliver left head");
        let old_left_token = left_page.deliveries[0].token;
        store
            .acknowledge_record_delivery_with_policy(
                &initial_policy,
                subscription,
                left_projection,
                old_left_token,
            )
            .expect("ack left head");
        let hidden_plan = store
            .prepare_record_subscription_poll_with_policy(&initial_policy, subscription, 1, 8)
            .expect("prepare unchanged route-hidden projection");
        let hidden = store
            .commit_record_subscription_poll_with_policy(
                &initial_policy,
                &hidden_plan,
                &RecordSubscriptionPollSelection {
                    deliverable: Vec::new(),
                    inactive: vec![left_projection],
                },
            )
            .expect("hide unchanged projection");
        assert!(hidden.deliveries.is_empty());
        let visible_again_plan = store
            .prepare_record_subscription_poll_with_policy(&initial_policy, subscription, 1, 8)
            .expect("prepare unchanged route-visible projection");
        let visible_again = store
            .commit_record_subscription_poll_with_policy(
                &initial_policy,
                &visible_again_plan,
                &record_subscription_selection(&visible_again_plan),
            )
            .expect("unchanged projection remains acknowledged");
        assert!(visible_again.deliveries.is_empty());

        let (right, right_sealed) = verified_record_for_remote_apply(
            &mut services.second,
            &mut services.reader,
            1,
            VersionVector::default(),
            b"record/subscription/aba",
            b"right",
        );
        store
            .apply_verified_record_with_policy(&initial_policy, &right, &right_sealed)
            .expect("apply concurrent right head");
        assert_eq!(
            store
                .acknowledge_record_delivery_with_policy(
                    &initial_policy,
                    subscription,
                    left_projection,
                    old_left_token,
                )
                .expect("exact reack survives uncommitted head-set change"),
            RecordDeliveryAck::AlreadyAcknowledged
        );
        let conflict_plan = store
            .prepare_record_subscription_poll_with_policy(&initial_policy, subscription, 1, 8)
            .expect("prepare complete conflict");
        assert_eq!(conflict_plan.candidates().len(), 1);
        assert_eq!(conflict_plan.candidates()[0].plan().heads().count(), 2);
        let conflict_projection = conflict_plan.candidates()[0].projection_id();
        assert_ne!(conflict_projection, left_projection);
        let conflict_page = store
            .commit_record_subscription_poll_with_policy(
                &initial_policy,
                &conflict_plan,
                &record_subscription_selection(&conflict_plan),
            )
            .expect("deliver conflict as one projection");
        assert_eq!(conflict_page.deliveries.len(), 1);
        assert_eq!(conflict_page.deliveries[0].plan.heads().count(), 2);
        let conflict_token = conflict_page.deliveries[0].token;
        let conflict_retry = store
            .prepare_record_subscription_poll_with_policy(&initial_policy, subscription, 1, 8)
            .expect("inspect conflict tenure");
        assert_eq!(conflict_retry.candidates()[0].delivery_tenure(), Some(2));

        let revoke_right = services
            .authority_signer
            .seal_chained_revocation_control(services.second.identity(), 1, 1, None)
            .expect("seal right-publisher revocation");
        let verified_revoke_right = services
            .reader
            .verify_control(&revoke_right)
            .expect("verify right-publisher revocation");
        store
            .ingest_verified_control(&verified_revoke_right, &revoke_right)
            .expect("apply right-publisher revocation");
        let left_again_policy = store
            .control_policy_snapshot()
            .expect("post-revocation policy");
        assert!(matches!(
            store.acknowledge_record_delivery_with_policy(
                &left_again_policy,
                subscription,
                conflict_projection,
                conflict_token,
            ),
            Err(StoreError::RecordSubscriptionPlanChanged)
        ));
        let left_again_plan = store
            .prepare_record_subscription_poll_with_policy(&left_again_policy, subscription, 1, 8)
            .expect("prepare ABA left head");
        assert_eq!(left_again_plan.candidates()[0].plan().heads().count(), 1);
        assert_eq!(
            left_again_plan.candidates()[0].projection_id(),
            left_projection
        );
        let left_again_page = store
            .commit_record_subscription_poll_with_policy(
                &left_again_policy,
                &left_again_plan,
                &record_subscription_selection(&left_again_plan),
            )
            .expect("deliver ABA left head in fresh tenure");
        assert_eq!(left_again_page.deliveries[0].attempt, 1);
        let fresh_left_token = left_again_page.deliveries[0].token;
        let fresh_left_plan = store
            .prepare_record_subscription_poll_with_policy(&left_again_policy, subscription, 1, 8)
            .expect("inspect fresh left tenure");
        assert_eq!(fresh_left_plan.candidates()[0].delivery_tenure(), Some(3));
        assert!(matches!(
            store.acknowledge_record_delivery_with_policy(
                &left_again_policy,
                subscription,
                left_projection,
                old_left_token,
            ),
            Err(StoreError::RecordDeliveryTenureChanged {
                current: 3,
                received: 1,
            })
        ));
        assert!(matches!(
            store.acknowledge_record_delivery_with_policy(
                &left_again_policy,
                subscription,
                conflict_projection,
                conflict_token,
            ),
            Err(StoreError::RecordDeliveryTenureChanged {
                current: 3,
                received: 2,
            })
        ));
        assert_eq!(
            store
                .acknowledge_record_delivery_with_policy(
                    &left_again_policy,
                    subscription,
                    left_projection,
                    fresh_left_token,
                )
                .expect("ack fresh left tenure"),
            RecordDeliveryAck::Acknowledged
        );

        assert!(
            store
                .remove_record_subscription_with_policy(&left_again_policy, subscription)
                .expect("remove subscription")
                .removed
        );
        let recreated = store
            .create_record_subscription_with_policy(&left_again_policy, &operation_key, spec)
            .expect("recreate same stable subscription");
        assert_eq!(recreated.id, subscription);
        let recreated_plan = store
            .prepare_record_subscription_poll_with_policy(&left_again_policy, subscription, 1, 8)
            .expect("prepare recreated subscription");
        let recreated_page = store
            .commit_record_subscription_poll_with_policy(
                &left_again_policy,
                &recreated_plan,
                &record_subscription_selection(&recreated_plan),
            )
            .expect("deliver recreated subscription");
        assert_eq!(recreated_page.deliveries[0].attempt, 1);
        assert!(matches!(
            store.acknowledge_record_delivery_with_policy(
                &left_again_policy,
                subscription,
                left_projection,
                fresh_left_token,
            ),
            Err(StoreError::RecordSubscriptionIncarnationChanged { .. })
        ));
        store
            .acknowledge_record_delivery_with_policy(
                &left_again_policy,
                subscription,
                left_projection,
                recreated_page.deliveries[0].token,
            )
            .expect("ack recreated subscription");

        let revoke_left = services
            .authority_signer
            .seal_chained_revocation_control(
                services.first.identity(),
                1,
                2,
                Some(verified_revoke_right.envelope_id()),
            )
            .expect("seal left-publisher revocation");
        let verified_revoke_left = services
            .reader
            .verify_control(&revoke_left)
            .expect("verify left-publisher revocation");
        store
            .ingest_verified_control(&verified_revoke_left, &revoke_left)
            .expect("apply left-publisher revocation");
        let empty_policy = store.control_policy_snapshot().expect("empty-head policy");
        let empty_plan = store
            .prepare_record_subscription_poll_with_policy(&empty_policy, subscription, 1, 8)
            .expect("prepare empty head set");
        assert_eq!(empty_plan.candidates().len(), 1);
        assert_eq!(empty_plan.candidates()[0].plan().heads().count(), 0);
        let empty_projection = empty_plan.candidates()[0].projection_id();
        assert!(matches!(
            store.commit_record_subscription_poll_with_policy(
                &empty_policy,
                &empty_plan,
                &RecordSubscriptionPollSelection {
                    deliverable: vec![empty_projection],
                    inactive: Vec::new(),
                },
            ),
            Err(StoreError::RecordSubscriptionPlanChanged)
        ));
        let empty_plan = store
            .prepare_record_subscription_poll_with_policy(&empty_policy, subscription, 1, 8)
            .expect("reprepare empty head set");
        let empty_page = store
            .commit_record_subscription_poll_with_policy(
                &empty_policy,
                &empty_plan,
                &record_subscription_selection(&empty_plan),
            )
            .expect("retire delivery evidence for empty head set");
        assert!(empty_page.deliveries.is_empty());
        assert_eq!(
            store.record_subscription_stats().expect("empty-head stats"),
            RecordSubscriptionStats {
                subscriptions: 1,
                pending_deliveries: 0,
                acknowledged_deliveries: 0,
                delivery_cursors: 1,
                selector_generation: 3,
            }
        );
    }

    #[test]
    fn record_aggregate_and_dedicated_operation_caps_roll_back_atomically() {
        let file = TestFile::new("Record quota rollback");
        let mut services = state_services(0xc4);
        let store = Store::open_with_limits_for_mission(
            &file.0,
            StoreLimits::new(
                MAX_CONTROL_ITEMS + CUSTODY_EMERGENCY_ITEM_RESERVE + 1,
                DEFAULT_MAX_TOTAL_PAYLOAD_BYTES,
            )
            .expect("limits"),
            services.authority,
        )
        .expect("limited Record store");
        let policy = store.control_policy_snapshot().expect("policy");
        let reservation = store
            .reserve_record_with_policy(
                &policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("reservation");
        let (record, sealed, intent) = reserved_record(
            &mut services.first,
            &mut services.reader,
            &reservation,
            b"record/quota",
            b"value",
            false,
            1,
        );
        let operation = RecordOperationKey::new(b"record/quota/op".to_vec()).expect("operation");
        let request = RecordOperationRequest::new(&operation, &intent, b"value").expect("request");
        assert!(matches!(
            store.commit_reserved_record_once_with_policy(
                &policy,
                &request,
                &reservation,
                &record,
                &sealed,
            ),
            Err(StoreError::ItemLimitExceeded { .. })
        ));
        assert_eq!(
            store.record_stats().expect("rolled-back stats"),
            RecordStoreStats::default()
        );
        store
            .commit_reserved_record_with_policy(&policy, &reservation, &record, &sealed)
            .expect("record alone fits quota");

        let write = store
            .database
            .begin_write()
            .expect("dedicated cap transaction");
        write
            .open_table(METADATA)
            .expect("metadata")
            .insert(RECORD_OPERATION_COUNT, MAX_RECORD_OPERATIONS)
            .expect("set operation cap");
        let cap_operation = RecordOperationKey::new(b"record/cap".to_vec()).expect("cap key");
        assert!(matches!(
            admit_record_operation(&write, store.limits, &cap_operation, 65),
            Err(StoreError::RecordOperationLimitExceeded {
                current: MAX_RECORD_OPERATIONS,
                limit: MAX_RECORD_OPERATIONS
            })
        ));
        drop(write);
        assert_eq!(store.record_stats().expect("cap rollback").operations, 0);
    }

    #[test]
    fn concurrent_record_tombstone_and_edit_cover_both_semantic_id_directions() {
        for (seed, edit_should_be_greater) in [(0xc6, true), (0xc7, false)] {
            let file = TestFile::new("Record tombstone ID direction");
            let mut services = state_services(seed);
            let store = Store::open_for_mission(&file.0, services.authority).expect("Record store");
            let policy = store.control_policy_snapshot().expect("policy");
            let tombstone_reservation = store
                .reserve_record_with_policy(
                    &policy,
                    services.first.identity(),
                    &state_topic(),
                    &state_scope(),
                )
                .expect("tombstone reservation");
            let edit_reservation = store
                .reserve_record_with_policy(
                    &policy,
                    services.second.identity(),
                    &state_topic(),
                    &state_scope(),
                )
                .expect("edit reservation");
            let tombstone_header = tombstone_reservation
                .header(
                    Priority::Immediate,
                    b"record/tombstone-order".to_vec(),
                    0,
                    true,
                    1,
                )
                .expect("tombstone header");
            let tombstone_sealed = services
                .first
                .seal_record(&tombstone_header, b"")
                .expect("seal tombstone")
                .bytes;
            let (tombstone, opened) = content_record(&mut services.reader, &tombstone_sealed);
            assert!(opened.is_empty());
            let tombstone_id = RecordSemanticId::new(tombstone.item_id());

            let (edit, edit_sealed) = (0..4096u32)
                .find_map(|index| {
                    let payload = format!("edit-{index}").into_bytes();
                    let header = edit_reservation
                        .header(
                            Priority::Immediate,
                            b"record/tombstone-order".to_vec(),
                            payload.len() as u64,
                            false,
                            1,
                        )
                        .expect("edit header");
                    let sealed = services
                        .second
                        .seal_record(&header, &payload)
                        .expect("seal edit")
                        .bytes;
                    let (record, opened) = content_record(&mut services.reader, &sealed);
                    assert_eq!(opened, payload);
                    let edit_id = RecordSemanticId::new(record.item_id());
                    ((edit_id > tombstone_id) == edit_should_be_greater).then_some((record, sealed))
                })
                .expect("find requested semantic-ID direction");
            let edit_id = RecordSemanticId::new(edit.item_id());
            assert_eq!(edit_id > tombstone_id, edit_should_be_greater);
            store
                .commit_reserved_record_with_policy(
                    &policy,
                    &tombstone_reservation,
                    &tombstone,
                    &tombstone_sealed,
                )
                .expect("commit tombstone");
            store
                .commit_reserved_record_with_policy(&policy, &edit_reservation, &edit, &edit_sealed)
                .expect("commit edit");
            let plan = store
                .prepare_record_projection_with_policy(
                    &policy,
                    &state_topic(),
                    &state_scope(),
                    b"record/tombstone-order",
                )
                .expect("projection");
            assert_eq!(plan.heads().count(), 2);
            let tombstone_role = plan
                .candidates()
                .iter()
                .find(|candidate| candidate.record().semantic_id == tombstone_id)
                .expect("tombstone candidate")
                .disposition();
            let edit_role = plan
                .candidates()
                .iter()
                .find(|candidate| candidate.record().semantic_id == edit_id)
                .expect("edit candidate")
                .disposition();
            if edit_should_be_greater {
                assert_eq!(edit_role, Some(RecordVersionDisposition::Current));
                assert_eq!(tombstone_role, Some(RecordVersionDisposition::Concurrent));
            } else {
                assert_eq!(tombstone_role, Some(RecordVersionDisposition::Current));
                assert_eq!(edit_role, Some(RecordVersionDisposition::Concurrent));
            }
        }
    }

    #[test]
    fn event_state_and_record_share_dot_high_water_and_frontier_but_not_markers_or_inventory() {
        let file = TestFile::new("Event State Record shared ledgers");
        let mut services = state_services(0xc8);
        let store = Store::open_for_mission(&file.0, services.authority).expect("shared store");
        let policy = store.control_policy_snapshot().expect("policy");
        let publisher = services.first.identity();

        let record_reservation = store
            .reserve_record_with_policy(&policy, publisher, &state_topic(), &state_scope())
            .expect("first Record reservation");
        assert_eq!(record_reservation.counter(), 1);
        let (record, record_sealed, _) = reserved_record(
            &mut services.first,
            &mut services.reader,
            &record_reservation,
            b"cross/record",
            b"record",
            false,
            1,
        );
        store
            .commit_reserved_record_with_policy(
                &policy,
                &record_reservation,
                &record,
                &record_sealed,
            )
            .expect("commit Record");

        let state_reservation = store
            .reserve_state_with_policy(&policy, publisher, &state_topic(), &state_scope())
            .expect("State reservation");
        assert_eq!(state_reservation.counter(), 2);
        assert!(
            state_reservation
                .context()
                .observes(record.header().stamp.dot)
        );
        let (state, state_sealed, _) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &state_reservation,
            b"cross/state",
            b"state",
            false,
            1,
        );
        store
            .commit_reserved_state_with_policy(&policy, &state_reservation, &state, &state_sealed)
            .expect("commit State");

        let event_reservation = store
            .reserve_event_with_policy(&policy, publisher, &state_topic(), &state_scope())
            .expect("Event reservation");
        assert_eq!(event_reservation.counter(), 3);
        assert_eq!(event_reservation.event_sequence(), 1);
        assert!(
            event_reservation
                .context()
                .observes(state.header().stamp.dot)
        );
        let event_header = event_reservation
            .header(
                Priority::Immediate,
                b"cross/event".to_vec(),
                None,
                5,
                false,
                1,
            )
            .expect("Event header");
        let event_sealed = services
            .first
            .seal_event(&event_header, b"event")
            .expect("seal Event")
            .bytes;
        let event = content_event(&mut services.reader, &event_sealed);
        store
            .commit_reserved_event_with_policy(&policy, &event_reservation, &event, &event_sealed)
            .expect("commit Event");

        let next = store
            .reserve_record_with_policy(&policy, publisher, &state_topic(), &state_scope())
            .expect("next Record reservation");
        assert_eq!(next.counter(), 4);
        assert!(next.context().observes(event.header().stamp.dot));
        assert_eq!(store.record_stats().expect("Record stats").records, 1);
        assert_eq!(store.state_stats().expect("State stats").states, 1);
        assert_eq!(store.event_stats().expect("Event stats").events, 1);
        let inventory = store.event_inventory().expect("Event-only inventory");
        assert_eq!(inventory.len(), 1);
        assert_eq!(
            inventory.iter().copied().collect::<Vec<_>>(),
            vec![EventTransferId::new(event.envelope_id())]
        );
        drop(store);
        let inspection = Store::inspect_existing(&file.0).expect("shared strict inspection");
        assert_eq!(inspection.record_stats.records, 1);
        assert_eq!(inspection.state_stats.states, 1);
        assert_eq!(inspection.event_stats.events, 1);
    }

    #[test]
    fn record_schema_migrates_only_whole_absent_and_corruption_fails_reopen_and_inspection() {
        let migrated = TestFile::new("Record whole absent migration");
        let authority = state_services(0xc5).authority;
        let store = Store::open_for_mission(&migrated.0, authority).expect("create schema");
        drop(store);
        let database = Database::open(&migrated.0).expect("raw migration database");
        let write = database.begin_write().expect("raw delete transaction");
        write.delete_table(RECORDS).expect("delete Record metadata");
        write
            .delete_table(RECORD_BYTES)
            .expect("delete Record bytes");
        write
            .delete_table(RECORD_ACCEPTANCE_MARKERS)
            .expect("delete Record markers");
        write
            .delete_table(RECORD_SEMANTIC_ITEMS)
            .expect("delete Record semantic index");
        write
            .delete_table(RECORD_GROUP_VERSIONS)
            .expect("delete Record groups");
        write
            .delete_table(RECORD_OPERATIONS)
            .expect("delete Record operations");
        write
            .delete_table(RECORD_ACCEPTANCE_ORDER)
            .expect("delete Record acceptance order");
        write
            .delete_table(record_subscription::RECORD_SUBSCRIPTIONS)
            .expect("delete Record subscriptions");
        write
            .delete_table(record_subscription::RECORD_SUBSCRIPTION_PENDING)
            .expect("delete Record pending deliveries");
        write
            .delete_table(record_subscription::RECORD_DELIVERY_ACKNOWLEDGEMENTS)
            .expect("delete Record acknowledgements");
        write
            .delete_table(record_subscription::RECORD_DELIVERY_CURSORS)
            .expect("delete Record delivery cursors");
        {
            let mut metadata = write.open_table(METADATA).expect("metadata");
            for field in [
                RECORD_ITEM_COUNT,
                RECORD_TOTAL_BYTES,
                LAST_RECORD_ACCEPTANCE_MARKER,
                RECORD_OPERATION_COUNT,
                RECORD_OPERATION_TOTAL_BYTES,
                record_subscription::RECORD_SUBSCRIPTION_COUNT,
                record_subscription::RECORD_PENDING_DELIVERY_COUNT,
                record_subscription::RECORD_ACKNOWLEDGEMENT_COUNT,
                record_subscription::RECORD_DELIVERY_CURSOR_COUNT,
                record_subscription::RECORD_SELECTOR_GENERATION,
            ] {
                metadata.remove(field).expect("remove Record counter");
            }
        }
        write.commit().expect("commit whole-absent fixture");
        drop(database);
        assert_eq!(
            Store::inspect_existing(&migrated.0)
                .expect("legacy inspection")
                .record_stats,
            RecordStoreStats::default()
        );
        let store = Store::open_for_mission(&migrated.0, authority).expect("atomic migration");
        assert_eq!(
            store.record_stats().expect("migrated stats"),
            RecordStoreStats::default()
        );
        drop(store);

        let partial = TestFile::new("Record partial schema");
        let store = Store::open_for_mission(&partial.0, authority).expect("partial base");
        drop(store);
        let database = Database::open(&partial.0).expect("raw partial database");
        let write = database.begin_write().expect("raw partial transaction");
        write
            .delete_table(RECORD_OPERATIONS)
            .expect("delete one Record table");
        write.commit().expect("commit partial fixture");
        drop(database);
        assert!(matches!(
            Store::inspect_existing(&partial.0),
            Err(StoreError::RecordInvariant(
                "mission-scoped Record schema group is incomplete"
            ))
        ));
        assert!(matches!(
            Store::open_for_mission(&partial.0, authority),
            Err(StoreError::RecordInvariant(
                "mission-scoped Record schema group is incomplete"
            ))
        ));
        let database = Database::open(&partial.0).expect("verify no repair");
        assert!(
            !database
                .begin_read()
                .expect("read")
                .list_tables()
                .expect("tables")
                .any(|table| table.name() == RECORD_OPERATIONS.name())
        );

        let wrong_kind = TestFile::new("Record wrong-kind schema");
        let store = Store::open_for_mission(&wrong_kind.0, authority).expect("wrong-kind base");
        drop(store);
        let database = Database::open(&wrong_kind.0).expect("raw wrong-kind database");
        let write = database.begin_write().expect("raw wrong-kind transaction");
        write
            .delete_table(RECORD_OPERATIONS)
            .expect("delete normal Record operation table");
        let definition =
            redb::MultimapTableDefinition::<&[u8], &[u8]>::new("aster.record-operations.v1");
        write
            .open_multimap_table(definition)
            .expect("wrong-kind Record operation table")
            .insert(b"operation".as_slice(), b"record".as_slice())
            .expect("wrong-kind Record operation row");
        write.commit().expect("commit wrong-kind Record schema");
        drop(database);
        for result in [
            Store::inspect_existing(&wrong_kind.0).map(|_| ()),
            Store::open_for_mission(&wrong_kind.0, authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::RecordInvariant(
                    "mission-scoped Record schema has the wrong table kind"
                ))
            ));
        }
    }

    #[test]
    fn record_acceptance_order_and_subscription_schema_migrate_exactly_and_reject_corruption() {
        let migrated = TestFile::new("Record acceptance-order migration");
        let mut services = state_services(0xd0);
        let (first_stored, second_stored) = {
            let store =
                Store::open_for_mission(&migrated.0, services.authority).expect("Record store");
            let policy = store.control_policy_snapshot().expect("settled policy");
            let (first, first_sealed) = verified_record_for_remote_apply(
                &mut services.first,
                &mut services.reader,
                1,
                VersionVector::default(),
                b"record/order/one",
                b"one",
            );
            let (second, second_sealed) = verified_record_for_remote_apply(
                &mut services.second,
                &mut services.reader,
                1,
                VersionVector::default(),
                b"record/order/two",
                b"two",
            );
            store
                .apply_verified_record_with_policy(&policy, &first, &first_sealed)
                .expect("apply first Record");
            store
                .apply_verified_record_with_policy(&policy, &second, &second_sealed)
                .expect("apply second Record");
            (
                store
                    .record_by_semantic_id(RecordSemanticId::new(first.item_id()))
                    .expect("read first Record")
                    .expect("first Record row"),
                store
                    .record_by_semantic_id(RecordSemanticId::new(second.item_id()))
                    .expect("read second Record")
                    .expect("second Record row"),
            )
        };
        {
            let database = Database::open(&migrated.0).expect("open legacy simulation");
            let write = database.begin_write().expect("legacy simulation write");
            write
                .delete_table(RECORD_ACCEPTANCE_ORDER)
                .expect("remove post-legacy Record acceptance order");
            for table in [
                record_subscription::RECORD_SUBSCRIPTIONS,
                record_subscription::RECORD_SUBSCRIPTION_PENDING,
                record_subscription::RECORD_DELIVERY_ACKNOWLEDGEMENTS,
                record_subscription::RECORD_DELIVERY_CURSORS,
            ] {
                write
                    .delete_table(table)
                    .expect("remove post-legacy Record table");
            }
            {
                let mut metadata = write.open_table(METADATA).expect("legacy metadata");
                for field in [
                    record_subscription::RECORD_SUBSCRIPTION_COUNT,
                    record_subscription::RECORD_PENDING_DELIVERY_COUNT,
                    record_subscription::RECORD_ACKNOWLEDGEMENT_COUNT,
                    record_subscription::RECORD_DELIVERY_CURSOR_COUNT,
                    record_subscription::RECORD_SELECTOR_GENERATION,
                ] {
                    metadata
                        .remove(field)
                        .expect("remove post-legacy Record metadata");
                }
            }
            write.commit().expect("commit legacy simulation");
        }
        let legacy = Store::inspect_existing(&migrated.0)
            .expect("exact legacy Record schema remains inspectable");
        assert_eq!(legacy.record_stats.records, 2);
        assert_eq!(
            legacy.record_subscription_stats,
            RecordSubscriptionStats::default()
        );
        drop(
            Store::open_for_mission(&migrated.0, services.authority)
                .expect("writable open atomically migrates Record extensions"),
        );
        {
            let database = redb::Builder::new()
                .open_read_only(&migrated.0)
                .expect("read migrated Record store");
            let read = database.begin_read().expect("read transaction");
            let order = read
                .open_table(RECORD_ACCEPTANCE_ORDER)
                .expect("migrated Record order");
            assert_eq!(
                order
                    .get(1)
                    .expect("first order row")
                    .expect("first row")
                    .value(),
                first_stored.transfer_id.as_bytes().as_slice()
            );
            assert_eq!(
                order
                    .get(2)
                    .expect("second order row")
                    .expect("second row")
                    .value(),
                second_stored.transfer_id.as_bytes().as_slice()
            );
        }
        {
            let database = Database::open(&migrated.0).expect("open corrupt Record index");
            let write = database.begin_write().expect("corrupt Record index write");
            write
                .open_table(RECORD_ACCEPTANCE_ORDER)
                .expect("Record acceptance order")
                .insert(1, second_stored.transfer_id.as_bytes().as_slice())
                .expect("misindex first marker");
            write.commit().expect("commit corrupt Record order");
        }
        for result in [
            Store::inspect_existing(&migrated.0).map(|_| ()),
            Store::open_for_mission(&migrated.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::RecordInvariant(
                    "Record acceptance-order index differs from its forward marker"
                ))
            ));
        }

        let missing_order = TestFile::new("current Record missing acceptance order");
        let store = Store::open_for_mission(&missing_order.0, services.authority)
            .expect("current Record store");
        let policy = store.control_policy_snapshot().expect("policy");
        store
            .create_record_subscription_with_policy(
                &policy,
                &RecordSubscriptionKey::new(b"application/current-record".to_vec())
                    .expect("subscription key"),
                RecordSubscriptionSpec {
                    topic: state_topic(),
                    scope: state_scope(),
                    include_descendant_scopes: false,
                },
            )
            .expect("create current Record subscription");
        drop(store);
        {
            let database = Database::open(&missing_order.0).expect("open current schema");
            let write = database.begin_write().expect("delete current Record order");
            write
                .delete_table(RECORD_ACCEPTANCE_ORDER)
                .expect("delete current Record acceptance order");
            write.commit().expect("commit missing-order corruption");
        }
        for result in [
            Store::inspect_existing(&missing_order.0).map(|_| ()),
            Store::open_for_mission(&missing_order.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::RecordInvariant(
                    "Record acceptance-order index is missing from current schema"
                ))
            ));
        }

        let wrong_kind = TestFile::new("Record acceptance-order wrong kind");
        drop(Store::open_for_mission(&wrong_kind.0, services.authority).expect("wrong-kind base"));
        {
            let database = Database::open(&wrong_kind.0).expect("open wrong-kind database");
            let write = database.begin_write().expect("wrong-kind write");
            write
                .delete_table(RECORD_ACCEPTANCE_ORDER)
                .expect("delete normal Record order");
            let definition = redb::MultimapTableDefinition::<u64, &[u8]>::new(
                "aster.semantic-record-acceptance-order.v1",
            );
            write
                .open_multimap_table(definition)
                .expect("wrong-kind Record order")
                .insert(1, b"not-a-transfer".as_slice())
                .expect("wrong-kind row");
            write.commit().expect("commit wrong-kind Record order");
        }
        for result in [
            Store::inspect_existing(&wrong_kind.0).map(|_| ()),
            Store::open_for_mission(&wrong_kind.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::RecordInvariant(
                    "mission-scoped Record schema has the wrong table kind"
                ))
            ));
        }
    }

    #[test]
    fn record_subscription_schema_corruption_fails_inspection_and_reopen_without_repair() {
        let authority = state_services(0xd1).authority;

        let missing_table = TestFile::new("Record subscription missing table");
        drop(
            Store::open_for_mission(&missing_table.0, authority)
                .expect("missing-table fixture base"),
        );
        {
            let database = Database::open(&missing_table.0).expect("open missing-table fixture");
            let write = database.begin_write().expect("missing-table write");
            write
                .delete_table(record_subscription::RECORD_DELIVERY_CURSORS)
                .expect("delete one Record subscription table");
            write.commit().expect("commit missing table");
        }
        for result in [
            Store::inspect_existing(&missing_table.0).map(|_| ()),
            Store::open_for_mission(&missing_table.0, authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::RecordInvariant(
                    "Record subscription schema group is incomplete"
                ))
            ));
        }
        let database = Database::open(&missing_table.0).expect("verify missing table unchanged");
        assert!(
            !database
                .begin_read()
                .expect("read missing table")
                .list_tables()
                .expect("list missing-table schema")
                .any(|table| table.name() == record_subscription::RECORD_DELIVERY_CURSORS.name())
        );
        drop(database);

        let wrong_kind = TestFile::new("Record subscription wrong kind");
        drop(Store::open_for_mission(&wrong_kind.0, authority).expect("wrong-kind fixture base"));
        {
            let database = Database::open(&wrong_kind.0).expect("open wrong-kind fixture");
            let write = database.begin_write().expect("wrong-kind write");
            write
                .delete_table(record_subscription::RECORD_SUBSCRIPTION_PENDING)
                .expect("delete normal pending table");
            let definition = redb::MultimapTableDefinition::<&[u8], &[u8]>::new(
                "aster.semantic-record-delivery-pending.v1",
            );
            write
                .open_multimap_table(definition)
                .expect("wrong-kind pending table")
                .insert(b"key".as_slice(), b"value".as_slice())
                .expect("wrong-kind pending row");
            write.commit().expect("commit wrong-kind pending table");
        }
        for result in [
            Store::inspect_existing(&wrong_kind.0).map(|_| ()),
            Store::open_for_mission(&wrong_kind.0, authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::RecordInvariant(
                    "Record subscription schema has the wrong table kind"
                ))
            ));
        }

        let missing_counter = TestFile::new("Record subscription missing counter");
        drop(
            Store::open_for_mission(&missing_counter.0, authority)
                .expect("missing-counter fixture base"),
        );
        {
            let database = Database::open(&missing_counter.0).expect("open missing counter");
            let write = database.begin_write().expect("missing-counter write");
            write
                .open_table(METADATA)
                .expect("metadata")
                .remove(record_subscription::RECORD_PENDING_DELIVERY_COUNT)
                .expect("remove pending counter");
            write.commit().expect("commit missing counter");
        }
        for result in [
            Store::inspect_existing(&missing_counter.0).map(|_| ()),
            Store::open_for_mission(&missing_counter.0, authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::RecordInvariant(
                    "Record subscription schema group is incomplete"
                ))
            ));
        }
        let database = Database::open(&missing_counter.0).expect("verify counter unchanged");
        assert!(
            database
                .begin_read()
                .expect("read missing counter")
                .open_table(METADATA)
                .expect("metadata")
                .get(record_subscription::RECORD_PENDING_DELIVERY_COUNT)
                .expect("read pending counter")
                .is_none()
        );
        drop(database);

        let mismatched_counter = TestFile::new("Record subscription mismatched counter");
        drop(
            Store::open_for_mission(&mismatched_counter.0, authority)
                .expect("mismatched-counter fixture base"),
        );
        {
            let database = Database::open(&mismatched_counter.0).expect("open mismatched counter");
            let write = database.begin_write().expect("mismatched-counter write");
            write
                .open_table(METADATA)
                .expect("metadata")
                .insert(record_subscription::RECORD_SUBSCRIPTION_COUNT, 1)
                .expect("inflate subscription counter");
            write.commit().expect("commit mismatched counter");
        }
        for result in [
            Store::inspect_existing(&mismatched_counter.0).map(|_| ()),
            Store::open_for_mission(&mismatched_counter.0, authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::AccountingMismatch {
                    field: record_subscription::RECORD_SUBSCRIPTION_COUNT,
                    durable: 1,
                    reconstructed: 0,
                })
            ));
        }
        let database = Database::open(&mismatched_counter.0).expect("verify mismatch unchanged");
        assert_eq!(
            database
                .begin_read()
                .expect("read mismatched counter")
                .open_table(METADATA)
                .expect("metadata")
                .get(record_subscription::RECORD_SUBSCRIPTION_COUNT)
                .expect("read subscription counter")
                .expect("counter remains present")
                .value(),
            1
        );
    }

    #[test]
    fn event_operation_intent_survives_randomized_reseal_and_rejects_changed_plaintext() {
        let file = TestFile::new("Event stable operation intent");
        let mut services = event_services(0xd1);
        let store = Store::open_for_mission(&file.0, services.authority).expect("store");
        let policy = store.control_policy_snapshot().expect("policy");
        let operation = EventOperationKey::new(b"event/stable-intent".to_vec()).expect("key");
        let payload = b"same";

        let first_reservation = store
            .reserve_event_with_policy(
                &policy,
                services.publisher.identity(),
                &event_topic(),
                &event_scope(),
            )
            .expect("first reservation");
        let first_header = first_reservation
            .header(
                Priority::Immediate,
                b"stable".to_vec(),
                None,
                payload.len() as u64,
                false,
                1,
            )
            .expect("first header");
        let intent = event_publication_intent(&first_header, payload);
        let request =
            EventOperationRequest::new(&operation, &intent, payload, None).expect("first request");
        let first = services
            .publisher
            .seal_event(&first_header, payload)
            .expect("first seal");
        let first_event = content_event(&mut services.reader, &first.bytes);
        assert!(matches!(
            store
                .commit_reserved_event_once_with_policy(
                    &policy,
                    &request,
                    &first_reservation,
                    &first_event,
                    &first.bytes,
                )
                .expect("first commit"),
            EventOnceOutcome::Inserted { .. }
        ));

        let retry_reservation = store
            .reserve_event_with_policy(
                &policy,
                services.publisher.identity(),
                &event_topic(),
                &event_scope(),
            )
            .expect("retry reservation");
        let retry_header = retry_reservation
            .header(
                Priority::Immediate,
                b"stable".to_vec(),
                None,
                payload.len() as u64,
                false,
                1,
            )
            .expect("retry header");
        let retry = services
            .publisher
            .seal_event(&retry_header, payload)
            .expect("retry seal");
        assert_ne!(
            first.id, retry.id,
            "fresh reservation changes semantic identity"
        );
        let retry_event = content_event(&mut services.reader, &retry.bytes);
        assert!(matches!(
            store
                .commit_reserved_event_once_with_policy(
                    &policy,
                    &request,
                    &retry_reservation,
                    &retry_event,
                    &retry.bytes,
                )
                .expect("stable retry"),
            EventOnceOutcome::Existing { .. }
        ));

        let changed_payload = b"evil";
        let changed_intent = event_publication_intent(&retry_header, changed_payload);
        let changed_request =
            EventOperationRequest::new(&operation, &changed_intent, changed_payload, None)
                .expect("changed request");
        let changed = services
            .publisher
            .seal_event(&retry_header, changed_payload)
            .expect("changed seal");
        let changed_event = content_event(&mut services.reader, &changed.bytes);
        assert!(matches!(
            store.commit_reserved_event_once_with_policy(
                &policy,
                &changed_request,
                &retry_reservation,
                &changed_event,
                &changed.bytes,
            ),
            Err(StoreError::EventOperationConflict)
        ));
        assert_eq!(store.event_stats().expect("stats").operations, 1);
    }

    #[test]
    fn proactive_legacy_event_operation_page_binds_exact_witness_without_row_growth() {
        let file = TestFile::new("Event proactive legacy witness");
        let mut services = event_services(0xd7);
        let store = Store::open_for_mission(&file.0, services.authority).expect("store");
        let policy = store.control_policy_snapshot().expect("policy");
        let operation = EventOperationKey::new(b"event/legacy-witness".to_vec()).expect("key");
        let payload = vec![0xa7; 4 * 1024 * 1024];
        let reservation = store
            .reserve_event_with_policy(
                &policy,
                services.publisher.identity(),
                &event_topic(),
                &event_scope(),
            )
            .expect("reservation");
        let header = reservation
            .header(
                Priority::Routine,
                b"legacy".to_vec(),
                None,
                payload.len() as u64,
                false,
                1,
            )
            .expect("header");
        let intent = event_publication_intent(&header, &payload);
        let request =
            EventOperationRequest::new(&operation, &intent, &payload, None).expect("request");
        let sealed = services
            .publisher
            .seal_event(&header, &payload)
            .expect("seal");
        let event = content_event(&mut services.reader, &sealed.bytes);
        let transfer_id = match store
            .commit_reserved_event_once_with_policy(
                &policy,
                &request,
                &reservation,
                &event,
                &sealed.bytes,
            )
            .expect("commit")
        {
            EventOnceOutcome::Inserted { transfer_id, .. } => transfer_id,
            outcome => panic!("unexpected outcome: {outcome:?}"),
        };

        // Recreate the exact released v1 row shape; migration must not invent
        // a plaintext digest from semantic metadata.
        let write = store.database.begin_write().expect("legacy rewrite");
        let (operation_count, operation_bytes) = {
            let mut operations = write.open_table(EVENT_OPERATIONS).expect("operations");
            let _old = operations
                .get(operation.as_bytes())
                .expect("read operation")
                .expect("operation row")
                .value()
                .to_vec();
            let mut legacy = Vec::with_capacity(34);
            legacy.push(EVENT_OPERATION_LEGACY_VERSION);
            legacy.extend_from_slice(transfer_id.as_bytes());
            legacy.push(0);
            operations
                .insert(operation.as_bytes(), legacy.as_slice())
                .expect("write legacy row");
            let mut operation_bytes = operation
                .as_bytes()
                .len()
                .checked_add(legacy.len())
                .expect("primary legacy row length");
            for alias_index in 1..MAX_EVENT_PAGE {
                let alias = EventOperationKey::new(
                    format!("event/legacy-witness/{alias_index:04}").into_bytes(),
                )
                .expect("legacy alias key");
                assert!(
                    operations
                        .insert(alias.as_bytes(), legacy.as_slice())
                        .expect("insert legacy alias")
                        .is_none()
                );
                operation_bytes = operation_bytes
                    .checked_add(alias.as_bytes().len())
                    .and_then(|value| value.checked_add(legacy.len()))
                    .expect("legacy alias accounting");
            }
            (MAX_EVENT_PAGE as u64, operation_bytes as u64)
        };
        {
            let mut metadata = write.open_table(METADATA).expect("metadata update");
            metadata
                .insert(EVENT_OPERATION_COUNT, operation_count)
                .expect("adjust operation count");
            metadata
                .insert(EVENT_OPERATION_TOTAL_BYTES, operation_bytes)
                .expect("adjust operation bytes");
        }
        write.commit().expect("commit legacy fixture");

        let candidates = store
            .unbound_legacy_event_operations_with_policy(&policy, None, 8)
            .expect("legacy page");
        assert_eq!(candidates.len(), 1);
        assert_eq!(candidates[0].predecessor(), None);
        assert_eq!(candidates[0].event().transfer_id, transfer_id);
        assert_eq!(candidates[0].event().sealed.len(), sealed.bytes.len());
        let recovery_operation = candidates[0].operation().clone();
        let recovery_request =
            EventOperationRequest::new(&recovery_operation, &intent, &payload, None)
                .expect("recovery request");
        assert!(matches!(
            store
                .bind_legacy_event_operation_intent_with_policy(
                    &policy,
                    &recovery_request,
                    &event,
                    &sealed.bytes,
                )
                .expect("bind witness"),
            Some(EventOperationResolution::Live(_))
        ));
        assert!(
            store
                .unbound_legacy_event_operations_with_policy(&policy, None, 8)
                .expect("post-bind page")
                .is_empty()
        );
        assert_eq!(
            store.event_stats().expect("stats").operations,
            MAX_EVENT_PAGE as u64
        );
        drop(store);
        Store::inspect_existing(&file.0).expect("inspect witnessed legacy row");
        Store::open_for_mission(&file.0, services.authority).expect("reopen witnessed legacy row");
    }

    #[test]
    fn ttl_tombstone_needs_no_custody_claim_and_is_not_quota_charged() {
        let file = TestFile::new("TTL tombstone custody");
        let mut services = event_services(0xd2);
        let transfer_id;
        {
            let store = Store::open_for_mission(&file.0, services.authority).expect("store");
            let mut header = event_header(
                services.publisher.identity(),
                1,
                1,
                VersionVector::default(),
                b"deleted",
                b"",
                Some(0),
            );
            header.tombstone = true;
            let sealed = services
                .publisher
                .seal_event(&header, b"")
                .expect("seal tombstone");
            transfer_id = EventTransferId::new(Sha256::digest(&sealed.bytes).into());
            let route = services
                .relay
                .verify_event(&sealed.bytes)
                .expect("route tombstone");
            assert!(matches!(
                store
                    .cache_route_verified_event(&route, &sealed.bytes)
                    .expect("cache tombstone without custody claim"),
                RouteCacheOutcome::Inserted { .. }
            ));
            let event = content_event(&mut services.reader, &sealed.bytes);
            assert!(matches!(
                store
                    .apply_verified_event(&event, &sealed.bytes)
                    .expect("accept tombstone without custody claim"),
                ApplyOutcome::Inserted { .. }
            ));
            assert_eq!(
                store.custody_usage(None).expect("ordinary usage"),
                CustodyUsage::default()
            );
            assert_eq!(
                store
                    .custody_age_status(CustodyObjectKey::event(transfer_id), None)
                    .expect("tombstone status"),
                Some(CustodyAgeStatus::Durable)
            );
        }
        let inspection = Store::inspect_existing(&file.0).expect("read-only audit");
        assert_eq!(inspection.custody_stats.items, 1);
        let reopened = Store::open_for_mission(&file.0, services.authority).expect("reopen");
        assert_eq!(
            reopened.custody_usage(None).expect("reopened usage"),
            CustodyUsage::default()
        );
        assert_eq!(reopened.event_stats().expect("Event stats").events, 1);
    }

    #[test]
    fn finite_retirement_mark_is_receiver_only_until_lease_drain() {
        let file = TestFile::new("finite retirement sender split");
        let mut services = event_services(0xd4);
        let store = Store::open_for_mission(&file.0, services.authority).expect("store");
        let policy = store.control_policy_snapshot().expect("policy");
        let operation = EventOperationKey::new(b"event/finite-retirement".to_vec()).expect("key");
        let payload = b"finite";
        let reservation = store
            .reserve_event_with_policy(
                &policy,
                services.publisher.identity(),
                &event_topic(),
                &event_scope(),
            )
            .expect("reservation");
        let header = reservation
            .header(
                Priority::Routine,
                b"finite".to_vec(),
                Some(100),
                payload.len() as u64,
                false,
                1,
            )
            .expect("header");
        let intent = event_publication_intent(&header, payload);
        let request = EventOperationRequest::new(&operation, &intent, payload, None)
            .expect("operation request");
        let sealed = services
            .publisher
            .seal_event(&header, payload)
            .expect("seal");
        let event = content_event(&mut services.reader, &sealed.bytes);
        let clock_id = [0x44; 16];
        let initial_sample = aster_mesh::CustodySample {
            clock_id,
            tick_ms: 1_000,
        };
        let transfer_id = match store
            .commit_reserved_event_once_with_custody_policy(
                &policy,
                LocalCustodyCheckpoint::new(
                    store.custody_policy_revision().expect("custody revision"),
                    initial_sample,
                ),
                &request,
                &reservation,
                &event,
                &sealed.bytes,
            )
            .expect("finite commit")
        {
            EventOnceOutcome::Inserted { transfer_id, .. } => transfer_id,
            outcome => panic!("unexpected finite commit: {outcome:?}"),
        };
        let key = CustodyObjectKey::event(transfer_id);
        let lease = store
            .begin_custody_send(
                services.relay.identity(),
                key,
                CustodyPeerSelectorRevision::new(1),
                Some(initial_sample),
                1,
                store.custody_policy_revision().expect("lease revision"),
            )
            .expect("lease");
        let expired_sample = aster_mesh::CustodySample {
            clock_id,
            tick_ms: 1_100,
        };
        let projection_revision = store
            .custody_policy_revision()
            .expect("projection revision");
        assert!(
            store
                .sender_transfer_inventory_with_policy(
                    &policy,
                    Some(expired_sample),
                    projection_revision,
                )
                .expect("expired projection")
                .is_empty()
        );
        assert!(
            store
                .sender_transfer_inventory_with_policy(
                    &policy,
                    Some(aster_mesh::CustodySample {
                        clock_id: [0x45; 16],
                        tick_ms: 1_050,
                    }),
                    projection_revision,
                )
                .expect("lost-continuity projection")
                .is_empty()
        );
        let report = store
            .collect_custody_garbage(
                Some(expired_sample),
                store.custody_policy_revision().expect("GC revision"),
                1,
            )
            .expect("mark expiry");
        assert_eq!(report.marked, vec![key]);
        assert!(report.retired.is_empty());
        assert_eq!(report.blocked_by_leases, 1);
        assert_eq!(store.get_event(transfer_id).expect("public get"), None);
        assert!(
            store
                .event_inventory()
                .expect("sender inventory")
                .is_empty()
        );
        assert_eq!(store.event_count().expect("live count"), 0);
        let stats = store.event_stats().expect("marked stats");
        assert_eq!((stats.events, stats.retiring_events), (1, 1));
        assert_eq!(
            store
                .custody_sender_status(key, Some(expired_sample))
                .expect("sender status"),
            Some(CustodySenderStatus::Retiring)
        );
        assert_eq!(
            store
                .load_scheduled_custody_transfer(
                    key,
                    Some(expired_sample),
                    store
                        .custody_policy_revision()
                        .expect("marked lookup revision"),
                )
                .expect("marked scheduled lookup"),
            None
        );
        assert!(
            store
                .sender_transfer_inventory_with_policy(
                    &policy,
                    Some(expired_sample),
                    store
                        .custody_policy_revision()
                        .expect("marked projection revision"),
                )
                .expect("marked projection")
                .is_empty()
        );
        let mut retained_visits = 0usize;
        assert_eq!(
            store
                .visit_retained_custody_event_sources_with_policy(
                    &policy,
                    store
                        .custody_policy_revision()
                        .expect("retained-source revision"),
                    |transfer| {
                        retained_visits += 1;
                        assert!(matches!(
                            transfer,
                            StoredEventTransfer::Accepted(event)
                                if event.transfer_id == transfer_id
                        ));
                        Ok::<(), StoreError>(())
                    },
                )
                .expect("retiring source remains available to authentication gate"),
            1
        );
        assert_eq!(retained_visits, 1);
        assert!(matches!(
            store
                .event_operation_resolution(&operation)
                .expect("operation resolution"),
            Some(EventOperationResolution::Withheld { .. })
        ));
        store
            .create_event_subscription_with_policy(
                &policy,
                &EventSubscriptionKey::new(b"retirement/carry".to_vec()).expect("selector key"),
                subscription_spec(EventSubscriptionMode::Carry),
            )
            .expect("create receive selector");
        let replication = store
            .event_replication_policy_snapshot()
            .expect("replication policy");
        assert_eq!(
            store
                .event_receiver_fences_with_policy(&replication, None, 1)
                .expect("receiver fence")[0]
                .object,
            key
        );

        store
            .release_transfer_lease(lease.id)
            .expect("release lease");
        let finalized = store
            .collect_custody_garbage(
                Some(expired_sample),
                store.custody_policy_revision().expect("finalize revision"),
                1,
            )
            .expect("finalize expiry");
        assert_eq!(finalized.retired, vec![key]);
        assert!(matches!(
            store
                .event_operation_resolution(&operation)
                .expect("retired operation"),
            Some(EventOperationResolution::Retired {
                reason: CustodyRetirementReason::Expired,
                ..
            })
        ));
        drop(store);
        let inspection = Store::inspect_existing(&file.0).expect("inspect retired store");
        assert_eq!(inspection.event_stats.retiring_events, 0);
        assert_eq!(inspection.custody_stats.retirements, 1);
        Store::open_for_mission(&file.0, services.authority).expect("reopen retired store");
    }

    #[test]
    fn delayed_same_clock_read_uses_persisted_continuity_high_water() {
        let file = TestFile::new("delayed custody read sample");
        let mut services = event_services(0xd5);
        let store = Store::open_for_mission(&file.0, services.authority).expect("store");
        let policy = store.control_policy_snapshot().expect("policy");
        let operation = EventOperationKey::new(b"event/delayed-sample".to_vec()).expect("key");
        let payload = b"age";
        let reservation = store
            .reserve_event_with_policy(
                &policy,
                services.publisher.identity(),
                &event_topic(),
                &event_scope(),
            )
            .expect("reservation");
        let header = reservation
            .header(
                Priority::Routine,
                b"age".to_vec(),
                Some(100),
                payload.len() as u64,
                false,
                1,
            )
            .expect("header");
        let intent = event_publication_intent(&header, payload);
        let request =
            EventOperationRequest::new(&operation, &intent, payload, None).expect("request");
        let sealed = services
            .publisher
            .seal_event(&header, payload)
            .expect("seal");
        let event = content_event(&mut services.reader, &sealed.bytes);
        let clock_id = [0x55; 16];
        let initial = aster_mesh::CustodySample {
            clock_id,
            tick_ms: 100,
        };
        let transfer_id = match store
            .commit_reserved_event_once_with_custody_policy(
                &policy,
                LocalCustodyCheckpoint::new(
                    store.custody_policy_revision().expect("revision"),
                    initial,
                ),
                &request,
                &reservation,
                &event,
                &sealed.bytes,
            )
            .expect("commit")
        {
            EventOnceOutcome::Inserted { transfer_id, .. } => transfer_id,
            outcome => panic!("unexpected outcome: {outcome:?}"),
        };
        let key = CustodyObjectKey::event(transfer_id);
        let lease = store
            .begin_custody_send(
                services.relay.identity(),
                key,
                CustodyPeerSelectorRevision::new(1),
                Some(initial),
                1,
                store.custody_policy_revision().expect("lease revision"),
            )
            .expect("seed retry");
        store
            .release_transfer_lease(lease.id)
            .expect("retain retry after lease release");
        let policy_before_stale = store
            .custody_policy_revision()
            .expect("policy before stale");
        let write = store.database.begin_write().expect("continuity write");
        let current = custody::observe_continuity_write(
            &write,
            aster_mesh::CustodySample {
                clock_id,
                tick_ms: 200,
            },
        )
        .expect("advance continuity");
        write.commit().expect("commit continuity");
        let stale = store
            .database
            .begin_write()
            .expect("stale continuity write");
        let normalized = custody::observe_continuity_write(
            &stale,
            aster_mesh::CustodySample {
                clock_id,
                tick_ms: 150,
            },
        )
        .expect("normalize stale same-clock sample");
        assert_eq!(normalized, current);
        stale.commit().expect("commit normalized continuity");
        assert_eq!(
            store.custody_policy_revision().expect("policy after stale"),
            policy_before_stale
        );
        assert_eq!(
            store
                .database
                .begin_read()
                .expect("retry read")
                .open_table(custody::CUSTODY_RETRIES)
                .expect("retry table")
                .len()
                .expect("retry count"),
            1
        );
        assert_eq!(
            store
                .custody_age_status(
                    key,
                    Some(aster_mesh::CustodySample {
                        clock_id,
                        tick_ms: 150,
                    }),
                )
                .expect("delayed read"),
            Some(CustodyAgeStatus::Expired { age_ms: 100 })
        );
        drop(store);
        let reopened = Store::open_for_mission(&file.0, services.authority).expect("reopen");
        assert_eq!(
            reopened
                .database
                .begin_read()
                .expect("reopened retry read")
                .open_table(custody::CUSTODY_RETRIES)
                .expect("reopened retry table")
                .len()
                .expect("reopened retry count"),
            1
        );
        assert_eq!(
            reopened
                .custody_sender_status(
                    key,
                    Some(aster_mesh::CustodySample {
                        clock_id,
                        tick_ms: 200,
                    }),
                )
                .expect("reopened sender status"),
            Some(CustodySenderStatus::Age(CustodyAgeStatus::Expired {
                age_ms: 100
            }))
        );
    }

    #[test]
    fn writable_reopen_clears_crash_stale_lease_but_preserves_retry() {
        let file = TestFile::new("crash stale custody lease");
        let mut services = event_services(0xd8);
        let transfer_id;
        let clock_id = [0x58; 16];
        {
            let store = Store::open_for_mission(&file.0, services.authority).expect("store");
            let policy = store.control_policy_snapshot().expect("policy");
            let operation = EventOperationKey::new(b"event/crash-lease".to_vec()).expect("key");
            let payload = b"durable";
            let reservation = store
                .reserve_event_with_policy(
                    &policy,
                    services.publisher.identity(),
                    &event_topic(),
                    &event_scope(),
                )
                .expect("reservation");
            let header = reservation
                .header(
                    Priority::Routine,
                    b"durable".to_vec(),
                    None,
                    payload.len() as u64,
                    false,
                    1,
                )
                .expect("header");
            let intent = event_publication_intent(&header, payload);
            let request = EventOperationRequest::new(&operation, &intent, payload, None)
                .expect("operation request");
            let sealed = services
                .publisher
                .seal_event(&header, payload)
                .expect("seal");
            let event = content_event(&mut services.reader, &sealed.bytes);
            transfer_id = match store
                .commit_reserved_event_once_with_policy(
                    &policy,
                    &request,
                    &reservation,
                    &event,
                    &sealed.bytes,
                )
                .expect("commit")
            {
                EventOnceOutcome::Inserted { transfer_id, .. } => transfer_id,
                outcome => panic!("unexpected outcome: {outcome:?}"),
            };
            let _abandoned = store
                .begin_custody_send(
                    services.relay.identity(),
                    CustodyObjectKey::event(transfer_id),
                    CustodyPeerSelectorRevision::new(1),
                    Some(aster_mesh::CustodySample {
                        clock_id,
                        tick_ms: 1_000,
                    }),
                    1,
                    store.custody_policy_revision().expect("lease revision"),
                )
                .expect("abandoned lease");
        }
        let stopped = Store::inspect_existing(&file.0).expect("inspect crash state");
        assert_eq!(stopped.custody_stats.transfer_leases, 1);
        assert_eq!(stopped.custody_stats.retries, 1);

        let reopened = Store::open_for_mission(&file.0, services.authority).expect("reopen");
        let read = reopened
            .database
            .begin_read()
            .expect("read recovered tables");
        assert_eq!(
            read.open_table(custody::CUSTODY_LEASES)
                .expect("leases")
                .len()
                .expect("lease count"),
            0
        );
        assert_eq!(
            read.open_table(custody::CUSTODY_RETRIES)
                .expect("retries")
                .len()
                .expect("retry count"),
            1
        );
        drop(read);
        let replacement = reopened
            .begin_custody_send(
                services.relay.identity(),
                CustodyObjectKey::event(transfer_id),
                CustodyPeerSelectorRevision::new(1),
                Some(aster_mesh::CustodySample {
                    clock_id,
                    tick_ms: 1_000_000,
                }),
                1,
                reopened
                    .custody_policy_revision()
                    .expect("replacement revision"),
            )
            .expect("retry becomes eligible after recovered lease");
        reopened
            .release_transfer_lease(replacement.id)
            .expect("release replacement");
    }

    #[test]
    fn carry_receipt_does_not_suppress_consume_reoffer_or_retry_cadence() {
        let source_file = TestFile::new("Carry receipt source");
        let receiver_file = TestFile::new("Carry receipt receiver");
        let mut services = event_services(0xe1);
        let source = Store::open_for_mission(&source_file.0, services.authority).expect("source");
        let receiver =
            Store::open_for_mission(&receiver_file.0, services.authority).expect("receiver");
        let mut header = event_header(
            services.publisher.identity(),
            1,
            1,
            VersionVector::default(),
            b"carry-to-consume",
            b"payload",
            None,
        );
        header.priority = Priority::Routine;
        let stored = accept_event(&source, &mut services, header, b"payload");
        let transfer_id = stored.transfer_id;
        let event_key = CustodyObjectKey::event(transfer_id);
        let route_key = CustodyObjectKey::route_event(transfer_id);
        let source_peer = services.reader.identity();
        let receiver_peer = services.publisher.identity();
        let source_sample = aster_mesh::CustodySample {
            clock_id: [0x81; 16],
            tick_ms: 1_000,
        };
        let receiver_sample = aster_mesh::CustodySample {
            clock_id: [0x82; 16],
            tick_ms: 2_000,
        };

        let receiver_policy = receiver.control_policy_snapshot().expect("receiver policy");
        receiver
            .create_event_subscription_with_policy(
                &receiver_policy,
                &EventSubscriptionKey::new(b"custody/carry".to_vec()).expect("Carry key"),
                subscription_spec(EventSubscriptionMode::Carry),
            )
            .expect("create Carry selector");
        let carry = receiver
            .event_replication_policy_snapshot()
            .expect("Carry replication policy");
        let route = services
            .relay
            .verify_event(&stored.sealed)
            .expect("route verification");
        let carry_outcome = receiver
            .cache_route_verified_event_with_replication_policy(&carry, &route, &stored.sealed)
            .expect("cache Carry representation");
        assert!(matches!(
            carry_outcome,
            RouteCacheOutcome::Inserted { transfer_id: id, .. } if id == transfer_id
        ));
        assert_eq!(
            carry_outcome.custody_disposition(),
            CustodyPeerApplyDisposition::Satisfied
        );

        // The receiver's own route-class receipt must also be invalidated by
        // its later route-to-accepted promotion rather than aliased to Event.
        let receiver_revision = receiver
            .custody_policy_revision()
            .expect("receiver custody revision");
        let receiver_lease = receiver
            .begin_custody_send(
                receiver_peer,
                route_key,
                CustodyPeerSelectorRevision::new(1),
                Some(receiver_sample),
                10,
                receiver_revision,
            )
            .expect("route lease");
        receiver
            .require_custody_send(&receiver_lease, Some(receiver_sample), receiver_revision)
            .expect("authorize route send");
        receiver
            .record_peer_custody_receipt(
                &receiver_lease,
                0,
                Some(receiver_sample),
                CustodyPeerSelectorRevision::new(1),
                receiver_revision,
            )
            .expect("record route-class receipt");

        // Carry receipt on the source suppresses ordinary retransmission.
        let source_revision = source
            .custody_policy_revision()
            .expect("source custody revision");
        let source_lease = source
            .begin_custody_send(
                source_peer,
                event_key,
                CustodyPeerSelectorRevision::new(1),
                Some(source_sample),
                10,
                source_revision,
            )
            .expect("source Event lease");
        source
            .require_custody_send(&source_lease, Some(source_sample), source_revision)
            .expect("authorize source send");
        source
            .record_peer_custody_receipt(
                &source_lease,
                0,
                Some(source_sample),
                CustodyPeerSelectorRevision::new(1),
                source_revision,
            )
            .expect("record Carry receipt");
        assert!(
            source
                .next_custody_outbound(
                    source_peer,
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::Blind(CustodyPeerSelectorRevision::new(1),),
                    ),
                    CustodyOutboundBudget {
                        max_items: 1,
                        max_bytes: u64::MAX,
                    },
                    Some(source_sample),
                    source_revision,
                )
                .expect("receipt-suppressed ordinary plan")
                .is_empty()
        );
        drop(source);
        drop(receiver);
        assert_eq!(
            Store::inspect_existing(&source_file.0)
                .expect("inspect source receipt")
                .custody_stats
                .peer_receipts,
            1
        );
        assert_eq!(
            Store::inspect_existing(&receiver_file.0)
                .expect("inspect route receipt")
                .custody_stats
                .peer_receipts,
            1
        );

        let source =
            Store::open_for_mission(&source_file.0, services.authority).expect("reopen source");
        let receiver =
            Store::open_for_mission(&receiver_file.0, services.authority).expect("reopen receiver");
        let receiver_policy = receiver
            .control_policy_snapshot()
            .expect("reopened receiver policy");
        receiver
            .create_event_subscription_with_policy(
                &receiver_policy,
                &EventSubscriptionKey::new(b"custody/consume".to_vec()).expect("Consume key"),
                subscription_spec(EventSubscriptionMode::Consume),
            )
            .expect("create dominating Consume selector");
        let consume = receiver
            .event_replication_policy_snapshot()
            .expect("Consume replication policy");
        assert_eq!(
            consume.effective_mode(&event_topic(), &event_scope()),
            Some(EventSubscriptionMode::Consume)
        );
        assert!(
            receiver
                .get_event(transfer_id)
                .expect("accepted lookup")
                .is_none()
        );
        assert!(
            receiver
                .get_route_cached_event(transfer_id)
                .expect("route lookup")
                .is_some()
        );

        // The authenticated Consume reconciliation difference supersedes the
        // older Event receipt atomically on the source.
        let source_revision = source
            .custody_policy_revision()
            .expect("reopened source revision");
        assert!(
            source
                .next_custody_outbound_bulk_from_transfers(
                    source_peer,
                    &[transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::Blind(CustodyPeerSelectorRevision::new(1)),
                    ),
                    1,
                    Some(source_sample),
                    source_revision,
                )
                .expect("blind scheduling remains receipt-suppressed")
                .is_empty()
        );
        let selected = source
            .next_custody_outbound_bulk_from_transfers(
                source_peer,
                &[transfer_id],
                CustodyReconciliationSelection::new(
                    Priority::Routine,
                    CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                        CustodyPeerSelectorRevision::new(2),
                    ),
                ),
                1,
                Some(source_sample),
                source_revision,
            )
            .expect("authenticated missing-set selection");
        assert_eq!(selected.len(), 1);
        assert_eq!(selected[0].object, event_key);

        let event = content_event(&mut services.reader, &stored.sealed);
        assert!(matches!(
            receiver
                .apply_verified_event_with_replication_policy(&consume, &event, &stored.sealed)
                .expect("promote route representation under Consume"),
            ApplyOutcome::Inserted { .. }
        ));
        assert!(
            receiver
                .get_event(transfer_id)
                .expect("promoted Event")
                .is_some()
        );
        assert!(
            receiver
                .get_route_cached_event(transfer_id)
                .expect("promoted route lookup")
                .is_none()
        );
        assert_eq!(
            receiver
                .next_custody_outbound(
                    receiver_peer,
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::Blind(CustodyPeerSelectorRevision::new(1),),
                    ),
                    CustodyOutboundBudget {
                        max_items: 1,
                        max_bytes: u64::MAX,
                    },
                    Some(receiver_sample),
                    receiver
                        .custody_policy_revision()
                        .expect("promoted receiver revision"),
                )
                .expect("accepted Event is a fresh receiver-side obligation")[0]
                .object,
            event_key
        );

        // Receipt invalidation does not bypass the durable retry floor.
        let link_floor_ms = 10;
        let lease = source
            .begin_custody_send(
                source_peer,
                event_key,
                CustodyPeerSelectorRevision::new(2),
                Some(source_sample),
                link_floor_ms,
                source_revision,
            )
            .expect("fresh Consume lease");
        source
            .require_custody_send(&lease, Some(source_sample), source_revision)
            .expect("authorize Consume reoffer");
        source
            .release_transfer_lease(lease.id)
            .expect("retain retry floor");
        drop(source);
        let source =
            Store::open_for_mission(&source_file.0, services.authority).expect("retry reopen");
        let source_revision = source.custody_policy_revision().expect("retry revision");
        assert!(
            source
                .next_custody_outbound_bulk_from_transfers(
                    source_peer,
                    &[transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                            CustodyPeerSelectorRevision::new(2),
                        ),
                    ),
                    1,
                    Some(source_sample),
                    source_revision,
                )
                .expect("retry-floor selection")
                .is_empty()
        );
        let due_sample = aster_mesh::CustodySample {
            clock_id: source_sample.clock_id,
            tick_ms: source_sample.tick_ms
                + aster_mesh::retry_delay_ms(Priority::Routine, 0, link_floor_ms),
        };
        assert_eq!(
            source
                .next_custody_outbound_bulk_from_transfers(
                    source_peer,
                    &[transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                            CustodyPeerSelectorRevision::new(2),
                        ),
                    ),
                    1,
                    Some(due_sample),
                    source_revision,
                )
                .expect("due retry selection")[0]
                .object,
            event_key
        );
        drop(source);
        drop(receiver);
        let source_inspection = Store::inspect_existing(&source_file.0).expect("inspect source");
        assert_eq!(source_inspection.custody_stats.peer_receipts, 0);
        assert_eq!(source_inspection.custody_stats.retries, 1);
        let receiver_inspection =
            Store::inspect_existing(&receiver_file.0).expect("inspect receiver");
        assert_eq!(receiver_inspection.custody_stats.peer_receipts, 0);
        assert_eq!(receiver_inspection.custody_stats.retries, 0);
        Store::open_for_mission(&source_file.0, services.authority).expect("final source reopen");
        Store::open_for_mission(&receiver_file.0, services.authority)
            .expect("final receiver reopen");
    }

    #[test]
    fn blind_receipts_are_bound_to_opaque_peer_selector_revision() {
        let file = TestFile::new("blind selector-bound receipt");
        let mut services = event_services(0xe5);
        let store = Store::open_for_mission(&file.0, services.authority).expect("store");
        let publisher = services.publisher.identity();
        let stored = accept_event(
            &store,
            &mut services,
            event_header(
                publisher,
                1,
                1,
                VersionVector::default(),
                b"blind-selector",
                b"payload",
                None,
            ),
            b"payload",
        );
        let object = CustodyObjectKey::event(stored.transfer_id);
        let peer = services.reader.identity();
        let sample = aster_mesh::CustodySample {
            clock_id: [0x86; 16],
            tick_ms: 70_000,
        };
        let policy = store.custody_policy_revision().expect("policy");
        let selector_zero = CustodyPeerSelectorRevision::new(0);
        let selector_one = CustodyPeerSelectorRevision::new(1);
        let selector_two = CustodyPeerSelectorRevision::new(2);
        let lease = store
            .begin_custody_send(peer, object, selector_zero, Some(sample), 1, policy)
            .expect("initial blind lease");
        assert!(matches!(
            store.settle_peer_custody_apply(
                &lease,
                CustodyPeerApplyEvidence::new(
                    CustodyPeerApplyDisposition::Satisfied,
                    selector_one,
                ),
                0,
                Some(sample),
                policy,
            ),
            Err(StoreError::Custody(CustodyStoreError::ItemChanged))
        ));
        store
            .require_custody_send(&lease, Some(sample), policy)
            .expect("mismatched selector evidence cannot consume the lease");
        store
            .record_peer_custody_receipt(&lease, 0, Some(sample), selector_zero, policy)
            .expect("selector-zero satisfied receipt");
        drop(store);

        let store = Store::open_for_mission(&file.0, services.authority).expect("receipt reopen");
        assert!(
            store
                .next_custody_outbound_bulk_from_transfers(
                    peer,
                    &[stored.transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::Blind(selector_zero),
                    ),
                    1,
                    Some(sample),
                    policy,
                )
                .expect("same selector revision remains suppressed")
                .is_empty()
        );
        assert_eq!(
            store
                .next_custody_outbound_bulk_from_transfers(
                    peer,
                    &[stored.transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::Blind(selector_one),
                    ),
                    1,
                    Some(sample),
                    policy,
                )
                .expect("changed selector revision permits one reoffer")[0]
                .object,
            object
        );
        let replacement = store
            .begin_custody_send(peer, object, selector_one, Some(sample), 1, policy)
            .expect("changed-selector lease");
        store
            .settle_peer_custody_apply(
                &replacement,
                CustodyPeerApplyEvidence::new(CustodyPeerApplyDisposition::Satisfied, selector_one),
                0,
                Some(sample),
                policy,
            )
            .expect("bind replacement receipt to selector one");
        assert!(
            store
                .next_custody_outbound_bulk_from_transfers(
                    peer,
                    &[stored.transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::Blind(selector_one),
                    ),
                    1,
                    Some(sample),
                    policy,
                )
                .expect("replacement selector remains suppressed")
                .is_empty()
        );

        // A second contact can install the newly satisfied receipt after a
        // stale plan was selected. Begin maps that race to typed stale work.
        assert_eq!(
            store
                .next_custody_outbound_bulk_from_transfers(
                    peer,
                    &[stored.transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::Blind(selector_two),
                    ),
                    1,
                    Some(sample),
                    policy,
                )
                .expect("selector-two stale plan")[0]
                .object,
            object
        );
        let competing = store
            .begin_custody_send(peer, object, selector_two, Some(sample), 1, policy)
            .expect("competing selector-two lease");
        store
            .settle_peer_custody_apply(
                &competing,
                CustodyPeerApplyEvidence::new(CustodyPeerApplyDisposition::Satisfied, selector_two),
                0,
                Some(sample),
                policy,
            )
            .expect("competing selector-two settlement");
        assert!(matches!(
            store.begin_custody_send(peer, object, selector_two, Some(sample), 1, policy),
            Err(StoreError::Custody(CustodyStoreError::ItemChanged))
        ));
        drop(store);
        let inspection = Store::inspect_existing(&file.0).expect("inspect selector receipts");
        assert_eq!(inspection.custody_stats.peer_receipts, 1);
        assert_eq!(inspection.custody_stats.retries, 0);
        assert_eq!(inspection.custody_stats.transfer_leases, 0);
        Store::open_for_mission(&file.0, services.authority).expect("final selector reopen");
    }

    #[test]
    fn legacy_unbound_peer_receipt_is_dropped_before_revision_zero_scheduling() {
        let file = TestFile::new("legacy unbound peer receipt");
        let mut services = event_services(0xe6);
        let store = Store::open_for_mission(&file.0, services.authority).expect("store");
        let publisher = services.publisher.identity();
        let stored = accept_event(
            &store,
            &mut services,
            event_header(
                publisher,
                1,
                1,
                VersionVector::default(),
                b"legacy-receipt",
                b"payload",
                None,
            ),
            b"payload",
        );
        let object = CustodyObjectKey::event(stored.transfer_id);
        let peer = services.reader.identity();
        let sample = aster_mesh::CustodySample {
            clock_id: [0x87; 16],
            tick_ms: 80_000,
        };
        let policy = store.custody_policy_revision().expect("policy");
        let selector = CustodyPeerSelectorRevision::new(7);
        let lease = store
            .begin_custody_send(peer, object, selector, Some(sample), 1, policy)
            .expect("seed version-two receipt lease");
        store
            .record_peer_custody_receipt(&lease, 0, Some(sample), selector, policy)
            .expect("seed version-two receipt");
        drop(store);

        let mut receipt_key = [0u8; 65];
        receipt_key[..32].copy_from_slice(&peer);
        receipt_key[32] = CustodyObjectClass::Event as u8;
        receipt_key[33..].copy_from_slice(stored.transfer_id.as_bytes());
        {
            let database = Database::open(&file.0).expect("raw legacy receipt database");
            let write = database.begin_write().expect("raw legacy receipt write");
            let mut encoded = write
                .open_table(custody::CUSTODY_PEER_RECEIPTS)
                .expect("receipt table")
                .get(receipt_key.as_slice())
                .expect("read receipt")
                .expect("receipt row")
                .value()
                .to_vec();
            assert_eq!(encoded.len(), 25);
            encoded[0] = 1;
            encoded.truncate(17);
            write
                .open_table(custody::CUSTODY_PEER_RECEIPTS)
                .expect("receipt table")
                .insert(receipt_key.as_slice(), encoded.as_slice())
                .expect("replace with version-one receipt");
            write.commit().expect("commit version-one receipt");
        }

        let stopped = Store::inspect_existing(&file.0).expect("inspect legacy receipt");
        assert_eq!(stopped.custody_stats.peer_receipts, 1);
        let store = Store::open_for_mission(&file.0, services.authority)
            .expect("writable legacy receipt migration");
        let policy = store
            .custody_policy_revision()
            .expect("post-migration policy");
        drop(store);
        let migrated = Store::inspect_existing(&file.0).expect("inspect migrated receipt");
        assert_eq!(migrated.custody_stats.peer_receipts, 0);
        assert_eq!(
            migrated.custody_stats.policy_revision,
            stopped.custody_stats.policy_revision
        );
        assert_eq!(
            migrated.custody_stats.mutation_revision,
            stopped
                .custody_stats
                .mutation_revision
                .checked_add(1)
                .expect("migration mutation revision")
        );
        let store = Store::open_for_mission(&file.0, services.authority)
            .expect("reopen migrated receipt store");
        let selector_zero = CustodyPeerSelectorRevision::new(0);
        let selected = store
            .next_custody_outbound_from(
                peer,
                &[object],
                CustodyReconciliationSelection::new(
                    Priority::Routine,
                    CustodyReconciliationEvidence::Blind(selector_zero),
                ),
                CustodyOutboundBudget {
                    max_items: 1,
                    max_bytes: u64::MAX,
                },
                Some(sample),
                policy,
            )
            .expect("legacy hint cannot suppress canonical selector zero");
        assert_eq!(selected.len(), 1);
        assert_eq!(selected[0].object, object);
        let lease = store
            .begin_custody_send(peer, object, selector_zero, Some(sample), 1, policy)
            .expect("revision-zero lease after legacy cleanup");
        store
            .release_transfer_lease(lease.id)
            .expect("release migrated retry lease");
        drop(store);
        Store::open_for_mission(&file.0, services.authority).expect("final migrated reopen");
    }

    #[test]
    fn content_pending_and_authenticated_peer_presence_settle_retry_exactly() {
        let source_file = TestFile::new("content-pending retry source");
        let receiver_file = TestFile::new("content-pending retry receiver");
        let mut services = event_services(0xe2);
        let source = Store::open_for_mission(&source_file.0, services.authority).expect("source");
        let receiver =
            Store::open_for_mission(&receiver_file.0, services.authority).expect("receiver");
        let mut header = event_header(
            services.publisher.identity(),
            1,
            1,
            VersionVector::default(),
            b"content-pending",
            b"payload",
            None,
        );
        header.priority = Priority::Routine;
        let stored = accept_event(&source, &mut services, header, b"payload");
        let transfer_id = stored.transfer_id;
        let object = CustodyObjectKey::event(transfer_id);
        let peer = services.reader.identity();
        let sample = aster_mesh::CustodySample {
            clock_id: [0x83; 16],
            tick_ms: 10_000,
        };
        let link_floor_ms = 10;

        let receiver_policy = receiver.control_policy_snapshot().expect("receiver policy");
        receiver
            .create_event_subscription_with_policy(
                &receiver_policy,
                &EventSubscriptionKey::new(b"custody/pending-consume".to_vec())
                    .expect("Consume key"),
                subscription_spec(EventSubscriptionMode::Consume),
            )
            .expect("create Consume selector");
        let consume = receiver
            .event_replication_policy_snapshot()
            .expect("Consume policy");
        let route = services
            .relay
            .verify_event(&stored.sealed)
            .expect("route verification without content key");
        let route_outcome = receiver
            .cache_route_verified_event_with_replication_policy(&consume, &route, &stored.sealed)
            .expect("retain route-only Consume representation");
        assert_eq!(
            route_outcome.custody_disposition(),
            CustodyPeerApplyDisposition::ContentAcceptancePending
        );

        // A prior satisfied receipt is superseded only after authenticated
        // normal reconciliation selects this exact missing transfer.
        let revision = source.custody_policy_revision().expect("revision");
        let prior = source
            .begin_custody_send(
                peer,
                object,
                CustodyPeerSelectorRevision::new(3),
                Some(sample),
                link_floor_ms,
                revision,
            )
            .expect("prior Carry lease");
        source
            .require_custody_send(&prior, Some(sample), revision)
            .expect("prior send authorization");
        source
            .record_peer_custody_receipt(
                &prior,
                0,
                Some(sample),
                CustodyPeerSelectorRevision::new(3),
                revision,
            )
            .expect("prior satisfied receipt");
        assert_eq!(
            source
                .next_custody_outbound_bulk_from_transfers(
                    peer,
                    &[transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                            CustodyPeerSelectorRevision::new(3),
                        ),
                    ),
                    1,
                    Some(sample),
                    revision,
                )
                .expect("authenticated receipt supersession")[0]
                .object,
            object
        );

        // A policy mutation after bytes left cannot prevent authenticated
        // Pending settlement. The lease drains, while its paid retry remains.
        let first = source
            .begin_custody_send(
                peer,
                object,
                CustodyPeerSelectorRevision::new(3),
                Some(sample),
                link_floor_ms,
                revision,
            )
            .expect("first promotion-attempt lease");
        source
            .require_custody_send(&first, Some(sample), revision)
            .expect("first promotion-attempt authorization");
        let current_revision = source
            .set_custody_protection(
                object,
                CustodyProtection::new(false, true, false, false),
                revision,
            )
            .expect("concurrent protection policy change");
        source
            .settle_peer_custody_apply(
                &first,
                CustodyPeerApplyEvidence::new(
                    CustodyPeerApplyDisposition::ContentAcceptancePending,
                    CustodyPeerSelectorRevision::new(3),
                ),
                0,
                Some(sample),
                revision,
            )
            .expect("content-pending settlement after policy change");
        drop(source);
        let pending = Store::inspect_existing(&source_file.0).expect("inspect pending retry");
        assert_eq!(pending.custody_stats.transfer_leases, 0);
        assert_eq!(pending.custody_stats.peer_receipts, 0);
        assert_eq!(pending.custody_stats.retries, 1);

        let source =
            Store::open_for_mission(&source_file.0, services.authority).expect("pending reopen");
        assert_eq!(
            source.custody_policy_revision().expect("reopened revision"),
            current_revision
        );
        assert!(
            source
                .next_custody_outbound_bulk_from_transfers(
                    peer,
                    &[transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                            CustodyPeerSelectorRevision::new(3),
                        ),
                    ),
                    1,
                    Some(sample),
                    current_revision,
                )
                .expect("retry is not immediately due")
                .is_empty()
        );
        let first_due = aster_mesh::CustodySample {
            clock_id: sample.clock_id,
            tick_ms: sample.tick_ms
                + aster_mesh::retry_delay_ms(Priority::Routine, 0, link_floor_ms),
        };
        assert_eq!(
            source
                .next_custody_outbound_bulk_from_transfers(
                    peer,
                    &[transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                            CustodyPeerSelectorRevision::new(3),
                        ),
                    ),
                    1,
                    Some(first_due),
                    current_revision,
                )
                .expect("first retry boundary")[0]
                .object,
            object
        );
        let second = source
            .begin_custody_send(
                peer,
                object,
                CustodyPeerSelectorRevision::new(3),
                Some(first_due),
                link_floor_ms,
                current_revision,
            )
            .expect("second promotion-attempt lease");
        source
            .require_custody_send(&second, Some(first_due), current_revision)
            .expect("second promotion-attempt authorization");
        source
            .settle_peer_custody_apply(
                &second,
                CustodyPeerApplyEvidence::new(
                    CustodyPeerApplyDisposition::ContentAcceptancePending,
                    CustodyPeerSelectorRevision::new(3),
                ),
                0,
                Some(first_due),
                current_revision,
            )
            .expect("second pending settlement");
        drop(source);

        let source = Store::open_for_mission(&source_file.0, services.authority)
            .expect("second pending reopen");
        let second_delay = aster_mesh::retry_delay_ms(Priority::Routine, 1, link_floor_ms);
        let before_second_due = aster_mesh::CustodySample {
            clock_id: sample.clock_id,
            tick_ms: first_due.tick_ms + second_delay - 1,
        };
        assert!(
            source
                .next_custody_outbound_bulk_from_transfers(
                    peer,
                    &[transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                            CustodyPeerSelectorRevision::new(3),
                        ),
                    ),
                    1,
                    Some(before_second_due),
                    current_revision,
                )
                .expect("second retry remains before deadline")
                .is_empty()
        );
        let second_due = aster_mesh::CustodySample {
            clock_id: sample.clock_id,
            tick_ms: first_due.tick_ms + second_delay,
        };
        assert_eq!(
            source
                .next_custody_outbound_bulk_from_transfers(
                    peer,
                    &[transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                            CustodyPeerSelectorRevision::new(3),
                        ),
                    ),
                    1,
                    Some(second_due),
                    current_revision,
                )
                .expect("second retry deadline")[0]
                .object,
            object
        );

        // Peer-present evidence never races an active send. Once that lease is
        // released, the same authenticated common set drains the retry and
        // installs one receipt for future blind suppression.
        let active = source
            .begin_custody_send(
                peer,
                object,
                CustodyPeerSelectorRevision::new(3),
                Some(second_due),
                link_floor_ms,
                current_revision,
            )
            .expect("active concurrent lease");
        assert_eq!(
            source
                .settle_authenticated_peer_inventory(
                    peer,
                    &[transfer_id],
                    &[],
                    CustodyPeerSelectorRevision::new(3),
                    current_revision,
                )
                .expect("active lease is excluded"),
            0
        );
        source
            .require_custody_send(&active, Some(second_due), current_revision)
            .expect("common settlement did not revoke active send");
        source
            .release_transfer_lease(active.id)
            .expect("release concurrent lease");
        assert_eq!(
            source
                .settle_authenticated_peer_inventory(
                    peer,
                    &[transfer_id],
                    &[],
                    CustodyPeerSelectorRevision::new(3),
                    current_revision,
                )
                .expect("settle authenticated peer-present retry"),
            1
        );
        assert!(
            source
                .next_custody_outbound_bulk_from_transfers(
                    peer,
                    &[transfer_id],
                    CustodyReconciliationSelection::new(
                        Priority::Routine,
                        CustodyReconciliationEvidence::Blind(CustodyPeerSelectorRevision::new(3)),
                    ),
                    1,
                    Some(second_due),
                    current_revision,
                )
                .expect("peer-present receipt suppresses blind scheduling")
                .is_empty()
        );
        drop(source);
        drop(receiver);
        let settled = Store::inspect_existing(&source_file.0).expect("inspect settled retry");
        assert_eq!(settled.custody_stats.transfer_leases, 0);
        assert_eq!(settled.custody_stats.retries, 0);
        assert_eq!(settled.custody_stats.peer_receipts, 1);
        Store::open_for_mission(&source_file.0, services.authority).expect("final source reopen");
        Store::open_for_mission(&receiver_file.0, services.authority)
            .expect("final receiver reopen");
    }

    #[test]
    fn equal_priority_retry_cap_preserves_multi_peer_progress() {
        let file = TestFile::new("peer-present retry cap");
        let mut services = event_services(0xe3);
        let store = Store::open_for_mission(&file.0, services.authority).expect("store");
        let peer_a = services.reader.identity();
        let peer_b = services.relay.identity();
        let sample = aster_mesh::CustodySample {
            clock_id: [0x84; 16],
            tick_ms: 1_000_000,
        };
        let revision = store.custody_policy_revision().expect("revision");
        let mut retry_ids = Vec::new();
        for index in 0..MAX_CUSTODY_RETRY_RECORDS {
            let counter = index + 1;
            let logical_key = counter.to_be_bytes();
            let mut header = event_header(
                services.publisher.identity(),
                counter,
                counter,
                VersionVector::default(),
                &logical_key,
                &logical_key,
                None,
            );
            header.priority = Priority::Routine;
            let stored = accept_event(&store, &mut services, header, &logical_key);
            let lease = store
                .begin_custody_send(
                    peer_a,
                    CustodyObjectKey::event(stored.transfer_id),
                    CustodyPeerSelectorRevision::new(4),
                    Some(sample),
                    1,
                    revision,
                )
                .expect("fill retry row");
            store
                .release_transfer_lease(lease.id)
                .expect("retain retry row");
            retry_ids.push(stored.transfer_id);
        }

        let next_counter = MAX_CUSTODY_RETRY_RECORDS + 1;
        let next_key = next_counter.to_be_bytes();
        let mut next_header = event_header(
            services.publisher.identity(),
            next_counter,
            next_counter,
            VersionVector::default(),
            &next_key,
            &next_key,
            None,
        );
        next_header.priority = Priority::Routine;
        let next = accept_event(&store, &mut services, next_header, &next_key);
        let peer_b_lease = store
            .begin_custody_send(
                peer_b,
                CustodyObjectKey::event(next.transfer_id),
                CustodyPeerSelectorRevision::new(4),
                Some(sample),
                1,
                revision,
            )
            .expect("another peer replaces one inactive equal-priority retry hint");
        store
            .require_custody_send(&peer_b_lease, Some(sample), revision)
            .expect("peer B send authorization");
        store
            .settle_peer_custody_apply(
                &peer_b_lease,
                CustodyPeerApplyEvidence::new(
                    CustodyPeerApplyDisposition::ContentAcceptancePending,
                    CustodyPeerSelectorRevision::new(4),
                ),
                0,
                Some(sample),
                revision,
            )
            .expect("peer B pending settlement remains durable");
        drop(store);

        let full = Store::inspect_existing(&file.0).expect("inspect full multi-peer retry set");
        assert_eq!(full.custody_stats.retries, MAX_CUSTODY_RETRY_RECORDS);
        assert_eq!(full.custody_stats.peer_receipts, 0);
        let store = Store::open_for_mission(&file.0, services.authority)
            .expect("reopen full multi-peer retry set");

        retry_ids.sort_unstable();
        let evicted = store
            .next_custody_outbound_bulk_from_transfers(
                peer_a,
                &retry_ids,
                CustodyReconciliationSelection::new(
                    Priority::Routine,
                    CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                        CustodyPeerSelectorRevision::new(4),
                    ),
                ),
                1,
                Some(sample),
                revision,
            )
            .expect("evicted peer A hint leaves custody work eligible");
        assert_eq!(evicted.len(), 1);
        assert!(retry_ids.contains(&EventTransferId::new(evicted[0].object.transfer_id())));
        let peer_a_replacement = store
            .begin_custody_send(
                peer_a,
                evicted[0].object,
                CustodyPeerSelectorRevision::new(4),
                Some(sample),
                1,
                revision,
            )
            .expect("peer A work remains eligible at the full cap");
        store
            .release_transfer_lease(peer_a_replacement.id)
            .expect("retain peer A replacement retry");
        assert_eq!(
            store
                .settle_authenticated_peer_inventory(
                    peer_b,
                    &[next.transfer_id],
                    &[],
                    CustodyPeerSelectorRevision::new(4),
                    revision,
                )
                .expect("settle peer B authenticated common set"),
            1
        );
        drop(store);

        let inspection = Store::inspect_existing(&file.0).expect("inspect cap settlement");
        assert_eq!(inspection.custody_stats.peer_receipts, 1);
        assert_eq!(
            inspection.custody_stats.retries,
            MAX_CUSTODY_RETRY_RECORDS - 1
        );
        Store::open_for_mission(&file.0, services.authority).expect("reopen cap settlement");
    }

    #[test]
    fn authenticated_missing_invalidates_only_the_selected_receipt() {
        let file = TestFile::new("selected receipt invalidation");
        let mut services = event_services(0xe4);
        let store = Store::open_for_mission(&file.0, services.authority).expect("store");
        let peer = services.reader.identity();
        let sample = aster_mesh::CustodySample {
            clock_id: [0x85; 16],
            tick_ms: 50_000,
        };
        let revision = store.custody_policy_revision().expect("revision");
        let mut routine_header = event_header(
            services.publisher.identity(),
            1,
            1,
            VersionVector::default(),
            b"selected/routine",
            b"routine",
            None,
        );
        routine_header.priority = Priority::Routine;
        let routine = accept_event(&store, &mut services, routine_header, b"routine");
        let mut flash_header = event_header(
            services.publisher.identity(),
            2,
            2,
            VersionVector::default(),
            b"selected/flash",
            b"flash",
            None,
        );
        flash_header.priority = Priority::Flash;
        let flash = accept_event(&store, &mut services, flash_header, b"flash");
        for transfer_id in [routine.transfer_id, flash.transfer_id] {
            let lease = store
                .begin_custody_send(
                    peer,
                    CustodyObjectKey::event(transfer_id),
                    CustodyPeerSelectorRevision::new(5),
                    Some(sample),
                    1,
                    revision,
                )
                .expect("receipt lease");
            store
                .record_peer_custody_receipt(
                    &lease,
                    0,
                    Some(sample),
                    CustodyPeerSelectorRevision::new(5),
                    revision,
                )
                .expect("record receipt");
        }
        let mut difference = [routine.transfer_id, flash.transfer_id];
        difference.sort_unstable();
        let selected = store
            .next_custody_outbound_bulk_from_transfers(
                peer,
                &difference,
                CustodyReconciliationSelection::new(
                    Priority::Routine,
                    CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                        CustodyPeerSelectorRevision::new(5),
                    ),
                ),
                1,
                Some(sample),
                revision,
            )
            .expect("select one authenticated reoffer");
        assert_eq!(selected.len(), 1);
        assert_eq!(
            selected[0].object,
            CustodyObjectKey::event(flash.transfer_id)
        );
        let flash_lease = store
            .begin_custody_send(
                peer,
                CustodyObjectKey::event(flash.transfer_id),
                CustodyPeerSelectorRevision::new(5),
                Some(sample),
                1,
                revision,
            )
            .expect("selected receipt was invalidated");
        store
            .release_transfer_lease(flash_lease.id)
            .expect("release selected lease");
        assert!(matches!(
            store.begin_custody_send(
                peer,
                CustodyObjectKey::event(routine.transfer_id),
                CustodyPeerSelectorRevision::new(5),
                Some(sample),
                1,
                revision,
            ),
            Err(StoreError::Custody(CustodyStoreError::ItemChanged))
        ));
        drop(store);
        let inspection = Store::inspect_existing(&file.0).expect("inspect selected invalidation");
        assert_eq!(inspection.custody_stats.peer_receipts, 1);
        assert_eq!(inspection.custody_stats.retries, 1);
        Store::open_for_mission(&file.0, services.authority).expect("reopen selected invalidation");
    }

    #[test]
    fn bulk_outbound_scans_one_custody_snapshot_for_maximal_sparse_difference() {
        let file = TestFile::new("bulk custody outbound");
        let mut services = event_services(0xdb);
        let store = Store::open_for_mission(&file.0, services.authority).expect("store");
        let publisher = services.publisher.identity();
        let mut routine_header = event_header(
            publisher,
            1,
            1,
            VersionVector::default(),
            b"bulk/routine",
            b"routine",
            None,
        );
        routine_header.priority = Priority::Routine;
        let stored = accept_event(&store, &mut services, routine_header, b"routine");
        let mut flash_header = event_header(
            publisher,
            2,
            2,
            VersionVector::default(),
            b"bulk/flash",
            b"flash",
            None,
        );
        flash_header.priority = Priority::Flash;
        let flash = accept_event(&store, &mut services, flash_header, b"flash");
        let immediate = accept_event(
            &store,
            &mut services,
            event_header(
                publisher,
                3,
                3,
                VersionVector::default(),
                b"bulk/immediate",
                b"immediate",
                None,
            ),
            b"immediate",
        );
        let mut difference = Vec::with_capacity(MAX_CUSTODY_BULK_CANDIDATES);
        for index in 0..(MAX_CUSTODY_BULK_CANDIDATES - 3) {
            let mut digest = [0u8; 32];
            digest[..8].copy_from_slice(
                &u64::try_from(index)
                    .expect("bounded bulk index")
                    .to_be_bytes(),
            );
            difference.push(EventTransferId::new(digest));
        }
        for transfer_id in [stored.transfer_id, flash.transfer_id, immediate.transfer_id] {
            if let Err(index) = difference.binary_search(&transfer_id) {
                difference.insert(index, transfer_id);
            }
        }
        assert!(difference.len() <= MAX_CUSTODY_BULK_CANDIDATES);
        let selected = store
            .next_custody_outbound_bulk_from_transfers(
                services.relay.identity(),
                &difference,
                CustodyReconciliationSelection::new(
                    Priority::Routine,
                    CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                        CustodyPeerSelectorRevision::new(1),
                    ),
                ),
                2,
                None,
                store.custody_policy_revision().expect("policy revision"),
            )
            .expect("one-snapshot sparse selection");
        assert_eq!(selected.len(), 2);
        assert_eq!(
            selected[0].object,
            CustodyObjectKey::event(flash.transfer_id)
        );
        assert_eq!(selected[0].priority, Priority::Flash);
        assert_eq!(
            selected[1].object,
            CustodyObjectKey::event(immediate.transfer_id)
        );
        assert_eq!(selected[1].priority, Priority::Immediate);
        assert_eq!(custody::bulk_custody_lookup_visits(1, 262_144), 2);
        assert_eq!(
            custody::bulk_custody_lookup_visits(MAX_CUSTODY_BULK_CANDIDATES, 3),
            3
        );
        let revision = store
            .custody_policy_revision()
            .expect("direct lookup revision");
        let direct = store
            .next_custody_outbound_bulk_from_transfers(
                services.relay.identity(),
                &[stored.transfer_id],
                CustodyReconciliationSelection::new(
                    Priority::Routine,
                    CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                        CustodyPeerSelectorRevision::new(1),
                    ),
                ),
                1,
                None,
                revision,
            )
            .expect("small exact set uses direct lookup");
        assert_eq!(direct.len(), 1);
        assert_eq!(
            direct[0].object,
            CustodyObjectKey::event(stored.transfer_id)
        );
        assert!(matches!(
            store
                .load_scheduled_custody_transfer(
                    direct[0].object,
                    None,
                    revision,
                )
                .expect("atomic scheduled transfer"),
            Some(StoredEventTransfer::Accepted(event)) if event.transfer_id == stored.transfer_id
        ));
        let control_policy = store.control_policy_snapshot().expect("control policy");
        let projections = store
            .sender_transfer_inventory_with_policy(&control_policy, None, revision)
            .expect("one-snapshot sender projection");
        assert_eq!(projections.len(), 3);
        let routine_projection = projections
            .iter()
            .find(|projection| projection.object() == CustodyObjectKey::event(stored.transfer_id))
            .expect("Routine projection");
        assert_eq!(
            routine_projection.semantic_id(),
            *stored.semantic_id.as_bytes()
        );
        assert_eq!(routine_projection.source_publisher(), publisher);
        assert_eq!(routine_projection.priority(), Priority::Routine);
        assert_eq!(routine_projection.ttl_ms(), None);
        assert!(!routine_projection.tombstone());
        assert_eq!(
            routine_projection.accounted_bytes(),
            u64::try_from(stored.sealed.len()).expect("bounded Event bytes")
        );
        assert_eq!(routine_projection.status(), CustodyAgeStatus::Durable);
        let mut visited_ids = Vec::new();
        let visited = store
            .visit_sender_transfer_sources_with_policy(
                &control_policy,
                None,
                revision,
                |transfer| {
                    visited_ids.push(match transfer {
                        StoredEventTransfer::Accepted(event) => event.transfer_id,
                        StoredEventTransfer::RouteCached(event) => event.transfer_id,
                    });
                    Ok::<(), StoreError>(())
                },
            )
            .expect("bounded sender source visitor");
        assert_eq!(visited, 3);
        assert_eq!(visited_ids.len(), 3);
        assert!(visited_ids.contains(&stored.transfer_id));
        let read = store.database.begin_read().expect("bounded snapshot read");
        assert!(matches!(
            sender_transfer_inventory_read(
                &read,
                None,
                StoreLimits::new(1, u64::MAX).expect("item preflight limits"),
            ),
            Err(StoreError::ItemLimitExceeded {
                current: 3,
                limit: 1,
            })
        ));
        assert!(matches!(
            sender_transfer_inventory_read(
                &read,
                None,
                StoreLimits::new(10, 1).expect("byte preflight limits"),
            ),
            Err(StoreError::PayloadByteLimitExceeded { limit: 1, .. })
        ));
        drop(read);
        let mut early_visits = 0usize;
        assert!(matches!(
            store.visit_sender_transfer_sources_with_policy(
                &control_policy,
                None,
                revision,
                |_| {
                    early_visits += 1;
                    Err(StoreError::SemanticVerification(
                        "intentional visitor stop".to_owned(),
                    ))
                },
            ),
            Err(StoreError::SemanticVerification(message))
                if message == "intentional visitor stop"
        ));
        assert_eq!(early_visits, 1);

        let revision = store
            .custody_policy_revision()
            .expect("validation revision");
        let duplicate = [stored.transfer_id, stored.transfer_id];
        assert!(matches!(
            store.next_custody_outbound_bulk_from_transfers(
                services.relay.identity(),
                &duplicate,
                CustodyReconciliationSelection::new(
                    Priority::Routine,
                    CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                        CustodyPeerSelectorRevision::new(1),
                    ),
                ),
                1,
                None,
                revision,
            ),
            Err(StoreError::Custody(CustodyStoreError::InvalidAdmission(
                "bulk Event transfer candidates must be strictly sorted and unique"
            )))
        ));
        let mut unsorted = [stored.transfer_id, flash.transfer_id];
        unsorted.sort();
        unsorted.reverse();
        assert!(matches!(
            store.next_custody_outbound_bulk_from_transfers(
                services.relay.identity(),
                &unsorted,
                CustodyReconciliationSelection::new(
                    Priority::Routine,
                    CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                        CustodyPeerSelectorRevision::new(1),
                    ),
                ),
                1,
                None,
                revision,
            ),
            Err(StoreError::Custody(CustodyStoreError::InvalidAdmission(_)))
        ));
        drop(difference);
        let over_cap = vec![EventTransferId::new([0; 32]); MAX_CUSTODY_BULK_CANDIDATES + 1];
        assert!(matches!(
            store.next_custody_outbound_bulk_from_transfers(
                services.relay.identity(),
                &over_cap,
                CustodyReconciliationSelection::new(
                    Priority::Routine,
                    CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                        CustodyPeerSelectorRevision::new(1),
                    ),
                ),
                1,
                None,
                revision,
            ),
            Err(StoreError::Custody(CustodyStoreError::PageLimitExceeded {
                requested,
                maximum: MAX_CUSTODY_BULK_CANDIDATES,
            })) if requested == MAX_CUSTODY_BULK_CANDIDATES + 1
        ));

        let event_key = CustodyObjectKey::event(stored.transfer_id);
        let mut encoded_event_key = [0u8; 33];
        encoded_event_key[0] = CustodyObjectClass::Event as u8;
        encoded_event_key[1..].copy_from_slice(stored.transfer_id.as_bytes());
        let mut encoded_route_key = encoded_event_key;
        encoded_route_key[0] = CustodyObjectClass::RouteEvent as u8;
        let write = store.database.begin_write().expect("dual custody write");
        let encoded_item = write
            .open_table(custody::CUSTODY_ITEMS)
            .expect("custody items")
            .get(encoded_event_key.as_slice())
            .expect("read custody item")
            .expect("accepted custody item")
            .value()
            .to_vec();
        write
            .open_table(custody::CUSTODY_ITEMS)
            .expect("custody items")
            .insert(encoded_route_key.as_slice(), encoded_item.as_slice())
            .expect("insert dual route row");
        write.commit().expect("commit dual custody row");
        assert!(matches!(
            store.next_custody_outbound_bulk_from_transfers(
                services.relay.identity(),
                &[stored.transfer_id],
                CustodyReconciliationSelection::new(
                    Priority::Routine,
                    CustodyReconciliationEvidence::AuthenticatedPeerMissing(
                        CustodyPeerSelectorRevision::new(1),
                    ),
                ),
                1,
                None,
                revision,
            ),
            Err(StoreError::SemanticInvariant(
                "one Event transfer appears in multiple live or retired custody states"
            ))
        ));
        assert!(matches!(
            store.sender_transfer_inventory_with_policy(&control_policy, None, revision),
            Err(StoreError::SemanticInvariant(
                "one Event transfer has custody state in both accepted and route namespaces"
            ))
        ));
        let write = store.database.begin_write().expect("dual custody cleanup");
        write
            .open_table(custody::CUSTODY_ITEMS)
            .expect("custody items")
            .remove(encoded_route_key.as_slice())
            .expect("remove dual route row");
        write.commit().expect("commit dual custody cleanup");

        let write = store
            .database
            .begin_write()
            .expect("dual representation write");
        let encoded_metadata = write
            .open_table(EVENTS)
            .expect("Event metadata")
            .get(stored.transfer_id.as_bytes().as_slice())
            .expect("read Event metadata")
            .expect("stored Event metadata")
            .value()
            .to_vec();
        write
            .open_table(ROUTE_CACHE)
            .expect("route bytes")
            .insert(
                stored.transfer_id.as_bytes().as_slice(),
                stored.sealed.as_slice(),
            )
            .expect("insert duplicate route bytes");
        write
            .open_table(ROUTE_CACHE_CLAIMS)
            .expect("route claims")
            .insert(
                stored.transfer_id.as_bytes().as_slice(),
                encoded_metadata.as_slice(),
            )
            .expect("insert duplicate route claim");
        write.commit().expect("commit dual representation");
        assert!(matches!(
            store.load_scheduled_custody_transfer(event_key, None, revision),
            Err(StoreError::SemanticInvariant(
                "one Event transfer has accepted and route exact representations"
            ))
        ));
        assert!(matches!(
            store.sender_transfer_inventory_with_policy(&control_policy, None, revision),
            Err(StoreError::SemanticInvariant(
                "one Event transfer has accepted and route exact representations"
            ))
        ));
        let write = store
            .database
            .begin_write()
            .expect("source corruption write");
        write
            .open_table(ROUTE_CACHE)
            .expect("route bytes")
            .remove(stored.transfer_id.as_bytes().as_slice())
            .expect("remove duplicate route bytes");
        write
            .open_table(ROUTE_CACHE_CLAIMS)
            .expect("route claims")
            .remove(stored.transfer_id.as_bytes().as_slice())
            .expect("remove duplicate route claim");
        write
            .open_table(EVENT_BYTES)
            .expect("Event bytes")
            .remove(stored.transfer_id.as_bytes().as_slice())
            .expect("remove live Event bytes");
        write.commit().expect("commit source corruption");
        assert!(matches!(
            store.load_scheduled_custody_transfer(event_key, None, revision),
            Err(StoreError::SemanticInvariant(
                "Event metadata is missing exact source bytes"
            )) | Err(StoreError::SemanticInvariant(
                "live accepted custody row is missing its exact Event representation"
            )) | Err(StoreError::SemanticInvariant(
                "sendable custody row is missing its exact Event transfer representation"
            ))
        ));
        assert!(matches!(
            store.sender_transfer_inventory_with_policy(&control_policy, None, revision),
            Err(StoreError::SemanticInvariant(
                "sender Event metadata, bytes, and acceptance marker are not atomically paired"
            ))
        ));
    }

    #[test]
    fn sender_projection_rejects_priority_ttl_length_and_class_tamper() {
        let file = TestFile::new("sender projection field tamper");
        let mut services = event_services(0xdc);
        let store = Store::open_for_mission(&file.0, services.authority).expect("store");
        let publisher = services.publisher.identity();
        let mut header = event_header(
            publisher,
            1,
            1,
            VersionVector::default(),
            b"projection/tamper",
            b"value",
            None,
        );
        header.priority = Priority::Routine;
        let stored = accept_event(&store, &mut services, header, b"value");
        let policy = store.control_policy_snapshot().expect("control policy");
        let revision = store.custody_policy_revision().expect("custody policy");
        let original_metadata = store
            .database
            .begin_read()
            .expect("metadata read")
            .open_table(EVENTS)
            .expect("Event metadata")
            .get(stored.transfer_id.as_bytes().as_slice())
            .expect("metadata lookup")
            .expect("stored metadata")
            .value()
            .to_vec();

        for tamper in ["priority", "ttl"] {
            let mut metadata = decode_event_metadata(&original_metadata).expect("decode metadata");
            match tamper {
                "priority" => metadata.header.priority = Priority::Flash,
                "ttl" => metadata.header.ttl_ms = Some(10),
                _ => unreachable!("fixed tamper table"),
            }
            let encoded =
                encode_event_metadata(metadata.transfer_id, metadata.semantic_id, &metadata.header)
                    .expect("encode tampered metadata");
            let write = store.database.begin_write().expect("metadata tamper write");
            write
                .open_table(EVENTS)
                .expect("Event metadata")
                .insert(stored.transfer_id.as_bytes().as_slice(), encoded.as_slice())
                .expect("tamper Event metadata");
            write.commit().expect("commit metadata tamper");
            assert!(matches!(
                store.sender_transfer_inventory_with_policy(&policy, None, revision),
                Err(StoreError::SemanticInvariant(
                    "sender custody projection differs from authenticated Event metadata or exact length"
                ))
            ));
            let write = store
                .database
                .begin_write()
                .expect("metadata restore write");
            write
                .open_table(EVENTS)
                .expect("Event metadata")
                .insert(
                    stored.transfer_id.as_bytes().as_slice(),
                    original_metadata.as_slice(),
                )
                .expect("restore Event metadata");
            write.commit().expect("commit metadata restore");
        }

        let mut longer_source = stored.sealed.clone();
        longer_source.push(0);
        let write = store.database.begin_write().expect("length tamper write");
        write
            .open_table(EVENT_BYTES)
            .expect("Event bytes")
            .insert(
                stored.transfer_id.as_bytes().as_slice(),
                longer_source.as_slice(),
            )
            .expect("tamper source length");
        write.commit().expect("commit length tamper");
        assert!(matches!(
            store.sender_transfer_inventory_with_policy(&policy, None, revision),
            Err(StoreError::SemanticInvariant(
                "sender custody projection differs from authenticated Event metadata or exact length"
            ))
        ));
        let write = store.database.begin_write().expect("length restore write");
        write
            .open_table(EVENT_BYTES)
            .expect("Event bytes")
            .insert(
                stored.transfer_id.as_bytes().as_slice(),
                stored.sealed.as_slice(),
            )
            .expect("restore source bytes");
        write.commit().expect("commit length restore");

        let revocation =
            encode_revocation_index(services.authority, 1, ControlTransferId::new([0xa1; 32]));
        let write = store
            .database
            .begin_write()
            .expect("revocation filter write");
        write
            .open_table(CONTROL_REVOCATIONS)
            .expect("revocations")
            .insert(publisher.as_slice(), revocation.as_slice())
            .expect("insert publisher revocation");
        write.commit().expect("commit publisher revocation");
        assert!(
            store
                .sender_transfer_inventory_with_policy(&policy, None, revision)
                .expect("revoked projection filter")
                .is_empty()
        );
        let write = store
            .database
            .begin_write()
            .expect("revocation cleanup write");
        write
            .open_table(CONTROL_REVOCATIONS)
            .expect("revocations")
            .remove(publisher.as_slice())
            .expect("remove publisher revocation");
        write.commit().expect("commit revocation cleanup");

        let future_epoch = encode_scope_epoch_index(2, ControlTransferId::new([0xa2; 32]));
        let write = store.database.begin_write().expect("epoch filter write");
        write
            .open_table(CONTROL_SCOPE_EPOCHS)
            .expect("scope epochs")
            .insert(event_scope().as_str(), future_epoch.as_slice())
            .expect("insert future active epoch");
        write.commit().expect("commit future epoch");
        assert!(
            store
                .sender_transfer_inventory_with_policy(&policy, None, revision)
                .expect("inactive epoch projection filter")
                .is_empty()
        );
        let write = store.database.begin_write().expect("epoch cleanup write");
        write
            .open_table(CONTROL_SCOPE_EPOCHS)
            .expect("scope epochs")
            .remove(event_scope().as_str())
            .expect("remove future active epoch");
        write.commit().expect("commit epoch cleanup");

        let mut event_key = [0u8; 33];
        event_key[0] = CustodyObjectClass::Event as u8;
        event_key[1..].copy_from_slice(stored.transfer_id.as_bytes());
        let mut route_key = event_key;
        route_key[0] = CustodyObjectClass::RouteEvent as u8;
        let write = store.database.begin_write().expect("class tamper write");
        let encoded_item = write
            .open_table(custody::CUSTODY_ITEMS)
            .expect("custody items")
            .remove(event_key.as_slice())
            .expect("remove Event custody")
            .expect("Event custody row")
            .value()
            .to_vec();
        write
            .open_table(custody::CUSTODY_ITEMS)
            .expect("custody items")
            .insert(route_key.as_slice(), encoded_item.as_slice())
            .expect("move custody to route class");
        write.commit().expect("commit class tamper");
        assert!(matches!(
            store.sender_transfer_inventory_with_policy(&policy, None, revision),
            Err(StoreError::SemanticInvariant(
                "live route custody row is missing its exact Event representation"
            ))
        ));
    }

    #[test]
    fn retained_source_authentication_precedes_expiry_maintenance() {
        let file = TestFile::new("retained source authentication before maintenance");
        let mut services = event_services(0xde);
        let store = Store::open_for_mission(&file.0, services.authority).expect("store");
        let publisher = services.publisher.identity();
        let mut header = event_header(
            publisher,
            1,
            1,
            VersionVector::default(),
            b"retained/source-auth",
            b"value",
            None,
        );
        header.priority = Priority::Routine;
        let stored = accept_event(&store, &mut services, header, b"value");
        let key = CustodyObjectKey::event(stored.transfer_id);
        let mut encoded_key = [0u8; 33];
        encoded_key[0] = CustodyObjectClass::Event as u8;
        encoded_key[1..].copy_from_slice(stored.transfer_id.as_bytes());

        // Corrupt both structural projections coherently: ordinary reopen
        // auditing cannot authenticate these claims against the sealed source.
        // The forged zero TTL would otherwise make maintenance immediately
        // retire the exact bytes and mint a permanent receiver fence.
        let write = store.database.begin_write().expect("coherent tamper write");
        let encoded_metadata = write
            .open_table(EVENTS)
            .expect("Event metadata")
            .get(stored.transfer_id.as_bytes().as_slice())
            .expect("metadata lookup")
            .expect("stored metadata")
            .value()
            .to_vec();
        let mut metadata = decode_event_metadata(&encoded_metadata).expect("decode metadata");
        metadata.header.priority = Priority::Flash;
        metadata.header.ttl_ms = Some(0);
        let tampered_metadata =
            encode_event_metadata(metadata.transfer_id, metadata.semantic_id, &metadata.header)
                .expect("encode coherent metadata tamper");
        let encoded_item = write
            .open_table(custody::CUSTODY_ITEMS)
            .expect("custody items")
            .get(encoded_key.as_slice())
            .expect("custody lookup")
            .expect("custody item")
            .value()
            .to_vec();
        let tampered_item =
            custody::reencode_item_source_claims_for_test(&encoded_item, Priority::Flash, Some(0))
                .expect("encode coherent custody tamper");
        write
            .open_table(EVENTS)
            .expect("Event metadata")
            .insert(
                stored.transfer_id.as_bytes().as_slice(),
                tampered_metadata.as_slice(),
            )
            .expect("tamper Event metadata");
        write
            .open_table(custody::CUSTODY_ITEMS)
            .expect("custody items")
            .insert(encoded_key.as_slice(), tampered_item.as_slice())
            .expect("tamper custody metadata");
        write.commit().expect("commit coherent metadata tamper");
        drop(store);

        // Structural inspection and writable reopen remain possible: fresh
        // source authentication, deliberately outside redb's trust boundary,
        // is the gate that must run before any mutation.
        Store::inspect_existing(&file.0).expect("structurally coherent inspection");
        let reopened = Store::open_for_mission(&file.0, services.authority)
            .expect("structurally coherent reopen");
        let policy = reopened.control_policy_snapshot().expect("control policy");
        let revision = reopened.custody_policy_revision().expect("custody policy");
        assert!(
            reopened
                .sender_transfer_inventory_with_policy(&policy, None, revision)
                .expect("expired sender projection")
                .is_empty()
        );
        assert_eq!(
            reopened
                .custody_age_status(key, None)
                .expect("expired custody status"),
            Some(CustodyAgeStatus::Expired { age_ms: 0 })
        );
        let before = {
            let read = reopened.database.begin_read().expect("pre-visitor read");
            let item = read
                .open_table(custody::CUSTODY_ITEMS)
                .expect("custody items")
                .get(encoded_key.as_slice())
                .expect("custody lookup")
                .expect("retained custody row")
                .value()
                .to_vec();
            let exact = read
                .open_table(EVENT_BYTES)
                .expect("Event bytes")
                .get(stored.transfer_id.as_bytes().as_slice())
                .expect("exact source lookup")
                .expect("retained exact source")
                .value()
                .to_vec();
            let metadata = read
                .open_table(EVENTS)
                .expect("Event metadata")
                .get(stored.transfer_id.as_bytes().as_slice())
                .expect("Event metadata lookup")
                .expect("retained Event metadata")
                .value()
                .to_vec();
            let marker = read
                .open_table(EVENT_ACCEPTANCE_MARKERS)
                .expect("Event markers")
                .get(stored.transfer_id.as_bytes().as_slice())
                .expect("Event marker lookup")
                .expect("retained Event marker")
                .value();
            let route_rows = (
                read.open_table(ROUTE_CACHE)
                    .expect("route bytes")
                    .len()
                    .expect("route byte rows"),
                read.open_table(ROUTE_CACHE_CLAIMS)
                    .expect("route claims")
                    .len()
                    .expect("route claim rows"),
            );
            let retirement_rows = read
                .open_table(custody::CUSTODY_RETIREMENTS)
                .expect("retirements")
                .len()
                .expect("retirement rows");
            (item, exact, metadata, marker, route_rows, retirement_rows)
        };

        let mut visits = 0usize;
        assert!(matches!(
            reopened.visit_retained_custody_event_sources_with_policy(
                &policy,
                revision,
                |transfer| {
                    visits += 1;
                    let (transfer_id, semantic_id, persisted_header, sealed) = match transfer {
                        StoredEventTransfer::Accepted(event) => (
                            event.transfer_id,
                            event.semantic_id,
                            &event.header,
                            event.sealed.as_slice(),
                        ),
                        StoredEventTransfer::RouteCached(event) => (
                            event.transfer_id,
                            event.semantic_claim,
                            &event.header_claim,
                            event.sealed.as_slice(),
                        ),
                    };
                    let verified = services
                        .reader
                        .verify_event(sealed)
                        .map_err(|error| StoreError::SemanticVerification(error.to_string()))?;
                    if EventTransferId::new(verified.envelope_id()) != transfer_id
                        || EventSemanticId::new(verified.item_id()) != semantic_id
                        || verified.header() != persisted_header
                    {
                        return Err(StoreError::SemanticVerification(
                            "persisted Event claim differs from fresh source verification"
                                .to_owned(),
                        ));
                    }
                    Ok(())
                },
            ),
            Err(StoreError::SemanticVerification(message))
                if message == "persisted Event claim differs from fresh source verification"
        ));
        assert_eq!(visits, 1);

        let after = {
            let read = reopened.database.begin_read().expect("post-visitor read");
            assert!(
                read.open_table(custody::CUSTODY_RETIREMENTS)
                    .expect("retirements")
                    .get(encoded_key.as_slice())
                    .expect("retirement lookup")
                    .is_none()
            );
            let item = read
                .open_table(custody::CUSTODY_ITEMS)
                .expect("custody items")
                .get(encoded_key.as_slice())
                .expect("custody lookup")
                .expect("retained custody row")
                .value()
                .to_vec();
            let exact = read
                .open_table(EVENT_BYTES)
                .expect("Event bytes")
                .get(stored.transfer_id.as_bytes().as_slice())
                .expect("exact source lookup")
                .expect("retained exact source")
                .value()
                .to_vec();
            let metadata = read
                .open_table(EVENTS)
                .expect("Event metadata")
                .get(stored.transfer_id.as_bytes().as_slice())
                .expect("Event metadata lookup")
                .expect("retained Event metadata")
                .value()
                .to_vec();
            let marker = read
                .open_table(EVENT_ACCEPTANCE_MARKERS)
                .expect("Event markers")
                .get(stored.transfer_id.as_bytes().as_slice())
                .expect("Event marker lookup")
                .expect("retained Event marker")
                .value();
            let route_rows = (
                read.open_table(ROUTE_CACHE)
                    .expect("route bytes")
                    .len()
                    .expect("route byte rows"),
                read.open_table(ROUTE_CACHE_CLAIMS)
                    .expect("route claims")
                    .len()
                    .expect("route claim rows"),
            );
            let retirement_rows = read
                .open_table(custody::CUSTODY_RETIREMENTS)
                .expect("retirements")
                .len()
                .expect("retirement rows");
            (item, exact, metadata, marker, route_rows, retirement_rows)
        };
        assert_eq!(after, before);
        assert_eq!(
            reopened
                .custody_policy_revision()
                .expect("unchanged custody policy"),
            revision
        );
        drop(reopened);
        Store::inspect_existing(&file.0).expect("nonmutating visitor inspection");
    }

    #[test]
    fn event_route_class_is_unique_across_live_and_retired_custody_state() {
        let file = TestFile::new("custody Event class uniqueness");
        let mut services = event_services(0xdd);
        let store = Store::open_for_mission(&file.0, services.authority).expect("store");
        let publisher = services.publisher.identity();
        let live = accept_event(
            &store,
            &mut services,
            event_header(
                publisher,
                1,
                1,
                VersionVector::default(),
                b"class/live",
                b"live",
                None,
            ),
            b"live",
        );
        let clock_id = [0x77; 16];
        let retired = accept_local_finite_event(
            &store,
            &mut services,
            2,
            b"retired",
            1,
            aster_mesh::CustodySample {
                clock_id,
                tick_ms: 10,
            },
        );
        let retired_report = store
            .collect_custody_garbage(
                Some(aster_mesh::CustodySample {
                    clock_id,
                    tick_ms: 11,
                }),
                store.custody_policy_revision().expect("GC revision"),
                1,
            )
            .expect("retire finite Event");
        assert_eq!(
            retired_report.retired,
            vec![CustodyObjectKey::event(retired)]
        );
        let control = store.control_policy_snapshot().expect("control policy");
        store
            .create_event_subscription_with_policy(
                &control,
                &EventSubscriptionKey::new(b"class/fences".to_vec()).expect("selector key"),
                subscription_spec(EventSubscriptionMode::Carry),
            )
            .expect("create fence selector");
        let replication = store
            .event_replication_policy_snapshot()
            .expect("replication policy");

        let mut retired_event_key = [0u8; 33];
        retired_event_key[0] = CustodyObjectClass::Event as u8;
        retired_event_key[1..].copy_from_slice(retired.as_bytes());
        let mut retired_route_key = retired_event_key;
        retired_route_key[0] = CustodyObjectClass::RouteEvent as u8;
        let mut live_route_key = [0u8; 33];
        live_route_key[0] = CustodyObjectClass::RouteEvent as u8;
        live_route_key[1..].copy_from_slice(live.transfer_id.as_bytes());
        let encoded_retirement = store
            .database
            .begin_read()
            .expect("retirement read")
            .open_table(custody::CUSTODY_RETIREMENTS)
            .expect("retirements")
            .get(retired_event_key.as_slice())
            .expect("retirement lookup")
            .expect("retired Event fence")
            .value()
            .to_vec();

        let write = store
            .database
            .begin_write()
            .expect("opposite retirement write");
        write
            .open_table(custody::CUSTODY_RETIREMENTS)
            .expect("retirements")
            .insert(live_route_key.as_slice(), encoded_retirement.as_slice())
            .expect("insert opposite retirement");
        write.commit().expect("commit opposite retirement");
        assert!(matches!(
            store.sender_transfer_inventory_with_policy(
                &control,
                None,
                store
                    .custody_policy_revision()
                    .expect("projection revision"),
            ),
            Err(StoreError::SemanticInvariant(
                "one Event transfer has custody state in both accepted and route namespaces"
            ))
        ));
        assert!(matches!(
            store.event_receiver_fences_with_policy(&replication, None, MAX_CUSTODY_PAGE),
            Err(StoreError::SemanticInvariant(
                "one Event transfer has custody state in both accepted and route namespaces"
            ))
        ));
        drop(store);
        for result in [
            Store::inspect_existing(&file.0).map(|_| ()),
            Store::open_for_mission(&file.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::Custody(CustodyStoreError::Invariant(
                    "one Event transfer appears in multiple live or retired custody states"
                )))
            ));
        }

        let database = Database::open(&file.0).expect("raw cleanup open");
        let write = database.begin_write().expect("raw cleanup write");
        write
            .open_table(custody::CUSTODY_RETIREMENTS)
            .expect("retirements")
            .remove(live_route_key.as_slice())
            .expect("remove opposite retirement");
        write.commit().expect("commit raw cleanup");
        drop(database);
        let store = Store::open_for_mission(&file.0, services.authority).expect("clean reopen");
        let replication = store
            .event_replication_policy_snapshot()
            .expect("reopened replication policy");
        let write = store.database.begin_write().expect("dual retirement write");
        write
            .open_table(custody::CUSTODY_RETIREMENTS)
            .expect("retirements")
            .insert(retired_route_key.as_slice(), encoded_retirement.as_slice())
            .expect("insert opposite retired class");
        write.commit().expect("commit dual retirement");
        assert!(matches!(
            store.event_receiver_fences_with_policy(&replication, None, MAX_CUSTODY_PAGE),
            Err(StoreError::SemanticInvariant(
                "one Event transfer has custody state in both accepted and route namespaces"
            ))
        ));
        drop(store);
        for result in [
            Store::inspect_existing(&file.0).map(|_| ()),
            Store::open_for_mission(&file.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::Custody(CustodyStoreError::Invariant(
                    "one Event transfer appears in multiple live or retired custody states"
                )))
            ));
        }
    }

    #[test]
    fn event_operation_witness_wrong_kind_fails_read_and_write_audits() {
        let file = TestFile::new("Event witness wrong kind");
        let services = event_services(0xd6);
        let store = Store::open_for_mission(&file.0, services.authority).expect("base store");
        drop(store);
        let database = Database::open(&file.0).expect("raw database");
        let write = database.begin_write().expect("raw write");
        write
            .delete_table(EVENT_OPERATION_WITNESSES)
            .expect("delete normal witness table");
        let wrong =
            redb::MultimapTableDefinition::<&[u8], &[u8]>::new(EVENT_OPERATION_WITNESSES.name());
        write
            .open_multimap_table(wrong)
            .expect("wrong-kind witness table")
            .insert(b"transfer".as_slice(), b"digest".as_slice())
            .expect("wrong-kind row");
        write.commit().expect("commit wrong kind");
        drop(database);
        for result in [
            Store::inspect_existing(&file.0).map(|_| ()),
            Store::open_for_mission(&file.0, services.authority).map(|_| ()),
        ] {
            assert!(matches!(
                result,
                Err(StoreError::SemanticInvariant(
                    "Event operation-witness index has the wrong table kind"
                ))
            ));
        }
    }

    #[test]
    fn tiny_store_limits_make_the_emergency_reserve_explicit_and_reopenable() {
        let default_limits = StoreLimits::default();
        let default_quota = CustodyQuota::for_store_limits(default_limits).expect("default quota");
        assert_eq!(
            default_quota.max_items(),
            DEFAULT_MAX_ITEMS - MAX_CONTROL_ITEMS - CUSTODY_EMERGENCY_ITEM_RESERVE
        );
        assert_eq!(
            default_quota.max_bytes(),
            DEFAULT_MAX_TOTAL_PAYLOAD_BYTES - MAX_CONTROL_BYTES - CUSTODY_EMERGENCY_BYTE_RESERVE
        );
        for bound in [1, 7, 8] {
            let limits = StoreLimits::new(bound, bound).expect("tiny limits");
            let quota = CustodyQuota::for_store_limits(limits).expect("derived quota");
            let (reserved_items, reserved_bytes) = custody::custody_emergency_reserve(limits);
            let (tombstone_items, tombstone_bytes) = custody::custody_tombstone_allowance(limits);
            assert_eq!(quota.max_items() + reserved_items, bound);
            assert_eq!(quota.max_bytes() + reserved_bytes, bound);
            assert!(reserved_items >= 1 && reserved_bytes >= 1);
            assert_eq!((tombstone_items, tombstone_bytes), (0, 0));
        }

        let file = TestFile::new("one-unit emergency reserve");
        let services = event_services(0xd3);
        let limits = StoreLimits::new(1, 1).expect("one-unit limits");
        let store = Store::open_with_limits_for_mission(&file.0, limits, services.authority)
            .expect("open one-unit store");
        assert_eq!(
            store.custody_usage(None).expect("empty usage"),
            CustodyUsage::default()
        );
        assert!(matches!(
            store.apply(item(0xd3), b""),
            Err(StoreError::ItemLimitExceeded {
                current: 0,
                limit: 0
            })
        ));
        drop(store);
        Store::inspect_existing(&file.0).expect("inspect one-unit store");
        Store::open_with_limits_for_mission(&file.0, limits, services.authority)
            .expect("reopen one-unit store");
    }

