    #[test]
    fn remote_state_ingest_is_policy_bound_idempotent_and_inventory_typed() {
        let origin_file = TestFile::new("remote State origin");
        let receiver_file = TestFile::new("remote State receiver");
        let mut services = state_services(0xe1);
        let origin =
            Store::open_for_mission(&origin_file.0, services.authority).expect("State origin");
        let receiver =
            Store::open_for_mission(&receiver_file.0, services.authority).expect("State receiver");
        let origin_policy = origin.control_policy_snapshot().expect("origin policy");
        let reservation = origin
            .reserve_state_with_policy(
                &origin_policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("origin reservation");
        let (state, sealed, _) = reserved_state(
            &mut services.first,
            &mut services.reader,
            &reservation,
            b"asset/network-state",
            b"ready",
            false,
            1,
        );
        origin
            .commit_reserved_state_with_policy(&origin_policy, &reservation, &state, &sealed)
            .expect("origin commit");

        let receiver_policy = receiver.control_policy_snapshot().expect("receiver policy");
        let inserted = receiver
            .apply_verified_state_with_policy(&receiver_policy, &state, &sealed)
            .expect("remote State insert");
        assert!(inserted.inserted());
        let duplicate = receiver
            .apply_verified_state_with_policy(&receiver_policy, &state, &sealed)
            .expect("remote State replay");
        assert!(!duplicate.inserted());
        let inventory = receiver
            .state_inventory_with_policy(&receiver_policy)
            .expect("State inventory");
        assert_eq!(inventory.len(), 1);
        assert_eq!(
            inventory.iter().copied().collect::<Vec<_>>(),
            vec![StateTransferId::new(state.envelope_id())]
        );
        assert_eq!(inventory.reconciliation_snapshot().len(), 1);
    }

    #[test]
    fn remote_record_ingest_preserves_disconnected_siblings_without_merge_code() {
        let first_file = TestFile::new("remote Record first origin");
        let second_file = TestFile::new("remote Record second origin");
        let receiver_file = TestFile::new("remote Record receiver");
        let mut services = state_services(0xe2);
        let first =
            Store::open_for_mission(&first_file.0, services.authority).expect("first origin");
        let second =
            Store::open_for_mission(&second_file.0, services.authority).expect("second origin");
        let receiver =
            Store::open_for_mission(&receiver_file.0, services.authority).expect("Record receiver");
        let first_policy = first.control_policy_snapshot().expect("first policy");
        let second_policy = second.control_policy_snapshot().expect("second policy");
        let first_reservation = first
            .reserve_record_with_policy(
                &first_policy,
                services.first.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("first reservation");
        let second_reservation = second
            .reserve_record_with_policy(
                &second_policy,
                services.second.identity(),
                &state_topic(),
                &state_scope(),
            )
            .expect("second reservation");
        let (first_record, first_sealed, _) = reserved_record(
            &mut services.first,
            &mut services.reader,
            &first_reservation,
            b"asset/network-record",
            b"alpha",
            false,
            1,
        );
        let (second_record, second_sealed, _) = reserved_record(
            &mut services.second,
            &mut services.reader,
            &second_reservation,
            b"asset/network-record",
            b"bravo",
            false,
            1,
        );
        first
            .commit_reserved_record_with_policy(
                &first_policy,
                &first_reservation,
                &first_record,
                &first_sealed,
            )
            .expect("first origin commit");
        second
            .commit_reserved_record_with_policy(
                &second_policy,
                &second_reservation,
                &second_record,
                &second_sealed,
            )
            .expect("second origin commit");

        let receiver_policy = receiver.control_policy_snapshot().expect("receiver policy");
        receiver
            .apply_verified_record_with_policy(&receiver_policy, &second_record, &second_sealed)
            .expect("second remote revision");
        receiver
            .apply_verified_record_with_policy(&receiver_policy, &first_record, &first_sealed)
            .expect("first remote revision");
        let duplicate = receiver
            .apply_verified_record_with_policy(&receiver_policy, &first_record, &first_sealed)
            .expect("remote Record replay");
        assert!(!duplicate.inserted());

        let plan = receiver
            .prepare_record_projection_with_policy(
                &receiver_policy,
                &state_topic(),
                &state_scope(),
                b"asset/network-record",
            )
            .expect("Record conflict projection");
        assert_eq!(plan.heads().count(), 2);
        let inventory = receiver
            .record_inventory_with_policy(&receiver_policy)
            .expect("Record inventory");
        assert_eq!(inventory.len(), 2);
        assert_eq!(inventory.reconciliation_snapshot().len(), 2);
    }

    #[test]
    fn remote_state_apply_stops_at_retained_item_cap_without_mutation_across_reopen() {
        let file = TestFile::new("remote State retained item cap");
        let mut services = state_services(0xe4);
        let publisher = services.first.identity();
        let (at_limit, at_limit_sealed) = verified_state_for_remote_apply(
            &mut services.first,
            &mut services.reader,
            1,
            VersionVector::default(),
            b"network-cap/state/exact",
            b"exact",
        );
        let mut second_context = VersionVector::default();
        second_context.observe(Dot {
            publisher,
            counter: 1,
        });
        let (over_limit, over_limit_sealed) = verified_state_for_remote_apply(
            &mut services.first,
            &mut services.reader,
            2,
            second_context,
            b"network-cap/state/over",
            b"over",
        );
        let store = Store::open_for_mission(&file.0, services.authority).expect("State store");
        let policy = store.control_policy_snapshot().expect("State policy");
        prefill_state_cap_fixture(
            &store,
            services.second.identity(),
            MAX_MUTABLE_NETWORK_ITEMS_PER_CLASS - 1,
            16 * (MAX_MUTABLE_NETWORK_ITEMS_PER_CLASS - 1),
        );

        let inserted = store
            .apply_verified_state_with_policy(&policy, &at_limit, &at_limit_sealed)
            .expect("admit exact State item bound");
        assert!(inserted.inserted());
        let exact_stats = store.state_stats().expect("exact State cap stats");
        assert_eq!(exact_stats.states, MAX_MUTABLE_NETWORK_ITEMS_PER_CLASS);
        assert_eq!(
            store
                .retained_state_sender_inventory_with_policy(&policy)
                .expect("exact State sender inventory")
                .len(),
            usize::try_from(MAX_MUTABLE_NETWORK_ITEMS_PER_CLASS).expect("State item cap usize")
        );
        assert!(
            !store
                .apply_verified_state_with_policy(&policy, &at_limit, &at_limit_sealed)
                .expect("duplicate State at item cap")
                .inserted()
        );
        assert!(matches!(
            store.apply_verified_state_with_policy(&policy, &over_limit, &over_limit_sealed,),
            Err(StoreError::ItemLimitExceeded {
                current: MAX_MUTABLE_NETWORK_ITEMS_PER_CLASS,
                limit: MAX_MUTABLE_NETWORK_ITEMS_PER_CLASS,
            })
        ));
        assert_eq!(
            store.state_stats().expect("State rejection stats"),
            exact_stats
        );
        assert_eq!(
            store
                .state_by_semantic_id(StateSemanticId::new(over_limit.item_id()))
                .expect("rejected State lookup"),
            None
        );
        drop(store);

        let reopened =
            Store::open_for_mission(&file.0, services.authority).expect("reopen State item cap");
        let reopened_policy = reopened.control_policy_snapshot().expect("reopened policy");
        assert_eq!(
            reopened.state_stats().expect("reopened State stats"),
            exact_stats
        );
        assert!(
            !reopened
                .apply_verified_state_with_policy(&reopened_policy, &at_limit, &at_limit_sealed)
                .expect("reopened duplicate State")
                .inserted()
        );
        assert!(matches!(
            reopened.apply_verified_state_with_policy(
                &reopened_policy,
                &over_limit,
                &over_limit_sealed,
            ),
            Err(StoreError::ItemLimitExceeded {
                current: MAX_MUTABLE_NETWORK_ITEMS_PER_CLASS,
                limit: MAX_MUTABLE_NETWORK_ITEMS_PER_CLASS,
            })
        ));
        assert_eq!(
            reopened.state_stats().expect("final State cap stats"),
            exact_stats
        );
    }

